INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ogSRXbA6VV2', 1, '{"title":"自序","description":"<p>我国自古相传有三坟，最是深奥难懂，历代以来所有名家都认为能解此三坟者就是最懂中华文化的人，这三坟就是《易经》，《黄帝内经》与《神农本草经》，今我收集历代各名家对本草所做之论述，再加上我个人自临床经验中所获得的知识，虽完成这部神农本草经的解说，但是必然有不足之处，敬请读者见谅，后来之高手名医必然可以再增加许多有效之说明与批注，个人期待所有有志学习中医的人士，能够自此书中得到一定的药物学知识，经方之用药是超出原书许多。因此我在本书之后增添许多经方的用药，以备将来研习经方时，能有药性之根据。本书虽未完善，但是已经包含所有将来研究伤寒与金匮所需的药性知识在内，因此如能熟读本书，将来研究经方时必然事半功倍，替研习经方者省去许多不必要的查询药物时间，将来一看到处方时，就可以心知肚明处方原因，剂量使用，用药原则等等，所谓开卷有益，即使看完全书后，只能得到一小点药物知识，这也是值得。期望我人纪班学员与购买者，在看完此书之后，能更上层楼，学无止尽，大家以此为基础，再向上向外发展研究，就不会迷失用药方向了。</p>\n<p>                                                                                                                                  汉唐中医 倪海厦谨记 06/18/2006 于佛州深夜丑时自家书房</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","section":9020001,"no":1}}', '2024-09-28T14:41:53.000Z', '2024-09-28T14:41:53.000Z', '2024-09-28T14:41:53.000Z', '我国自古相传有三坟，最是深奥难懂，历代以来所有名家都认为能解此三坟者就是最懂中华文化的人，这三坟就是《易经》，《黄帝内经》与《神农本草经》，今我收集历代各名家对本草所做之论述，再加上我个人自临床经验中所获得的知识，虽完成这部神农本草经的解说，但是必然有不足之处，敬请读者见谅，后来之高手名医必然可以再增加许多有效之说明与批注，个人期待所有有志学习中医的人士，能够自此书中得到一定的药物学知识，经方之用药是超出原书许多。因此我在本书之后增添许多经方的用药，以备将来研习经方时，能有药性之根据。本书虽未完善，但是已经包含所有将来研究伤寒与金匮所需的药性知识在内，因此如能熟读本书，将来研究经方时必然事半功倍，替研习经方者省去许多不必要的查询药物时间，将来一看到处方时，就可以心知肚明处方原因，剂量使用，用药原则等等，所谓开卷有益，即使看完全书后，只能得到一小点药物知识，这也是值得。期望我人纪班学员与购买者，在看完此书之后，能更上层楼，学无止尽，大家以此为基础，再向上向外发展研究，就不会迷失用药方向了。 汉唐中医 倪海厦谨记 06/18/2006 于佛州深夜丑时自家书房', '2024-09-28T14:41:53.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AqW78YcR3FS', 1, '{"title":"第一章 前 言","description":"<p>         神农本草经成书年代，说法不一，有人认为是战国时期，有人认为是秦汉时期，也有人认为是东汉时期，经过许多医家综合整理，不断收集秦汉时期资料，再整理而成，之后再托名神农而成之书。姑且不论源起于何时期，但它是我国最早的一部本草药典。其地位是无庸置疑的，其原著早于唐代初年已经失传，现在流传的版本是明清以后的学者根据宋代《太平御览》《证类本草》，和明代的《本草纲目》等书，进行整复编辑后，重新出刊的，以清代孙星衍，孙冯冀合辑本（1799）最为广传。</p>\n<p>        原书共载药物三百六十五种，其中植物药二百五十二种，动物药六十七种，矿物药四十六种，这些药大多疗效确实，至今仍被使用，其中涉及病症约一百七十多种，包括了内、外、妇、眼、耳、喉、齿等各科的疾病。对于有毒性的药物，强调必须以小剂量开始。逐渐增加剂量，以免造成药物中毒的后果，其原则是“若用毒药疗病，先起黍粟，病去即止，不去，倍之；不去，十之，取去为度”，对于服药法也有规定，“病在胸膈以上者，先食后服药，病在心腹以下者，先服药而后食，病在四肢血脉者，宜空腹而在旦；病在骨髓者，宜饱满而在夜”，因东汉时期盛行签纬神学，故书中时见如“久服神仙不死”、“主杀鬼”、“能行水上”等用词，这些都是我们可以舍弃不用的。</p>\n<p>         本书所引用的药物药性学，都来自历代的伤寒家，也就是经方家，如陶弘景编录之《名医别录》，雷公之《雷公炮制论》，唐之名医甄权对药性说明。陈藏器的《本草拾遗》，孟铣的《食疗本草》，王好古（1200—1264），字进之，号海藏老人，元代越州人，其著有《汤液本草》，其好经方，善用硫磺、附子、肉桂、干姜、乌头等峻药，清唐容川的《本草问答》，日本东洞吉益先生的《药征》，清徐灵胎的《神农本草经百种录》等等，千年以来温病与伤寒之争论不休，由于二派所认定的药性有所出入，是故选用药物的方式也大异其趣、剂量多少也完全不同，而张仲景所研究的《胎胪药录》早已失传，经方中的药物应该都是出自此书。我们除了在孙思邈的《千金要方》与《千金翼方》二书中可以略窥一二外，在其它药典之中实在无法找出关于《胎胪药录》的药性解说，因此现代有志研习经方的中医们，想更了解经方之中的每味药性，唯一最有效的方式，就是利用伤寒与金匮中的处方方向与使用剂量大小，反过来推知这些药物在东汉时期《胎胪药录》一书对于药性的说明了，然而此法必须要非常了解《黄帝内经》的素问与灵枢、八十一难与阴阳大论，才有可能将这《胎胪药录》重新还其原貌。</p>\n<p>           由于原神农本草经中之药物，有些己经无人识得，有些不切实际。我将之保留不做说明，同学们可以自行查看市面上的有关本草药性的说明，与此同时我增加在伤寒金匮中张仲景所使用之药物，这些药物并不见于原神农本草经中，但是必然出现在《胎胪药录》之中，我将以我对伤寒金匮中处方内的每味药所理解的药性，为之补强说明，希望后来之学者能将之发扬光大。更加能够增润本书的内容。</p>\n<p>          前言：我国医学始于神农、有谓神农尝百草，一日遇七十毒，复命僦贷季（歧伯之师）理色脉，所以上古是先有药而后有医也，是故治病之道必先于用药，而用药之道必先于识药，此书共分上中下三种药物的说明。其中上药一百二十味，中药一百二十味，下药一百二十五味，一共定三百六十五味药，合于天数一年之日数。</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","section":9020002,"no":2}}', '2024-09-28T14:50:00.000Z', '2024-09-28T14:50:00.000Z', '2024-09-28T14:50:00.000Z', '神农本草经成书年代，说法不一，有人认为是战国时期，有人认为是秦汉时期，也有人认为是东汉时期，经过许多医家综合整理，不断收集秦汉时期资料，再整理而成，之后再托名神农而成之书。姑且不论源起于何时期，但它是我国最早的一部本草药典。其地位是无庸置疑的，其原著早于唐代初年已经失传，现在流传的版本是明清以后的学者根据宋代《太平御览》《证类本草》，和明代的《本草纲目》等书，进行整复编辑后，重新出刊的，以清代孙星衍，孙冯冀合辑本（1799）最为广传。 原书共载药物三百六十五种，其中植物药二百五十二种，动物药六十七种，矿物药四十六种，这些药大多疗效确实，至今仍被使用，其中涉及病症约一百七十多种，包括了内、外、妇、眼、耳、喉、齿等各科的疾病。对于有毒性的药物，强调必须以小剂量开始。逐渐增加剂量，以免造成药物中毒的后果，其原则是“若用毒药疗病，先起黍粟，病去即止，不去，倍之；不去，十之，取去为度”，对于服药法也有规定，“病在胸膈以上者，先食后服药，病在心腹以下者，先服药而后食，病在四肢血脉者，宜空腹而在旦；病在骨髓者，宜饱满而在夜”，因东汉时期盛行签纬神学，故书中时见如“久服神仙不死”、“主杀鬼”、“能行水上”等用词，这些都是我们可以舍弃不用的。 本书所引用的药物药性学，都来自历代的伤寒家，也就是经方家，如陶弘景编录之《名医别录》，雷公之《雷公炮制论》，唐之名医甄权对药性说明。陈藏器的《本草拾遗》，孟铣的《食疗本草》，王好古（1200—1264），字进之，号海藏老人，元代越州人，其著有《汤液本草》，其好经方，善用硫磺、附子、肉桂、干姜、乌头等峻药，清唐容川的《本草问答》，日本东洞吉益先生的《药征》，清徐灵胎的《神农本草经百种录》等等，千年以来温病与伤寒之争论不休，由于二派所认定的药性有所出入，是故选用药物的方式也大异其趣、剂量多少也完全不同，而张仲景所研究的《胎胪药录》早已失传，经方中的药物应该都是出自此书。我们除了在孙思邈的《千金要方》与《千金翼方》二书中可以略窥一二外，在其它药典之中实在无法找出关于《胎胪药录》的药性解说，因此现代有志研习经方的中医们，想更了解经方之中的每味药性，唯一最有效的方式，就是利用伤寒与金匮中的处方方向与使用剂量大小，反过来推知这些药物在东汉时期《胎胪药录》一书对于药性的说明了，然而此法必须要非常了解《黄帝内经》的素问与灵枢、八十一难与阴阳大论，才有可能将这《胎胪药录》重新还其原貌。 由于原神农本草经中之药物，有些己经无人识得，有些不切实际。我将之保留不做说明，同学们可以自行查看市面上的有关本草药性的说明，与此同时我增加在伤寒金匮中张仲景所使用之药物，这些药物并不见于原神农本草经中，但是必然出现在《胎胪药录》之中，我将以我对伤寒金匮中处方内的每味药所理解的药性，为之补强说明，希望后来之学者能将之发扬光大。更加能够增润本书的内容。 前言：我国医学始于神农、有谓神农尝百草，一日遇七十毒，复命僦贷季（歧伯之师）理色脉，所以上古是先有药而后有医也，是故治病之道必先于用药，而用药之道必先于识药，此书共分上中下三种药物的说明。其中上药一百二十味，中药一百二十味，下药一百二十五味，一共定三百六十五味药，合于天数一年之日数。', '2024-09-28T14:50:00.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mJqoZNa7qmm', 1, '{"title":"第二章 药性总义 $a{参考本草备要（清·汪讱庵）}","description":"<p>1、五味之义──凡药酸属木入肝，苦属火入心，甘属土入脾，辛属金入肺，咸属水入肾。</p><p>2、五色之义──青属木入肝，赤属火入心，黄属土入脾，白属金入肺，黑属水入肾。</p><p>3、五味之用──凡药酸者能涩能收，苦者能泻能燥能坚，甘者能补能和能缓，辛者能散能润能横行，咸者能下能软坚，淡者能利窍能渗泄。</p><p>4、阴阳之义──寒热温凉是气也，酸苦甘辛咸是味也，气为阳味为阴，其气厚者为阳中之阳，薄者阳中之阴也。味厚者阴中之阴，薄者阴中之阳，气薄主发泄散表，厚则发热与温，味厚则泄降，薄则通窍，利渗湿，辛甘发散为阳，酸苦涌泄为阴，咸味涌泄为阴，淡味渗泄为阳，轻清升浮为阳，重浊沉降为阴，阳气出上窍， 阴味出下窍，清阳发肌理。浊阴走五脏。清阳实四肢，浊阴归六腑。</p><p>5、药之相从──凡药清虚者浮而升，重实者沉而降，味薄者升而生如春季，气薄者降而收象秋季。气厚者浮而长象夏天，味厚者沉而藏象冬天，味平者化而成象长夏，气厚味薄者浮而升，味厚气薄者沉而降，气味俱厚者能浮能沉，气味俱薄者可升可降，酸咸无升，辛甘无降，寒无浮，热无沉，此升降浮沉之义也，凡药根在土中者，半身以上则上升，半身以下则下降，药为枝者达四肢，为皮者达皮肤。为心为干者内行脏腑，质轻者上入心肺，重者下入肝肾，中空者发表，内实者攻里，枯燥者入气分，润泽者入血分，此上下内外之相从也。</p><p>6、药色之入经脉──</p>\n<p>   凡药色青，味酸，气臊，性属木，皆入足厥阴肝，足少阳胆经。</p>\n<p>   色赤味苦，气焦，性属火者，皆入手少阴心，手太阳小肠经。</p>\n<p>   色黄味甘，气香性属土者，皆入足太阴脾，足阳明胃经。</p>\n<p>   色白味辛，气腥，性属金者，皆入手太阴肺，手阳明大肠经。</p>\n<p>   色黑味咸，气腐性属水者，皆入足少阴肾，足太阳膀胱经。</p>\n<p>   十二经中唯手厥阴心包，手少阳三焦经无所主，其经通于足厥阴少阳，而厥阴主血，诸</p>\n<p>   药入肝经血分者，并入心包，少阳主气。诸药入胆经气分者并入三焦，命门相火，散行于胆</p>\n<p>   三焦心包，故入命门者并入三焦，此诸药入诸经之分布也。药有相需者，同类而不可离者。</p>\n<p>   相使者，我之佐使也。相恶者，夺我之能也。相畏者，受彼之制也，相反者。两不相合也。</p>\n<p>相杀者，制彼之毒也，此异同之义也。</p><p>7、五脏补泻之义──</p>\n<p>       肝苦急，急食甘而缓之；肝欲散，急食辛以散之，以辛补之，以酸泻之。</p>\n<p>       心苦缓，急食酸以收之；心欲软，急食咸以软之，以咸补之，以甘泻之。</p>\n<p>       脾苦湿，急食苦以燥之；脾欲缓，急食甘以缓之，以甘补之，以苦泻之。</p>\n<p>       肺苦气上逆，急食苦以泻之；肺欲收，急食酸以收之，以酸补之，以辛泻之。</p>\n<p>       肾苦燥，急食辛以润之；肾欲坚，急食苦以坚之，以苦补之，以咸泻之，此是其义也。</p><p>8、六淫主治──</p>\n<p>      风淫于内，治以辛凉，佐以苦甘，以甘缓之，以辛散之。</p>\n<p>      热淫于内，治以咸寒，佐以甘苦，以酸收之，以苦发之。</p>\n<p>      湿淫于内，治以苦热，佐以酸淡，以苦燥之，以淡泄之。</p>\n<p>     火淫于内，治以咸冷，佐以苦辛，以酸收之，以苦发之。</p>\n<p>     燥淫于内，治以苦温，佐以甘辛，以苦下之。</p>\n<p>     寒淫于内，治以甘热，佐以苦辛，以咸泻之，以辛润之，以苦坚之。</p>\n<p>此六淫主治，各有所宜，故药性须明，而施用贵审也。</p><p>9、五行相生──人之五藏应五行，子母相生，</p>\n<p>经曰：虚则补其母，实则泻其子。又曰：子能令母实，母能令子虚，</p>\n<p>        如肾为肝母，心为肝子，故入肝者并入肾与心。</p>\n<p>         肝为心母，脾为心子，故入心者并入肝与脾。</p>\n<p>         心为脾母，肺为脾子，故入脾者并入心与肺。</p>\n<p>         脾为肺母，肾为肺子，故入肺者并入脾与肾。</p>\n<p>         肺为肾母，肝为肾子，故入肾者并入肺与肝。</p>\n<p>此五行相生子母相应之义也。</p><p>10、五行相克──酸伤筋，辛胜酸；苦伤气，咸胜苦；甘伤肉，酸胜甘；辛伤皮毛，苦胜辛；咸伤血，甘胜咸。因为酸主收敛，敛则筋缩，苦能泻气，辛能疏散肌理，咸能渗泄。</p><p>11、五病所禁──</p>\n<p>       酸走筋，故筋病勿多食酸，筋得酸则拘急，收引益盛。</p>\n<p>       苦走骨，故骨病勿多食苦，骨得苦则阴益盛，令人重而难举。</p>\n<p>       甘走肉，肉痛勿多食甘，肉病得甘则壅气，臃肿益甚。</p>\n<p>       辛走气，气病勿多食辛，气得辛则散，而益虚。</p>\n<p>       咸走血，血病勿多食咸，血得咸则凝涩，而口渴也。</p><p>12、五味所伤──</p>\n<p>        多食咸，则脉凝泣而变色。</p>\n<p>        多食苦，则皮槁而毛拔。</p>\n<p>        多食辛，则筋急而爪枯。</p>\n<p>        多食酸，则肉消皮厚而唇开。</p>\n<p>        多食甘，则骨痛而发落。</p>\n<p>药之为物，各有其形性气质，其入诸经，有因形相类者，有因性相从者，有因气相求者，有因质相同者，自然之理，可以以意得也。</p>\n<p>药有以形名者，人参狗脊之类是也，有以色名者，黄连黑参之类是也，有以气名者，稀签香薷之类是也，有以味名者，甘草苦参之类是也，有以质名者，石膏石脂归身归尾之类是也，有以时名者，夏枯款冬之类是也，有以能名者，何首乌骨碎补之类是也。</p>\n<p>    凡药火制四，煨炙炒煅也。</p>\n<p>            水制三，浸泡洗也，水火共制二，蒸煮也，酒制升提，姜制温散。</p>\n<p>            入盐走肾而软坚。</p>\n<p>            用醋注肝而收敛。</p>\n<p>            童便制，除劣性而降下，</p>\n<p>            米泔制，去燥性而和中，</p>\n<p>            乳制润枯生血，蜜制甘缓益元。</p>\n<p>            陈壁土制，藉土气以补中州。</p>\n<p>            面裹曲制，抑酷性勿伤上膈。</p>\n<p> 黑豆甘草汤渍，并解毒致平和，羊酥猪脂涂烧，咸渗骨容易脆断，去穰者免胀，去心者除烦，此制治各有所宜也。</p>\n<p>         一药之为用，或地道不真，则美恶迥别，或市肆饰伪，则气味全乖，或收采非时，则良楛异质，或头尾误用，则呼应不灵，或制治不精，则功力大减，用者不察，顾归咎于药之罔功，譬之兵不精炼，思以荡寇克敌，适以覆众舆ㄕ也，治疗之家，其可忽诸。</p>\n<p>        千金云：凡药须治择熬泡毕，然后秤用，不得生秤，湿润药先皆增分两，燥乃秤之。</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","section":9020003,"no":3}}', '2024-09-28T14:51:17.000Z', '2024-09-28T14:51:17.000Z', '2024-09-28T14:51:17.000Z', '1、五味之义──凡药酸属木入肝，苦属火入心，甘属土入脾，辛属金入肺，咸属水入肾。 2、五色之义──青属木入肝，赤属火入心，黄属土入脾，白属金入肺，黑属水入肾。 3、五味之用──凡药酸者能涩能收，苦者能泻能燥能坚，甘者能补能和能缓，辛者能散能润能横行，咸者能下能软坚，淡者能利窍能渗泄。 4、阴阳之义──寒热温凉是气也，酸苦甘辛咸是味也，气为阳味为阴，其气厚者为阳中之阳，薄者阳中之阴也。味厚者阴中之阴，薄者阴中之阳，气薄主发泄散表，厚则发热与温，味厚则泄降，薄则通窍，利渗湿，辛甘发散为阳，酸苦涌泄为阴，咸味涌泄为阴，淡味渗泄为阳，轻清升浮为阳，重浊沉降为阴，阳气出上窍， 阴味出下窍，清阳发肌理。浊阴走五脏。清阳实四肢，浊阴归六腑。 5、药之相从──凡药清虚者浮而升，重实者沉而降，味薄者升而生如春季，气薄者降而收象秋季。气厚者浮而长象夏天，味厚者沉而藏象冬天，味平者化而成象长夏，气厚味薄者浮而升，味厚气薄者沉而降，气味俱厚者能浮能沉，气味俱薄者可升可降，酸咸无升，辛甘无降，寒无浮，热无沉，此升降浮沉之义也，凡药根在土中者，半身以上则上升，半身以下则下降，药为枝者达四肢，为皮者达皮肤。为心为干者内行脏腑，质轻者上入心肺，重者下入肝肾，中空者发表，内实者攻里，枯燥者入气分，润泽者入血分，此上下内外之相从也。 6、药色之入经脉── 凡药色青，味酸，气臊，性属木，皆入足厥阴肝，足少阳胆经。 色赤味苦，气焦，性属火者，皆入手少阴心，手太阳小肠经。 色黄味甘，气香性属土者，皆入足太阴脾，足阳明胃经。 色白味辛，气腥，性属金者，皆入手太阴肺，手阳明大肠经。 色黑味咸，气腐性属水者，皆入足少阴肾，足太阳膀胱经。 十二经中唯手厥阴心包，手少阳三焦经无所主，其经通于足厥阴少阳，而厥阴主血，诸 药入肝经血分者，并入心包，少阳主气。诸药入胆经气分者并入三焦，命门相火，散行于胆 三焦心包，故入命门者并入三焦，此诸药入诸经之分布也。药有相需者，同类而不可离者。 相使者，我之佐使也。相恶者，夺我之能也。相畏者，受彼之制也，相反者。两不相合也。 相杀者，制彼之毒也，此异同之义也。 7、五脏补泻之义── 肝苦急，急食甘而缓之；肝欲散，急食辛以散之，以辛补之，以酸泻之。 心苦缓，急食酸以收之；心欲软，急食咸以软之，以咸补之，以甘泻之。 脾苦湿，急食苦以燥之；脾欲缓，急食甘以缓之，以甘补之，以苦泻之。 肺苦气上逆，急食苦以泻之；肺欲收，急食酸以收之，以酸补之，以辛泻之。 肾苦燥，急食辛以润之；肾欲坚，急食苦以坚之，以苦补之，以咸泻之，此是其义也。 8、六淫主治── 风淫于内，治以辛凉，佐以苦甘，以甘缓之，以辛散之。 热淫于内，治以咸寒，佐以甘苦，以酸收之，以苦发之。 湿淫于内，治以苦热，佐以酸淡，以苦燥之，以淡泄之。 火淫于内，治以咸冷，佐以苦辛，以酸收之，以苦发之。 燥淫于内，治以苦温，佐以甘辛，以苦下之。 寒淫于内，治以甘热，佐以苦辛，以咸泻之，以辛润之，以苦坚之。 此六淫主治，各有所宜，故药性须明，而施用贵审也。 9、五行相生──人之五藏应五行，子母相生， 经曰：虚则补其母，实则泻其子。又曰：子能令母实，母能令子虚， 如肾为肝母，心为肝子，故入肝者并入肾与心。 肝为心母，脾为心子，故入心者并入肝与脾。 心为脾母，肺为脾子，故入脾者并入心与肺。 脾为肺母，肾为肺子，故入肺者并入脾与肾。 肺为肾母，肝为肾子，故入肾者并入肺与肝。 此五行相生子母相应之义也。 10、五行相克──酸伤筋，辛胜酸；苦伤气，咸胜苦；甘伤肉，酸胜甘；辛伤皮毛，苦胜辛；咸伤血，甘胜咸。因为酸主收敛，敛则筋缩，苦能泻气，辛能疏散肌理，咸能渗泄。 11、五病所禁── 酸走筋，故筋病勿多食酸，筋得酸则拘急，收引益盛。 苦走骨，故骨病勿多食苦，骨得苦则阴益盛，令人重而难举。 甘走肉，肉痛勿多食甘，肉病得甘则壅气，臃肿益甚。 辛走气，气病勿多食辛，气得辛则散，而益虚。 咸走血，血病勿多食咸，血得咸则凝涩，而口渴也。 12、五味所伤── 多食咸，则脉凝泣而变色。 多食苦，则皮槁而毛拔。 多食辛，则筋急而爪枯。 多食酸，则肉消皮厚而唇开。 多食甘，则骨痛而发落。 药之为物，各有其形性气质，其入诸经，有因形相类者，有因性相从者，有因气相求者，有因质相同者，自然之理，可以以意得也。 药有以形名者，人参狗脊之类是也，有以色名者，黄连黑参之类是也，有以气名者，稀签香薷之类是也，有以味名者，甘草苦参之类是也，有以质名者，石膏石脂归身归尾之类是也，有以时名者，夏枯款冬之类是也，有以能名者，何首乌骨碎补之类是也。 凡药火制四，煨炙炒煅也。 水制三，浸泡洗也，水火共制二，蒸煮也，酒制升提，姜制温散。 入盐走肾而软坚。 用醋注肝而收敛。 童便制，除劣性而降下， 米泔制，去燥性而和中， 乳制润枯生血，蜜制甘缓益元。 陈壁土制，藉土气以补中州。 面裹曲制，抑酷性勿伤上膈。 黑豆甘草汤渍，并解毒致平和，羊酥猪脂涂烧，咸渗骨容易脆断，去穰者免胀，去心者除烦，此制治各有所宜也。 一药之为用，或地道不真，则美恶迥别，或市肆饰伪，则气味全乖，或收采非时，则良楛异质，或头尾误用，则呼应不灵，或制治不精，则功力大减，用者不察，顾归咎于药之罔功，譬之兵不精炼，思以荡寇克敌，适以覆众舆ㄕ也，治疗之家，其可忽诸。 千金云：凡药须治择熬泡毕，然后秤用，不得生秤，湿润药先皆增分两，燥乃秤之。', '2024-09-28T14:51:17.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'chapter', NULL);
