INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BIn3yW1iKmb', 4, '{"title":"第902000101条・自序","description":"<p>我国自古相传有三坟，最是深奥难懂，历代以来所有名家都认为能解此三坟者就是最懂中华文化的人，这三坟就是《易经》，《黄帝内经》与《神农本草经》，今我收集历代各名家对本草所做之论述，再加上我个人自临床经验中所获得的知识，虽完成这部神农本草经的解说，但是必然有不足之处，敬请读者见谅，后来之高手名医必然可以再增加许多有效之说明与批注，个人期待所有有志学习中医的人士，能够自此书中得到一定的药物学知识，经方之用药是超出原书许多。因此我在本书之后增添许多经方的用药，以备将来研习经方时，能有药性之根据。本书虽未完善，但是已经包含所有将来研究伤寒与金匮所需的药性知识在内，因此如能熟读本书，将来研究经方时必然事半功倍，替研习经方者省去许多不必要的查询药物时间，将来一看到处方时，就可以心知肚明处方原因，剂量使用，用药原则等等，所谓开卷有益，即使看完全书后，只能得到一小点药物知识，这也是值得。期望我人纪班学员与购买者，在看完此书之后，能更上层楼，学无止尽，大家以此为基础，再向上向外发展研究，就不会迷失用药方向了。</p>\n<p>                                                                                                                                  汉唐中医 倪海厦谨记 06/18/2006 于佛州深夜丑时自家书房</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000101,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-28T14:41:53.000Z', '2024-09-28T14:41:53.000Z', '2024-09-28T14:41:53.000Z', '我国自古相传有三坟，最是深奥难懂，历代以来所有名家都认为能解此三坟者就是最懂中华文化的人，这三坟就是《易经》，《黄帝内经》与《神农本草经》，今我收集历代各名家对本草所做之论述，再加上我个人自临床经验中所获得的知识，虽完成这部神农本草经的解说，但是必然有不足之处，敬请读者见谅，后来之高手名医必然可以再增加许多有效之说明与批注，个人期待所有有志学习中医的人士，能够自此书中得到一定的药物学知识，经方之用药是超出原书许多。因此我在本书之后增添许多经方的用药，以备将来研习经方时，能有药性之根据。本书虽未完善，但是已经包含所有将来研究伤寒与金匮所需的药性知识在内，因此如能熟读本书，将来研究经方时必然事半功倍，替研习经方者省去许多不必要的查询药物时间，将来一看到处方时，就可以心知肚明处方原因，剂量使用，用药原则等等，所谓开卷有益，即使看完全书后，只能得到一小点药物知识，这也是值得。期望我人纪班学员与购买者，在看完此书之后，能更上层楼，学无止尽，大家以此为基础，再向上向外发展研究，就不会迷失用药方向了。 汉唐中医 倪海厦谨记 06/18/2006 于佛州深夜丑时自家书房', '2024-09-28T14:41:53.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'ogSRXbA6VV2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xUWCvYuSML4', 4, '{"title":"第902000201条・第一章 前 言","description":"<p>         神农本草经成书年代，说法不一，有人认为是战国时期，有人认为是秦汉时期，也有人认为是东汉时期，经过许多医家综合整理，不断收集秦汉时期资料，再整理而成，之后再托名神农而成之书。姑且不论源起于何时期，但它是我国最早的一部本草药典。其地位是无庸置疑的，其原著早于唐代初年已经失传，现在流传的版本是明清以后的学者根据宋代《太平御览》《证类本草》，和明代的《本草纲目》等书，进行整复编辑后，重新出刊的，以清代孙星衍，孙冯冀合辑本（1799）最为广传。</p>\n<p>        原书共载药物三百六十五种，其中植物药二百五十二种，动物药六十七种，矿物药四十六种，这些药大多疗效确实，至今仍被使用，其中涉及病症约一百七十多种，包括了内、外、妇、眼、耳、喉、齿等各科的疾病。对于有毒性的药物，强调必须以小剂量开始。逐渐增加剂量，以免造成药物中毒的后果，其原则是“若用毒药疗病，先起黍粟，病去即止，不去，倍之；不去，十之，取去为度”，对于服药法也有规定，“病在胸膈以上者，先食后服药，病在心腹以下者，先服药而后食，病在四肢血脉者，宜空腹而在旦；病在骨髓者，宜饱满而在夜”，因东汉时期盛行签纬神学，故书中时见如“久服神仙不死”、“主杀鬼”、“能行水上”等用词，这些都是我们可以舍弃不用的。</p>\n<p>         本书所引用的药物药性学，都来自历代的伤寒家，也就是经方家，如陶弘景编录之《名医别录》，雷公之《雷公炮制论》，唐之名医甄权对药性说明。陈藏器的《本草拾遗》，孟铣的《食疗本草》，王好古（1200—1264），字进之，号海藏老人，元代越州人，其著有《汤液本草》，其好经方，善用硫磺、附子、肉桂、干姜、乌头等峻药，清唐容川的《本草问答》，日本东洞吉益先生的《药征》，清徐灵胎的《神农本草经百种录》等等，千年以来温病与伤寒之争论不休，由于二派所认定的药性有所出入，是故选用药物的方式也大异其趣、剂量多少也完全不同，而张仲景所研究的《胎胪药录》早已失传，经方中的药物应该都是出自此书。我们除了在孙思邈的《千金要方》与《千金翼方》二书中可以略窥一二外，在其它药典之中实在无法找出关于《胎胪药录》的药性解说，因此现代有志研习经方的中医们，想更了解经方之中的每味药性，唯一最有效的方式，就是利用伤寒与金匮中的处方方向与使用剂量大小，反过来推知这些药物在东汉时期《胎胪药录》一书对于药性的说明了，然而此法必须要非常了解《黄帝内经》的素问与灵枢、八十一难与阴阳大论，才有可能将这《胎胪药录》重新还其原貌。</p>\n<p>           由于原神农本草经中之药物，有些己经无人识得，有些不切实际。我将之保留不做说明，同学们可以自行查看市面上的有关本草药性的说明，与此同时我增加在伤寒金匮中张仲景所使用之药物，这些药物并不见于原神农本草经中，但是必然出现在《胎胪药录》之中，我将以我对伤寒金匮中处方内的每味药所理解的药性，为之补强说明，希望后来之学者能将之发扬光大。更加能够增润本书的内容。</p>\n<p>          前言：我国医学始于神农、有谓神农尝百草，一日遇七十毒，复命僦贷季（歧伯之师）理色脉，所以上古是先有药而后有医也，是故治病之道必先于用药，而用药之道必先于识药，此书共分上中下三种药物的说明。其中上药一百二十味，中药一百二十味，下药一百二十五味，一共定三百六十五味药，合于天数一年之日数。</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000201,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-28T14:50:00.000Z', '2024-09-28T14:50:00.000Z', '2024-09-28T14:50:00.000Z', '神农本草经成书年代，说法不一，有人认为是战国时期，有人认为是秦汉时期，也有人认为是东汉时期，经过许多医家综合整理，不断收集秦汉时期资料，再整理而成，之后再托名神农而成之书。姑且不论源起于何时期，但它是我国最早的一部本草药典。其地位是无庸置疑的，其原著早于唐代初年已经失传，现在流传的版本是明清以后的学者根据宋代《太平御览》《证类本草》，和明代的《本草纲目》等书，进行整复编辑后，重新出刊的，以清代孙星衍，孙冯冀合辑本（1799）最为广传。 原书共载药物三百六十五种，其中植物药二百五十二种，动物药六十七种，矿物药四十六种，这些药大多疗效确实，至今仍被使用，其中涉及病症约一百七十多种，包括了内、外、妇、眼、耳、喉、齿等各科的疾病。对于有毒性的药物，强调必须以小剂量开始。逐渐增加剂量，以免造成药物中毒的后果，其原则是“若用毒药疗病，先起黍粟，病去即止，不去，倍之；不去，十之，取去为度”，对于服药法也有规定，“病在胸膈以上者，先食后服药，病在心腹以下者，先服药而后食，病在四肢血脉者，宜空腹而在旦；病在骨髓者，宜饱满而在夜”，因东汉时期盛行签纬神学，故书中时见如“久服神仙不死”、“主杀鬼”、“能行水上”等用词，这些都是我们可以舍弃不用的。 本书所引用的药物药性学，都来自历代的伤寒家，也就是经方家，如陶弘景编录之《名医别录》，雷公之《雷公炮制论》，唐之名医甄权对药性说明。陈藏器的《本草拾遗》，孟铣的《食疗本草》，王好古（1200—1264），字进之，号海藏老人，元代越州人，其著有《汤液本草》，其好经方，善用硫磺、附子、肉桂、干姜、乌头等峻药，清唐容川的《本草问答》，日本东洞吉益先生的《药征》，清徐灵胎的《神农本草经百种录》等等，千年以来温病与伤寒之争论不休，由于二派所认定的药性有所出入，是故选用药物的方式也大异其趣、剂量多少也完全不同，而张仲景所研究的《胎胪药录》早已失传，经方中的药物应该都是出自此书。我们除了在孙思邈的《千金要方》与《千金翼方》二书中可以略窥一二外，在其它药典之中实在无法找出关于《胎胪药录》的药性解说，因此现代有志研习经方的中医们，想更了解经方之中的每味药性，唯一最有效的方式，就是利用伤寒与金匮中的处方方向与使用剂量大小，反过来推知这些药物在东汉时期《胎胪药录》一书对于药性的说明了，然而此法必须要非常了解《黄帝内经》的素问与灵枢、八十一难与阴阳大论，才有可能将这《胎胪药录》重新还其原貌。 由于原神农本草经中之药物，有些己经无人识得，有些不切实际。我将之保留不做说明，同学们可以自行查看市面上的有关本草药性的说明，与此同时我增加在伤寒金匮中张仲景所使用之药物，这些药物并不见于原神农本草经中，但是必然出现在《胎胪药录》之中，我将以我对伤寒金匮中处方内的每味药所理解的药性，为之补强说明，希望后来之学者能将之发扬光大。更加能够增润本书的内容。 前言：我国医学始于神农、有谓神农尝百草，一日遇七十毒，复命僦贷季（歧伯之师）理色脉，所以上古是先有药而后有医也，是故治病之道必先于用药，而用药之道必先于识药，此书共分上中下三种药物的说明。其中上药一百二十味，中药一百二十味，下药一百二十五味，一共定三百六十五味药，合于天数一年之日数。', '2024-09-28T14:50:00.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'AqW78YcR3FS');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('G9OnR1ZMxW2', 4, '{"title":"第902000301条・第二章 药性总义 $a{参考本草备要（清·汪讱庵）}","description":"<p>1、五味之义──凡药酸属木入肝，苦属火入心，甘属土入脾，辛属金入肺，咸属水入肾。</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000301,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-28T14:51:17.000Z', '2024-09-28T14:51:17.000Z', '2024-09-28T14:51:17.000Z', '1、五味之义──凡药酸属木入肝，苦属火入心，甘属土入脾，辛属金入肺，咸属水入肾。', '2024-09-28T14:51:17.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'mJqoZNa7qmm');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2A3nIGxNTyJ', 4, '{"title":"第902000312条・第二章 药性总义 $a{参考本草备要（清·汪讱庵）}","description":"<p>12、五味所伤──</p>\n<p>        多食咸，则脉凝泣而变色。</p>\n<p>        多食苦，则皮槁而毛拔。</p>\n<p>        多食辛，则筋急而爪枯。</p>\n<p>        多食酸，则肉消皮厚而唇开。</p>\n<p>        多食甘，则骨痛而发落。</p>\n<p>药之为物，各有其形性气质，其入诸经，有因形相类者，有因性相从者，有因气相求者，有因质相同者，自然之理，可以以意得也。</p>\n<p>药有以形名者，人参狗脊之类是也，有以色名者，黄连黑参之类是也，有以气名者，稀签香薷之类是也，有以味名者，甘草苦参之类是也，有以质名者，石膏石脂归身归尾之类是也，有以时名者，夏枯款冬之类是也，有以能名者，何首乌骨碎补之类是也。</p>\n<p>    凡药火制四，煨炙炒煅也。</p>\n<p>            水制三，浸泡洗也，水火共制二，蒸煮也，酒制升提，姜制温散。</p>\n<p>            入盐走肾而软坚。</p>\n<p>            用醋注肝而收敛。</p>\n<p>            童便制，除劣性而降下，</p>\n<p>            米泔制，去燥性而和中，</p>\n<p>            乳制润枯生血，蜜制甘缓益元。</p>\n<p>            陈壁土制，藉土气以补中州。</p>\n<p>            面裹曲制，抑酷性勿伤上膈。</p>\n<p> 黑豆甘草汤渍，并解毒致平和，羊酥猪脂涂烧，咸渗骨容易脆断，去穰者免胀，去心者除烦，此制治各有所宜也。</p>\n<p>         一药之为用，或地道不真，则美恶迥别，或市肆饰伪，则气味全乖，或收采非时，则良楛异质，或头尾误用，则呼应不灵，或制治不精，则功力大减，用者不察，顾归咎于药之罔功，譬之兵不精炼，思以荡寇克敌，适以覆众舆ㄕ也，治疗之家，其可忽诸。</p>\n<p>        千金云：凡药须治择熬泡毕，然后秤用，不得生秤，湿润药先皆增分两，燥乃秤之。</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000312,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-28T15:03:02.000Z', '2024-09-28T15:03:02.000Z', '2024-09-28T15:03:02.000Z', '12、五味所伤── 多食咸，则脉凝泣而变色。 多食苦，则皮槁而毛拔。 多食辛，则筋急而爪枯。 多食酸，则肉消皮厚而唇开。 多食甘，则骨痛而发落。 药之为物，各有其形性气质，其入诸经，有因形相类者，有因性相从者，有因气相求者，有因质相同者，自然之理，可以以意得也。 药有以形名者，人参狗脊之类是也，有以色名者，黄连黑参之类是也，有以气名者，稀签香薷之类是也，有以味名者，甘草苦参之类是也，有以质名者，石膏石脂归身归尾之类是也，有以时名者，夏枯款冬之类是也，有以能名者，何首乌骨碎补之类是也。 凡药火制四，煨炙炒煅也。 水制三，浸泡洗也，水火共制二，蒸煮也，酒制升提，姜制温散。 入盐走肾而软坚。 用醋注肝而收敛。 童便制，除劣性而降下， 米泔制，去燥性而和中， 乳制润枯生血，蜜制甘缓益元。 陈壁土制，藉土气以补中州。 面裹曲制，抑酷性勿伤上膈。 黑豆甘草汤渍，并解毒致平和，羊酥猪脂涂烧，咸渗骨容易脆断，去穰者免胀，去心者除烦，此制治各有所宜也。 一药之为用，或地道不真，则美恶迥别，或市肆饰伪，则气味全乖，或收采非时，则良楛异质，或头尾误用，则呼应不灵，或制治不精，则功力大减，用者不察，顾归咎于药之罔功，譬之兵不精炼，思以荡寇克敌，适以覆众舆ㄕ也，治疗之家，其可忽诸。 千金云：凡药须治择熬泡毕，然后秤用，不得生秤，湿润药先皆增分两，燥乃秤之。', '2024-09-28T15:03:02.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'mJqoZNa7qmm');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oxGV3wVuvfJ', 4, '{"title":"第902000311条・第二章 药性总义 $a{参考本草备要（清·汪讱庵）}","description":"<p>11、五病所禁──</p>\n<p>       酸走筋，故筋病勿多食酸，筋得酸则拘急，收引益盛。</p>\n<p>       苦走骨，故骨病勿多食苦，骨得苦则阴益盛，令人重而难举。</p>\n<p>       甘走肉，肉痛勿多食甘，肉病得甘则壅气，臃肿益甚。</p>\n<p>       辛走气，气病勿多食辛，气得辛则散，而益虚。</p>\n<p>       咸走血，血病勿多食咸，血得咸则凝涩，而口渴也。</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000311,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-28T15:03:02.000Z', '2024-09-28T15:03:02.000Z', '2024-09-28T15:03:02.000Z', '11、五病所禁── 酸走筋，故筋病勿多食酸，筋得酸则拘急，收引益盛。 苦走骨，故骨病勿多食苦，骨得苦则阴益盛，令人重而难举。 甘走肉，肉痛勿多食甘，肉病得甘则壅气，臃肿益甚。 辛走气，气病勿多食辛，气得辛则散，而益虚。 咸走血，血病勿多食咸，血得咸则凝涩，而口渴也。', '2024-09-28T15:03:02.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'mJqoZNa7qmm');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ia40BaduUJo', 4, '{"title":"第902000310条・第二章 药性总义 $a{参考本草备要（清·汪讱庵）}","description":"<p>10、五行相克──酸伤筋，辛胜酸；苦伤气，咸胜苦；甘伤肉，酸胜甘；辛伤皮毛，苦胜辛；咸伤血，甘胜咸。因为酸主收敛，敛则筋缩，苦能泻气，辛能疏散肌理，咸能渗泄。</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000310,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-28T15:03:02.000Z', '2024-09-28T15:03:02.000Z', '2024-09-28T15:03:02.000Z', '10、五行相克──酸伤筋，辛胜酸；苦伤气，咸胜苦；甘伤肉，酸胜甘；辛伤皮毛，苦胜辛；咸伤血，甘胜咸。因为酸主收敛，敛则筋缩，苦能泻气，辛能疏散肌理，咸能渗泄。', '2024-09-28T15:03:02.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'mJqoZNa7qmm');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uaDM7VA1G0c', 4, '{"title":"第902000309条・第二章 药性总义 $a{参考本草备要（清·汪讱庵）}","description":"<p>9、五行相生──人之五藏应五行，子母相生，</p>\n<p>经曰：虚则补其母，实则泻其子。又曰：子能令母实，母能令子虚，</p>\n<p>        如肾为肝母，心为肝子，故入肝者并入肾与心。</p>\n<p>         肝为心母，脾为心子，故入心者并入肝与脾。</p>\n<p>         心为脾母，肺为脾子，故入脾者并入心与肺。</p>\n<p>         脾为肺母，肾为肺子，故入肺者并入脾与肾。</p>\n<p>         肺为肾母，肝为肾子，故入肾者并入肺与肝。</p>\n<p>此五行相生子母相应之义也。</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000309,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-28T15:03:02.000Z', '2024-09-28T15:03:02.000Z', '2024-09-28T15:03:02.000Z', '9、五行相生──人之五藏应五行，子母相生， 经曰：虚则补其母，实则泻其子。又曰：子能令母实，母能令子虚， 如肾为肝母，心为肝子，故入肝者并入肾与心。 肝为心母，脾为心子，故入心者并入肝与脾。 心为脾母，肺为脾子，故入脾者并入心与肺。 脾为肺母，肾为肺子，故入肺者并入脾与肾。 肺为肾母，肝为肾子，故入肾者并入肺与肝。 此五行相生子母相应之义也。', '2024-09-28T15:03:02.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'mJqoZNa7qmm');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PyyZy9oSj9o', 4, '{"title":"第902000308条・第二章 药性总义 $a{参考本草备要（清·汪讱庵）}","description":"<p>8、六淫主治──</p>\n<p>      风淫于内，治以辛凉，佐以苦甘，以甘缓之，以辛散之。</p>\n<p>      热淫于内，治以咸寒，佐以甘苦，以酸收之，以苦发之。</p>\n<p>      湿淫于内，治以苦热，佐以酸淡，以苦燥之，以淡泄之。</p>\n<p>     火淫于内，治以咸冷，佐以苦辛，以酸收之，以苦发之。</p>\n<p>     燥淫于内，治以苦温，佐以甘辛，以苦下之。</p>\n<p>     寒淫于内，治以甘热，佐以苦辛，以咸泻之，以辛润之，以苦坚之。</p>\n<p>此六淫主治，各有所宜，故药性须明，而施用贵审也。</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000308,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-28T15:03:02.000Z', '2024-09-28T15:03:02.000Z', '2024-09-28T15:03:02.000Z', '8、六淫主治── 风淫于内，治以辛凉，佐以苦甘，以甘缓之，以辛散之。 热淫于内，治以咸寒，佐以甘苦，以酸收之，以苦发之。 湿淫于内，治以苦热，佐以酸淡，以苦燥之，以淡泄之。 火淫于内，治以咸冷，佐以苦辛，以酸收之，以苦发之。 燥淫于内，治以苦温，佐以甘辛，以苦下之。 寒淫于内，治以甘热，佐以苦辛，以咸泻之，以辛润之，以苦坚之。 此六淫主治，各有所宜，故药性须明，而施用贵审也。', '2024-09-28T15:03:02.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'mJqoZNa7qmm');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GS0ZPdF4YHx', 4, '{"title":"第902000307条・第二章 药性总义 $a{参考本草备要（清·汪讱庵）}","description":"<p>7、五脏补泻之义──</p>\n<p>       肝苦急，急食甘而缓之；肝欲散，急食辛以散之，以辛补之，以酸泻之。</p>\n<p>       心苦缓，急食酸以收之；心欲软，急食咸以软之，以咸补之，以甘泻之。</p>\n<p>       脾苦湿，急食苦以燥之；脾欲缓，急食甘以缓之，以甘补之，以苦泻之。</p>\n<p>       肺苦气上逆，急食苦以泻之；肺欲收，急食酸以收之，以酸补之，以辛泻之。</p>\n<p>       肾苦燥，急食辛以润之；肾欲坚，急食苦以坚之，以苦补之，以咸泻之，此是其义也。</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000307,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-28T15:03:02.000Z', '2024-09-28T15:03:02.000Z', '2024-09-28T15:03:02.000Z', '7、五脏补泻之义── 肝苦急，急食甘而缓之；肝欲散，急食辛以散之，以辛补之，以酸泻之。 心苦缓，急食酸以收之；心欲软，急食咸以软之，以咸补之，以甘泻之。 脾苦湿，急食苦以燥之；脾欲缓，急食甘以缓之，以甘补之，以苦泻之。 肺苦气上逆，急食苦以泻之；肺欲收，急食酸以收之，以酸补之，以辛泻之。 肾苦燥，急食辛以润之；肾欲坚，急食苦以坚之，以苦补之，以咸泻之，此是其义也。', '2024-09-28T15:03:02.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'mJqoZNa7qmm');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Yd75UuDpkn8', 4, '{"title":"第902000306条・第二章 药性总义 $a{参考本草备要（清·汪讱庵）}","description":"<p>6、药色之入经脉──</p>\n<p>   凡药色青，味酸，气臊，性属木，皆入足厥阴肝，足少阳胆经。</p>\n<p>   色赤味苦，气焦，性属火者，皆入手少阴心，手太阳小肠经。</p>\n<p>   色黄味甘，气香性属土者，皆入足太阴脾，足阳明胃经。</p>\n<p>   色白味辛，气腥，性属金者，皆入手太阴肺，手阳明大肠经。</p>\n<p>   色黑味咸，气腐性属水者，皆入足少阴肾，足太阳膀胱经。</p>\n<p>   十二经中唯手厥阴心包，手少阳三焦经无所主，其经通于足厥阴少阳，而厥阴主血，诸</p>\n<p>   药入肝经血分者，并入心包，少阳主气。诸药入胆经气分者并入三焦，命门相火，散行于胆</p>\n<p>   三焦心包，故入命门者并入三焦，此诸药入诸经之分布也。药有相需者，同类而不可离者。</p>\n<p>   相使者，我之佐使也。相恶者，夺我之能也。相畏者，受彼之制也，相反者。两不相合也。</p>\n<p>相杀者，制彼之毒也，此异同之义也。</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000306,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-28T15:03:02.000Z', '2024-09-28T15:03:02.000Z', '2024-09-28T15:03:02.000Z', '6、药色之入经脉── 凡药色青，味酸，气臊，性属木，皆入足厥阴肝，足少阳胆经。 色赤味苦，气焦，性属火者，皆入手少阴心，手太阳小肠经。 色黄味甘，气香性属土者，皆入足太阴脾，足阳明胃经。 色白味辛，气腥，性属金者，皆入手太阴肺，手阳明大肠经。 色黑味咸，气腐性属水者，皆入足少阴肾，足太阳膀胱经。 十二经中唯手厥阴心包，手少阳三焦经无所主，其经通于足厥阴少阳，而厥阴主血，诸 药入肝经血分者，并入心包，少阳主气。诸药入胆经气分者并入三焦，命门相火，散行于胆 三焦心包，故入命门者并入三焦，此诸药入诸经之分布也。药有相需者，同类而不可离者。 相使者，我之佐使也。相恶者，夺我之能也。相畏者，受彼之制也，相反者。两不相合也。 相杀者，制彼之毒也，此异同之义也。', '2024-09-28T15:03:02.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'mJqoZNa7qmm');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jYrSkmEk44o', 4, '{"title":"第902000305条・第二章 药性总义 $a{参考本草备要（清·汪讱庵）}","description":"<p>5、药之相从──凡药清虚者浮而升，重实者沉而降，味薄者升而生如春季，气薄者降而收象秋季。气厚者浮而长象夏天，味厚者沉而藏象冬天，味平者化而成象长夏，气厚味薄者浮而升，味厚气薄者沉而降，气味俱厚者能浮能沉，气味俱薄者可升可降，酸咸无升，辛甘无降，寒无浮，热无沉，此升降浮沉之义也，凡药根在土中者，半身以上则上升，半身以下则下降，药为枝者达四肢，为皮者达皮肤。为心为干者内行脏腑，质轻者上入心肺，重者下入肝肾，中空者发表，内实者攻里，枯燥者入气分，润泽者入血分，此上下内外之相从也。</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000305,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-28T15:03:02.000Z', '2024-09-28T15:03:02.000Z', '2024-09-28T15:03:02.000Z', '5、药之相从──凡药清虚者浮而升，重实者沉而降，味薄者升而生如春季，气薄者降而收象秋季。气厚者浮而长象夏天，味厚者沉而藏象冬天，味平者化而成象长夏，气厚味薄者浮而升，味厚气薄者沉而降，气味俱厚者能浮能沉，气味俱薄者可升可降，酸咸无升，辛甘无降，寒无浮，热无沉，此升降浮沉之义也，凡药根在土中者，半身以上则上升，半身以下则下降，药为枝者达四肢，为皮者达皮肤。为心为干者内行脏腑，质轻者上入心肺，重者下入肝肾，中空者发表，内实者攻里，枯燥者入气分，润泽者入血分，此上下内外之相从也。', '2024-09-28T15:03:02.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'mJqoZNa7qmm');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MLuDFINyET8', 4, '{"title":"第902000304条・第二章 药性总义 $a{参考本草备要（清·汪讱庵）}","description":"<p>4、阴阳之义──寒热温凉是气也，酸苦甘辛咸是味也，气为阳味为阴，其气厚者为阳中之阳，薄者阳中之阴也。味厚者阴中之阴，薄者阴中之阳，气薄主发泄散表，厚则发热与温，味厚则泄降，薄则通窍，利渗湿，辛甘发散为阳，酸苦涌泄为阴，咸味涌泄为阴，淡味渗泄为阳，轻清升浮为阳，重浊沉降为阴，阳气出上窍， 阴味出下窍，清阳发肌理。浊阴走五脏。清阳实四肢，浊阴归六腑。</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000304,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-28T15:03:02.000Z', '2024-09-28T15:03:02.000Z', '2024-09-28T15:03:02.000Z', '4、阴阳之义──寒热温凉是气也，酸苦甘辛咸是味也，气为阳味为阴，其气厚者为阳中之阳，薄者阳中之阴也。味厚者阴中之阴，薄者阴中之阳，气薄主发泄散表，厚则发热与温，味厚则泄降，薄则通窍，利渗湿，辛甘发散为阳，酸苦涌泄为阴，咸味涌泄为阴，淡味渗泄为阳，轻清升浮为阳，重浊沉降为阴，阳气出上窍， 阴味出下窍，清阳发肌理。浊阴走五脏。清阳实四肢，浊阴归六腑。', '2024-09-28T15:03:02.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'mJqoZNa7qmm');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('O1rUb335iZp', 4, '{"title":"第902000303条・第二章 药性总义 $a{参考本草备要（清·汪讱庵）}","description":"<p>3、五味之用──凡药酸者能涩能收，苦者能泻能燥能坚，甘者能补能和能缓，辛者能散能润能横行，咸者能下能软坚，淡者能利窍能渗泄。</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000303,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-28T15:03:02.000Z', '2024-09-28T15:03:02.000Z', '2024-09-28T15:03:02.000Z', '3、五味之用──凡药酸者能涩能收，苦者能泻能燥能坚，甘者能补能和能缓，辛者能散能润能横行，咸者能下能软坚，淡者能利窍能渗泄。', '2024-09-28T15:03:02.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'mJqoZNa7qmm');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rbDuekOE3ZY', 4, '{"title":"第902000302条・第二章 药性总义 $a{参考本草备要（清·汪讱庵）}","description":"<p>2、五色之义──青属木入肝，赤属火入心，黄属土入脾，白属金入肺，黑属水入肾。</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000302,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-28T15:03:02.000Z', '2024-09-28T15:03:02.000Z', '2024-09-28T15:03:02.000Z', '2、五色之义──青属木入肝，赤属火入心，黄属土入脾，白属金入肺，黑属水入肾。', '2024-09-28T15:03:02.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'mJqoZNa7qmm');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hs9D8jyhCvk', 4, '{"title":"第902000401条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>1、丹砂,朱砂</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000401,"note":"\n【本经原文】性味甘，微寒无毒，主治身体五脏百病，可以养精神安魂魄。益气明目，杀精魅邪恶鬼，久服通神明，不老能化为汞，畏磁石恶盐水，其色真珠光色如云母，可折者良。又名朱砂。\n\n【产地】在我国四川湖南等山中。以辰州为最佳，故又号辰砂，属石类。\n\n【主治】丹砂为安神要药。\n\n【别录】通血脉，止烦满，消渴，益精神，悦泽人面。除中恶腹痛，毒气疥廔诸疮。\n\n【甄权】镇心，主抽风传ㄕ痨痵等。\n\n【大明】润心肺，治疮痂息肉，可外涂之。\n\n【灵贻】入心镇怯，定魂除邪。\n\n【用量】一般水飞用以拌合他药，单服时可用二，三分。以至钱许。\n\n【禁忌】丹砂只可生研水飞用。火炼则为水银而有毒。不可用，多服丹砂因其性质重坠，使人神定目呆。坊间名为朱砂，一般使用方式是用来拌合他药或做丸衣用，因为其功用在安神镇静，所以多被加入一些安神药中，海藏曰“如同龙骨牡蛎合用，可以养心气，同当归丹参合用，可以养心血。同枸杞地黄合用可以养神，同厚朴川椒等合用可以养脾，同南星川乌同用可以却风。可以明目安胎，也可以解毒，可以发汗，端视医师如何使用而见其功”。因其色红，内合真汞之水，属火中有水之药性，故其象心之性，而其性属微寒，得治心病所必须之寒性，服之使人心神内敛神守，故能安眠。为补心之要药。即朱砂，由天地自然熔铸而成，阳中含阴，外露火色，内含水阴，具硫磺水银之相合之性，因属火体中含有水气，故丹砂能入心，益阴以安神，养血安神为之最。有阳中之阴药称，与人参南北称王。一般言北方属水，故多气分之药，南方属火，故多血分之药。\n\n【炮制】取朱砂打碎，选去夹石，用磁石吸尽铁削。研成粉未。置砵内，加入适量清水研磨成糊状，然后再加入清水搅拌，使之沉淀。倒出悬浮液。只取下沉粉末，如此反复多次。至手捻之细腻则止，倒出水后，将粉末晒干即得。瓦罐装，置干燥处。","videoMemo":"","fangList":[],"bieMing":"丹砂,朱砂"}}', '2024-09-28T15:05:43.000Z', '2024-09-28T15:05:43.000Z', '2024-09-28T15:05:43.000Z', '1、丹砂,朱砂', '2024-09-28T15:05:43.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('q0AzCdsI40o', 4, '{"title":"第902000404条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>4、石钟乳,虚中</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000404,"note":"\n【本经原文】味甘，主咳逆上气，明目益精，安五脏，通百节利九窍，下乳汁，又名虚中。  神农辛，黄帝甘，扁鹊甘无毒，如乳汁黄白色，空中相通，计然云出武都黄白者善。 \n\n【产地】中国日本俱有出产，生于山中石洞穴中，我国以广西陕西等省多此洞。 \n\n【性味】味甘，性温，无毒。 \n\n【主治】石钟乳为补阳益精要药，主治肺气虚损，咳逆上气，明目利窍，补髓疗弱，消渴引饮。 \n\n【别录】益气补虚损，疗脚弱疼冷，下焦伤竭，强阴。 \n\n【甄权】主泄经，寒嗽，壮元气，益阳事，通声。 \n\n【括要】补五劳七伤。补骨髓，治消渴引饮。 \n\n【灵胎】入肺降逆，利窍下乳。 \n\n【用量】普通水飞用，五分至一钱。 \n\n【禁忌】石药性悍，不宜久服。 其下垂象天，石又属金，故主镇降肺气。 \n\n【炮制】拣去杂质。洗净晒干，置铁锅内煅透，取出放凉，研粉即得。","videoMemo":"","fangList":[],"bieMing":"石钟乳,虚中"}}', '2024-10-26T14:19:44.000Z', '2024-10-26T14:19:44.000Z', '2024-10-26T14:19:44.000Z', '4、石钟乳,虚中', '2024-10-26T14:19:44.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('h6B0Qrdw9ls', 4, '{"title":"第902000403条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>3、玉泉,玉桃</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000403,"note":"\n【本经原文】味甘平，主五脏百病，柔筋强骨，安魂魄，长肌肉益气，久服耐寒暑，不饥渴，不老神仙，人临死服五斤，三年色不变，一名玉桃。 畏款冬恶青竹，白玉桃如白头公。玉为阳精之纯者，食之以御水气。 古传食玉之法来自抱朴子仙药篇云：玉可以乌米酒及地榆酒化之为水，亦可以葱浆消之为液。亦可饵之为丸，亦可以烧以为粉，服之一年以上，入水不沾，入火不灼，刃之不伤百毒不犯也。不可用已经做成玉器之物必伤人也，璞玉乃可用也。  \n\n【产地】玉乃石之美者，产山中，我国西南深山中多有之，以钟山蓝田产者最良，于阗国之白玉最好。  \n\n【性味】甘平，无毒。  \n\n【主治】清热解渴，安神养肌。  \n\n【别录】除胃中热，喘息，烦满，止渴，明耳目。  \n\n【大明】润心肺，助喉声，滋毛发。  \n\n【括要】面身瘢痕，真玉日日磨之则自灭。 \n\n【炮制】取净生玉，置砂罐内，煅至火红透，取出，冷却研粉即得。  ","videoMemo":"","fangList":[],"bieMing":"玉泉,玉桃"}}', '2024-10-26T14:19:44.000Z', '2024-10-26T14:19:44.000Z', '2024-10-26T14:19:44.000Z', '3、玉泉,玉桃', '2024-10-26T14:19:44.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3674DdI36p7', 4, '{"title":"第902000402条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>2、云母,云华,云英,云液,云沙,磷石</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000402,"note":"\n【本经原文】味甘平，主身皮死肌，中风寒热，古时在车船上可以除邪气，安五脏，益子精， 明目，久服轻身延年，又名云华，云英，云液，云沙，磷石。  \n        按：抱朴子迁药篇云──云母有五种，其多五色并具，如见青色多者名云英，宜春服之，见赤色多者名云珠，宜夏服之，多白色者名云液，宜秋服之，多黑色者宜冬服之，如见只有青黄二色者名云沙， \n        宜长夏服之，如见晶莹剔透纯白者，可以四时常服之。  \n\n【产地】产四川及各省山中，种类甚多，有黑云母及白云母等，白者良，属玉类。 \n\n【性味】味甘性平，无毒。 \n\n【主治】云母主补肺下气，补中坚肌，除邪气，安精神。 \n\n【别录】下气坚肌，续绝补中，疗五痨七伤，虚损少气，止痢，久服悦泽不老，耐寒暑。  \n\n【甄权】主下痢肠澼，补肾冷。 \n\n【括要】生产不下，用云母细末，调酒涂于阴门。  \n\n【灵胎】清肺明目。  \n\n【用量】一般内服数分起。  \n\n【禁忌】古称云母治百病，服食无忌，但制炼须慎，不可过量服食。 \n\n【炮制】取净生云母，置铁锅内，煅至火红透，取出，冷却研粉即得。 ","videoMemo":"","fangList":[],"bieMing":"云母,云华,云英,云液,云沙,磷石"}}', '2024-10-26T14:19:44.000Z', '2024-10-26T14:19:44.000Z', '2024-10-26T14:19:44.000Z', '2、云母,云华,云英,云液,云沙,磷石', '2024-10-26T14:19:44.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iHecMuJmwkz', 4, '{"title":"第902000411条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>11、曾青</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000411,"note":"\n【别录】养肝胆，除寒热，杀白虫，疗头风，脑中寒，止烦渴，补不足，盛阴气。味酸性小寒无毒，目痛止泪出，风痹，利关节，通九窍，破症瘕积聚。  \n\n【本经】养肝胆，除寒热，杀白虫，疗头风，脑中寒，止烦渴，补不足，盛阴气。  \n\n【炮制】拣去杂质即可。 ","videoMemo":"","fangList":[],"bieMing":"曾青"}}', '2024-10-26T14:25:04.000Z', '2024-10-26T14:25:04.000Z', '2024-10-26T14:25:04.000Z', '11、曾青', '2024-10-26T14:25:04.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5VlBTZEcs6n', 4, '{"title":"第902000410条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>10、空青</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000410,"note":"\n【本经原文】味甘寒，主青盲，耳聋明目利九窍，通血脉，养精神益肝，久服轻身延年不老，能化铜铁铅锡作金。吴普曰空青神农甘一经酸，久服有神仙玉女来侍，使人志高。  \n\n【产地】产河南山西陕西山中，色青质轻，近罕见。今名丹青。  \n\n【主治】空青为一切眼目要药，主治目赤目痛，青盲耳聋，利九窍通血脉，养神益肝。  \n\n【别录】疗目赤痛，去肤翳止泪出，利水道，下乳汁，通关节，破坚积。  \n\n【甄权】治头风镇肝，瞳仁破者，得再见物。 \n\n【大明】钻孔取浆，点多年青盲，内障翳膜，养精气，其壳摩翳。  \n\n【用量】内服外用，分许至一、二钱，外用点目可以与贝母同用。  \n\n【禁忌】勿过量使用。一日点二次即止。\n\n【炮制】拣去杂质即可。  ","videoMemo":"","fangList":[],"bieMing":"空青"}}', '2024-10-26T14:25:04.000Z', '2024-10-26T14:25:04.000Z', '2024-10-26T14:25:04.000Z', '10、空青', '2024-10-26T14:25:04.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mFNk6KzHGIc', 4, '{"title":"第902000409条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>9、石胆,胆矾</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000409,"note":"\n【本经原文】味酸寒，主明目目痛金创，诸痫痉，女子阴蚀痛，石淋寒热，崩中下血，诸邪毒气，令人有子，炼饵服之不老，久服增寿神仙。能化铁为铜成金银。 神农酸小寒，扁鹊苦无毒，周礼疡医凡疗疡以五毒攻之，石胆丹砂雄黄矾石慈石其中烧之三日三夜，其烟上着以鸡羽扫取之，以注创恶肉破骨则尽出。  \n\n【产地】产山中，为蓝色结晶。  \n\n【性味】味酸辛，性寒，有小毒。 \n\n【主治】胆矾为腐蚀催吐要药，功能蚀恶疮散症积，涌吐风痰，治咽喉口鼻疮毒及目患。  \n【大明】治虫牙，鼻内息肉。  \n\n【苏颂】入吐风痰药最快。  \n\n【用量】入煎剂一钱至二钱，研末服一分许。  \n\n【禁忌】胃弱人不宜多服。  \n\n【吴克潜】胆矾有腐蚀性与收敛性，故能治恶疮，吐顽痰，喉痹欲死，研末醋调灌之，大吐胶痰而愈，治狐臭，胆矾枯矾各一钱，轻粉百药煎各五分，为细末敷之效，著名方剂有铁桶膏（铜绿胆矾五倍子白芷轻粉郁金麝香）治发背将溃时，根脚走散不收者，用以涂疮四周根上效。  \n\n【炮制】拣去杂质即可。  ","videoMemo":"","fangList":[],"bieMing":"石胆,胆矾"}}', '2024-10-26T14:25:05.000Z', '2024-10-26T14:25:05.000Z', '2024-10-26T14:25:05.000Z', '9、石胆,胆矾', '2024-10-26T14:25:05.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Z4ykxxcklgw', 4, '{"title":"第902000408条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>8、滑石</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000408,"note":"\n【本经原文】味甘寒，主身热泄澼，女子乳难癃闭，利小便，荡胃中积聚寒热，益精气，久服轻身耐饥长生。  \n\n【产地】产我国山东及西南诸省山中。色青白或黄白及银灰色。  \n\n【性味】味甘性寒无毒。  \n\n【主治】滑石为去湿热利小便要药，主通六府九窍津液。上开肌理下通膀胱，治淋疾，水肿，黄疸。  \n\n【丹溪】燥湿，分水道，实大肠，化食毒，行积滞，逐凝血，解燥渴，补脾胃，降心火，偏主石淋为要药。  \n\n【容川】为去暑之要药，去暑只宜清气利湿，不可用燥药，如黄连亦然，甘草也可。  \n\n【药征】主治小便不利，旁治渴也。  \n\n【灵胎】荡肠胃热，利大小便。  \n\n【用量】普通一钱至三四钱。  \n\n【禁忌】凡阴精不足内热，以致小便短少赤涩，或不利，及烦渴身热，由于阴虚火热水涸者，均忌，脾胃俱虚者虽不做泄亦忌，因其性滑也。  \n\n【炮制】拣去杂质，洗净，研细粉，即可。","videoMemo":"","fangList":[],"bieMing":"滑石"}}', '2024-10-26T14:25:05.000Z', '2024-10-26T14:25:05.000Z', '2024-10-26T14:25:05.000Z', '8、滑石', '2024-10-26T14:25:05.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oE2K4jv7vjE', 4, '{"title":"第902000407条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>7、朴消 </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000407,"note":"\n【本经原文】味苦寒，主百病，除寒热邪气，逐六府积聚，结固留癖，能化七十二种石，炼饵服之轻身神仙。 吴普曰朴硝，神农歧伯曰无毒。  \n\n【产地】生于盐卤之地，凡煎炼水硝，结出细芒者为芒硝，结出马牙状者为马牙硝，其凝于底成块者，通为朴硝。  \n\n【性味】味咸辛苦，性寒无毒。 \n\n【主治】朴消主软坚化积，逐六腑积聚结固留癖。清热泻下，外用消食化积。  \n\n【甄权】治腹胀，大小便不通，女子月经不通。 \n\n【大明】通泄五脏百病，及症结，天行热疾，头痛消肿毒，排脓润毛发。  \n\n【容川】咸味虽重，尚未至于极，故犹有寒水石之性，能大下其火。凡盐味之咸。内皆有火热之性，而水中之火即是命门之火也。微咸之味者，皆能引火下行。大咸者能助火升发也。芒硝得水中阴凝之性，味咸能软坚，下气分之热，以其得水之阴味，未得水中之阳气，故降而不升，能降气分之热，是治热要药，与大黄入血分治火要药不同。  \n\n【药征】主软坚，治心下痞坚，心下石鞭，小腹急结，结胸燥屎，大便鞭，旁治宿食腹满，小腹肿痞，诸般难解之毒。  \n\n【用量】普通三五分。  \n\n【禁忌】辛香走窜，不宜多用。  \n\n【炮制】拣去杂质即可。  ","videoMemo":"","fangList":[],"bieMing":"朴消 "}}', '2024-10-26T14:25:05.000Z', '2024-10-26T14:25:05.000Z', '2024-10-26T14:25:05.000Z', '7、朴消', '2024-10-26T14:25:05.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('36NgAq6p0O5', 4, '{"title":"第902000406条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>6、芒硝,硝石,消石</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000406,"note":"\n【本经原文】味苦寒，主五脏积热，胃张闭，涤去蓄结饮食，推陈致新除邪气，炼之如膏，久服轻身。 吴普曰消石，农曰苦，扁鹊曰甘，名医曰一名芒消。今之硝石。  \n\n 【产地】产于东印度埃及等热带地方及我国西北。投入火中则爆鸣，立即燃烧而发鲜明之焰。\n\n【性味】味苦性寒，无毒， \n\n【主治】硝石主清积热利小便，治五淋。 \n\n【别录】疗五脏十二经脉中百二十疾，暴伤寒，腹中大热，止烦满消渴利小便，及瘘蚀疮，能化七十二种石。 \n\n【甄权】破积散坚，治腹胀，破血下瘰疬。泻得根出。 \n\n【大明】含咽治喉痹。黑疸，周身皮肤眼目俱现黑色，为疸症之最重者。 \n\n【灵胎】消积解癖。 \n\n【用量】普通五分至一钱。 \n\n【禁忌】忌火。 \n\n【炮制】拣去杂质即可。 ","videoMemo":"","fangList":[],"bieMing":"芒硝,硝石,消石"}}', '2024-10-26T14:25:05.000Z', '2024-10-26T14:25:05.000Z', '2024-10-26T14:25:05.000Z', '6、芒硝,硝石,消石', '2024-10-26T14:25:05.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('S7TXbQk2nqQ', 4, '{"title":"第902000405条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>5、涅石,羽泽</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000405,"note":"\n【本经原文】味酸寒，主寒热，泄利白沃，阴蚀恶创，目痛，坚筋骨齿，炼饵服之轻身不老，增年寿。  吴普曰矾石，一名羽泽，神农歧伯酸，扁鹊咸，雷公酸无毒。歧伯曰久服伤人骨。  \n\n【产地】产我国四川陕甘，我国南省诸山亦多有之，色白净者为明矾。 \n\n【性味】味酸性寒无毒。 \n\n【主治】矾石为收湿解毒止血要药，功能除湿化痰，追延坠浊，主明目坚齿，除风杀虫，蚀恶肉，生好肉，治蛇虫咬伤。 \n\n【别录】除固热在骨髓，去鼻中息肉。 \n\n【大明】除风去热，消痰止渴，暖水脏。治中风失音，和桃仁葱汤浴可出汗。 \n\n【甄权】生含咽津治急喉痹。疗鼻漏鼻血，瘰疬疥癣。 \n\n【宗奭】又名枯矾。贴嵌甲牙缝中治血出如衄。 \n\n【灵胎】敛气固精，杀虫止利。 \n\n【用量】普通内服数分至一钱，外用无定量。 \n\n【禁忌】虽可常用无所忌，但不可多服。 \n\n【吴克潜】编药性字典曰矾石用之甚广。今南方人多用置水缸中以解毒，其水澈底澄清。陈师古曰矾石之用有四，吐利风热痰延，取其酸苦涌泄也。治诸血痛，脱肛阴挺疮疡，取其酸涩而收也。治痰饮泄痢，崩带风眼，取其收而燥湿也。治喉痹中蛊蛇虫伤蛰，取其解毒也，矾石经火炙后为枯矾，研细用做敷扑良，渗小儿脐眼，防腐收湿，矾石治一切疮痈恶毒，或 为蛇虫所伤，配黄蜡二倍，溶化研细，外用亦可内服。其它配合方剂很多，举凡矾石色暗者不入药，以白而明最佳，故色白者曰白矾：色光明者曰明矾。 \n\n【倪注】枯矾可与麝香合用，因为麝香无孔不入，配合之则可去脑鼻之间的风寒与瘀伤。 \n\n【炮制】取净生白矾，研粉即得。 枯矾：  \n\n【炮制】取净生白矾，置炽锅内，煅至全部泡松呈白色蜂巢状，取出放凉研粉即得。二矾极酸，变为涩味，酸则收而引津，涩则止而不流。 胆矾：生铜中，有酸木之味，正得铜中金收之性，金性缓，能平木气。  ","videoMemo":"","fangList":[],"bieMing":"涅石,羽泽"}}', '2024-10-26T14:25:05.000Z', '2024-10-26T14:25:05.000Z', '2024-10-26T14:25:05.000Z', '5、涅石,羽泽', '2024-10-26T14:25:05.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mLJySNONKKA', 4, '{"title":"第902000416条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>16、赤石脂,黄石脂,白石脂,黑石脂,青石脂</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000416,"note":"\n【本经原文】味甘平，主黄疸泄利肠癖脓血，阴蚀下血，赤白邪气痈肿疽痔，恶疮头疡疥掻，久服补骨髓益气肥健不饥，轻身延年，五石脂各随五色补五脏。   计然曰赤石脂出河东赤色者善，列仙传曰赤须子好食石脂。 \n\n【产地】生南山之阳山谷中。产山西山东河南，他省亦多。 \n\n【性味】性味酸辛，性大温无毒。 \n\n【主治】为固肠收敛要药，主治赤白久痢，赤白带下，厚肠胃，除水湿，收脱肛。 \n\n【甄权】补五脏虚气。 \n\n【括要】固肠胃，有收敛之能，下胞衣，无推荡之峻。 \n\n【灵胎】功能治温，分补五脏。 \n\n【用量】普通二钱至三四钱。 \n\n【禁忌】凡火热暴注者不宜用，滞下全是湿热，于法当利，自非的受寒邪，下利白积者不宜用，崩中法当补阴清热，带下本属湿热积滞，法当去湿除积，止涩非宜。 \n\n【容川】赤石脂粘涩又味甘，能填补止泻利，土之质也，能燥湿。 \n\n【倪注】此药常与禹余粮合用，因同属涩剂，多用于温中止血痢不止。 \n\n【药征】主治水毒下利，故兼治便脓血。 \n\n【炮制】拣去杂质，刷去灰尘，捣碎，置铁锅内，煅透，趁热倒入醋渍淬，取出，晒干，研粉即得。用醋淬可以增强收敛之功。  \n","videoMemo":"","fangList":[],"bieMing":"赤石脂,黄石脂,白石脂,黑石脂,青石脂"}}', '2025-01-13T09:33:59.000Z', '2025-01-13T09:33:59.000Z', '2025-01-13T09:33:59.000Z', '16、赤石脂,黄石脂,白石脂,黑石脂,青石脂', '2025-01-13T09:33:59.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vQaIJYiRg6k', 4, '{"title":"第902000415条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>15、紫石英</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000415,"note":"\n【本经原文】味甘温，主心腹咳逆邪气，补不足，女子风寒在子宫绝孕，十年无子，久服轻身延年。 \n\n【产地】产深山中。 \n\n【性味】味甘辛，性温无毒。 \n\n【主治】主镇怯润枯，养心益肝，治女子风寒在子宫不孕。 \n\n【别录】疗上气心腹痛，寒热邪气结心，补心气不足，定惊悸安魂魄，填下焦，止消渴，除胃中久寒，散痈肿，令人悦泽。 \n\n【甄权】养肺气，治惊痫，蚀脓。 \n\n【灵胎】补血降气。 \n\n【用量】普通煎用二至三钱，火炙过后用量宜少。 \n\n【禁忌】凡绝孕由阴虚火旺，不能摄受精气者忌用。 \n\n【炮制】拣去杂质，刷去灰尘，捣碎，置铁锅内，煅透，趁热倒入醋渍淬，取出，晒干，研粉即得。","videoMemo":"","fangList":[],"bieMing":"紫石英"}}', '2025-01-13T09:33:59.000Z', '2025-01-13T09:33:59.000Z', '2025-01-13T09:33:59.000Z', '15、紫石英', '2025-01-13T09:33:59.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qa9TMxAPhFw', 4, '{"title":"第902000414条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>14、白石英</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000414,"note":"\n【本经原文】味甘微温，主消渴，阴萎不足咳逆，膈间久寒益气除风湿痹，久服轻身延年。形如紫石英，选白泽长者二三寸。  \n\n【产地】产深山中。  \n\n【性味】味甘微温无毒。  \n\n【主治】肺大肠枯燥，疗肺痿肺痈消渴。  \n\n【甄权】治肺痈吐脓，咳逆上气，黄疸。  \n\n【用量】普通煎用二至三钱，火炙过用。 \n\n【禁忌】不可久服，寇氏曰紫白二石英攻疾可暂煮汁，未闻久服之益，仲景只为咀嚼不为细 末，岂无意焉。  \n\n【炮制】拣去杂质，刷去灰尘，捣碎，置铁锅内，煅透，趁热倒入醋渍淬，取出，晒干，研粉即得。  ","videoMemo":"","fangList":[],"bieMing":"白石英"}}', '2025-01-13T09:33:59.000Z', '2025-01-13T09:33:59.000Z', '2025-01-13T09:33:59.000Z', '14、白石英', '2025-01-13T09:33:59.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('k49zQ6RbYfx', 4, '{"title":"第902000413条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>13、太一余粮,太乙余粮</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000413,"note":"\n【本经原文】味甘平，主治咳逆上气，症瘕血闭，漏下除邪气，久服耐寒暑不饥，轻身飞行千里神仙。生泰山上，石如甲，甲中有白，白中有黄如鸡子黄色，又名太乙余粮，与禹余粮同，唯质较佳者。  \n\n【抱朴子金丹篇】灵丹经用丹砂雄黄雌黄石硫磺曾青矾石戎盐太一余粮，亦用六一泥及神室祭蘸合之三十六日成。  ","videoMemo":"","fangList":[],"bieMing":"太一余粮,太乙余粮"}}', '2025-01-13T09:33:59.000Z', '2025-01-13T09:33:59.000Z', '2025-01-13T09:33:59.000Z', '13、太一余粮,太乙余粮', '2025-01-13T09:33:59.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0gkpLN9PrRy', 4, '{"title":"第902000412条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>12、禹余粮</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000412,"note":"\n【本经原文】味甘寒，主咳逆寒热烦满，痢赤白，血闭，症瘕大热，炼饵服之不饥轻身延年。\n\n【产地】生太山山谷 产于山岛或是池泽，乃石中黄粉。  \n\n【性味】味甘寒，无毒。 \n\n【主治】禹余粮为固补下焦要药，主治滑泄下血，血闭血虚，四肢虚而不仁，崩露赤白。  \n\n【别录】疗小腹痛结烦疼。  \n\n【甄权】主崩中。 \n\n【大明】治邪气及骨节疼，四肢不仁，痔露等疾，久服耐寒暑。  \n\n【灵胎】除热燥湿，止利消瘀。  \n\n【用量】入煎剂钱半至三钱，水飞用五分至一钱。  \n\n【禁忌】重可去怯，故为镇纳固补之剂，下焦有实热者忌，虚者良。  \n\n【倪注】此药多使用于下脓血利不止，常与赤石脂同用。 \n\n【炮制】拣去杂质，刷去灰尘，捣碎，置铁锅内，煅透，趁热倒入醋渍淬，取出，晒干，研粉即得。  \n\n【容川】是石谷中之土质，又具涩性，故以填涩胃肠，甘而微咸，甘能补正以止利，咸能入肾以涩精。  ","videoMemo":"","fangList":[],"bieMing":"禹余粮"}}', '2025-01-13T09:33:59.000Z', '2025-01-13T09:33:59.000Z', '2025-01-13T09:33:59.000Z', '12、禹余粮', '2025-01-13T09:33:59.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wTLTKYgtd12', 4, '{"title":"第902000421条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>21、人参  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000421,"note":"\n【本经原文】味甘微寒，主补五脏，安精神，定魂魄，止惊悸，除邪气，明目开心益智，久服轻身延年。采根，竹刀刮，曝干，无令见风。人形皆具者能做儿啼。  \n\n【产地】生上党山谷。我国吉林辽宁产者最良，山西长子县云南姚安县安徽舒城县亦有出产，高丽产出丰。\n\n【性味】味甘微苦性微寒无毒。 \n\n【主治】人参为大补元气要药，功能治一切衰弱痨瘵，通行周身补五脏之气，泻五脏之火，效益多但功缓，红色曰高丽参，性温而力较峻。  \n\n【甄权】主五劳七伤，虚损痿弱，止呕哕，补五脏六腑，保中守神。消胸中痰，治肺痿及痫 疾，冷气上逆，伤寒不下食，凡虚而多梦者可用。  \n\n【元素】治肺胃阳气不足，肺气虚促短气少气，补中缓中。泻心肺脾胃中火邪，止渴生津液。\n\n【容川】人参多用于病后元气伤者、用人参佐他药来调理，病人邪去正脱者，用人参佐他药调理之，现今人参多人工栽植，药力不如野参，我们可用黄耆甘草代人参，方剂中多以党参代人参。  \n\n因生于阴湿之地，禀水阴润泽之气，故味苦甘而有汁液，发为三枒五叶，阳数也，因生于阴而出阳，故于甘苦味中而有一番生阳之气。人身之元气，由肾水之中而上达于肺，此亦生于阴而出阳，与人参同一理，因此人参大能化气，气化而上，出于口鼻，即为津液，所以人参能生津也。人参生于北方、有阴中之阳药称，有化气补津之功。  \n\n【炮制】用湿布包裹，焖润用火烤，再晾干或烘干即可。 \n\n【药征】主治心下痞坚，痞鞭支结，旁治不食呕吐喜唾心痛腹痛烦悸等。  \n\n【灵胎】升提元气，兼补五脏，有崇正去邪之功，然非虚者勿服。\n\n【用量】普通五分至三钱，大剂一两。  \n\n【禁忌】肺家有热诸症及阴虚火动之候与痘疹之初发，身虽热而斑点未形，与伤寒始作，形症未定而邪热炽均忌，反藜芦。  ","videoMemo":"","fangList":[],"bieMing":"人参  "}}', '2025-01-14T02:53:18.000Z', '2025-01-14T02:53:18.000Z', '2025-01-14T02:53:18.000Z', '21、人参', '2025-01-14T02:53:18.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('N9bx7OTTnG2', 4, '{"title":"第902000420条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>20、菊花,鞠华,杭菊</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000420,"note":"\n【本经原文】味苦平，主风，头眩肿痛，目欲脱泪出，皮肤死肌，恶风湿痹，久服利气血，轻身耐老延年，生川野及田野。今之菊花。  \n\n【产地】处处有之，种类很多，黄白二种入药，味苦，家庭玩赏之菊不入药，今杭州出产多，号称杭菊。  \n\n【性味】味苦甘平无毒。  \n\n【甄权】治头目风热，风眩倒地，脑骨疼痛，身上一切游风令消散，利血脉，调四肢。  \n\n【大明】作枕明目，叶亦明目，生熟都可食。  \n\n【元素】养目血，去翳膜。 \n\n【容川】菊叶为治疮之要药，因其性散，能去肌肉中之风邪也。  \n\n【灵胎】平肝熄风。  \n\n【用量】普通一钱至三钱。 \n\n【禁忌】味苦辣者，陈久者，不堪用，其甘者亦名甘菊，可饮可食亦入药。  \n\n【吴克潜】近世用为平肝良药，头痛目疼多因肝经风热上乘所致，菊花入肝，兼行周身，血脉不利而死肌，得菊花之利血脉皆效，特长于解毒，外科方剂用之治疔毒发背者，沈金鳌曰菊花并茎叶打汁饮，外涂内服皆可。时医用之因防邪热过久而酝酿化毒；平淡多奇功。  \n\n【附加菊叶】菊叶解毒之功胜于花，以鲜者良，捣汁敷一切肿毒，亦可内服。\n\n【炮制】拣去杂质及梗叶，拍去灰尘即得。  ","videoMemo":"","fangList":[],"bieMing":"菊花,鞠华,杭菊"}}', '2025-01-14T02:53:18.000Z', '2025-01-14T02:53:18.000Z', '2025-01-14T02:53:18.000Z', '20、菊花,鞠华,杭菊', '2025-01-14T02:53:18.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uCQcyTmr1yQ', 4, '{"title":"第902000419条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>19、菖蒲,石菖蒲,兰荪</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000419,"note":"\n【本经原文】味辛温，主风寒湿痹，咳逆上气，开心孔补五脏，通九窍，明耳目，出声音，主耳聋痈疽，温肠胃，止小便利，久服轻身不忘不迷惑延年，生池泽。  \n\n吕氏春秋云冬至后五旬七日昌始生，昌者百草之先，于是始耕，又名兰荪。即今之菖蒲 也。  \n\n【产地】我国四川，今处处有之，多生水滨，可供盆栽，西洋及日本亦俱产之，根入药，一寸九节者良。  \n\n【性味】味辛性温无毒。  \n\n 【主治】菖蒲为宣窍泄热，健胃行滞要药，主开心孔通九窍，明耳目出声音，治咳嗽上逆，霍乱转筋，健脾胃杀诸虫，疗噤口痢。 \n\n【别录】四肢湿痹不得曲伸，小儿温疟，身积热不解，可作浴汤。  \n\n【甄权】治耳鸣，头风泪下，鬼气，杀虫，恶疮疥掻。  \n\n【大明】除风下气，丈夫水脏女人血海冷败，多忘，除烦闷，止心腹痛，霍乱转筋及耳痛者，作末炒，趁热裹。  \n\n【好古】心积伏梁。  \n\n【时珍】解巴豆大戟毒。  \n\n【灵胎】下逆开窍。 \n\n【用量】普通生用二三钱，干用五分至一钱半。  \n\n【禁忌】忌饴糖羊肉铁器。  \n\n【吴克潜】菖蒲南人多常用置食水中，或加矾少许，解一切毒，周颠仙曰常食菖蒲饮水，永无腹痛之疾，沈金鳌曰治禁口痢，屡用屡效，道藏经曰能治一切风，手足顽痹瘫痪不遂。正传曰九节菖蒲去毛捣末，入黑猪心一个，批开煮服，之癫痫风疾，著名方剂有$x{菖蒲丸}（$u{石菖蒲}、$u{人参}、$u{丹参}、$u{天冬}、$u{麦冬}、$u{赤石脂}）。治小儿心气不足，不能言语。又醋糊丸棉裹置耳中，治耳内卒痛，聋闭不闻，有$x{菖蒲益智丸}（$u{菖蒲}、$u{远志}、$u{人参}、$u{桔梗}、$u{牛膝}、$u{附子}、$u{茯苓}、$u{桂心})。治健忘恍惚，破积聚止痛，安心定神聪明耳目均效。  \n\n【倪注】常用于鼻塞不通，脑部受损。内服外用皆宜。  \n\n【炮制】拣去杂质，刷去灰尘，洗净晒干，去灰尘即得。  ","videoMemo":"","fangList":[],"bieMing":"菖蒲,石菖蒲,兰荪"}}', '2025-01-14T02:53:18.000Z', '2025-01-14T02:53:18.000Z', '2025-01-14T02:53:18.000Z', '19、菖蒲,石菖蒲,兰荪', '2025-01-14T02:53:18.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1F3QtwDH4Sl', 4, '{"title":"第902000418条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>18、扁青</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000418,"note":"\n【本经原文】味甘平，主目痛明目，折跌痈肿，金创不疗，破积聚解毒气，利精神，久服轻身不老。神农雷公小寒无毒，治丈夫内绝令人有子。去寒热风痹，及丈夫茎中百病益精。  \n\n【别录】吐风痰，癫痫，平肝。\n\n 【灵胎】养肝明目。  ","videoMemo":"","fangList":[],"bieMing":"扁青"}}', '2025-01-14T02:53:18.000Z', '2025-01-14T02:53:18.000Z', '2025-01-14T02:53:18.000Z', '18、扁青', '2025-01-14T02:53:18.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KiMeG5FTzU0', 4, '{"title":"第902000417条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>17、白青</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000417,"note":"\n【本经原文】味甘平，主明目利九窍，耳聋心下邪气令人吐，杀诸毒三虫。久服通神明，轻 身延年不老。  ","videoMemo":"","fangList":[],"bieMing":"白青"}}', '2025-01-14T02:53:18.000Z', '2025-01-14T02:53:18.000Z', '2025-01-14T02:53:18.000Z', '17、白青', '2025-01-14T02:53:18.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3vlZtYZfdqV', 4, '{"title":"第902000446条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>46、天麻,赤箭</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000446,"note":"\n【本经原文】味辛温，主杀鬼精物蛊毒恶气，久服益气力长阴肥健轻身增年。今之天麻。  \n\n【产地】产四川及各地山野林中之阴地，苗名赤箭，根即天麻。  \n\n【性味】味辛性平无毒。 \n\n【主治】天麻为祛风镇痉要药，功能治诸风头痛头眩，风湿痹，小儿精痫拘挛。  \n\n【甄权】治冷气麻痹瘫缓不随，语多恍惚，善惊失志。 \n\n【大明】助阳气，补五劳七伤，鬼疥（病），通血脉，开窍。  \n\n【禁忌】风药多燥，风能胜湿故也。凡病人觉津液少，口干舌燥，咽干痛，大便涩，及火炎头晕，血虚头痛，似中风症皆忌。  \n\n 【东垣曰】肝虚不足者，天麻川芎以补之。罗天益曰眼黑头眩，风虚内作，非天麻不能治，因此天麻有养血之功。汪昂云风药中必兼养血药，以制其燥，养血药须兼收风药，宣其滞也。古云治风先治血，血行风自灭。举凡能宣血之滞，故能发痘疹。  ","videoMemo":"","fangList":[],"bieMing":"天麻,赤箭"}}', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '46、天麻,赤箭', '2025-01-14T04:02:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NrdG5v0LQEm', 4, '{"title":"第902000445条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>45、白蒿</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000445,"note":"\n【本经原文】味甘平，主五脏邪气风寒湿痹，补中益气，长毛发令黑，疗心悬少食常饥，久服轻身耳目聪明不老。  \n\n【产地】到处皆有，以水生蒌蒿最好，辛香而美。  ","videoMemo":"","fangList":[],"bieMing":"白蒿"}}', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '45、白蒿', '2025-01-14T04:02:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tmA9u3KhgYV', 4, '{"title":"第902000444条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>44、白英 </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000444,"note":"\n【本经原文】味甘寒，主寒热八疽消渴补中益气，久服轻身延年。 \n\n【产地】生川泽，为野生蔓草，全草可用。 \n\n【性味】根苗叶味甘，性寒。 \n\n【效用】白英为解热药，治风疹，丹毒，黄疸及热疟。有补益之效。\n\n【弘景】叶做羹饮，可疗劳。 \n\n【藏器】烦热，风疹，丹毒，瘴疟寒热，小儿结热，煮汁饮之。","videoMemo":"","fangList":[],"bieMing":"白英 "}}', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '44、白英', '2025-01-14T04:02:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OOQYD52EXdr', 4, '{"title":"第902000443条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>43、巴戟天</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000443,"note":"\n【本经原文】味辛微温主大风邪气，阴痿不起，强筋骨安五脏，补中增智益气。\n\n【产地】产四川者最佳，多山林内，叶经冬不枯，根似联珠，入药。  \n\n【性味】味辛甘，性微温，无毒。 \n\n【主治】巴戟天为补气益精要药，功能祛风除湿，强筋骨，壮元阳，治遗精。  \n\n【别录】疗头面游风，小腹及阴中相引痛，补五劳，益精，利男子。  \n\n【甄权】男子夜梦鬼交泄精，强阴，下气，治风癞。  \n\n【日华】治一切风，疗水胀。  \n\n【用量】普通一钱至三钱。  \n\n【禁忌】凡相火炽，思欲不得，便赤口苦，目昏目痛，烦燥口渴，大便燥结者均忌，恶雷丸丹参，得覆盆子良。此药治肾亏最佳，故遗精滑精者宜，阳痿者良，有虚火者禁忌。  \n\n【容川】色紫而根实，能温肝，足厥阴主风，属阴中之阳，药气温者即阴中之阳，故入肝。  ","videoMemo":"","fangList":[],"bieMing":"巴戟天"}}', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '43、巴戟天', '2025-01-14T04:02:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('X5zQM0e1bC2', 4, '{"title":"第902000442条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>42、石斛</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000442,"note":"\n【本经原文】味甘平主伤中除痹下气，补五脏虚劳羸瘦，强阴，久服厚肠胃轻身延年。  \n\n【产地】产我国四川湖南湖北安徽等地，多自生于山谷湿润之石上，日人用以栽种，出产丰，  \n\n【性味】味甘性平无毒。 \n\n【主治】石斛为除热益阴要药，主养脾胃，益心肾，补虚劳，退虚热，治自汗盗汗，小便余沥，脚痛痹弱。  \n\n 【别录】补内绝不足，平胃气，长肌肤肉，逐皮肤邪热，疿气脚湿，疼冷痹弱，定志除惊。\n\n【甄权】益气除热，男女腰脚软弱，健阳，逐皮肌风痹，骨中久疼，补肾益力。 \n\n【日华】壮筋骨，暖水脏，益智清气。 \n\n【灵胎】养胃生津，补虚除痹。 \n\n【用量】普通一钱至三钱。  \n\n【禁忌】多服能寒胃，至大便溏薄，入姜一二片为辅，则无此弊，清肺补脾也，恶凝水石巴豆，畏雷丸僵蚕。  \n\n【附录】 鲜石斛—石斛茎之鲜者，以铁皮鲜石斛为最良，治胃中大热，津液干竭，凉肺生精，胜于石斛。 钗石斛—石斛之状似金钗者，较之寻常石斛凉性多而黏性少，滋阴降火，于小儿胃热尤宜。川石斛—石斛之产于四川者，其茎紧小，清热之功较着。","videoMemo":"","fangList":[],"bieMing":"石斛"}}', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '42、石斛', '2025-01-14T04:02:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2YxgQ0GBp32', 4, '{"title":"第902000441条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>41、细辛</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000441,"note":"\n【本经原文】味辛温，主咳逆头痛，脑动，百节拘挛，风湿痹痛，死肌，久服明目利九窍， 轻身长年。岐伯曰无毒。色白者善。  \n\n【产地】生华阴山谷。产我国陕西及关外，今北地多有之，为多年生草本，叶下开花，状似杜衡，唯苗叶经冬则凋，根外淡褐而内白色，气味辛烈。  \n\n【性味】味辛性温无毒。  \n\n【主治】细辛为风痛要药，功能深入散风袪寒，主治咳逆上气，风湿，痹痛，头痛，齿痛，泄热破痰，开窍行水。  \n\n【别录】温中下气，破痰，利水道，开胸中滞积，除喉痹，鼻塞不闻香臭，风痫癫疾，下乳 结，汗不出，血不行，安五脏，益肝胆，通精气。  \n\n【甄权】添胆气，治咳嗽，去皮风湿痒。风眼泪下，除齿痛，血闭，妇人血沥腰痛。  \n\n【弘景】含之去口臭。  \n\n【好古】治督脉为病，脊强而厥。  \n\n【吴克潜】曰细辛主治诸痛，但用不可过剂。宗奭曰治头面风不可缺此。元素曰以独活为使治少阴头痛如神。张子和曰治头痛，太阳经则羌活，少阴则细辛，阳明则白芷，厥阴则川芎 吴萸，少阳则柴胡。成无己曰胆气不足，细辛补之。著名方剂有伤寒论之麻黄附子细辛汤，小青龙汤等。  \n\n【容川】细辛形细色黑，故入少阴经，味大辛，能温散少阴之风寒，而少阴为寒水之脏，寒则水气上泛，细辛散少阴之寒，能达水中之阳，故能逐水饮。  \n\n【药征】主治宿饮停水也，故治水气在心下而咳满，或上逆，或胁痛。  \n\n【灵胎】疏风散邪，驱逐寒气。  \n\n【用量】普通三分至一钱。  \n\n【禁忌】升燥发散性烈，凡内热及火升炎上，上盛下虚，气虚有汗，血虚头痛，阴虚咳嗽，均忌。  ","videoMemo":"","fangList":[],"bieMing":"细辛"}}', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '41、细辛', '2025-01-14T04:02:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Z2NiTlFLoMR', 4, '{"title":"第902000440条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>40、龙胆</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000440,"note":"\n【本经原文】味苦涩，主骨间寒热，惊痫邪气，续绝伤，定五脏，杀蛊毒，久服益智不忘，轻身耐老。  \n\n【产地】山野自生之宿根草，其叶经霜雪不凋，根茎黑暗褐色入药。  \n\n【性味】味甘涩，性大寒，无毒。  \n\n【主治】龙胆草为涤邪火除湿热要药，功能健胃清热，治痢杀虫，主治肝火胆火胃火，下焦湿热。  \n\n【别录】除胃中伏热，时气温热，热泄下痢，去肠中小虫，益肝胆气，止惊惕。  \n\n【甄权】治小儿壮热骨蒸，惊痫入心，时疾热黄，痈肿口干。  \n\n【大明】客忤疳气，热狂，明目止渴治疥疮。  \n\n【元素】去目中黄及睛赤肿胀，瘀肉高起，痛不可忍。  \n\n【东垣】退肝经邪热，除下焦湿热之肿，泻膀胱之火。  \n\n【容川】味苦而坚涩，兼水火之性，故能泻肝胆之火。且龙胆草根多而深细，故泻火并兼降利，能清热以利少阳三焦与胆之火。  \n\n【倪注】去中焦肝胆脾胃之湿热。  \n\n【灵胎】泻肝胆火。  \n\n【用量】普通五分至钱半。  \n\n【禁忌】胃虚血少，脾胃两虚作泻，病虚有热均忌。 龙胆草大苦大寒，所治多湿热之病，洁古曰下行之功与防己同，酒浸则能上行外行，柴胡为主龙胆为使，治目疾必用之药。因性大寒故不可久服，恐伤胃气。  \n\n【炮制】拣去杂质，洗凈泥砂，捞出，沥干，稍闷，除去残茎，切 0.5-1  厘米，晒干或烘焙， 去灰即得。  ","videoMemo":"","fangList":[],"bieMing":"龙胆"}}', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '40、龙胆', '2025-01-14T04:02:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('exeSGhoDZHN', 4, '{"title":"第902000439条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>39、远志</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000439,"note":"\n【本经原文】苦温，主咳逆伤中补不足，除邪气，利九窍，益智慧，耳目聪明不忘，强志倍力，久服轻身不老。 \n\n【产地】产陕西河南，为山野自生之常绿草，其根入药。 \n\n【性味】味甘苦性温无毒。 \n\n【主治】远志为强心益智要药，功能治神虚怔忡，痰涎咳逆。 \n\n【别录】利丈夫，定心气，止惊悸益精，去心下隔气，皮肤中热，面目黄。 \n\n【之才】杀天雄附子乌头毒，煎汁饮之。 \n\n【甄权】治健忘，安魂魄，令人不迷，坚壮阳道。 \n\n【好古】肾积奔豚。 \n\n【灵胎】补心通窍，益智除邪。 \n\n【用量】普通八分至二三钱。 \n\n【禁忌】凡心经有实火为心家实热应用黄连生地者，禁与参术等助阳气药物同用，畏珍珠藜芦得茯苓良。  \n\n【容川】其性与桂枝同，但桂枝四达，远志则系根体细瘦，故主入心经，以散心中之滞血。味苦亦入心，兼有辛温之性，故能补心火。  ","videoMemo":"","fangList":[],"bieMing":"远志"}}', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '39、远志', '2025-01-14T04:02:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5rAIvE6z5r2', 4, '{"title":"第902000438条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>38、泽泻</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000438,"note":"\n【本经原文】味甘寒，主风寒湿痹，乳难消水，养五脏，益气力，肥健，久服耳目聪明，不饥延年，轻身，面生光，能行水上。其叶如车前草，味亦相似。 \n\n【产地】生汝南池泽。产我国福建陕西河南山东等地，生于水泽池沼，根作圆球形，色黄，入药。 \n\n【性味】味甘咸，性寒无毒。 \n\n【主治】泽泻为渗湿利尿要药，主风寒湿痹，逐膀胱三焦停水，通淋沥，止遗泄，利小便，消肿胀。 \n\n【别录】补虚损，五脏痞满，起阴气，止泄精，消渴，淋沥，逐膀胱三焦停水。 \n\n【甄权】主肾虚精自出，治五淋，宣通水道。 \n\n【大明】主头眩耳虚鸣，筋骨挛缩，通小肠，止尿血，主难产，补女人血海，令人有子。 \n\n【元素】入肾经，去旧水，养新水，利小便，消肿胀，渗泄止渴。 \n\n【东垣】去肤中留垢，心下水痞。 \n\n【药征】主治小便不利冒眩也，旁治渴。 \n\n【灵胎】消水利肿。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】凡病人无湿无饮而阴虚，及肾气乏绝，阳衰精自流出，肾气不固，精滑目痛，虚寒作泄等候，均忌。\n\n 古方常以配合补剂用，因欲补必兼泻邪，邪去则补药得力，宗奭曰多服昏人眼，以行去其水也，凡服泽泻散，未有尿不多者，尿既多肾气焉得实。海藏曰泻伏水去留垢，故明目，小便利，肾气虚，故昏目，是可知泽泻之能明目，在能渗湿，若已中病而用之过量，则诛伐无过，使肾气虚而昏目，药本在治病救偏，过量则害，百药皆然，岂独泽泻而已。著名方剂有疏凿饮（泽泻商陆赤小豆羌活大腹皮椒目木通秦艽茯苓槟榔生姜）治水气通身浮肿。烦燥喘渴，小便不利。泽泻汤（泽泻五两白术二两）治心下有支饮其人苦冒眩者。五苓散（茯苓 猪苓白术泽泻肉桂）治水分有热，小便不利，烦渴或水饮内停，脐下悸者。 生于根下，则化气上行，引肾阳以达上。 \n\n【炮制】拣去杂质，大小分开，浸泡四小时，热天加少量明矾，冬天不用。捞出，沥干除水，  \n\n用盐水喷洒，晒干，火烤使色现微黄色，取出，冷却即得。  ","videoMemo":"","fangList":[],"bieMing":"泽泻"}}', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '38、泽泻', '2025-01-14T04:02:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xQBDgg43TzC', 4, '{"title":"第902000437条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>37、薏苡仁</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000437,"note":"\n【本经原文】味甘微寒，主筋急拘挛不可屈伸，风湿痹，下气，久服轻身益气，其根下三虫，一名解蠡。 \n\n【产地】产我国直隶陕西及安南等地，他处亦多有种植，仁白，咬之觉粘者良。 \n\n【性味】味甘淡，性微寒，无毒。 \n\n【主治】薏苡仁为除湿行水，健胃补肺要药，主除筋骨邪气，拘痹不仁，利肠胃，消水肿， 祛风湿，治脚气。 \n\n【别录】除筋骨中邪气不仁，利肠胃，消水肿，令人能食。  \n\n 【藏器】炊饭做面食，主不饥，温气，煮饮止消渴，杀蛔虫。 \n\n【甄权】治肺痿，肺气积脓血，咳嗽涕唾上气，煎服破毒肿。 \n\n【孟铣】祛干湿脚气大验。 \n\n【药征】主治浮肿也。 \n\n【灵胎】养胃舒筋，除湿泄热。 \n\n【用量】普通三钱至六钱。 \n\n【禁忌】大便燥结，因寒转筋，及孕妇忌。 汪讱庵曰，泻水所以益土，故健脾益土，所以生金，故补肺清热，扶土所以抑肝木，故 治风热拘挛。\n\n【宗奭曰】本经言薏苡仁主筋急拘挛，但拘挛有两等，素问注中大筋受热，则缩而短，故挛不伸，此是因热而拘挛也，故可以用薏苡仁，若素问言因寒则筋急者，此盖受寒 使人筋急，不可以用薏苡仁，寒热使人筋挛，若但受热不曾受寒，亦使人筋缓，受湿则又引长无力，此药力极缓和，凡用须加倍，即见效。又经疏谓孕妇忌服，不识何故，或未必然也。又日医记载其能治疣，颇功效。 生于茎上，化气下行，故能引肺阳达下。 \n\n【炮制】取去壳之仁，清水洗净晒干，拣去杂质即可。  \n\n【容川】此药生于水中，味极淡，不补又不涩，专于渗利。凡味淡气薄皆能降而渗利，其属阳之阴，不行在上之窍，而行在下之清窍，故能利小便。  \n\n【附录】苡仁根──主下三焦，能堕胎，治黄疸，卒心腹烦满，胸胁痛。  ","videoMemo":"","fangList":[],"bieMing":"薏苡仁"}}', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '37、薏苡仁', '2025-01-14T04:02:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5Yy9orU8Qyr', 4, '{"title":"第902000436条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>36、山药,薯豫,淮山,怀山</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000436,"note":"\n【本经原文】味甘温，主伤中，补虚羸，除寒热邪气，补中，益气力，长肌肉，久服耳目聪  \n\n明，轻身不饥，延年。又名薯豫。又名山药。今名淮山。 \n\n【产地】产河南及浙江等地，他处亦多有之，为山野自生之宿根蔓草，根入药。 \n\n【性味】味甘性温平，无毒。 \n\n【主治】署豫为补虚扶弱要药，主益肺脾，清虚热，治虚羸，长肌肉，补心益肾，疗健忘遗精，生捣敷痈疮，消肿硬。 \n\n【别录】主头面游风，头风眼眩，下气，止腰痛，治虚劳羸瘦，充五脏，除烦热。 \n\n【甄权】补五劳七伤，去冷风，镇心神，安魂魄，补心气不足，开达心孔多记事。 \n\n【大明】强筋骨，主泄精健忘。 \n\n【丹溪】生捣贴肿硬毒能消散。 \n\n【用量】普通钱半至三钱。 \n\n【禁忌】恶甘遂，不宜与面同食。 \n\n【容川】味甘有液，得土之湿气，功能补脾阴即补脾之水以补湿，因其色白，得土中之金气，故有益肺之功，带酸之性故兼入肝肺。  ","videoMemo":"","fangList":[],"bieMing":"山药,薯豫,淮山,怀山"}}', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '36、山药,薯豫,淮山,怀山', '2025-01-14T04:02:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5CrXaBDOctN', 4, '{"title":"第902000435条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>35、木香</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000435,"note":"\n【本经原文】味辛。主邪气，辟毒疫温鬼，强志，主淋露，久服不梦寤魇寐。 \n\n【产地】我国云南贵州两广皆出产，其根外面灰黄，内部灰白，有香气入药。 \n\n【性味】味辛苦，性温无毒。 \n\n【主治】木香为开胃调气要药，功能行三焦之气，宣扬肠胃之滞，主治心腹诸痛呕吐泄泻，消痞积，辟邪气。  \n\n 【别录】消毒，杀鬼、精物、温疟、蛊毒，气劣气不足，肌中偏寒，引药之精。 \n\n【大明】治心腹一切气，膀胱冷痛，呕逆反胃，霍乱泄泻，痢疾，健脾，消食安胎。 \n\n【甄权】九种心痛，积年冷气，痃症块，胀痛，壅气上冲，烦闷羸劣，女人血气刺心，痛不可忍，末酒服之。  \n\n 【元素】散滞气，调诸气，和胃气，泄肺气。 \n\n【丹溪】行肝经气，煨熟实大肠。 \n\n【好古】治冲脉为病，逆气里急，主浮，渗小便秘。 \n\n【灵胎】辟邪逐疫。 \n\n【用量】普通五分至二钱。 \n\n【禁忌】肺虚有热，元气虚脱，及阴虚内热，诸病有热，心痛属火，均忌。 \n\n【吴克潜】曰木香调气定痛，功力甚佳，治中下二焦气结滞而不运，宜槟榔为使，故治痢疾腹痛，有木香槟榔丸之设也。 \n\n【宗奭】曰此专决泄胸腹间滞塞冷气。他则次之，得橘皮蔻仁生姜相佐，效尤速。 \n\n【弘景】曰木香疗毒肿消恶气有验，今唯制蛀虫丸中用之，至于木香配合之成方颇多，著者有木香丸（香附黄柏胡黄连木香），治腹痛食伤，气郁作痛，诸虫痛，盖佐以苦寒之药，则不仅治冷痛也。香连丸（木香黄连）治痢疾为调和之剂，木香丸（木香附子卤砂）治寒疝绕脐作痛，结鞭不消，木香饼（生地木香作饼），热熨贴之，治结肿成核，消乳中结核酸痛等，均有灵效。  \n\n【容川】木香之理气，以其香气归脾，而味兼微辛，气浮味沉，得木气之温，力能疏土，茎是五枝五节，合于脾之数。其气浮味沉，能理上中下三焦。  ","videoMemo":"","fangList":[],"bieMing":"木香"}}', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '35、木香', '2025-01-14T04:02:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IMEooEMqSG5', 4, '{"title":"第902000434条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>34、车前子</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000434,"note":"\n【本经原文】味甘寒，无毒，主气癃，止痛，利水道小便，除湿痹，久服轻身耐老。因喜在牛迹中生，故又名当道也。 \n\n【产地】产泽野及路旁，处处有之，自地下生叶，从叶中抽茎，长数寸，多子。 \n\n【性味】味甘，性寒，无毒。 \n\n【主治】车前子为行水泄热要药，主利小便，通淋沥，清肺肝风热，渗膀胱湿热，强阴益精明目。 \n\n【别录】男子伤中，女子淋沥不欲食，养肺，强阴益精，令人有子，明目疗赤痛。 \n\n【甄权】去风毒，肝中风热，毒风冲眼，赤痛障翳，脑痛泪出，压丹石毒，去心胸烦热。 \n\n【灵胎】专利小便。 \n\n【用量】普通钱半至三钱。 \n\n【禁忌】内伤劳倦，阳气下陷者忌，肾气虚脱者忌与淡渗药同用。 \n\n【吴克潜】曰车前子能利水道而不走真气，与茯苓同功，治暑湿暴下，则泌别清浊，使小便利而泄泻自止，治五淋则渗泄湿热，使从小便下而淋自止，且以通为补，车前尤能强肾益精，如五子衍宗丸等。  \n\n【附录】车前叶──凉血除热，止吐衄，消症瘕，与车前子同功。  ","videoMemo":"","fangList":[],"bieMing":"车前子"}}', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '34、车前子', '2025-01-14T04:02:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vNDi2zWmIio', 4, '{"title":"第902000433条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>33、独活</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000433,"note":"\n【本经原文】味苦平，主风寒所击，金疮止痛，贲豚，痫痓，女子疝瘕，久服轻身耐老。此药有风花不动，无风独摇。  \n\n【产地】产我国四川陕西甘肃，或云产西羌者名羌活，或云即系一种，独活根老而气细，羌活根嫩而气雄。  \n\n【性味】味辛苦，性温，无毒。 \n\n【主治】独活为风痛要药，主治头痛身痛脚痛，机关不利，风湿诸痹。  \n\n【别录】疗诸贼风，百节痛风，无问久新。  \n\n 【甄权】治诸中风湿冷，奔喘气逆，皮肤苦痒，手足挛痛，劳损风毒齿痛。  \n\n【好古】去肾间风邪，搜肝风，泻肝气，治项强，腰脊痛。  \n\n【用量】普通一钱至三钱。  \n\n【禁忌】凡血虚发痉，血虚头痛，及遍身疼痛，骨痛，因而带寒热者，均属内症，均忌，误用必反剧。  \n\n【容川】色黑，故兼入少阴经，以达太阳，能散背脊之风寒，同$u{天麻}与$u{白头翁}皆有风不动，无风而动。但味太辛，气太温，能散风寒，其力胜于天麻，兼能燥湿，但不如天麻之刚柔得中也。  ","videoMemo":"","fangList":[],"bieMing":"独活"}}', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '33、独活', '2025-01-14T04:02:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uuMN8TyaKKf', 4, '{"title":"第902000432条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>32、麦门冬</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000432,"note":"\n【本经原文】味甘平，主心腹结气，伤中伤饱，胃络脉绝羸瘦短气，久服轻身不老，不饥。生川谷及堤阪。 陶弘景云：实如青珠，根似穬麦，故谓麦门冬。 \n\n【产地】生函谷川谷。生山谷肥地，我国陕西及江浙一带，多有之。叶绿，四季不凋，根黄白色，入药。\n\n【性味】味甘性寒，无毒。 \n\n【主治】麦冬为润肺清火要药，主治肺中伏火，痰多，心腹结气，肺弱胃弱，津少口渴，止咳嗽，疗肺病吐脓血。 \n\n【别录】疗身重目黄，心下支满，虚劳客热，口干燥渴，止呕吐，愈痿躄，强阴益精，消谷 调中，保神定肺气，定五脏，令人肥健，美颜色，有子。 \n\n【藏器】去心热，止烦热寒热体劳，下痰饮，合车前地黄丸服去湿痹。 \n\n【甄权】治热毒大小，面目肢节浮肿，下水主泄积。 \n\n【元素】治肺中伏火，补心气不足，主血妄行，及经水枯，乳汁不下。 \n\n【灵胎】补土生金，寒咳勿用。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】麦冬性寒，虽主脾胃而虚寒泄泻及痘疮虚寒作泻，产后虚寒作泻均忌，入补药，酒浸良。秉水阴，能滋肺以清气分。 \n\n【炮制】拣去杂质，洗净晒干即得。  ","videoMemo":"","fangList":[],"bieMing":"麦门冬"}}', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '32、麦门冬', '2025-01-14T04:02:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dQzmQUTj5Dk', 4, '{"title":"第902000431条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>31、柴胡,茈胡</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000431,"note":"\n【本经原文】味苦平，主心腹，去肠胃中结气，饮食积聚，寒热邪气，推陈致新，久服轻身明目益精。现名柴胡。  \n\n【产地】生弘农川谷。出关东陕西各地，今各处亦有产，分南北两种，性味相同，产银州者曰银柴胡，性味稍异。  \n\n【性味】味苦性平无毒。  \n\n【主治】柴胡为发表清热要药，功能散三焦肝胆诸经之热邪，主治寒热疟疾，口苦耳聋，头痛眩晕。  \n\n【别录】除伤寒心下烦热，诸痰热结实，胸中邪气，五脏间游气，大肠停积水胀，及湿痹拘急，亦可做浴汤。  \n\n【甄权】治热劳骨蒸烦疼，热气，肩背疼痛，劳乏羸瘦，下气消食，宣畅气血，主时疾内外 热不解，单煮服食良。  \n\n【备要】伤寒邪热，痰热结实，虚劳肌热，十二经疮疽血凝气聚，功同连翘。  \n\n【容川】柴胡一茎直上，花清香，故能升散郁结。专治胸前逆满，太阳经气陷于胸中，不得外达，以致胸满，唯柴胡能透达，其色青，生于春而采于夏，得木火之气，从中土以达木火之气，使不侮肺也，故功能透胸前之结，仲景用柴胡以治少阳，少阳为水中之阳，发于三焦，以行腠理，寄居胆中，以化水谷，故必三焦之膜网通畅，肝胆之木火清和，则水中之阳乃由内达外，柴胡茎中虚松，有白丝通气，象人之三焦膜网，少阳木火，郁于腠理，而不达者，则作寒热，柴胡能达之，阳气得发散，且味清苦，良柴胡须用一茎直上，茎色青，叶生四面，细如竹叶，开小黄花者，乃为真柴胡，此为仲景所用。四川梓潼产柴胡最佳，价极廉。今多不知用，因药典有软柴胡，银柴胡，红柴胡等，皆以假乱真，柴胡入肝经。附银柴胡：柴胡之产于陕西银州者，色黄白而大，味甘性微寒，凡热在骨髓者，非此不除，为清热凉血之品，优于发散而推陈致新，治虚劳者酌用之。  \n\n【药征】主治胸胁苦满也，旁治往来寒热也，腹中痛，胁下痞鞭。\n\n【灵胎】其性轻扬，能逐半表半里之邪。  \n\n【用量】普通八分至一钱，大剂三四钱。 \n\n【禁忌】凡虚人气升呕吐，及阴虚火热炎上，法同所忌。 汪昂曰凡胁痛，多属肝旺，宜小柴胡汤。加青皮川芎白芍，左胁痛宜治活血行气，右胁痛宜 消食行痰，因胁痛须开郁，故加柴胡则皆宜也。  ","videoMemo":"","fangList":[],"bieMing":"柴胡,茈胡"}}', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '31、柴胡,茈胡', '2025-01-14T04:02:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XdKenp1eqkk', 4, '{"title":"第902000430条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>30、防葵 ,梨盖</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000430,"note":"\n【本经原文】味辛寒，主疝瘕，肠泄，膀胱热结，溺不下，咳逆，温疟，癫痫，惊邪狂走，久服坚骨髓，益气轻身。又名梨盖。  \n\n【性味】防葵味辛苦，性寒。 \n\n【效用】根为解热利尿，镇静药，治膀胱宿水，膀胱热结，癃闭，癫狂痫症。  \n\n【甄权】主痃癖气块，膀胱宿水，血气瘤大如盆者，悉能消散。  ","videoMemo":"","fangList":[],"bieMing":"防葵 ,梨盖"}}', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '30、防葵 ,梨盖', '2025-01-14T04:02:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3sKevYpLU0r', 4, '{"title":"第902000429条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>29、玉竹,女萎</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000429,"note":"\n【本经原文】味甘平，主中风暴热不能动摇，跌筋结肉，诸不足，久服去面黑皯，好颜色，润泽，轻身不老。又名萎蕤。现名玉竹。 郭璞云药草也，叶似竹，大者如箭竿有节叶狭而长，表白里青根大如指长一二尺，可啖。 \n\n【产地】生于山麓阴地之多年生草，各地皆有，以产南部地方者为上，其地下茎粗大有三棱，节作紫黑色。  \n\n【性味】味甘性平无毒。  \n\n【主治】萎蕤为治风热风湿入肌作痛要药，功能祛风清热，除湿止痛，主邪热头痛，及腰痛身痛，补劳伤。  \n\n【别录】心腹中结气，虚热湿毒肿痛，茎中寒，及目痛眦烂泪出。 \n\n【甄权】时疾寒热，内补不足，去虚劳客热，头痛不安加而用之良。  \n\n【弘景】服诸石人不调和者，煮汁饮之。  \n\n【容川】风能胜湿，风伤血则筋燥，玉竹可以润燥。  \n\n【用量】普通二钱至四钱，大剂二三两。  \n\n【禁忌】畏咸卤。  ","videoMemo":"","fangList":[],"bieMing":"玉竹,女萎"}}', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '29、玉竹,女萎', '2025-01-14T04:02:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pEil1J2ZgNC', 4, '{"title":"第902000428条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>28、益母草,充蔚子,益母</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000428,"note":"\n【本经原文】味辛微温，主明目益精，除水气，久服轻身，茎主瘾疹痒，可做浴汤，一名益母。 \n\n【产地】多生于原野及近水处，叶为深裂式，茎做方形，名益母草，即茺蔚子。 \n\n【性味】味辛苦性微寒，无毒。 \n\n【主治】此药为去瘀生新，通调月经，及产后要药，根茎功用相同。 \n\n【别录】疗血逆，大热头痛心烦。 \n\n【吴瑞】舂仁生食补中益气，通血脉，填精髓，止渴，润肝。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】血崩及瞳子散大均忌，唯热血欲贯瞳仁者，可与凉药同用。 \n\n【吴克潜】曰近医多用于行血止血，如胎动下血，经行不止，小便混有鲜血，可熬膏用。 \n\n【附录】益母草性味通茺蔚子，主瘾疹，可做浴汤，捣汁服用主浮肿下水，消恶毒疔肿，乳痈丹游等毒可敷之，又服汁主治胎死腹中及产后血胀闷，滴汁入耳治耳聤。  ","videoMemo":"","fangList":[],"bieMing":"益母草,充蔚子,益母"}}', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '28、益母草,充蔚子,益母', '2025-01-14T04:02:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MG6smmOQ0fw', 4, '{"title":"第902000427条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>27、牛膝</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000427,"note":"\n【本经原文】味苦酸，主寒湿痿痹，四肢拘急，膝痛不可屈伸，逐血气伤热火烂，堕胎，久服轻身耐老。 \n\n【产地】产我国河南一带，四川亦有出产，为山野自生之多年生草本，根入药。 \n\n【性味】味苦酸性平无毒。 \n\n【主治】牛膝为寒湿痹痿，骨节疼痛要药，走血能补，益肝肾强筋骨，痛淋浊，引诸药下行，治膝痛，能堕胎。 【别录】疗伤中少气，男子阴消，老人失溺，补中续绝，益精，利阴气，填骨髓，止白发，除脑中痛，及腰脊痛，妇人月水不调血结。 \n\n【甄权】治阴痿，补肾助十二经脉，逐恶血。 \n\n【大明】治腰膝软怯弱，破症结，排脓止痛，产后心腹痛，并血晕，落死胎。 \n\n【灵胎】舒筋行血，降气堕胎。 \n\n【用量】普通钱半至三钱。 \n\n【禁忌】牛膝误用必伤胎，经闭未久，疑似有妊者忌用，上焦药中勿用，梦遗失精，脾虚下陷，血崩不止亦忌。忌牛肉牛乳。 \n\n【附录】杜牛膝──性专走下，毫无补益，散恶血破症瘕，止痛，治淋药中宜用。 \n\n【容川】牛膝性降，因根深味苦，故能引水火下行。因根坚实，形不空，无升达之孔道，味既苦泻，故下行双足。其节如膝，能利膝胫，以其形似也。  ","videoMemo":"","fangList":[],"bieMing":"牛膝"}}', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '27、牛膝', '2025-01-14T04:02:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Q4eCHta12Se', 4, '{"title":"第902000426条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>26、菟丝子</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000426,"note":"\n【本经原文】味辛平，主续绝伤，补不足，益气力肥健，汁去面皯，久服明目，轻身延年。  \n\n【产地】产朝鲜川泽及田野，我国亦有之，夏生苗，初如细丝，得地种植物而缠绕之，自绝其根，即借他物之养料以生长，子入药。  \n\n【性味】味辛甘，性平无毒。  \n\n【主治】菟丝子为补肾益精要药，主绝续伤，补不足，坚筋骨，强阴分，治茎中寒，精自出，溺有余沥，腰痛膝冷。  \n\n【甄权】治男女虚冷，添精益髓，去腰疼膝冷，消渴热中，久服去面皯，悦颜色。  \n\n【大明】补五劳七伤，治鬼交泄精，尿血，润心肺。  \n\n【灵胎】补益肝脾，接续筋骨。  \n\n【用量】普通一钱至三钱。 \n\n【禁忌】肾家多火，阳强不痿，及大便燥急者，均忌，得酒良。\n\n【倪注】现在已经是属于被管制中药，因为植物保护法。  ","videoMemo":"","fangList":[],"bieMing":"菟丝子"}}', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '26、菟丝子', '2025-01-14T04:02:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RPBsInG1YfU', 4, '{"title":"第902000425条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>25、白术,山精</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000425,"note":"\n【本经原文】味苦，主风寒湿痹，死肌痉疸止汗，除热消食，作煎饵，久服轻身延年，不饥。一名山精，神药经云：必欲长生服山精。  \n\n【产地】生郑山山谷。产河南浙江安徽及各地，为山间多年野生草，根细者如指，大者如拳，外微褐，肉白入药。  \n\n【性味】味甘性温无毒。 \n\n【主治】白术为健脾胃要药，功能利水去湿，和中调气，外科用托疡疮。  \n\n【别录】大风在身面，风眩头痛，眼泪出，消痰水，逐皮间风水结肿，除心下急满，霍乱吐 下不止，利腰脐间血，益津液，暖胃消谷嗜食。  \n\n【甄权】治心腹胀满，腹中冷痛，胃虚下利，多年气痢，除寒热止呕逆。  \n\n【大明】反胃利小便，主五劳七伤，补腰膝长肌肉，治妇人症瘕。  \n\n【好古】理胃益脾，补肝风虚，主舌本强，食即呕，胃脘痛，心下急痛，心下水痞，冲脉为病，气逆里急脐腹痛。  \n\n【容川】内含甘润之油质，可以滋脾之阴，外发辛香之温性，故可以畅达脾之阳，尤以浙产之油质最厚，可补脾之膏油，油不粘水，故能利水，其气香味甘而苦温，能升发，故补脾温土，使脾土之气上达，和肝气以伸脾气，为补脾之正药。  \n\n【药征】主利水也，故能治小便自利，不利，旁治身烦疼，痰饮失精，眩冒下利喜唾。  \n\n【灵胎】白术补脾补气，苍术燥湿发汗。  \n\n【用量】普通半至三钱，大剂二三两。  \n\n【禁忌】凡病属阴虚血少，精不足，内热骨蒸，口干唇燥，咳嗽吐痰，吐血鼻血，齿血，咽塞，便秘，滞下均忌，溃疡用之反生脓作痛，忌与蛤雀桃李菘菜青鱼同食。  ","videoMemo":"","fangList":[],"bieMing":"白术,山精"}}', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '25、白术,山精', '2025-01-14T04:02:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ToSn0hzLkEC', 4, '{"title":"第902000424条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>24、地黄</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000424,"note":"\n【本经原文】味甘寒，主折跌绝筋，伤中逐血痹，填骨髓长肌肉，作汤除寒热积聚，除痹，生者尤良，久服轻身不老，一名地髓。 鲜生地根绞汁晒干曰干生地，大者今称大生地，细者称细生地。 \n\n【产地】生咸阳川泽。产陕西河南者良，生川泽黄土之地。根入药，根须之鲜者即鲜生地。  \n\n【性味】味甘性寒无毒。  \n\n【别录】主男子五劳七伤，女子伤中胞露下血，破恶血溺血，利大小肠，去胃中宿食，饱力断绝，补五脏内伤不足，通血脉益气力，利耳目。 \n\n【大明】助心胆气，强筋骨，长志安魂定魄，治惊悸劳力，心肺损吐血，鼻血，妇人崩中血 晕。  \n\n【元素】凉血生血，补肾水真阴，除皮肤燥，去诸湿热。  \n\n【好古】主心病掌中热痛，脾气痿蹶，嗜卧，足下热而痛。  \n\n【容川】产中州，得土深水厚之性，内含润泽之湿也。原色为黄，制后为黑，故人知地黄之能滋肾阴，不知地黄实滋脾阴，内经云脾为阴中之至阴，地黄以湿归脾，脾阴足，则肝肾自受其灌溉。其不辛温，故能益水液，滋血之源，而不能变化、以成血色。以水配火，不使壮火食气，如此气纳矣。  \n\n【药征】主治血症及水病也。 \n\n【灵胎】熟地补血，生地凉血。 \n\n【用量】普通二钱至四钱，大剂二三两。  \n\n【禁忌】凡病人脾胃弱，大便泄，产后不食或泻，及胸膈多痰，气道不利者均忌，忌铜铁及茶，得清酒麦冬良。  \n\n【吴克潜】曰现市面用药有三种，鲜生地干地黄熟地黄，一物各有其用，鲜生地多用于肺胃实热，口燥烦渴，舌苔光绛色。干地黄多用于滋养阴血，血虚内热之症。熟地黄则用于补阴 生精，扶养亏弱之虚。是故元素曰生地凉血，血热者须用。熟地微温，血衰者须用。  \n\n【王硕】曰男子多阴虚宜熟地，女子多血热宜生地。  ","videoMemo":"","fangList":[],"bieMing":"地黄"}}', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '24、地黄', '2025-01-14T04:02:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qZm2Wve6dS7', 4, '{"title":"第902000423条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>23、甘草</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000423,"note":"\n【本经原文】味甘平，主五脏六腑寒热邪气，坚筋骨长肌肉倍力，金创肿解毒，久服轻身延年，生河西沙山及上郡。 郭璞云：今甘草蔓延生，叶似荷青黄，茎赤黄有节，节有枝。  \n\n【产地】生河西川谷。我国四川陕西出产，江苏福建亦有，日本种植颇多，茎高二三尺。  \n\n【性味】味甘性平无毒。 \n\n【主治】甘草为调合周身气血要药，功能解百毒，补脏腑，泻诸火，在上去痰止咳，在中调和脾胃，在下清热利溲，入和剂则补益，入汗剂则解肌，入凉剂则泻热，入润剂则生津，入峻剂则缓正气，制药之暴性，效益甚多，为诸药之君。  \n\n【别录】温中下气，烦满短气，伤脏咳嗽，止渴。通经脉，利气血，解百药毒，为九土之精，安和七十二种石，一千二百种草。  \n\n【甄权】主腹中冷痛，治惊痫除腹胀满，补益五脏，肾气内伤，令人不痿，主妇人血沥腰痛，凡虚而多热者加用之。  \n\n【大明】安魂定魄，补五劳七伤，一切虚损，惊悸烦闷健忘，通九窍利百脉，益精养气壮筋 骨。  \n\n【好古】吐肺痿之脓血，消五发之疮疽。  \n\n【仲醇】凡解毒必入甘草。  \n\n【吴克潜】曰九土即九州岛岛土气之精华，故能解诸毒如神，古时有炼石为丹服之者多中药石之毒，服甘草而解，故曰安和七十二种石。  \n\n【容川】味甘正入脾。守而不走，补中气，和诸药，根深四五尺，与黄耆同，但黄耆中空，属气分，是得土中之水气，甘草中实，纯得土气之厚，故深长且实，能补脾阴，益胃之阳。炙用是取其益胃，使胃气上升，如炙甘草汤。生用取其气平，如芍药甘草汤。  \n\n【倪注】仲景经方中使用甘草多处，即知道仲师之重视甘草，而现今却被西洋人购去制造成许多药品或是食物，再回销我国，实在是感叹国家之愚昧竟至于斯，我辈当以复兴中医药为职志，将中药制剂卖到国外，既造福人类又可以赚取外汇，岂非一举两得。甘草缓中，故遇排腹积水时忌用，因其能守，故不利于排水。  \n\n【药征】主治急迫，治里急急痛，旁治厥冷烦躁冲逆之症。  \n\n【灵胎】生用泻火，解毒炙用，和中益气。  \n\n【用量】普通生者五分至钱半，炙者三分至一钱，大剂一两左右。 \n\n【禁忌】凡中满人呕家酒家，诸湿肿满及胀满均忌，反$u{大戟}、$u{甘遂}、$u{芫花}、$u{海藻}，恶$u{远志}忌猪肉。  ","videoMemo":"","fangList":[],"bieMing":"甘草"}}', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '23、甘草', '2025-01-14T04:02:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('H0XO7beni5N', 4, '{"title":"第902000422条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>22、天门冬 ,天冬 </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000422,"note":"\n【本经原文】味苦平，主诸暴风湿偏痹，强肾髓，杀三虫去伏尸，久服轻身益气延年。  \n\n【产地】处处有之，近以浙东产者为多，或生于暖地海滨或种植各地，藤蔓大，根似麦门冬而色白。  \n\n【主治】为清虚热润燥痰要药，主肺气咳逆，风湿偏痹益肌肤，保肺气治消渴、疗咳血。\n\n【别录】保定肺气去寒热养肌肤，利小便，冷而能补。  \n\n【甄权】肺气咳逆，喘息促急，肺痿生痈吐脓，除热气通肾，止消渴去热，中风，治湿疥，宜久服煮食之，令人肌体滑泽白净，除身上一切恶气不洁之疾。  \n\n【大明】镇心润五脏，补五劳七伤吐血，治咳嗽消痰，去风热烦闷。  \n\n【好古】主心病嗌干，心痛渴欲饮，痿躄嗜卧，足下热而痛。  \n\n【用量】普通一钱至三钱。  \n\n【禁忌】胃虚无热及泻者均忌，忌鲤鱼。  \n\n【吴克潜】曰天冬麦冬性相近，故一般方剂二药并用。仲醇曰痰之标在脾胃肺，其本在肾，若非肾家有火，炎上薄肺，煎熬津而成黏腻，则痰何自成。天冬味苦气寒，能清热保肺，下通于肾，故为消痰止咳必用要药，观此则天冬治痰乃治本元不足虚火所生之痰，而与外感咳 嗽，痰饮咳嗽，虚寒痰嗽，风火痰喘等均不相同，著名方剂如天门冬散治小儿心胸烦闷，体热咳嗽。三才封髓丹治虚火上炎，梦遗失精，滋阴养血，降心火益肾水。三才丸治气血俱虚，虚劳咳嗽。天王补心丹治心血不足，津液枯涸，健忘怔忡。 秉水阴，能滋肺以清气分。  \n\n【炮制】拣去杂质，洗净晒干即得。  ","videoMemo":"","fangList":[],"bieMing":"天门冬 ,天冬 "}}', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '2025-01-14T04:02:35.000Z', '22、天门冬 ,天冬', '2025-01-14T04:02:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4gY3FnOarPY', 4, '{"title":"第902000453条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>53、芎䓖,川芎</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000453,"note":"\n【本经原文】味辛温，主中风入脑，头痛寒痹，筋挛缓急，金疮，妇人血闭无子。一名川芎。  \n\n【产地】产四川陜西及江南各地，为多年生草本，或自生或栽种，根为块状结节，味辛烈，入药。  \n\n【性味】味辛性温无毒。  \n\n【主治】川芎为顺气行血要药，功能行气开郁，入肝理血，上行头目，下行血海，主治头痛及妇女一切气郁血郁，心腹痛，腰脚软，破宿血，养新血，补肝散风。  \n\n【别录】除脑中冷痛，面上游风去来，目泪多涕唾，忽忽如醉，诸寒冷气，心腹坚痛，中恶 卒急肿痛，胁风痛。  \n\n【甄权】脚膝软弱，半身不遂，胞衣不下。  \n\n【大明】一切风一切气，一切劳损，一切血，补五劳，壮筋骨，调众脉，破症结宿血，养新血，吐血，鼻血，溺血，脑瘫，发背，瘰疬瘿赘痔瘘疮疥，长肉排脓，消瘀痰血。  \n\n【好古】搜肝风，补肝血，润肝燥，益肝虚。  \n\n【容川】川芎之味更辛苦于当归，得木火之性尤烈，苦而兼辛，有生血之功，质不柔润，性专走窜，故专主行心肝之血。苦者火之味也，苦而兼辛，则性温而有生血之功，苦而不辛，则性凉而专主泻血，温者阴中之阳，是风木本气，故入肝经，根又主上升故能至于巅顶，以散风寒，气滞血瘀，寒热身疼，女子经闭不通，当行血中之气。  \n\n【用量】普通三分至钱半。 \n\n【禁忌】其性疏散，不宜久服，反能损肝，畏黄连，伏雌黄。","videoMemo":"","fangList":[],"bieMing":"芎䓖,川芎"}}', '2025-01-14T06:24:10.000Z', '2025-01-14T06:24:10.000Z', '2025-01-14T06:24:10.000Z', '53、芎䓖,川芎', '2025-01-14T06:24:10.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SPDWTilaBGp', 4, '{"title":"第902000452条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>52、蓝实</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000452,"note":"\n【本经原文】味苦寒，主解毒，杀蛊蚑，注鬼，螫毒，久服头不白轻身。又今俗名青黛。\n\n【产地】从属于大青科名蓝草者之蓝叶制出，体轻质细，药用最良，今多见于园艺。 \n\n【性味】味咸性寒无毒。  \n\n【主治】蓝实（青黛）为解散热毒要药，主散五脏郁火，治时疾热狂与大青同功，并敷热疮虫咬，头生黄水疮，治小儿丹毒。  \n\n【甄权】填骨髓，明耳目，利五脏，调六腑，通关节，治经络中结气，使人健少睡，益心力。  \n\n【苏颂】疗肿毒。  \n\n【时珍】主解班蝥，芫青，朱砂，橒鸡，砒石毒。  \n\n【备要】外敷治痈疽蛇犬毒。  \n\n【用量】普通三分至钱半。 \n\n【禁忌】凡血证非血分实热，而由阴虚内热，阳无所附，火气因空上炎，发为唾咯吐血诸证，切不可用青黛等，盖血得寒则凝，则寒热交作，胸膈或痛，愈增其病。  \n\n【附录】 蓝汁—蓝叶之汁，主一切毒，百毒药，天行热狂，游风热毒肿毒，吐衄血，金疮血闷，烦渴，女人产后血晕。 蓝淀—蓝汁中合有石灰者，主解诸毒，敷热疮，小儿秃疮热肿。其止血拔毒杀虫之功，更胜于蓝。  ","videoMemo":"","fangList":[],"bieMing":"蓝实"}}', '2025-01-14T06:24:10.000Z', '2025-01-14T06:24:10.000Z', '2025-01-14T06:24:10.000Z', '52、蓝实', '2025-01-14T06:24:10.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4uAYAmWAFuU', 4, '{"title":"第902000451条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>51、卷柏</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000451,"note":"\n【本经原文】味辛温，主五脏邪气，女子阴中寒热，痛，症瘕，血闭，绝子，久服轻身和颜色。一名万岁。 \n\n【产地】产陜西山东等地，多附生深山石壁，叶细似柏，生于地上者曰地柏，茎高数吋。 \n\n【性味】味辛性平无毒。 \n\n【主治】卷柏生用平，主破血通经，炙用性温，治肠风脱肛。 \n\n【别录】止咳逆，治脱肛，散淋结，头中风眩，痿躄，强阴益精。 \n\n【甄权】通月经，治ㄕ疰（由病死之人传染的病）鬼疰，腹痛百邪，鬼魅啼泣。 \n\n【大明】镇心，除面皯，头风，暖水脏，生用破血，炙用止血。  \n\n 【用量】普通一钱至三钱。 \n\n【禁忌】多用于止血药中，其他方剂罕用。","videoMemo":"","fangList":[],"bieMing":"卷柏"}}', '2025-01-14T06:24:10.000Z', '2025-01-14T06:24:10.000Z', '2025-01-14T06:24:10.000Z', '51、卷柏', '2025-01-14T06:24:10.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OpX2bEfY166', 4, '{"title":"第902000450条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>50、赤芝,黑芝,青芝,白芝,黄芝,紫芝</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000450,"note":"\n      赤芝—味苦平，主胸中结，益心气，补中，增慧智，不忘，久服轻身不老，延年神仙。一名丹芝。生霍山。\n\n     黑芝—味咸平，主癃，利水道，益肾气，通九窍，聪察，久服轻身不老，延年神仙。一名元芝。生恒山。  \n\n     青芝—味酸平，主明目补肝气，安精魂，仁恕，久服轻身不老，延年神仙。一名龙芝。生太白。 \n\n     白芝—味辛平，主咳逆上气，益肺气，通利口鼻，强志意，勇悍，安魂，久服轻身不老，延年神仙。一名玉芝。生华山。\n\n     黄芝—味甘平，主心腹五邪，益脾气，安神，忠信和乐，久服轻身不老，延年神仙。一名金 芝。生嵩山。 \n\n     紫芝—味甘温，主耳聋，利关节，保神，益精气，坚筋骨，好颜色，久服轻身不老，延年神仙。一名木芝。生高夏地上，色紫形如桑。 六芝皆无毒，六月八月采。  ","videoMemo":"","fangList":[],"bieMing":"赤芝,黑芝,青芝,白芝,黄芝,紫芝"}}', '2025-01-14T06:24:10.000Z', '2025-01-14T06:24:10.000Z', '2025-01-14T06:24:10.000Z', '50、赤芝,黑芝,青芝,白芝,黄芝,紫芝', '2025-01-14T06:24:10.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Hv9Y6RY0bH8', 4, '{"title":"第902000448条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>48、析蓂子</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000448,"note":"\n【本经原文】味辛微温，主明目目痛泪出，除痹痛，补五脏益精光，久服轻身不老。 ","videoMemo":"","fangList":[],"bieMing":"析蓂子"}}', '2025-01-14T06:24:10.000Z', '2025-01-14T06:24:10.000Z', '2025-01-14T06:24:10.000Z', '48、析蓂子', '2025-01-14T06:24:10.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('O1OzT6yS633', 4, '{"title":"第902000449条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>49、蓍实</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000449,"note":"\n【本经原文】味苦平主益气充肌，明目聪慧先知，久服不饥不老轻身。  \n\n【灵胎】此因其物之所能，以益人之能也，昔圣人幽赞于神明而生耆，此草中之神物也，服之则补人之心神，自能聪慧前知，食肉者鄙，不益信夫。能益智通灵。  ","videoMemo":"","fangList":[],"bieMing":"蓍实"}}', '2025-01-14T06:24:10.000Z', '2025-01-14T06:24:10.000Z', '2025-01-14T06:24:10.000Z', '49、蓍实', '2025-01-14T06:24:10.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('s7lX1NnY4ir', 4, '{"title":"第902000447条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>47、奄闾子</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000447,"note":"\n【本经原文】味苦微寒，主五脏瘀血，腹中水气，胪张留热，风寒湿痹，身体诸痛，久服轻身延年不老。 \n\n【产地】处处有之，状似蒿艾，其茎可以盖覆奄闾，故名。 \n\n【性味】味苦性微寒，无毒。 \n\n【主治】奄闾主五脏瘀血，风寒湿痹，身体诸痛，明目益气消食。 \n\n【别录】疗心下坚，隔中寒热，周痹，妇人月水不通。 \n\n【甄权】益气，主男子阴痿不起，治心腹胀满。 \n\n【大明】腰脚重痛，膀胱痛，及骨节烦痛，不下食。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】用之治扑打损伤效，罕有用于调理者。  ","videoMemo":"","fangList":[],"bieMing":"奄闾子"}}', '2025-01-14T06:24:10.000Z', '2025-01-14T06:24:10.000Z', '2025-01-14T06:24:10.000Z', '47、奄闾子', '2025-01-14T06:24:10.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3HEicK50Zz2', 4, '{"title":"第902000496条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>96、枸杞</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000496,"note":"\n【本经原文】味苦寒，主五内邪气，热中消渴，周痹，久服坚筋骨，轻身不老。\n\n【产地】处处有之，其子名枸杞，根皮名地骨皮，均入药。  \n\n【性味】味甘苦，性平，无毒。  \n\n【主治】枸杞子为滋肾养肝要药，生精润肺要药，主五内邪热，周痹风湿，坚筋骨，补精气，治虚劳，明目。  \n\n【别录】下胸胁气，客热头痛，补内伤大劳嘘吸，强阴，利大小肠。  \n\n【甄权】补精气，诸不足，易颜色，变白，明目安神。\n\n【孟铣】坚筋骨，耐老，除风去虚劳，补精气。  \n\n【好古】主心病嗌干，心痛，渴而引饮，肾病消中。  \n\n【用量】普通一钱至三钱。  \n\n【禁忌】凡有外邪实热，脾虚有湿及肠滑者忌。","videoMemo":"","fangList":[],"bieMing":"枸杞"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '96、枸杞', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Gx5UrAzIY9K', 4, '{"title":"第902000495条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>95、槐实</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000495,"note":"\n【本经原文】味苦寒，主五内邪气热，止涎唾，补绝伤，五痔，火创，妇人乳瘕，子藏急痛。\n\n【产地】槐树处处有之，其花与实均入药。  \n\n【性味】味苦性平，无毒。  \n\n【主治】槐花为凉血要药，主五痔肠风，解毒杀虫，凉大肠，润肝燥，治吐衄，崩中，痢疾，漏下。  \n\n【大明】主五痔，心痛，眼赤，杀腹脏虫，及皮肤风热，肠风泻血，赤白痢，并炒研服。  \n\n【灵胎】清湿火疗疮痔。  \n\n【用量】普通一钱至三钱。  \n\n【禁忌】病人虚寒作泄及阴虚血热而非实热者均忌。  \n\n【附录】槐角子即槐实，味苦性寒，无毒，主一切热，散一切结，清一切火，治五痔瘘疮（熬膏丸入谷道，日三易），邪热，妇人乳瘕，子脏急痛，补绝伤，疗火疮，阴疮湿痒，大热难产，能明目补脑，除头脑心胸间热，风眩欲倒，心头吐涎如车船上晕者。  ","videoMemo":"","fangList":[],"bieMing":"槐实"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '95、槐实', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kBlP05x0vZF', 4, '{"title":"第902000494条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>94、松脂</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000494,"note":"\n【本经原文】味苦温，主疽恶创，头伤白秃，疥搔风气，安五脏，除热，久服轻身不老延年。  \n\n【产地】产于松树之脂，处处有之。 \n\n【性味】松脂味苦甘，性温。松子味甘，性微温。松花味甘，性温。松节味苦，性温。  \n\n【主治】松脂为袪风寒湿，止痛，生肌，杀虫药；治痈疽恶疮，风痹，死肌，疥癣，蛀齿。松子为祛风，滋润强壮药；治骨节风痹，气虚头眩，肺燥咳嗽，及老人虚闭。松花为驱风，镇静药；治头眩脑肿。松节为驱风，止痛药；治历节风痛，风痹，脚弱。  \n\n【别录】松脂除胃中伏热，咽干消渴，风痹死肌，炼之令白，其赤者主恶痹。  \n\n【甄权】松脂治骨节风，头眩，去死肌，变白，散水气，润五脏。  \n\n【大明】松脂除邪下气，润心肺，治耳聋。  \n\n【弘景】松节酿酒，主脚弱骨节风。  \n\n【灵胎】除湿火敷疮疡。  \n\n【用量】普通一钱至三钱。  \n\n【禁忌】燥热症者忌。  \n\n【附方】 肿毒疮疖——翠玉膏：松脂八两，铜绿二两，麻油二两，雄猪胆汁三个，先溶松脂，乃下油胆，倾入水中扯拔，每用摊贴，不须再换。 历节风痛——松节酒：松节二十斤，酒五斗，浸二十一天，每服一杯，日五六服。（外台） 头旋脑肿——三月取松花连苔如鼠尾者，切一升，以绢袋浸三升酒中，五日后，空心暖饮五杯。（普济）  \n\n肺燥咳嗽——风髓膏：松子仁一两，胡桃仁二两，蜜半两，和研膏，每服二钱。（外台）  ","videoMemo":"","fangList":[],"bieMing":"松脂"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '94、松脂', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('57bx1KmoLvO', 4, '{"title":"第902000493条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>93、菌桂,小桂</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000493,"note":"\n【本经原文】味辛温，主百病，养精神和颜色，为诸药先聘通使。久服轻身不老，面生光华媚好，常如童子。又名肉桂。  \n\n【产地】产安南及我国云南两广等地，木高大，皮入药。  \n\n【性味】味辛甘，性大热，有小毒。  \n\n【主治】肉桂为温补要药，主扶火助阳，温中逐寒，能引火归元，治上热下寒，破沉寒痼冷，疗霍乱转筋，心腹诸痛，疝瘕奔豚。  \n\n【好古】补命门不足，能益火消阴。  \n\n【元素】补下焦不足，治沉寒痼冷之病，去荣卫中风寒，表虚自汗，春夏为禁药，秋冬下部腹痛。非此不能止。  \n\n【汪昂】木得桂而枯，又能抑肝风而扶脾土，脾虚恶食、湿盛泄泻，补劳通经。  \n\n【灵胎】补助阳气，驱逐阴邪。  \n\n【用量】普通三分至一钱。  \n\n【禁忌】忌生葱石脂及火炙，凡阴虚内热。液少口干者慎用，食木实或瓜类中毒，及闭口蜀 椒中毒，俱用肉桂煎汁饮之可解。 肉桂——一般生用冲服之，力更大。 禀地二之火，入血分，但仲景取其化气，非是化血。肉桂导心火下交于水，须有附子来  \n\n【炮制】拣去杂质，刮去粗皮，刷去灰尘即得。肉桂大辛大温，虽得金味，实为木火之性，故主入心肝血分，能助血之化源，桂皮尤能上行。张仲景之复脉汤，用桂枝。取其入心助火，以化血也。  \n\n【容川】肉桂比枝味更厚，气更凝聚。乃木之极致，大辛则大温，能益心火，为以木生火之专药，其实是温肝之品。肝为心之母，虚则补其母也，心肝皆司血分，故肉桂又为温血之要 药，仲景用肾气丸，是接引心肝之火使之下归于肾。  \n\n【倪注】一般桂枝多用于动脉有循环问题，能行阳达表。  \n\n【附录】桂心主补阳活血，治一切风气，补五劳七伤，通九窍利关节，益精明目，暖腰膝，破痃癖症瘕，消瘀血治风痹骨节挛缩，续筋骨，生肌肉。  \n\n【日华】主九种心痛，腹内冷气痛不可忍，咳逆结气雍塞，脚痹不仁，止下利，杀三虫，治  \n鼻中息肉，破血通利月闭，胎衣不下。  \n\n【甄权】主引血化汗化脓，内托痈疽痘疮，治噎膈满腹。  ","videoMemo":"","fangList":[],"bieMing":"菌桂,小桂"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '93、菌桂,小桂', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BCdFGQBHBIi', 4, '{"title":"第902000492条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>92、桂枝,桂,大桂,牡桂</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000492,"note":"\n【本经原文】味辛温，主上气咳逆。结气喉痹吐吸，利关节，补中益气，久服通神轻身不老。一名肉桂，一名桂枝，一名桂心。 桂之供药有两种，一曰菌桂，又称小桂，其皮为肉桂，或称筒桂：一曰牡桂，又称大桂，或单称桂，其皮为官桂，其枝为桂枝。  \n\n【产地】产安南及我国云南两广等地。  \n\n【性味】味辛甘，性温无毒。 \n\n【主治】桂枝为发表解肌要药。主温经通脉，表虚中风，治手足痛风，伤寒头痛，无汗能发，有汗能止，行肺气，散寒邪，调和营卫，横通肢节。  \n\n【别录】心痛胁痛胁风，温经通脉，止烦出汗。  \n\n【甄权】去冷风疼痛。  \n\n【丹溪】横行手臂治痛风。 \n\n【元素】去伤风头痛，开肌理，解表发汗，去皮肤风湿。  \n\n【容川】色赤味辛，入心肝助火，但桂枝实因苓泽之利水，方能入水以化气，可以导心火以下交于水，故多用之以降冲逆之气，加入补血药中，因而能温通血脉，桂枝能散四肢，质较坚实，故桂枝能兼走筋骨。味辛又得土之气，故能散血脉肌肉中之风寒。  \n\n【药征】主治冲逆也，旁治奔豚头痛，发热恶风，汗出身痛。  \n\n【用量】普通三分至钱半。  \n\n【禁忌】凡阴虚火炎，温病大热，喉症血症均忌。  \n\n【倪注】桂枝为古今皆用之要药，治疗甚广，与麻黄柴胡荆芥防风生姜葱白等同用，治风寒束表，与桑枝附子牛膝威灵仙茯苓防己等同用，治关节疼痛。与白芥子厚朴杏仁半夏等同用，治上气咳逆。与白芍同用解肌和中，与葛根同用发汗退热，伤寒论中使用最多的就是桂枝了。  \n\n【炮制】拣去杂质。刮去粗皮，刷去灰尘即得。  ","videoMemo":"","fangList":[],"bieMing":"桂枝,桂,大桂,牡桂"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '92、桂枝,桂,大桂,牡桂', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kzRfRpGmt5N', 4, '{"title":"第902000491条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>91、淮木</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000491,"note":"\n【本经原文】味苦平，主久咳上气，伤中虚羸，女子阴蚀漏下，赤白沃。\n\n【产地】今人已不识此物，至为可惜。  ","videoMemo":"","fangList":[],"bieMing":"淮木"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '91、淮木', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9TtaZtqUT1X', 4, '{"title":"第902000490条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>90、屈草</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000490,"note":"\n【本经原文】味苦，主胸胁下痛邪气腹间寒热，阴痹，久服轻身益气耐老。因方药无人用，今无人识者。 ","videoMemo":"","fangList":[],"bieMing":"屈草"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '90、屈草', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JpgJb65ZP1u', 4, '{"title":"第902000489条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>89、别羁</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000489,"note":"\n【本经原文】味苦微温，主风寒湿痹，身重四肢疼酸。寒邪历节痛。  \n\n【产地】生蓝田，今俗亦绝耳。","videoMemo":"","fangList":[],"bieMing":"别羁"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '89、别羁', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cDuqb5uY83V', 4, '{"title":"第902000488条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>88、姑活,冬葵子</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000488,"note":"\n【本经原文】味甘温，主大风邪气，湿痹寒痛。久服轻身益寿耐老，一名冬葵子。  \n\n【产地】处处有之。 \n\n【性味】冬葵子及叶，根味皆甘，性滑。  \n\n【甄权】冬葵苗煮汁服利小肠，治时行黄病，干叶为末及烧灰服治金疮出血。  \n\n【思邈】此脾之菜也，宜脾，利胃气，滑大肠。\n\n【用量】一钱至三钱，大剂一两。  \n\n【附方】 肉锥怪疾——手足忽长倒生肉刺，痛不可忍，但食冬葵叶即可。 消中尿多——尿崩，日夜尿七八升。冬葵根浓煎。每日平旦服二升。 妊妇下血——葵子水煎服，日三。 妊妇水肿——小便不利，身重，恶寒，起即头眩。冬葵子，茯苓等分为末，饮服方寸匕，日三，小便利即愈。 胎死腹中，葵子为末，酒服方寸匕，口噤不开者，灌之即生  ","videoMemo":"","fangList":[],"bieMing":"姑活,冬葵子"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '88、姑活,冬葵子', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Bpkqboby5kn', 4, '{"title":"第902000487条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>87、胡麻,青蘘</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000487,"note":"\n【本经原文】味甘寒，主五藏邪气，风寒湿痹，益气，补脑髓。坚筋骨。久服耳目聪明，不饥不老增寿，乃巨胜之苗也。今称胡麻，此植物叶名青蘘，种子名胡麻。 \n\n【产地】处处有之，昔从胡来，故曰胡麻，今名脂麻有黑白黄三种，其大者曰巨胜子，入药。\n\n【性味】青蘘性味如上，胡麻味甘性平无毒。 \n\n【主治】胡麻主长肌肉，补虚羸，滋润五脏，利大小肠，其油亦作解毒用。 \n\n【别录】胡麻坚筋骨，明耳目，耐饥渴。疗金疮止痛，及伤寒温疟，大吐后虚热羸困。 \n\n【日华】补中养气，润养五脏，补肺气，止心惊，利太小肠，耐寒暑，逐风湿气，游风头风，治劳气，产后羸困，催生落胞，细研涂发令长，白蜜蒸饵治百病。 \n\n【廷飞】炒食不食，风病人久食，则步履端正，语言不蹇。 \n\n【苏颂】生嚼涂小儿头疮，煎汤浴恶疮，妇女阴疮大效。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】多用为服食，少以入药，如入药，大便溏泄者忌之。 \n\n【附录】麻油主利大肠，产妇胞衣不下。  \n\n 【别录】天行热闷，膈内热结，服一合，取利为度。 \n\n【藏器】下三焦热毒气，通大小肠，治蚘心痛，敷一切恶疮疥癣，杀一切虫，取一合和鸡子二个，芒硝一两，搅服，少时即泻下热毒。 \n\n【孟铣】士良曰外科熬膏多用之，以其能凉血解毒，止毒生肌也，虞鍑曰生用消疮毒，熟用利肠胃。  \n\n **胡麻**：胡麻历史上被称为胡麻，这个名称体现了它的外来属性，“胡”字前缀在中国古代常用以指代西方或外来的事物。\n\n **芝麻**：芝麻古代同样被称作胡麻，但后来为了避讳“胡”字，改名为芝麻。这个名字也与其作为油料作物的特性有关。","videoMemo":"","fangList":[],"bieMing":"胡麻,青蘘"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '87、胡麻,青蘘', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Q2OYNPl7fx6', 4, '{"title":"第902000486条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>86、升麻</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000486,"note":"\n【本经原文】味甘辛，主解百毒，杀百老物殃鬼，辟温疾障邪气毒蛊，入口皆吐出，中恶腹痛，时气毒疠，头痛，寒热，风肿诸毒，喉痛口疮，久服不夭。  \n\n 【产地】产益州山谷中，今四川陕西淮南溪涧阴地皆有之，根紫黑色、体轻，入药。 \n\n【性味】味甘苦，性平无毒。 \n\n【主治】升麻为升阳散毒要药，功能升清气，散浊邪，治斑疹疮毒，时气寒热，阳明胃经风邪。 \n\n【甄权】小儿惊痫，热拥不通，疗痈，豌豆疮，水煎绵沾拭疮上。 \n\n【大明】安魂定魄，鬼附啼泣，疳疮游风肿毒。 \n\n【元素】治阳明头痛，补脾胃，去皮肤风邪，解肌肉间风热，疗肺痿咳唾脓血，能发浮汗。\n\n【好古】牙根浮烂恶臭，太阳鼻衄，为疮家圣药。 \n\n【用量】普通八分至一钱半。 \n\n【禁忌】凡吐衄多痰，阴虚火动，气逆呕吐，惊悸怔忡癫狂等病，均忌。误用多致危。  \n\n 【容川】升麻味甘，能升脾胃之气，其能升之理则因根中有孔道，引水气上达于苗，故性主升，然无四散之性，因为是根之性，升麻根大于苗，故根之得气也厚，故专取其根。  ","videoMemo":"","fangList":[],"bieMing":"升麻"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '86、升麻', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Iwd7Cox9gLT', 4, '{"title":"第902000485条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>85、王不留行</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000485,"note":"\n【本经原文】味苦平，主金创止血，逐痛出剌，除风痹内寒，久服轻身耐老。 \n\n【产地】处处有之，为一年生草本植物，因其性走而不守，虽有王命，不能留行，故名之。\n\n【性味】味苦性平，无毒 \n\n【主治】王不留行为行血要药，走血分通血脉，行月经，下乳汁，催生定痛，治金疮。 \n\n【别录】主金疮，止血逐痛，出刺。除风痹，内塞，止心烦，鼻衄，痈疽恶疮瘘乳，妇人难产。 \n\n【甄权】治风毒，通血脉。 \n\n【元素】下乳汁。  \n\n【日华】游风风疹，妇人经血不匀，发背。\n\n【用量】普通一钱至二钱。  \n\n【禁忌】走而不守，血症慎用，孕妇忌之。 民间方治妇人乳少，因气郁者：王不留行，穿山甲，炒龙骨，瞿麦穗，麦门冬等分为末，每服一钱，热酒调之，后食猪蹄汤。此名涌泉汤。 ","videoMemo":"","fangList":[],"bieMing":"王不留行"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '85、王不留行', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iuK5v28rqmu', 4, '{"title":"第902000484条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>84、云实</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000484,"note":"\n【本经原文】味辛温，主泄利，肠澼，杀虫蛊毒，去邪恶结气，止痛除热，主见鬼精物，多食令人狂走，久服轻身通神明。  \n\n【产地】处处有之。  \n\n【性味】味辛微苦，性温。  \n\n【主治】云实为止泻，截疟，杀虫要药。  \n\n【苏颂】治疟多用。  \n\n【用量】普通一钱至三钱。  \n\n【禁忌】寒利者禁忌。","videoMemo":"","fangList":[],"bieMing":"云实"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '84、云实', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Y3sFgPOvHWL', 4, '{"title":"第902000483条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>83、鹿衔草,薇衔</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000483,"note":"\n【本经原文】味苦平，主风湿痹历节痛，惊痫吐舌，悸气贼风，鼠瘘痈肿。今名鹿衔草。  \n\n【产地】产我国陕西河南，叶似茺蔚。 \n\n【性味】味苦性平无毒。 \n\n【主治】鹿衔草主治风湿痹，逐水。益筋节，疗痿躄，婴儿先天不足。\n\n 【别录】暴症，逐水。疗痿躄。 \n\n【藏器】妇人服之，绝产无子。 \n\n【用量】普通一二钱。 \n\n【禁忌】待孕之妇忌服，绝产。  ","videoMemo":"","fangList":[],"bieMing":"鹿衔草,薇衔"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '83、鹿衔草,薇衔', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PMtOKRrz8SV', 4, '{"title":"第902000482条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>82、石龙刍,龙须草</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000482,"note":"\n【本经原文】味苦微寒，主心腹邪气，小便不利，淋闭，风湿，鬼注，恶毒，久服补虚羸， 轻身，耳目聪明，延年。一名龙须草。  \n\n【产地】生长泽地，产山西河南一带，茎以九节多珠者良。  \n\n【性味】味苦性微寒，无毒。 \n\n【主治】龙须草为泻心经之热，通利小肠膀胱要药，主治小便不通，小便带血；茎中热痛及淋闭。 \n\n【别录】补内虚不足痞满，身无润泽。出汗。除茎中热痛，疗疣虫肿不消食。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】小便不通不因于热者勿用。  ","videoMemo":"","fangList":[],"bieMing":"石龙刍,龙须草"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '82、石龙刍,龙须草', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2bBKRzbI3DG', 4, '{"title":"第902000481条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>81、徐长卿</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000481,"note":"\n【本经原文】味辛温，主鬼物百精蛊毒，疫疾邪恶气，温疟，久服强悍轻身。 \n\n【产地】生山东陕西甘肃，如细辛微粗而长，徐长卿乃人名，尝以此药治邪病，人遂以名之。\n\n【性味】味辛性温无毒。  \n\n 【主治】徐长卿主辟邪恶，近时用者不多，功与鬼督邮相近。 \n\n【别录】鬼疰精物邪恶气，杀百虫蛊毒老魅注易，立走啼哭。悲伤恍惚。  \n\n 【用量】普通八分至钱半。 \n\n【禁忌】治鬼之药多有毒。用之宜慎。  ","videoMemo":"","fangList":[],"bieMing":"徐长卿"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '81、徐长卿', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rCBY5msESc6', 4, '{"title":"第902000480条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>80、白兔藿</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000480,"note":"\n【本经原文】味苦平，主蛇虺蜂藌猘狗蔡肉蛊毒。  ","videoMemo":"","fangList":[],"bieMing":"白兔藿"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '80、白兔藿', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iVDTrrZgkNu', 4, '{"title":"第902000479条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>79、沙参</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000479,"note":"\n【本经原文】味苦微寒，主血积，惊气，除寒热，补中益肺气，久服利人。  \n\n【产地】产北方沙地，故又号北沙参，叶椭圆有锯齿，根粗大，似参而质松，产南方者为南沙参，体虚力逊。  \n\n【性味】味甘苦，性微寒，无毒。  \n\n【主治】沙参为清补肺气要药，功能清肺中之热，祛肺中之痰。补肺中之气，治久咳，退邪 热，安神，南沙参力减。  \n\n【别录】疗胸痹，心腹结热，邪气头痛，皮间邪热，安五脏，久服利人，又云主头肿痛，益气长肌肉。  \n\n【甄权】去皮肌浮风，疝气下坠。治常欲眠。养肝气，宣五脏风气。 \n\n【大明】补虚止惊烦，益心肺：并一切恶疮疥癣及身痒，排脓消肿毒。  \n\n【灵胎】补中益气。  \n\n【元素】肺寒者用人参，肺热者用沙参，故举凡属肺家有虚热。嗽痰咳血，潮热似痨症，用之甚佳，如属风寒初客肺，浊痰未成，此时宜解表为先。  ","videoMemo":"","fangList":[],"bieMing":"沙参"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '79、沙参', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WetxCmnIYhu', 4, '{"title":"第902000478条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>78、杜若,杜衡</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000478,"note":"\n【本经原文】味辛微温，主胸胁下逆气，温中风，入脑户，头肿痛，多涕泪出，久服益精明目，轻身。一名杜衡。  \n\n【产地】山中阴地之多年生草，叶做心脏形，似细辛，惟经冬不凋，与细辛异，根入药。  \n\n【性味】味辛，性温，无毒。 \n\n【主治】杜衡主治发热头痛，能催吐，近世用者不多。  \n\n【甄权】止气奔喘促，消痰饮，破留血，项间瘿瘤之疾。  \n\n【括要】下气杀虫，利小便，发汗通经，将根末吹入鼻中，能做轻嚏。  \n\n【用量】普通五分至一钱。 \n\n【禁忌】使人呕恶，不宜多用。  ","videoMemo":"","fangList":[],"bieMing":"杜若,杜衡"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '78、杜若,杜衡', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IUtq9aZlRzo', 4, '{"title":"第902000477条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>77、茵陈蒿</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000477,"note":"\n【本经原文】味苦平，主风湿寒热，邪气热结黄疸，久服轻身，益气耐老，面白悦。今名茵陈蒿。  \n\n【产地】生于山野或河岸沙石之多年生草，其叶状似青蒿而背白，茎叶枯，则由陈茎再生，故名茵陈。  \n\n【性味】味苦性平微寒，无毒。  \n\n【主治】茵陈蒿为黄疸要药，功能除湿利尿，主治脾胃湿热，天行时热，周身发黄，以此为君。  \n\n【别录】治通身发黄，小便不利，除头热，去伏瘕。  \n\n【藏器】通关节，去滞热，伤寒用之。  \n\n【大明】石茵陈治天行时疾热狂，头痛头旋，风眼疼痛，瘴疟，女人症瘕，并闪损乏绝。  \n\n【药征】主治发黄也。  ","videoMemo":"","fangList":[],"bieMing":"茵陈蒿"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '77、茵陈蒿', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('v5FoWIGUPRT', 4, '{"title":"第902000476条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>76、景天</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000476,"note":"\n【本经原文】味苦平，主大热，火创身热烦邪恶气华，主女人漏下赤白，轻身明目。  \n\n【产地】多自生于高山上，庭中盆景俱可栽种，叶入药。 \n\n【性味】味苦甘，性寒。无毒。 \n\n【主治】景天主治肿疡蜂螫，能吸脓拔毒。消毒止血药，火疮，丹毒，风疹、狂热赤眼，脑 膜炎头痛。 \n\n【括要】治虫毒蜂螫，傅肿伤，吸脓拔毒。 \n\n【甄权】风疹恶疮，小儿丹毒及发热。 \n\n【弘景】疗金疮止血。煎水浴小儿，去烦热惊风。 \n\n【用量】普通一钱，外用无定量。 \n\n【禁忌】为外用药，少内服。  ","videoMemo":"","fangList":[],"bieMing":"景天"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '76、景天', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('54Wt1Ehsi7L', 4, '{"title":"第902000475条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>75、地肤子</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000475,"note":"\n【本经原文】味苦寒，主膀胱热，利小便，补中益精气，久服耳聪目明，轻身耐老。 \n\n【产地】生田野间，处处有之，子落则老茎可以为少帚，故又名落帚。 \n\n【性味】味苦性寒。无毒。 \n\n【主治】地肤子为利小便要药，主膀胱热，通利五淋，强阴益精，治下焦虚而有热良。 \n\n【别录】主皮肤中热气，使人润泽，散恶疮疝瘕，强阴。 \n\n【甄权】治阴卵颓疾；去风热，可做汤沐浴，与阳起石同服，主丈夫阴痿不起，补气益力。\n\n【日华】治客热丹肿。 \n\n【用量】普通一钱至二三钱。 \n\n【禁忌】老人小便短而频数，是膀胱气化不足，小肠火偏弱也，法当补小肠火；如乌药艾叶，不可独用地肤子。  \n\n【附录】地肤子煎——煎水洗目，去热暗雀盲涩痛，煎水服利小便诸淋，解恶疮。","videoMemo":"","fangList":[],"bieMing":"地肤子"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '75、地肤子', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('f7ViV0XBQto', 4, '{"title":"第902000474条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>74、蛇床子</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000474,"note":"\n【本经原文】味苦平，主妇人阴中肿痛，男子阴痿湿痒，除痹气，利关节，癫痫，恶创，久服轻身。  \n\n【产地】产于海滨或下湿地。我国江北及关外皆有之。  \n\n【性味】味辛苦，性温无毒。 \n\n【主治】蛇床子为疏风去湿强阳益阴要药，主治下焦留湿，男子阳痿湿痒，女人阴肿痛痒。恶疮湿癣。外用煎汤浴良。 \n\n【别录】温中下气，令妇人子脏热。男子阴强，久服令人有子。 \n\n【甄权】治男子女人虚湿痹，毒风屌痛。去男子腰痛，浴男子阴，去风冷，大益阳事。 \n\n【大明】暖丈夫阳气，女人阴气，治腰胯酸疼，四肢顽痹，缩小便，去阴汗，湿癣，齿痛，赤白带下。小儿惊痫，扑损瘀血，煎汤浴大风身痒。  \n\n 【灵胎】专治下体湿毒之病。  \n\n【用量】普通一钱至三钱。 \n\n【禁忌】肾家有火，下部有热。及阳易举者，虽有湿，宜酙酌用之。恶丹皮，巴豆，贝母，伏硫磺。  ","videoMemo":"","fangList":[],"bieMing":"蛇床子"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '74、蛇床子', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('25OKUhkSt88', 4, '{"title":"第902000473条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>73、兰草 </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000473,"note":"\n【本经原文】味辛平，主利水道，杀蛊毒，辟不祥，久服益气，轻身不老通神明。  \n\n【性味】味辛性平无毒。 \n\n【主治】兰草为消炎除恶荡涤肠胃要药，功能推陈致新，生津止渴，治消渴，辟秽毒。  \n\n【别录】除胸中痰癖。 \n\n【东垣】其气清香，生津止渴，润肌肉，治消渴、胆痹。 \n\n【元素】辛平能散肺气郁结，芬芳能去胃气郁滞。 \n\n【汪机】兰草走气分，故能利水道除痰癖，杀蛊辟恶而为消渴良药。与泽兰同走血分，能消水肿，除痈毒，除症破瘀，为妇人要药。  \n\n【好古】消痈肿。调月经，煎水解中牛马毒。  \n\n【用量】普通一钱至三钱。  \n\n【禁忌】无。 我国药物同名甚多。因兰草又名省头草。今药房所谓佩兰，其名亦省头草，解释为籣草为较老草，佩兰为较嫩草，同为一株。  ","videoMemo":"","fangList":[],"bieMing":"兰草 "}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '73、兰草', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('13W9nLb2OrO', 4, '{"title":"第902000472条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>72、旋覆花,旋华 </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000472,"note":"\n【本经原文】味甘温，主益气，去面皯黑，色媚好，其根味辛，主腹中寒热邪气，利小便，久服不饥轻身。今名旋覆花。  \n\n【产地】为野生多年蔓草，处处有，花及根供药用。\n\n【性味】旋花之花，根，茎，叶俱甘滑微苦，性温。  \n\n【主治】旋花为固精强壮药并可合金疮，补劳损。  \n\n【别录】续筋骨，合金疮。 太乙金锁丹：功于秘精益髓，龙骨，覆盆子各五两，莲花蕊四两，栀子花三两，芡实米100 粒，共为末，另以金樱子200 枚，去皮臼杵捣烂，水七升煮浓汁一升，加药粉杵为丸梧子大，每空心盐酒服下30 丸，服至百日，极效。  \n\n【用量】普通五分至一二钱。  \n\n【禁忌】无。 \n\n【容川】旋覆花味微咸，花黄色，滴露而生，得金之气多，得水之气少，故润肺而利金降痰。  ","videoMemo":"","fangList":[],"bieMing":"旋覆花,旋华 "}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '72、旋覆花,旋华', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('U0nO3Lv8gc8', 4, '{"title":"第902000471条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>71、五味子</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000471,"note":"\n【本经原文】味酸温，主益气，咳逆上气，劳伤羸酸，补不足，强阴，益男子精。  \n\n【产地】生齐山山谷。产高丽及我国山东陕西一带，江浙间亦有，有南五味北五味黑五味诸种，就中以北五味最良，子赤黑色，含有滋润，入药。 \n\n【性味】味酸（皮甘肉酸核辛苦，都具咸味，五味俱备）性温无毒。 \n\n【主治】五味子为肺虚咳逆上气要药，主敛肺滋肾，祛痰止咳，生津止渴，敛汗退热，治劳伤，补不足。 \n\n【别录】养五脏，除热，生阴中肌。 \n\n【甄权】治中下气，止呕逆，补虚劳，令人体悦泽。 \n\n【大明】明目，暖水脏，壮筋骨，治风，消食，反胃，霍乱转筋，痃癖，奔豚冷气，消水肿，心腹气胀，止渴除烦热，解酒毒。 \n\n【好古】治喘咳逆，壮水镇阳。 \n\n【容川】五味子酸敛肝木，得金收之性，使木气不上逆，则水火二者皆不上冲于肺，其味酸而质润，囊大而中空，有肺中空虚之象，又生于叶间，其性轻浮，故专攻敛肺生津。这是药能敛肝故能敛肺也。性极沉。 \n\n【药征】主治咳而冒者也。 \n\n【灵胎】敛肺补肾。 \n\n【用量】普通五分至一钱。大剂倍用。  \n\n【禁忌】咳初起脉数，有实火，及肝家有动气，肺气有实热痧疹初发，及一切停饮，均忌。五味子本兼滋补及收敛之长，故祛痰止咳治肺气虚而似实者，效倍之。东垣曰酸以收逆气，肺寒气逆宜与干姜同治之，又五味收肺气，乃火热必用之药，故治咳嗽，有痰加半夏，喘加阿胶。丹溪曰五味大能收肺气，宜其有补肾之功，收肺气即是除热，补肾即是暖水脏，故乃火热嗽必用之药，黄昏嗽乃火气浮入肺中，不宜用凉药，宜五味子敛而降之。  ","videoMemo":"","fangList":[],"bieMing":"五味子"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '71、五味子', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VWWyAPpLpO9', 4, '{"title":"第902000470条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>70、飞廉</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000470,"note":"\n【本经原文】味苦平，主骨节热，胫重酸疼，久服令人身轻。 \n\n【产地】陶弘景曰处处有之，极似苦芙，叶多缺刻，叶下茎多有皮起。 \n\n【性味】飞廉根及花味苦，性平。 \n\n【主治】飞廉花根为去风湿止痛活血药，能下乳汁及杀虫。\n\n 【别录】头眩顶重，皮间邪气，如蜂螫针剌，鱼子细起，热疮，痈疽，痔，湿痹，止风邪咳嗽，下乳汁，可煮、可干用。\n\n 【苏敬】主留血，疗疳蚀，杀虫。 \n\n【萧炳】小儿疳痢，为散水服，大效。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】里有寒，又兼下痢者禁用。  ","videoMemo":"","fangList":[],"bieMing":"飞廉"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '70、飞廉', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('11pUGZQF0sf', 4, '{"title":"第902000469条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>69、茜根 </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000469,"note":"\n【本经原文】味苦寒，主寒湿，风痹，黄疸，补中，现名茜草。 \n\n【产地】生山谷中，为多年生蔓草，亦可种植根形如圆柱，色红褐入药。 \n\n【性味】味酸咸，性寒无毒。 \n\n【主治】茜草为凉血通经要药，主吐血下血，月经不通，月经不止，治骨节风痛，折跌损伤，凉无病之血，行已伤之血。 \n\n【别录】止血内崩，下血，膀胱不足，踒跌，蛊毒，久服益精气，可以染绛，又苗根主痹及热中，伤跌折。 \n\n【甄权】治六极伤，心肺吐血，泻血。 \n\n【大明】止鼻洪尿血，产后血运，月经不止，带下，扑损瘀血，泄精，痔瘘疮节，排脓，酒 煎服。 \n\n【用量】普通一钱至二钱。  \n\n【禁忌】病人虽见血证，若加泄泻，饮食不进者忌。 茜草一名血见愁，其理血之效可知，俗方用治女子经水不通。以一两煎酒服之。仲醇曰治疸，此治因蓄血而发黄的疸，不专于湿热者也。 黑发方：茜根一斤，生地三斤，加水熬成膏，每日酒服半匙，一月发尽黑。  \n\n【容川】色赤味苦，根长，故下行之力必重，专能降泄行血。 ","videoMemo":"","fangList":[],"bieMing":"茜根 "}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '69、茜根', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cc5HQBHt6DI', 4, '{"title":"第902000468条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>68、丹参</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000468,"note":"\n【本经原文】味苦微寒，主心腹邪气，肠鸣幽幽如走水，寒热积聚，破症除瘕，止烦满益气。  \n\n【产地】产陕西一带，今各处俱有之，叶对生，作心脏形，根紫赤色，入药。  \n\n【性味】味苦性微寒，无毒。 \n\n【主治】丹参为通经要药，功能活血调经，治心腹邪气，寒热积聚，宿血恶露。  \n\n【别录】养血，去心腹痛疾，结气，腰脊强，脚痹，除风邪留热。  \n\n【大明】养神定志，通利关脉，治冷热劳，骨结疼痛。四肢不遂，头痛赤眼，热温狂闷，破 宿血，生新血，安生胎，落死胎，止崩带，调月经，血邪心烦，恶疮疥癣瘿赘，一切肿毒。  \n\n【纲目】活血通心包络，治疝痛。  \n\n【灵胎】养血消瘀。  \n\n【用量】普通二钱至三四钱，大剂一两。  \n\n【禁忌】孕妇无故忌，畏咸水，反藜芦。 丹参为女子调经良药，故有一味丹参功兼四物之称，产后养血去瘀，能入心养血，故天王补心丹中用此味治劳心过度，神志不宁，烦热健忘，怔忡。又言丹参入心又曰赤参。  ","videoMemo":"","fangList":[],"bieMing":"丹参"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '68、丹参', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BJDJ7KFE3ki', 4, '{"title":"第902000467条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>67、决明子</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000467,"note":"\n【本经原文】味咸平，主青盲目淫，肤赤白膜，眼赤痛泪出，久服益精光。 \n\n【产地】山野自生之草本植物，产陕西山西一带，今处处可移植，与草决明为截然二种。\n\n【性味】味甘苦咸，性平。 \n\n【主治】决明子为泻肝明目要药，能补肝虚泻肝经风热，主头风头痛，治一切眼病。  \n【别录】疗唇口青。  \n\n【甄权】治肝热，风泪赤眼，每旦取一匙洗净，空心吞之，百日后夜见物光。 \n\n【日华】助肝气益精，以水调末涂肿毒，治太阳穴头痛，又贴胸心止鼻洪，作枕头治头风明目。  \n\n【灵胎】明目益精。  \n\n【用量】普通一钱至三钱。  \n\n【禁忌】恶麻仁，疗目疾外，其他用者鲜，惟外治可以疗蛇伤虫刺。  ","videoMemo":"","fangList":[],"bieMing":"决明子"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '67、决明子', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ylX43vQImXc', 4, '{"title":"第902000466条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>66、天名精</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000466,"note":"\n【本经原文】味甘寒，主瘀血，血瘕欲死，下血止血，利小便，久服轻身耐老。 \n\n【产地】产平原川泽，处处有之，纲目属湿草类。 \n\n【性味】味甘苦性平无毒。 \n\n【主治】天名精主治瘀血症瘕，诸毒疔肿，破血生肌杀虫，内外皆可用。 \n\n【别录】除小虫去痹，除胸中结热，止烦渴，逐水，大吐下。 \n\n【唐本】破血生肌，止鼻衄，杀三虫，除诸毒肿疔疮瘘痔金疮内射，身痒瘾疹不止者，皆之立已。 【注】血瘕，留着肠胃之外及少腹间，下有积气，坚牢如石，女子多因经行未尽，饮食过度，血留经络而得之，治法不一。 \n\n【用量】普通一二钱。 \n\n【禁忌】时珍曰有小毒，生汁吐人。  ","videoMemo":"","fangList":[],"bieMing":"天名精"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '66、天名精', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JxrBHcedROP', 4, '{"title":"第902000465条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>65、营实</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000465,"note":"\n【本经原文】味酸温，主痈疽恶创，结肉跌筋，败创热气，阴蚀不瘳，利关节。 \n\n【产地】处处有之，亦名蔷薇，茎多刺，花红色，亦有白色黄色者，子即营实，入药。  \n\n【性味】味酸，性温，无毒。  \n\n【主治】营实主痈疽，下停水。 \n\n【效用】营实为清热解毒要药，治痈疽恶疮，热毒阴蚀，蔷薇根能清热生肌，缩尿。  \n\n【别录】蔷薇根主泄痢腹痛、五脏客热，除邪逆气，疽癞诸恶疮，金疮伤打，生肉复肌。  \n\n【括要】口舌縻烂，蔷薇根煮汁温含，口疮日久，延及胸前生疮，三年以上不愈者，用此效，杨梅疮筋骨毒痛，取根皮煮汁多饮效，下疳用黄花蔷薇叶焙研洗之敷之良。  \n\n【用量】普通一二钱。 \n\n【禁忌】用以配大黄，行水之效甚著，普通方药罕用之。 ","videoMemo":"","fangList":[],"bieMing":"营实"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '65、营实', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aiPnnWqEShx', 4, '{"title":"第902000464条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>64、漏芦</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000464,"note":"\n【本经原文】味苦咸寒，主皮肤热，恶创，疽痔，湿痹，下乳汁，久服轻身益气，耳聪目明，不老延年。  \n\n【产地】生于向阳之地之草木植物，秋后则草枯而变黑，异乎他草，根苗皆入药。 \n\n【性味】味苦咸，性寒，无毒。 \n\n【主治】漏芦为泄热解毒要药，主治恶疮热毒，湿痹，扑损，能排脓止血，通经脉。 \n\n【别录】止遗漏，热气疮痒如麻豆，可作浴汤。 \n\n【大明】通小肠，泄精尿血，肠风，赤眼，小儿壮热，扑损续筋骨，乳痈瘰疠金疮，止血排脓，补血长肉，通经脉。 【括要】下乳汁，消热毒，排脓止血生肌杀虫，能预解时行痘疹毒，取其寒胜热，又入阳明故也，无则以山栀取代之。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】妊娠禁用，疮疡阴证平塌不起发者，真气虚也，法当内塞，漏芦苦寒，非所宜投。  ","videoMemo":"","fangList":[],"bieMing":"漏芦"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '64、漏芦', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('l8pBv60Yi93', 4, '{"title":"第902000463条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>63、续断</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000463,"note":"\n【本经原文】味苦微温，主伤寒，补不足，金疮痈伤，折跌续筋骨，妇人乳难，久服益气力。\n\n【产地】产我国山西陕西四川一带，为原野自生多年生草，其根细长，作赤黄色，入药。 \n\n【性味】味苦，性微温，无毒。 \n\n【主治】续断为补益筋骨要药，主伤中，腰脊痛，折跌续筋骨，疮痈止痛生肌，破瘀生新，补肝肾，安胎气，并治产后诸病。 \n\n【别录】妇人崩中漏血。金疮血内漏，止痛生肌肉，及腕伤恶血腹痛，关节缓急。 \n\n【甄权】去诸温毒，通宣血脉。助气补五劳七伤，破症结瘀血，消肿毒，肠风痔瘘乳痈瘰疬，妇人产后一切病，胎漏，子宫冷，面黄虚肿，缩小便，止泄精尿血。 \n\n【容川】此物多筋，故治绝伤，因其筋象骨节，故主接筋骨；去骨节间之风寒。 \n\n【灵胎】补益劳伤，强续筋骨。 \n\n【用量】普通二钱至三四钱。 \n\n【禁忌】禁与苦寒药治血病，及大辛热药用于胎前，又气味颇劣，颇不宜于胃，恶雷丸。 此药多用于金疮折跌，现多用于妇女胎产良药，因其补益筋骨，破瘀生新。  \n\n【仲醇】欲行血理伤，当与当归牛膝肉桂延胡索同用，欲止血疗崩中补不足，则与白胶阿胶地黄麦冬杜仲人参山茱萸杞子黄耆五味同用，欲安胎则与凉血补血顺气药同用，欲疗金疮，则与金疮药同用。  ","videoMemo":"","fangList":[],"bieMing":"续断"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '63、续断', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nw9PlwSRpp3', 4, '{"title":"第902000462条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>62、香蒲</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000462,"note":"\n【本经原文】味甘平，主五脏心下邪气，口中烂臭，坚齿明目聪耳，久服轻身耐老。\n\n 【产地】香蒲为生于池沼之宿根草，处处有之。 \n\n【性味】味甘，性平。 时医多用蒲黄，鲜少用香蒲。","videoMemo":"","fangList":[],"bieMing":"香蒲"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '62、香蒲', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UezODQ8vFQ2', 4, '{"title":"第902000461条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>61、蒲黄</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000461,"note":"\n【本经原文】味甘平，主心腹膀胱寒热，利小便，止血消瘀血，久服轻身，益气力延年神仙。\n\n【产地】香蒲为生于池沼之宿根草，处处有之，蒲黄乃蒲花之花粉，入药。 \n\n【性味】味甘辛，性平，无毒。 \n\n【主治】蒲黄为凉血活血散结除热要药，生用消瘀通经，疗扑打损伤，炒黑用止血止崩，止带止遗。 \n\n【甄权】治痢血鼻衄，吐血，尿血，泻血，利水道，通经络，止女子崩中。 \n\n【大明】妇人带下，月侯不匀，血气心腹痛，妊妇下血，坠眙，血运，血症，儿枕气痛，颠扑血闷，排脓，疮疖，游风肿毒，下乳汁，止泄精。 \n\n【用量】普通七分至二钱。 \n\n【禁忌】一切劳伤发热，阴虚内热，无瘀血者忌。 蒲黄配合五灵脂，治产后腹痛，产后血晕，不省人事，亦治妇人痛经，单用炒黑，止一切血均效。  \n","videoMemo":"","fangList":[],"bieMing":"蒲黄"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '61、蒲黄', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('k5tRP0ymuOH', 4, '{"title":"第902000460条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>60、防风</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000460,"note":"\n【本经原文】味甘温无毒，主大风头眩痛，恶风，风邪，目盲无所见，风行周身，骨节疼痹烦满，久服轻身。\n\n【产地】产蒙古及山西河南等地，根黄白色，入药。 \n\n【性味】味甘辛，性温，无毒。 \n\n【主治】防风为伤风头痛要药，功能散表发汗，主诸般风，周身痛，搜肝泻肺，散风胜湿。\n\n【别录】烦满胁痛，风头面去来，四肢挛急，字乳，金疮内痉。 \n\n【大明】治三十六般风，男子一切劳劣，补中益神，风赤眼，止冷泪，及瘫痪，通利五脏关脉，五劳七伤，羸损盗汗，心烦体重，能安神定志匀气脉。 \n\n【元素】治上焦风邪，泻肺实，散头目中滞气，经络中留湿，主上部见血。 \n\n【吴克潜】防风善表散，故用以解毒，如砒毒，乌头毒。芫花毒，野菌毒，诸毒药，又防风本制黄耆，黄耆得防风而功最大，治风邪久留不去，表虚自汗不止。 徐之才曰得葱白行周身，得泽泻橐本疗风，得归芍阳起石禹余粮治妇人子脏风，元素曰治风 去湿之仙药也。 \n\n【容川】防风辛而味甘入肌，气香而温，故入脾。散肌肉之风寒。  \n\n【灵胎】专治风邪。  \n\n【用量】普通一钱至三钱。 \n\n【禁忌】似中风，产后血虚发痉，诸病血虚痉急，头痛不因风寒，溏泻不因寒湿，二便秘涩，小儿慢惊，阴虚盗汗，阳虚自汗，均忌。  ","videoMemo":"","fangList":[],"bieMing":"防风"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '60、防风', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5I7YTMW6nmz', 4, '{"title":"第902000459条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>59、肉苁蓉,肉松容</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000459,"note":"\n【本经原文】味甘微温，主五劳七伤，补中，除茎中寒热痛，养五脏，强阴益精气多子，妇人症瘕，久服轻身。一名肉苁蓉。 \n\n【产地】生于各处高山，为一种寄生植物，茎富肉质，叶细如鳞。 \n\n【性味】味甘酸咸，性温无毒。 \n\n【主治】肉苁蓉为益髓壮阳要药，功能治精血不足，阳痿不举，女子绝产阴痛，润枯燥，滑大肠。 \n\n【别录】除膀胱邪气，腰痛止痢。 \n\n【甄权】益髓悦颜色，大补壮阳，治女子血崩。 \n\n【大明】男子绝阳不兴，女人绝阴不产，润五脏，长肌肉，暖腰膝，男子泄精血，遗沥，女子带下阴痛。 \n\n【容川】象人之阴，味咸入肾，温润而强阴，能助肾中之阳，益命门之火也。 \n\n【灵胎】补精益气，养血润肠。 \n\n【用量】普通二钱至四钱。 \n\n【禁忌】凡泄泻，肾中有热，强阳易兴而精不固者均忌，忌犯铁器。 \n\n【泡制】洗净，大小分开，浸泡4 - 8 小时，捞出，润透，切6 毫米纵片，用清水漂4 - 6 小时，捞出，晒干或烘干即得。 \n\n【酒制】取肉苁蓉片，加白酒调匀，置密闭容器内，隔水蒸至酒被吸尽，停火稍闷，取出晒 干即得。一般酒制后，较能温肾助阳。","videoMemo":"","fangList":[],"bieMing":"肉苁蓉,肉松容"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '59、肉苁蓉,肉松容', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GgS3SvUEhbc', 4, '{"title":"第902000458条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>58、黄芪</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000458,"note":"\n【本经原文】味甘微温，主痈疽久败疮，排脓止痛，大风癞疾，五痔鼠瘘，补虚，小儿百病。  \n\n【产地】我国山西陕西均有出产，山西绵上者佳，茎卧地成蔓状，叶为羽状复叶，根肥大，短而理横，味苦者不堪入药。 \n\n【性味】味甘性微温无毒。 \n\n【主治】黄耆为补气要药，功能助肺气，实皮毛，升清气，泻火气，补虚损五劳，痘疮不起，外症治痈疽，托毒止痛。 \n\n【别录】女人子脏冷，逐五脏间恶血，补丈夫虚损五劳羸瘦，止渴，腹痛泄痢，益气，利阴气。 \n\n【甄权】主虚喘，肾衰耳聋，疗寒热，治发背，内补。 \n\n【日华】助气，壮筋骨，长肌肉补血，破症癖瘰疬瘿赘，肠风血崩带下，赤白痢，产前后一切病，月侯不匀。痰嗽，头风，热毒，赤目。 \n\n【元素】治虚劳自汗，补肺气，泻肺火心火，实皮毛，益胃气，去肌热，及诸经之痛。 \n\n【好古】太阴疟疾，阳维为病苦寒热，督脉为病逆气里急。 \n\n【容川】禀北方水中之阳气以生，以北耆最佳，人身之阳气皆从肾与膀胱之气海出发，上循三焦油膜，以达于肺，而为呼吸，分布于皮毛，则为卫气，北耆之体极松，内行水道之孔更大，故知其气盛，黄耆之根长数尺，深入土中，吸收土下之水以上其苗叶，气即水也，故其气盛而能补气，色黄如三焦油膜，故为三焦之良药，能拓里达表，行三焦之水气，又皮色黑，是水火之色也，色黄味甘，乃土之色味也，得味厚故能补，黄耆入土最深，得土之气最厚，故又大补脾，所以黄耆归脾经，又能通利三焦也。与升麻不同，升麻味不厚，故能升不能补。\n\n【药征】主治肌表之水，故能治黄汗盗汗皮水，又旁治身体肿或不仁者。 \n\n【灵胎】内补脾胃，外托疮毒。 \n\n【用量】普通生者钱半至三钱，炙者八分至三钱，大剂一二两。 \n\n【禁忌】黄耆功能实表，有表邪者忌，又能塞补不足，胸膈气闭闷，肠胃有积滞者忌，又能补阳，阳盛阴虚者忌，上焦热甚，下焦虚寒，及病人多怒肝气不和，并痘疮血分热者均忌。\n\n【倪注】一般言黄耆专于补气，凡气虚之症皆可用，又治自汗，补中气之不足，外科及痘科多以之托里透脓，肾亏溺血亦治之。 \n\n【附录】黄耆皮——性味功用同黄耆，善走表逐水湿，治虚浮及脚肿。 \n\n【炮制】拣去杂质，刮去粗皮，洗净捞出，沥干水分，切片晒干，再筛去灰即得。炙黄耆，用蜂蜜与水置锅中炒至干，取出冷却，即是。  ","videoMemo":"","fangList":[],"bieMing":"黄芪"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '58、黄芪', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JwOja84LpU6', 4, '{"title":"第902000457条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>57、蒺藜子,刺疾藜</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000457,"note":"\n【本经原文】味苦温，主恶血，破症结积聚，喉痹乳难，久服长肌肉，明目轻身。又名刺疾藜。  \n\n【产地】到处皆有。  \n\n【性味】味苦性温。  \n\n【别录】主身体风痿，头痛，咳逆伤肺，肺痿，止烦下气，小儿头疮，痈肿阴溃，可做磨粉。  \n\n【大明】主身益精，疗水脏冷，小便多，止遗沥泄精，溺血肿痛。\n\n【毅民】白疾藜治睛球凹陷，及睛生障翳，视物模糊。  \n\n【容川】利湿，此以金行水也。  \n\n【时方】腰脊引痛——捣末为蜜丸，胡豆大，酒服二丸日三。年久失明——阴干捣散，食后水服方寸匕。（外台）  \n","videoMemo":"","fangList":[],"bieMing":"蒺藜子,刺疾藜"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '57、蒺藜子,刺疾藜', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('W1IndvileJ6', 4, '{"title":"第902000456条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>56、络石</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000456,"note":"\n【本经原文】味苦温，主风热死肌痈伤，口干舌焦，痈肿不消，喉舌肿，水浆不下，久服轻身明目，润泽好颜色，不老延年。 又名耐冬，云花，为野生常绿藤本，茎有气根，藉以攀缘于他物上。此药以石上生者为最佳，故又名石龙藤。  \n\n【产地】产山谷阴湿之地，为自生常绿之草，茎入药。  \n\n【性味】味苦性微寒，无毒。 \n\n【主治】络石主利筋骨关节，治风热痈肿，能凉血退热，舒筋活络。 \n\n【别录】大惊入腹除邪气，养肾主腰髋痛，坚筋利关节，久服明目润泽。  ","videoMemo":"","fangList":[],"bieMing":"络石"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '56、络石', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WSPquWJeaiV', 4, '{"title":"第902000455条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>55、黄连</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000455,"note":"\n【本经原文】味苦寒，主热气，目痛，眦伤，泣出，明目，肠澼，腹痛，下利，妇人阴中肿痛，久服令人不忘。  \n\n【产地】生巫阳川谷。产四川者良，雅州者尤可贵，云南及他省亦有之，为山野多年生草本，日本产者劣，然多流入我国。根色黄，故名。  \n\n【性味】味苦性寒无毒。 \n\n【主治】黄连为清火除湿健胃要药，功能治湿滞，解热毒，益肝胆，厚肠胃，主治肠澼下痢，天行热疾，胎毒疳疾，效益甚多。  \n\n【别录】五脏冷热，久下泄澼脓血，止消渴，大惊，调胃厚肠益胆，疗口疮。  \n\n【大明】治五劳七伤益气，止心腹痛，惊悸烦燥，润心肺，长肉止血，天行热疾，止盗汗，并疮疥，猪肚蒸为丸，治小儿疳气，安疣杀虫。  \n\n【好古】心病逆而盛，心积伏梁。  \n\n【容川】黄连之味正苦，入心经以泻火。清火之药，是水交于火也，故能止血，凡药得苦味者，其中必含水性，故能降火，此为水火互根之理。其质枯而不泽，其纯于苦味而无气，故守而不走，为去暑之要药。  \n\n【倪注】按此药专治热与利湿，凡出现热症皆可用，但是须要辨明是属于何种热，例如虚热，则须在去热药中增加补虚的药物，像黄连阿胶汤；如是实热，则须在去热的药中加去实的药物，像三黄泻心汤之类，学者按此推之，即可善用黄连。黄连大寒，得水之性，故去热。与阿胶鸡子黄为填离清坎之药，故治心内之热。  \n\n【药征】主治心中烦悸也，旁治心下痞，吐下腹中痛。  \n\n【灵胎】除热燥湿，明目止利。  \n\n【用量】普通三分至一钱。 \n\n【禁忌】血少气虚，致惊悸烦燥，小儿痘疮阳虚作泄，行浆后泄泻，老人脾胃虚寒泻，真阴不足内热均忌。  ","videoMemo":"","fangList":[],"bieMing":"黄连"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '55、黄连', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('e3tQi1rwTKb', 4, '{"title":"第902000454条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>54、蘼芜,川芎之苗</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000454,"note":"\n【本经原文】味辛性温，主咳逆定惊气辟邪恶，除蛊毒鬼注，去三虫，久服通神。即川芎之 苗也。  \n\n【别录】身中老风，头中久风，风眩。  \n\n【苏颂】作饮止泄泻。  \n\n【时珍】蘼芜花入面脂用。","videoMemo":"","fangList":[],"bieMing":"蘼芜,川芎之苗"}}', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '2025-01-14T07:49:28.000Z', '54、蘼芜,川芎之苗', '2025-01-14T07:49:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xR44Mby2VM0', 4, '{"title":"第902000522条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>122、蜂子，蜂蜜，蜂蜡 </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000522,"note":"【本经原文】味甘平，主风头，除蛊毒，补虚羸伤中，久服令人光泽好颜色不老，大黄蜂子主心腹胀满痛，轻身益气，土蜂子主痈肿。 \n\n【产地】产我国南方诸省岩岭间，今江浙之间多自养蜂，出蜜佳，国外产者亦佳。 \n\n【性味】味甘，性平，无毒。 \n\n【主治】$n{蜂蜜}为润脏腑要药，主益气补中，滋养脾胃，调和营卫，治五脏不足，肠胃燥结，肌肉疼痛，除心烦，疗肠澼，作榳入谷道，导便秘。\n\n               $n{蜂蜡}为止血，安胎，补益药，治孕妇胎 动下血有殊效，又为硬膏基础剂。\n\n              ${蜜蜂子}为补虚，解毒药，治麻风病及肠寄生虫结聚腹痛，滇越等地常以油炸佐膳。 \n\n【别录】蜂蜜益气补中，止痛解毒，除众病，和百药，久服强志轻身。 \n\n【藏器】蜂蜜治牙齿疳虫，唇口疮，目肤赤障，杀虫。 \n\n【孟铣】蜂蜜治心腹血气刺痛，及白痢，同生地黄汁各一匙服，即下。 \n\n【本经】蜂蜡主下利脓血，补中，续绝伤金疮，益气。 \n\n【甄权】蜂蜡主孕妇胎动，下血不绝欲死，以鸡子大煎三五沸。投美酒半升立愈，又主白发镊去，消蜡点孔中即生黑发。 \n\n【本经】蜜蜂子治头风，除蛊毒，补虚羸伤中，久服令人光泽。 \n\n【别录】蜜蜂子治心腹痛，面目黄，大人小儿腹中五虫从口吐出者。 \n\n【藏器】蜜蜂子主丹毒风疹，腹中留热，利大小便涩，去浮血，下乳汁，妇人带下病。 \n\n【用量】可做食品，无定量。 \n\n【禁忌】无。  \n\n【附方】 阴头生疮——以蜜煎甘草涂之。 肛门生疮——白蜜一斤、猪胆汁一枚相和，微火煎令可丸，作挺长约三寸，大如手指，涂油纳肛门内，卧令后重，须臾通泻。 热油灼痛——以白蜜涂之。 肝虚雀目——黄蜡溶汁，入蛤粉相合所得，冷却，每以二钱夹入猪肝内煮之，乘热食肝  \n饮汁，日二，以平安为度。  \n\n大风疠疾——须眉已无，皮肉已烂成疮者：蜜蜂子，胡蜂子，黄蜂子并炒各一分，白花蛇，乌梢蛇并酒浸去皮骨炙干，全蝎，僵蚕并炒，各一两，地龙炒半两，蝎虎（守宫），赤足蜈蚣各15 条，丹砂一两，雄黄 一分（醋炒），龙脑半钱，共为细末，每服一钱匕，蜜汤调下，月三五服。（圣济）。","videoMemo":"","fangList":[],"bieMing":"蜂蜜,蜂子,蜂蜡  "}}', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '122、蜂子，蜂蜜，蜂蜡', '2025-01-14T09:06:34.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uzDoyDtOLdL', 4, '{"title":"第902000521条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>121、石蜜  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000521,"note":"【本经原文】味甘平，主心腹邪气，诸惊痫痓，安五藏，诸不足，益气补中，止痛解毒除众病，和百药，久服强志轻身，不饥不老。  \n\n【性味】味甘，性寒，无毒。 \n\n【主治】石蜜主和中益脾，润心肺解酒毒，治目中热膜，燥热咳嗽，心腹胀热，口干渴。  \n\n【唐本】主心腹热胀，口干渴。 \n\n【孟铣】治目中热膜明目，和枣肉巨藤末为丸含之，润肺气，五脏生津。  \n\n【灵胎】养胃和中。 \n\n【用量】普通做食品，入药无定量。  \n\n【禁忌】无。  \n\n【吴克潜】曰糖之赤者为赤沙糖，白者为白沙糖，凝结成块者为冰糖，入药用冰糖最良，膏 泛丸多用之。时珍曰蔗糖甘寒，能泻大热，素问甘温除大热意也，煎炼成糖则甘温而助湿热，所谓积温成热也，又白糖霜主润心肺，和中消痰，解酒生津，大约功专润泽，赤沙糖主心腹热胀，润心肺大小肠热，解酒毒，又为和血去积之药。  ","videoMemo":"","fangList":[],"bieMing":"石蜜"}}', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '121、石蜜', '2025-01-14T09:06:34.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('X8dHXoz6uX3', 4, '{"title":"第902000520条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>120、雁肪,野鸭</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000520,"note":"\n【本经原文】味甘平，主风挛拘急，偏枯气不通利，久服益气不饥，轻身耐老。即野鸭。  \n\n【产地】野鸭之脂。 \n\n【性味】味甘平无毒。 \n\n【主治】四肢拘急，半身不遂等偏风。 \n\n【用量】无一定剂量，可做食用。 \n\n【禁忌】勿与犬肉猪肉牛肉等并煮，主腹泻。","videoMemo":"","fangList":[],"bieMing":"雁肪,野鸭"}}', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '120、雁肪,野鸭', '2025-01-14T09:06:34.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9dHx4ZJhUas', 4, '{"title":"第902000519条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>119、丹雄鸡</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000519,"note":"\n【本经原文】味甘微温，主女人崩中漏下，赤白沃，补虚温中，止血通神，杀毒辟不祥头，主杀鬼，东门上者尤良。肪主耳聋，肠主遗溺，肶胵裹黄皮，主泄利，尿白主消渴，伤寒寒热，黑雌鸡主风寒湿痹，五缓六急，安胎，翮羽主下血闭，鸡子主除热火疮痫痉，可作虎魄 神物。鸡白蠹肥脂。即鸡一种。  \n\n【产地】处处有之。  \n\n【灵胎】疏肝养窜，鸡金消积。 \n\n【白雄鸡】味酸甘性微温无毒。主调中除邪，下气疗狂，安五脏利小便。  \n\n【乌雄鸡】味甘性微温无毒，主补中止痛，除心腹恶气，治风湿麻痹，诸虚羸，安胎，疗折伤。  \n\n【黑雄鸡】味甘酸性温平，无毒，主风寒湿痹五缓六急，破恶血，补新血，安胎，治产后虚羸，除邪辟恶痈疽排脓，酒浸饮，令人肥白。  \n\n【黄雄鸡】味甘酸咸．性平无毒，主伤中消渴，小便数而不禁，肠澼泄痢，补盖五脏绝伤，添髓生精，助阳气，疗五劳，益气力，去冷气，消水癖，治产后虚羸，煮汁煎药服佳。  \n\n【乌骨鸡】味甘性平无毒，主补虚劳羸弱．治消渴，益产妇，治女人崩带，一切虚损诸病，大人小儿噤口痢，并煮食饮汁，验鸡舌黑者良。  \n\n【用量】普通为服食之品，入药无定量。  \n\n【禁忌】鸡肉不可合葫蒜葱芥子食，不可合犬肉食，不可合獭肉兔肉鱼汁食，多食动风发疾，小儿五岁以下不宜食，忌与糯米同食。  \n\n【鸡内金】味甘性平无毒，主化积，治反胃，疗泄痢尿血下血，崩中带下，小儿食疟疳积，大人淋沥，消导酒积，外敷治一切口疮，牙疳腿疮，谷道生疮。  \n\n【鸡屎白】味苦性微寒无毒，主行水消积，治鼓胀，疗转筋入腹，破石淋二便，下气破血，治伤寒，寒热中风，贼风风痹，白虎风，贴风痛头痛，止遗溺，灭瘢痕，小儿客忤惊啼，解 金银毒，酒服疗乳妒乳痈乳头破裂，外敷秃疮耳疮瘰疬。  \n\n救急方——古人急救吊死或勒死之人时，将活雄鸡一只，腹部切开，趁热直接放置到死人的脖子位置，病患保持平躺姿势，可以救助于危急之时。  \n","videoMemo":"","fangList":[],"bieMing":"丹雄鸡"}}', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '119、丹雄鸡', '2025-01-14T09:06:34.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sB3OlqMU4X0', 4, '{"title":"第902000518条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>118、阿胶</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000518,"note":"\n【本经原文】味甘平，主心腹内崩，劳极洒洒如疟状，腰腹痛，四肢酸疼，女子下血安胎，久服轻身益气。  \n\n【产地】原产山东东阿县，用阿井之水将牛皮或驴皮煎熬而成，今者阿井之水久湮，处处皆有出产，多以驴皮熬胶入药。  \n\n【性味】味甘，性平，无毒。  \n\n【主治】阿胶为养阴清热要药，主清补肺脏，滋益肝肾和血液，坚筋骨，治风痛．虚劳喘嗽吐血，妇人血枯经闭，崩中带下。  \n\n【别录】丈夫小腹痛，虚劳羸瘦，阴气不足，脚酸不能久立，养肝气。  \n\n【药性】坚筋骨，益气，止痢。  \n\n【药征】主治诸血症，故兼治心烦不得眠者。 \n\n【容川】阿胶以水济火，是以坎填离，此阴汁得心火化为赤，即为血，益阴气，使阳不动、保持厥阴之本体，阿胶得阿井伏流之水性，故能伏水中之阳。 \n\n【灵胎】养肝滋血，补脾安胎。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】气味虽平和然其性黏腻，胃弱作呕吐，脾虚食不消者均忌。  ","videoMemo":"","fangList":[],"bieMing":"阿胶"}}', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '118、阿胶', '2025-01-14T09:06:34.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('X0rNi0JuuAy', 4, '{"title":"第902000517条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>117、白胶 </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000517,"note":"\n【本经原文】味甘平，主伤中劳绝，腰痛羸瘦，补中益气，妇人血闭无子．止痛安胎，久服轻身延年，一名鹿角胶。  \n\n【产地】鹿之角茸。产我国东北西北地区。  \n\n【性味】味甘，性平，无毒。  \n\n【主治】主补中益气，长肌增髓，止痛安胎．黑须发。强筋骨，壮腰膝，生精血，治伤中，虚损，劳嗽，吐血，尿血，下血，多汗淋露，腰痛羸瘦，四肢作痛，崩中带下，疗疮疡，肿毒。  \n\n【别录】疗虚劳洒洒如疟，羸瘦，四肢酸疼，腰脊痛，小便数利，泄精溺血，破瘀血在腹，散石淋，痈肿，骨中热疽痒，安胎下气，杀鬼精物，久服耐老，不可近丈夫阴令痿。  \n\n【日华】补男子腰肾虚冷，脚膝无力，夜梦鬼交，精溢自出，女人崩中漏血，赤白带下，炙末空心服方寸匕，壮筋骨。  \n\n【灵胎】补督脉，强肾气。  \n\n【用量】普通七分至钱半。  \n\n【禁忌】壮年慎用，阴虚火旺者忌。麻勃为使畏大黄，不可嗅，有虫恐入鼻内，药不能治，男子阴茎近入，易于痿弱。  \n\n鹿茸——味甘咸性温无毒．鹿茸为大补真阳要药，主养血益阳，强筋健骨，生精充髓，治男子虚劳，老人精衰，腰膝无力，滑精眩晕，妇人崩漏带下。  \n\n鹿角——味咸性温无毒，主益气补阳，强骨髓，续绝伤，治腰脊痛，心腹痛少腹血急痛，脱精尿血，夜梦鬼交、疗女子胞中余血不尽欲死，恶疮痈疽，煮成粉名鹿角霜，治脾胃虚寒，呕逆食少便溏。  \n\n【吴克潜】曰鹿茸为纯阳之物，性温而燥，专补元阳，凡男子虚怯老人阳亏允为合宜，若吐血尿血等症，由于阴虚火旺下焦有热者居多，误用鹿茸必致反剧，故鹿茸治血症乃治阳衰气虚而不摄血者。治痈疽亦为阴症而火衰者，研习者须知。  ","videoMemo":"","fangList":[],"bieMing":"白胶 "}}', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '117、白胶', '2025-01-14T09:06:34.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eW7T0JYYoiy', 4, '{"title":"第902000516条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>116、熊脂</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000516,"note":"\n【本经原文】味甘微寒，主风痹不仁，筋急，五藏腹中积聚，寒热羸瘦，头疡白秃，面皯， 久服强志，不饥轻身。  \n\n【产地】熊身上之脂肪。今已经不用。","videoMemo":"","fangList":[],"bieMing":"熊脂"}}', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '116、熊脂', '2025-01-14T09:06:34.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zUKI1v4ESFL', 4, '{"title":"第902000515条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>115、牛黄</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000515,"note":"\n【本经原文】味苦平，主惊痫寒热，热盛狂痓，除邪逐鬼。 \n\n【产地】牛黄生于病牛胆中，状如鸡子黄，多出陕西甘肃等地。 \n\n【性味】味苦，性平，有小毒。 \n\n【主治】牛黄为泻热定惊，利痰清心要药，主惊痫，寒热中恶，口噤，小儿惊邪，痘疮发狂，治痰迷，痉急，斑痧疮毒，益肝胆，定魂魄。 \n\n【别录】疗小儿百病，诸痫热，口不开，大人狂癫，又堕胎，久服令人不忘。 \n\n【甄权】安魂定魄，辟鬼邪，卒中恶，小儿夜啼。 \n\n【日华】主中风失音，口噤，惊悸，天行时疾，健忘虚乏。 \n\n【思邈】益肝胆，定精神，除热，止惊痢，辟恶气，除百病。 \n\n【灵胎】化痰定痫，泄热除邪。 \n\n【用量】普通五分至一钱。  \n\n【禁忌】恶龙骨龙胆（钱乙方中不忌）地黄常山蜚蠊，畏牛膝干漆，风热未深者忌用。","videoMemo":"","fangList":[],"bieMing":"牛黄"}}', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '115、牛黄', '2025-01-14T09:06:34.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('P7ZyJ3ki7eO', 4, '{"title":"第902000514条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>114、麝香</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000514,"note":"\n【本经原文】味辛温，主辟恶气．杀鬼精物，温疟，虫毒，痫痓，去三虫，久服除邪，不梦寤魇寐。  \n\n【产地】产我国青海西藏陕西甘肃四川等地，似鹿而小，牡麝之脐部有囊，分泌奇香之质，曰麝脐香，结成颗粒者曰当门子。  \n\n【性味】味辛，性温，无毒。  \n\n【主治】麝脐香为开关通窍要药，主内透骨髓，外彻皮毛，走窜开通。治中恶，痞满，风毒，风痰，暴痛卒闭，疗痰厥惊痫，鼻塞耳聋目翳。  \n\n【别录】疗诸凶邪鬼气，中恶，心腹暴痛，胀急，痞满，风毒，去面黡，目中肤翳，妇人难产，堕胎。  \n\n【日华】治蛇蚕咬，沙蛊溪瘴毒，辟蛊气，杀脏腑虫，治疟疾，吐风痰，疗一切虚损恶病，纳子宫，暖水脏，止冷带下。  \n\n【弘景】佩服及置枕间辟恶梦，及ㄕ疰鬼气，又疗蛇毒。  \n\n【药性】热水研服一粒，治小儿惊痫客忤，镇心安神，止小便利，又能蚀一切痈疮脓水。  \n\n【好古】疗鼻窒不闻香臭。 \n\n【孟铣】除百病，治一切恶气，及惊怖恍惚。  \n\n【灵胎】除邪辟秽，开窍杀虫。  \n\n【用量】普通数厘至分许。  \n\n【禁忌】凡病之属于虚者，当补益，概勿施用。劳怯及孕妇均不宜佩带，忌蒜及近鼻嗅之。  \n\n【吴克潜】中医之用麝香乃因其有开窍之功，一般毛孔闭塞者麻黄以通之，腠理闭塞者葛根以通之，荣卫闭塞者桂枝以通之，风塞者独活羌活以通之，血塞者延胡郁金以通之，肺气塞 者桔梗前胡以通之，心气塞者菖蒲远志以通之，胃气塞者藿香川朴以通之，肝气塞者香附川芎以通之。但是此类用法可以一脏一腑一经为治，并非闭塞之重者。当诸邪深入，或内病暴作，内则经络全被遏阻之势，外则诸窍亦有闭塞之象，是故心神失其主，神志为蒙，此时势非麝香通之不可，著名方剂有麝香天麻丸（麝香天麻防风川芎天南星菊花，治风痰气厥，头痛目眩、四肢倦怠，睡卧不宁），麝昏蟾酥丸（麝香蟾酥轻粉乳香砒石雄黄巴豆寒水石治痈疽发背．疔疮内毒），及至宝丹紫雪丹苏合丸牛黄清心丸等。  ","videoMemo":"","fangList":[],"bieMing":"麝香"}}', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '114、麝香', '2025-01-14T09:06:34.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ovjMikvI91B', 4, '{"title":"第902000513条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>113、龙骨</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000513,"note":"\n【本经原文】味甘平，主心腹鬼注，精物老魅，咳逆泄利脓血，女子漏下，症瘕坚结，小儿热气惊痫。齿，主小儿大人惊痫癫疾狂走，心下结气，不能喘息，诸痉，杀精物，久服轻身，通神明延年。  \n\n【产地】多产于我国山西四川等处山岩中，为一种化石。  \n\n【性味】味甘，性平，无毒。  \n\n【主治】龙骨为固敛正气，镇纳浮阳要药，主安心神辟惊烦，治泄痢脓血，崩带遗精，镇喘逆，敛虚汗，收疮口，疗脱肛。  \n\n【别录】心腹烦满，恚怒，气伏在心下不得喘息，肠痈内疽，阴蚀，四肢痿枯，夜卧自惊汗出，止汗，缩小便，溺血，养精神，定魂魄，安五脏。白龙骨主多寐泄精，小便泄精。  \n\n【甄权】逐邪气，安心神，止夜梦鬼交，虚而多梦纷纭，止冷痢，下脓血，女子崩中带下。  \n\n【日华】怀孕漏胎，止肠风下血，鼻洪吐血，止泻痢渴疾，健脾，涩肠胃。  \n\n【药征】主治脐下动也，旁治烦惊失精。  \n\n【灵胎】敛气涩血，定志安神。  \n\n【用量】普通二钱至三四钱。  \n\n【禁忌】收摄太过，若非久痢虚脱者，切勿妄投，火盛失精者误用，多致溺赤涩痛，得人参牛黄良，畏石膏川椒，忌鱼及铁器。 龙骨今所用者皆石质也，过去有人误解为龙之骨化石，实则为化石之一种，质细而性纯，如 同禹余粮亦为石之一种，故二者功能相近，常与牡蛎合用。系土中石类，潜藏于土中，是天  \n水之阳，以归地下，故能潜纳肾气．收敛心神．因其潜纳之性也。  \n\n【炮制】拣去杂质，刷去泥沙即得，煅龙骨即置铁锅中，煅透，即得。","videoMemo":"","fangList":[],"bieMing":"龙骨"}}', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '113、龙骨', '2025-01-14T09:06:34.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('u2JpWO5UYa3', 4, '{"title":"第902000512条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>112、发髲 </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000512,"note":"\n【本经原文】味苦温，主五癃关格不通，利小便水道。疗小儿痫，大人痓，仍自还神化。 \n\n【产地】乃人身头上之发也，处处有之。 \n\n【性味】味苦，性温，无毒。 \n\n【主治】发髲主益阴泄热，治小便不利，五癃关格，小儿惊痫，血闷血晕，去瘀血，止好血。\n\n【别录】合鸡子黄煎之消积水，疗小儿惊热百病。 \n\n【大明】止血闷血运金疮伤风血痢，入药烧存性用，煎膏长肉，消瘀血。 \n\n【苏敬】乱发烧灰，疗转胞小便不通，赤白痢，痈肿疔肿骨疽。 \n\n【丹溪】乱发消瘀血，止舌血，补阴甚捷。 \n\n【用量】普通三五分。 \n\n【禁忌】发灰气味不佳，胃弱者勿服。  ","videoMemo":"","fangList":[],"bieMing":"发髲 "}}', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '112、发髲', '2025-01-14T09:06:34.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GYPXsJphe5a', 4, '{"title":"第902000511条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>111、陈皮,橘柚</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000511,"note":"\n【本经原文】味辛温，主胸中瘕热逆气，利水谷，久服去臭，下气通神。又名橘皮。今之陈皮。 \n\n【产地】产我国广东，即广橘皮，以晒干陈久为良，故名陈皮。 \n\n【性味】味苦辛，性温，无毒。 \n\n【主治】陈皮为宣通疏利要药，主行气健胃，去湿化痰，能发散清热，消积水气。 \n\n【别录】下气止呕咳，治气冲胸中，吐逆霍乱，疗脾不能消谷，止泄，除膀胱留热停水，起淋，利小便，去寸白虫。 【甄权】清痰涎，治上气咳嗽．开胃主气痢，破症瘕痃癖。  \n【药征】主治呃逆也，旁治胸痹停痰。\n\n【用量】普通一钱至三钱。  \n\n【禁忌】凡中气虚，气不归元者，忌与耗气药同用，胃虚有火呕吐，忌与温热香燥药同用，阴虚咳嗽生痰，忌与半夏南星等同用，疟非寒甚者忌。  \n\n成无己曰陈皮和百药，脾为气母，肺为气籥，凡补药涩药必用陈皮以利气，凡用陈皮取 其发散皮肤也，故陈皮之用在于行气，气行则领导百药，有痰者因气行而化，有湿者亦因气行而消，其它因食积及饮食之毒亦无不因气行而消解，气虚不能归元，则仅存之气不可再行而耗之，故忌。  \n\n【容川】陈皮亦木实也，能治胃，兼治脾，但兼辛香，又能上达于肺。枳壳不辛香，故不走肺，厚朴辛，而气太沉，故不走肺。因肺通于大肠，故厚朴可泄肺气。其气不轻不重，故可降上焦与中焦之气。 ","videoMemo":"","fangList":[],"bieMing":"陈皮,橘柚"}}', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '111、陈皮,橘柚', '2025-01-14T09:06:34.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('22Emc0IY2D3', 4, '{"title":"第902000510条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>110、蕤核</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000510,"note":"\n【本经原文】味甘温，主心腹邪气，明目，目赤痛，伤泪出，久服轻身，益气不饥。 \n\n【产地】产我国陝西河南等地，核仁入药。 \n\n【性味】味甘，性温，无毒。 \n\n【主治】蕤核主心腹邪热结气，治目赤痛伤泪出，翳膜，眦烂，生用疗多睡，熟用治不眠。\n\n【别录】破心下结痰痞气，齆鼻。 \n\n【甄权】治鼻衄。 \n\n【吴普】强志，明耳目。 \n\n【藏器】生治足睡，熟治不眠。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】能补肝虚，今人多用治眼疾，然非火风暴眼所宜用也。","videoMemo":"","fangList":[],"bieMing":"蕤核"}}', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '110、蕤核', '2025-01-14T09:06:34.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('V1OuyfZvIur', 4, '{"title":"第902000509条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>109、木兰</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000509,"note":"\n【本经原文】味苦寒，主身大热在皮肤中，去面热，赤疱酒皻，恶风瘨疾，阴下痒湿，明耳目。  \n\n【产地】处处有之，庭院可种植。  \n\n【性味】木兰皮味苦，性寒。 \n\n【主治】木兰皮为解热，行血，祛湿药。治面疱，酒糟鼻，水肿，酒疸，重舌，及阴下湿痒。\n\n【别录】疗中风伤寒，及痈疽，水肿，去臭气。  \n\n 【用量】普通一钱至三钱。  \n\n【禁忌】体寒之人禁。  \n\n【附方】 面上疱——木兰皮一斤，细切酒渍百日晒干，栀子一斤，共为末，每服方寸匕，日三。（肘后）。 酒疸发斑——赤黑黄色，心下懊痛，足胫肿满，小便黄，由大醉当风，入水所致：木兰皮一两，黄花二两，为末，酒服方寸匕，日三。（肘后）。  ","videoMemo":"","fangList":[],"bieMing":"木兰"}}', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '109、木兰', '2025-01-14T09:06:34.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BWR1hu5SCGd', 4, '{"title":"第902000508条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>108、女贞实,女贞子</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000508,"note":"\n【本经原文】味苦平，主补中安五脏，养精神，除百疾，久服肥健，轻身不老。又名女贞子。 \n \n【产地】处处有之，生川谷中，叶隆冬不凋，实入药。 \n\n【性味】味苦，性平，无毒。 \n\n【主治】女贞子为除热益精要药，主补中安五脏，养精神，健腰膝，治白发。\n\n【用量】普通一至三钱。 \n\n【禁忌】气味俱阴，老人当入保脾胃药及椒红温暖之剂，不然恐腹痛作泻。 ","videoMemo":"","fangList":[],"bieMing":"女贞实,女贞子"}}', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '108、女贞实,女贞子', '2025-01-14T09:06:34.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ywKCCnDkBRH', 4, '{"title":"第902000507条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>107、杜仲</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000507,"note":"\n【本经原文】味辛平，主腰脊痛，补中益精气，坚筋骨强志，除阴下痒湿，小便余沥、久服轻身耐老。 \n\n【产地】产我国陕西四川等地，树皮中有银丝如棉，故亦名锦杜仲，入药。 \n\n【性味】味辛甘，性温，无毒。 \n\n【主治】杜仲为健筋骨补腰肾要药，主腰膝酸痛，体虚强直，治胎漏胎堕，精气亏弱。 \n\n【别录】脚中酸痛，不欲践地。 \n\n【甄权】肾冷膂腰痛，人虚而身强直，风也，腰不利加重。 \n\n【大明】治肾劳腰脊挛。 \n\n【东垣】能使筋骨相着。 \n\n【好古】润肝燥，补肝经风虚。 \n\n【汪机】治胎漏胎堕。 \n\n【容川】杜仲柔韧，象人之筋膜，能伸能缩，极其坚韧，包紫黑，味纯厚，故入肝肾，以强人筋骨。 \n\n【用量】普通二钱至三四钱，大剂二三两。 \n\n【禁忌】恶元参蛇蜕，肾虚火炽者忌，当知母黄柏同用。 常用于胎前能安，胎后能补。  ","videoMemo":"","fangList":[],"bieMing":"杜仲"}}', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '107、杜仲', '2025-01-14T09:06:34.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0kjztwiUwvX', 4, '{"title":"第902000506条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>106、桑寄生,桑上寄生</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000506,"note":"\n【本经原文】味苦平，主腰痛，小儿背强，痈肿，安胎充肌肤，坚发齿，长须眉，其实明目轻身通神。  \n\n【产地】产我国广西．或云处处有之，但寄生杂树者多，寄生桑树者少。 \n\n【性味】味苦，性平，无毒。 \n\n【主治】桑上寄生为补肝肾坚筋骨要药，主腰痛背强，益血脉，安胎孕，治女子内伤不足，怀孕胎漏，产后余疾。 \n\n【别录】去女子崩中内伤不足，产后余疾，下乳汁，主金疮，去痹。 \n\n【容川】此药味酸枝繁，具木之性，生于桑树之上，桑者，木中之金也，寄生附之，故独得金木之间气，且根不粘土，纯感风气而生，故为清散风木之要药。此药附木而生，象胆附肝，味酸苦，得木火之味，能清肝胆之火，治风热，筋脉结等症，胆通三焦之网膜，外连于筋，寄生如藤附木，象人之筋，故治之。  \n\n【灵胎】驱风养血安胎。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】忌见火。  ","videoMemo":"","fangList":[],"bieMing":"桑寄生,桑上寄生"}}', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '106、桑寄生,桑上寄生', '2025-01-14T09:06:34.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pQYpG7G2fIW', 4, '{"title":"第902000505条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>105、辛夷</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000505,"note":"\n【本经原文】味辛温，主五脏身体，寒风头脑，面皯，久服下气，轻身明目，增年耐老。 \n\n【产地】处处有之，庭园可以种植，树高大，苞入药。 \n\n【性味】味辛，性温，无毒。 \n\n【主治】辛夷为升阳治上要药，主头脑各病，鼻渊鼻塞，行胃气，宣肺气。 \n\n【别录】温中解肌，利九窍，通鼻塞涕出，治面肿，引齿痛，眩冒身几几如在车船之上者，生须发，去白虫。 \n\n【大明】通关脉，治头痛，憎寒体噤，搔痒，入面脂生光泽。 \n\n【灵胎】疏肝散风。 \n\n【用量】普通一二钱。 \n\n【禁忌】凡气虚人忌，偶感风寒鼻塞亦忌，头脑痛属血虚火炽亦忌，齿痛属胃火者亦忌，恶赤石脂，畏菖蒲黄连蒲黄石膏。  \n此药性升，故主头面各疾，可引诸药上升至头面，经曰脑渗为涕，王冰曰胆液不澄，则为浊涕，如泉不已，故名鼻渊。 \n\n【容川】辛夷花在树梢，其性极升，而味辛散，故能散脑鼻之间风寒。 \n\n【炮制】拣去杂质及柄，去灰即得。  ","videoMemo":"","fangList":[],"bieMing":"辛夷"}}', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '105、辛夷', '2025-01-14T09:06:34.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('suLnMWEajHl', 4, '{"title":"第902000504条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>104、蔓荆实</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000504,"note":"\n【本经原文】味苦微寒，主筋骨间寒热痹，拘挛明目，坚齿利九窍，去白虫，久服轻身耐老。\n\n【产地】产我国河南甘肃江浙等地，子入药。 \n\n【性味】味苦辛，性微寒，无毒。 \n\n【主治】蔓荆子为搜风凉血要药，主利九窍，散风邪，明目坚齿，治风头痛脑鸣，湿痹拘挛。\n\n【别录】风头痛脑鸣，目泪出，益气，令人光泽，脂致。 \n\n【甄权】治贼风，长髭发。 \n\n【大明】利关节，治痫疾，赤目。 \n\n【元素】太阳头痛头沉昏闷，除昏闷，散风邪，凉诸经血，止目精内痛。 \n\n【好古】搜肝风。  \n\n【用量】普通八分至二钱。 \n\n【禁忌】头目痛不因风邪而由血虚有火者忌，胃虚人不可服，恐生痰疾。\n\n【容川】蔓荆子气烈，味辛而气发散，而质轻，故主散头目之风。  ","videoMemo":"","fangList":[],"bieMing":"蔓荆实"}}', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '104、蔓荆实', '2025-01-14T09:06:34.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ve0H6XbH8NG', 4, '{"title":"第902000503条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>103、五加皮</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000503,"note":"\n【本经原文】味辛温，主心腹疝气腹痛，益气疗躄，小儿不能行，疽创阴蚀。 \n\n【产地】产我国陕西江浙湖南等地，五叶者良，根皮入药。 \n\n【性味】味辛，性温，无毒。 \n\n【主治】五加皮为祛风湿壮筋骨要药，主疼痹风弱，五缓虚羸，小儿行迟，疝气腹痛，治瘀留皮肌，阴痒囊湿。 \n\n【别录】男子阴痿囊下湿，小便余沥，女人阴痒及腰脊痛，两脚疼痹风弱，五缓虚羸，补中益精，坚筋骨，强志意。 \n\n【甄权】破逐恶风，四肢不遂，贼风伤人，软脚兼腰，主多年瘀血在皮肌，治痹湿内不足。\n\n【大明】明目下气，治中风骨节挛急。 \n\n【苏颂】酿酒饮治风痹，四肢挛急。 \n\n【雷斅】作末浸酒饮，治目僻眼瘫。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】下部无寒湿邪而有火，及肝肾虚而有火，均忌。 ","videoMemo":"","fangList":[],"bieMing":"五加皮"}}', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '103、五加皮', '2025-01-14T09:06:34.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SQP7q7NwuKW', 4, '{"title":"第902000502条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>102、干漆</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000502,"note":"\n【本经原文】味辛温，无毒，主绝伤补中，续筋骨，填髓脑安五脏，五缓六急，风寒湿痹，生漆去长虫，久服轻身耐老。 \n\n【产地】产我国四川安徽等地，为漆树之脂，自然干者入药。 \n\n【性味】味辛，性温，无毒。 \n\n【主治】干漆主破瘀血，续筋骨，治风寒湿痹，积滞，疝瘕，心痛，闭经。 \n\n【别录】干漆疗咳嗽，消瘀血痞结腰痛，女子疝瘕，利小肠，去疣虫。 \n\n【甄权】杀三虫，主女人经脉不通。 \n\n【大明】治传尸劳，除风。 \n\n【元素】削年深坚结之积滞，破日久凝结之瘀血。 \n\n【灵胎】养筋骨，祛风湿。 \n\n【用量】普通五分至二钱。 \n\n【禁忌】畏川椒紫苏鸡卵及蟹，忌油脂，然大伤营血卫气，若胃虚大疮及无瘀血者均忌用，","videoMemo":"","fangList":[],"bieMing":"干漆"}}', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '102、干漆', '2025-01-14T09:06:34.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YJOJ7Ajo5QR', 4, '{"title":"第902000501条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>101、黄柏</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000501,"note":"\n【本经原文】味苦寒，主五脏肠胃中结热，黄疸，肠痔，止泄利，女下漏下，赤白阴阳蚀疮。今名黄柏。 \n\n【产地】生汉中山谷。产我国四川，故亦称川柏，他处亦有之，日本输入者劣，树皮入药。 \n\n【性味】味苦，性寒，无毒。 \n\n【主治】黄柏为除热杀虫，坚肾益阴要药，主结热，黄疸，诸痿，瘫痪，治诸疮痛，泄痢，下血，泻膀胱相火，疗淋浊白带，肠胃结热。 \n\n【别录】疗惊气在皮间肌肤赤起，目热赤口疮。 \n\n【甄权】男子阴痿及传茎上疮，治下血如鸡鸭肝片。 \n\n【藏器】热疮疱起，虫疮，血痢，止消渴，杀蛀虫。 \n\n【元素】泻膀胱相火，补肾水不足，坚肾壮骨髓，疗下焦虚，诸痿瘫痪，利下窍，除热。 \n\n【大明】安心除劳治骨蒸，洗肝目多泪，口干心热，杀疳虫，治疣心痛，鼻衄，肠风下血，后急热肿痛。 \n\n【东垣】泻伏火救肾水，治冲脉气逆，不渴而小便不通，诸疮痛不可忍。 \n\n【丹溪】得知母降阴火，得苍术除湿清热，为治痿要药，得细辛泻膀胱火，治口舌生疮。 \n\n【灵胎】清热燥湿。 \n\n【用量】普通五分至二钱。 \n\n【禁忌】恶干漆，伏硫磺，阴阳两虚，脾胃薄弱者均忌。  ","videoMemo":"","fangList":[],"bieMing":"黄柏"}}', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '101、黄柏', '2025-01-14T09:06:34.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0vmeFK9J9cq', 4, '{"title":"第902000500条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>100、酸枣仁,酸枣</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000500,"note":"\n【本经原文】味酸平，主心腹寒热，邪结气聚，四肢酸疼，湿痹，久服安五脏，轻身延年。\n\n【产地】产我国山西河南等地，多生山野间，或作棘实，，乃棘树之实也，实之大者名酸枣仁，入药。 \n\n【性味】味酸，性平，无毒。 \n\n【主治】酸枣仁为宁心敛汗要药，主心腹寒热，邪结气聚，烦心不眠，虚汗烦渴，治四肢酸痛湿痹，益肝养筋。  \n\n【别录】烦心不得眠，脐上下痛，血转久泄，虚汗烦渴，补中益肝气，坚筋骨，助阴气。\n\n【甄权】筋骨风，炒仁研汤服。 \n\n【药征】主治胸膈烦躁，不能眠也。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】凡肝胆心脾有实邪热者，禁用，以收敛故也。  ","videoMemo":"","fangList":[],"bieMing":"酸枣仁,酸枣"}}', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '100、酸枣仁,酸枣', '2025-01-14T09:06:34.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uGtF9UxrvYs', 4, '{"title":"第902000499条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>99、榆皮,榆白皮</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000499,"note":"\n【本草原文】味甘平，主大小便不通，利水道，除邪气，久服轻身不饥。今名榆白皮。  \n\n【产地】榆树处处有之，树之白皮入药。 \n\n【性味】味甘性平，滑利，无毒。 \n\n【主治】榆白皮为泄滞去着，利水消肿要药，主大小便不通，利五淋，渗湿热，治肠胃邪热，水肿，痈肿，外敷疗癣湿，头疮。 \n\n【别录】疗肠胃邪热气，消肿，治小儿头疮痂疕。 \n\n【甄权】滑胎，利五淋，治喘疗不眠。 \n\n【大明】通经脉，捣涎傅癣疮。 \n\n【孟铣】生皮捣和三年醋泡封，暴患赤肿，女人妒乳肿，日六七易效。 \n\n【用量】普通二三钱。  \n\n【禁忌】此能利窍渗湿热，去有形之积，气盛而壅者宜之，若胃寒而虚者，久服恐泄真气。  ","videoMemo":"","fangList":[],"bieMing":"榆皮,榆白皮"}}', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '99、榆皮,榆白皮', '2025-01-14T09:06:34.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('El4o235Igd8', 4, '{"title":"第902000498条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>98、茯苓</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000498,"note":"\n【本经原文】味甘平，主胸胁逆气，忧恚惊邪恐悸，心下结痛，寒热烦满，咳逆，口焦舌干，利小便，久服安魂养神，不饥延年。  \n\n【产地】生太山山谷。产我国云南及各省山中大松树下，年久而巨大者良，有白色者，有微赤者，皆入药。\n\n【性味】味甘性平无毒。  \n\n【主治】茯苓为利水行痰，通补兼长要药，主胸胁逆气，忧恚惊恐，治烦满咳逆，水肿淋沥，能除湿益燥，开胃平呕，除虚热，安心神。  \n\n【别录】止消渴好睡。大腹淋沥，膈中痰水，水肿淋结，开胸腑，调脏气，伐肾邪，长阴益气力，保神气。  \n\n【甄权】开胃止呕逆，善安心神，主肺痿痰壅，心腹胀满，小儿惊痫，女人热淋。\n\n 【大明】补五劳七伤，开心益志，止健忘，暖腰膝，安胎。  \n\n【元素】止渴利小便，除湿益燥，和中益气，利腰脐间血。 \n\n【东垣】逐水暖脾，生津导气，平火止泄，除虚热，开肌理。  \n\n【好古】泻膀胱，益脾胃，治肾积奔豚。 \n\n【药征】主治悸及肉瞬筋惕也。旁治小便不利，头眩烦躁。  \n\n【灵胎】补脾生津，化痰利水。 \n\n【用量】普通钱半至四钱，大剂二三两。  \n\n【禁忌】恶白敛，畏地榆雄黄秦艽鳖甲，忌米醋及酸物，凡病人肾虚，小水自利或不禁，或虚寒，精清精滑均忌，入补药，宜乳蒸晒干用。  \n\n【吴克潜】茯苓能行气而和缓，利水而不伤正，故通补皆宜，古今方中用者很多，著名方剂有茯苓半夏汤（茯苓，白术，半夏，神曲，大麦芽，陈皮，天麻，治胃气虚弱，身重有痰， 恶心欲吐）。茯苓四逆汤（茯苓，人参，甘草，干姜，生附子，治伤寒太阳证厥而心下悸，汗下后烦燥者）。四苓散（茯苓，猪苓，泽泻，陈皮，一方有白术无陈皮，治湿热霍乱，胸闷胀痛，溺涩烦渴）。茯苓甘草汤（茯苓，甘草桂枝生姜，治伤寒太阳证汗出不渴，或厥而 心下悸，或咳而遗溺，或小便不利）。茯苓厚朴汤（治伤寒伤风，夹痰呕逆。及吐泻后喉涎牵响，脾胃气虚，饮食减少）。茯苓桂枝甘草大枣汤（治太阳证发汗后，脐下悸，欲做奔豚）。茯苓杏仁甘草汤（治水邪射肺，阻其出气，治胸痹短气）。茯苓补心汤（茯苓，桂枝，炙甘 草，紫英石，人参，麦冬，大枣，赤小豆，治心气不足，悲愁恚怒，烦热，面黄衄血，喉痛 舌强，妇人气血两虚）等。  \n\n【附录】 赤茯苓：性质功用与白茯苓同，尤能利窍行水，破结气，泻心小肠膀胱湿热，凡外感证多用之。  \n\n茯苓皮：主利水道，开肌理，治水肿肤胀，行水而不耗气，胜于大腹皮。  \n\n【容川】茯苓得木之气，又能疏土，故能化气行水。  ","videoMemo":"","fangList":[],"bieMing":"茯苓"}}', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '98、茯苓', '2025-01-14T09:06:34.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WSQ3bPhQ4wr', 4, '{"title":"第902000497条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>97、柏实</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000497,"note":"\n【本经原文】味甘平，主惊悸，安五脏，益气除湿痹，久服令人悦泽美色，耳目聪明，不饥不老，轻身延年。今名柏子仁。  \n\n【产地】处处有之，山野最宜种植，树高大可做木材，叶侧生者入药，名侧柏叶，实名柏子仁，亦入药。  \n\n【性味】味甘性平无毒。 \n\n【主治】柏子仁为滋润要药，主养心气，润肾燥，除风湿，治痹痛，疗恍惚虚损，养肝舒脾。  \n\n【别录】疗恍惚虚损，吸吸历节，腰中重痛，益血止汗。 \n\n【甄权】治头风腰肾中冷，膀胱冷，浓宿水，兴阳道，去百邪鬼魅，小儿惊痫。  \n\n【好古】润肝。 \n\n【灵胎】养心气，润肌肤。  \n\n【用量】普通一钱至三钱。 \n\n【禁忌】肠滑做泻，膈间多痰，阳道数举，肾家有热，暑湿做泻者均忌。  \n\n【吴克潜】曰柏子仁不寒不燥，味甘而补，辛而能润，既养心肾，兼益脾肾，凡补脾药多燥，唯此独润而气味清香，故脾约宜之，燥脾药中，加用最良，著名方剂有柏子养心丸（柏子仁，枸杞子，麦冬，当归，石菖蒲，伏神，元参，熟地，甘草），治劳欲过度，心血亏损，精神恍惚，怔忡惊悸，及健忘遗精等症。柏子仁汤（柏子仁，人参，茯苓，陈皮，甘草，麝香少 许），治肠胃中津液枯少，脉虚微无力，大便艰涩者。柏子仁散（柏子仁，远志，人参，桑寄生，防风，琥珀，当归，生地，甘草）治产后败血挟邪攻心，乱语狂言，乍见鬼神等症。柏子仁丸（柏子仁，干地黄，茯苓，枳壳，覆盆子，北五味，附子，石斛，鹿茸，酸枣仁，桂心，沉香，黄耆）治妇人臂痛，筋脉挛急，遇寒则剧者。  ","videoMemo":"","fangList":[],"bieMing":"柏实"}}', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '2025-01-14T09:06:34.000Z', '97、柏实', '2025-01-14T09:06:34.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LyBxBymPLNS', 4, '{"title":"第902000542条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>142、苦菜  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000542,"note":"\n【本经原文】味苦寒，主五脏邪气，厌谷胃痹，久服安心益气，聪察少卧，轻身耐老。\n\n【产地】处处有之，凌冬不死，诗云谁谓荼苦，即此物也。 \n\n【性味】味苦，性寒，无毒。 \n\n【主治】苦菜主明目，除热，治痈疮，黄疸，调经脉，去邪气。 \n\n【别录】肠澼，渴热中疾，恶疮，久服耐饥寒。 \n\n【嘉佑】调十二经脉，霍乱后胃气烦逆，久服强力，虽冷甚益人。 \n\n【臓器】捣汁饮除面目皮及舌下黄，其白汁涂疔肿拔根，滴痈上利溃。 \n\n【纲目】主明目诸痢血淋痔瘘。 \n\n【用量】普通二至三钱。 \n\n【禁忌】脾胃虚寒人不可食，不可共蜜食。","videoMemo":"","fangList":[],"bieMing":"苦菜"}}', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '142、苦菜', '2025-01-15T08:44:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wV3IKroe6Kc', 4, '{"title":"第902000541条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>141、白瓜子  ,冬瓜子</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000541,"note":"\n【本经原文】味甘平，主令人悦泽好颜色，益气不饥，久服轻身耐老。 \n\n【产地】热带地区处处有之。今名冬瓜。其子为白瓜子。 \n\n【性味】甘寒。 \n\n【主治】泻寒热，甘益脾，利二便，消水肿，止消渴，散热毒痈肿。子能补肝明目。现药物中所用之瓜子，皆冬瓜子也。","videoMemo":"","fangList":[],"bieMing":"白瓜子,冬瓜子"}}', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '141、白瓜子 ,冬瓜子', '2025-01-15T08:44:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RMxSuXjQhYI', 4, '{"title":"第902000540条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>140、瓜蒂  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000540,"note":"\n【本经原文】味苦寒，主大水。身面四肢浮肿，下水杀虫毒，咳逆上气及食诸果，病在胸腹 中，皆吐下之。即甜瓜之蒂也。 \n\n【产地】生嵩高平泽。处处有之，取甜瓜之苦蒂入药。 \n\n【性味】味苦，性寒，无毒。 \n\n【主治】上焦之实症，以吐取之，浊痰壅塞，全身水肿等实症。 \n\n【倪注】主治因上焦不通造成之全身性水肿，专治膈上之疾，中风浊痰不出，无法吞咽。仲景方之瓜蒂散。 \n\n【药征】主治胸中有毒，欲吐而不吐也。 \n\n【用量】普通一钱至二钱。 \n\n【禁忌】凡虚弱之人禁忌之。吐后不止，可服半夏解之。","videoMemo":"","fangList":[],"bieMing":"瓜蒂"}}', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '140、瓜蒂', '2025-01-15T08:44:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RhFRJhfSNSw', 4, '{"title":"第902000539条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>139、苋实  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000539,"note":"\n【本经原文】味甘寒，主青盲明目，除邪，利大小便，去寒，久服益气力，不饥，轻身。  ","videoMemo":"","fangList":[],"bieMing":"苋实"}}', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '139、苋实', '2025-01-15T08:44:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VAFTs4Xlbk9', 4, '{"title":"第902000537条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>137、麻蕡  ,麻子仁,火麻仁</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000537,"note":"\n【本经原文】味辛平，主五劳七伤，利五脏，下血寒气，多食令人见鬼狂走，久服通神明轻身。今名麻勃(花粉)，火麻仁（果仁）。 \n\n【产地】生太山川谷。大麻处处有之，种者尤多，生圆形坚果，中含扁平之仁，即为麻子仁，入药，其花粉即麻勃。 \n\n【性味】麻仁味甘，性平。麻勃味辛，性温。 \n\n【主治】麻仁为滑润，行血，除风，强壮药，治大便燥，乳汁少，热淋经闭。麻勃为除风，通经，健脑药。 \n\n【别录】麻仁治中风汗出，逐水气，利小便，破积血，复血脉，乳妇产后余疾，沐发长润。\n\n【开宝】主补虚劳，润五脏，疏风气，治大肠风热结涩，利大小便。 \n\n【孟铣】取汁煮粥去五脏风，润肺，治关节不通，发落，产后余疾。 \n\n【士良】主润五脏，利大肠风热燥结及热淋。 \n\n【日华】补虚劳，逐一切风气；长肌肉，益毛发，通乳汁，止消渴，催生难产。 \n\n【用量】普通钱半至三钱。 \n\n【禁忌】大便溏者禁忌麻仁，患疔肿者忌麻勃，见之致死，用胡麻针砂烛尽为末，醋合敷之，可解。 麻勃药性——主一百二十种恶风，黑色遍身苦痒，逐诸风恶血，治女人经侯不通。  \n\n【附方】 产后秘塞——老人虚秘，麻仁，紫苏子等分，淘净研细，再以水研滤取汁，煮粥饮之。\n\n（本事） 月经不通——二三月或半年者，麻仁，桃仁等分，研匀，老酒浸一宿后，日饮一升．（普济） 发落不生——麻仁研汁煮粥频食之。（圣济总录） 大风癞疾——大麻浸酒，研取白汁，滤去渣，纳瓶中，煮数沸，每饮一杯。（圣惠） 健忘——麻勃一升，人参二两，为末，蒸令气遍，每卧服一刀圭。（范汪）  \n\n【容川】麻仁油滑，而无辛烈之性，故但能润降，不能速下。","videoMemo":"","fangList":[],"bieMing":"麻子仁,火麻仁,麻蕡"}}', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '137、麻蕡 ,麻子仁,火麻仁', '2025-01-15T08:44:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AF5LriF9qfd', 4, '{"title":"第902000538条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>138、冬葵子  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000538,"note":"\n【本经原文】味甘寒，主五脏六腑，寒热羸瘦。五癃，利小便，久服坚骨，长肌肉，轻身延年。 \n\n【产地】处处有之，苗叶做菜茹，味甘美为百菜主。 \n\n【性味】味甘，性寒，无毒。 \n\n【主治】冬葵子为润燥滑肠利窍要药，主通行荣卫，行津液，利二便，下乳滑胎，治癃闭，水肿。 \n\n【别录】疗妇人乳内闭肿痛。 \n\n【孟铣】出痈疽头。 \n\n【弘景】下丹石毒。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】葵菜心有毒伤人不宜食，葵性滑利不益人，病后食之令人失明。 葵菜——功同葵子，孕妇食之，胎滑易生，散脓血，治带下，疗手足长倒生肉刺痛不可  \n忍者奇效。 菜根——功同葵子，小儿吞钱不出，煮汁饮之妙，治疮疽恶毒。  ","videoMemo":"","fangList":[],"bieMing":"冬葵子"}}', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '138、冬葵子', '2025-01-15T08:44:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vfSCZkEwwKr', 4, '{"title":"第902000536条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>136、胡麻  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000536,"note":"\n【本经原文】味甘平，主伤中虚羸，补五内，益气力，长肌肉，填髓脑，久服轻身不老。 \n\n【产地】处处有之，昔从胡来故曰胡麻，今名脂麻，有黑白黄三种，其大者曰巨胜子。 \n\n【性味】味甘，性平，无毒。 \n\n【主治】胡麻主长肌肉，补虚羸，滋润五脏，利大小便，其油亦作解毒用。 \n\n【别录】坚筋骨，明耳目，耐饥渴，疗金疮止痛，及伤寒温疟，大吐后虚热羸困。 \n\n【日华】补中养气，润养五脏，补肺气，止心惊，利大小肠，耐寒暑，逐风湿气，游风头风，治劳气，产后羸困，催生落胞，细研涂发令长，白蜜蒸饵止百病。 \n\n【廷飞】炒食不生风病，风人久食则步履端正，语言不蹇。 \n\n【苏颂】生嚼涂小儿头疮，煎汤浴恶疮；妇人阴疮大效。 \n\n【用量】普通一钱至三钱。  \n\n【禁忌】多用为服食，少以入药，便溏者禁之。 \n\n【容川】麻油因其油质，故主滑利，但性不热，故行缓，无辛，故气不走窜，故下大便也缓。","videoMemo":"","fangList":[],"bieMing":"胡麻"}}', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '136、胡麻', '2025-01-15T08:44:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2A8eoZmcD9a', 4, '{"title":"第902000535条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>135、鸡头实,鸡头米,芡实</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000535,"note":"\n【本经原文】味甘平，主湿痹，腰脊膝痛，补中，除暴疾，益精气强志，令耳目聪明，久服  \n\n【产地】处处有之，产水泽中，俗名鸡头米。 \n\n【性味】味甘淡，性平，无毒。 \n\n【主治】芡实为固本益精要药，主泄泻遗精，带下白浊，治湿痹腰脊膝痛。 \n\n【日华】开胃助气。 \n\n【容川】微甘而涩，能收湿气，故健脾。 \n\n【灵胎】补脾益胃。 \n\n【用量】普通二至三钱。 \n\n【禁忌】生食动冷气，小儿不宜多食，以难化也，故食芡必细嚼，使华液流通，转相灌输，其功胜于乳汁。  ","videoMemo":"","fangList":[],"bieMing":"芡实,鸡头实"}}', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '135、鸡头实,鸡头米,芡实', '2025-01-15T08:44:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('E0kG2mTgYe4', 4, '{"title":"第902000534条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>134、蓬蘽,覆盆子</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000534,"note":"\n【本经原文】味酸平，安五脏，益精气长阴，令坚强志，倍力有子，久服轻身不老．今名覆盆子。  \n\n【产地】处处有之，多生于山野向阳之林木中。 \n\n【性味】味甘酸，性微温，无毒。 \n\n【主治】覆盆子为补涩要药，主益肾脏，缩小便，起阳事，固精液，治遗尿遗精。\n\n【藏器】食之令人好颜色，榨汁涂发不白。 \n\n【甄权】主男子肾精虚竭阴痿，能令坚长，女子食之有子。 \n\n【宗奭】益肾脏，缩小便，取汁同少蜜煎为稀膏，点服治肺气虚寒。 \n\n【括要】补虚续绝，强阴健阳，悦泽肌肤，安和五脏，温中益力，疗劳损风。 \n\n【用量】普通一钱至二至三钱。 \n\n【禁忌】小便短涩者不宜。（今之前列腺肿大或是癌症均不宜。）  ","videoMemo":"","fangList":[],"bieMing":"覆盆子,蓬蘽"}}', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '134、蓬蘽,覆盆子', '2025-01-15T08:44:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eOVMxNkmnQy', 4, '{"title":"第902000533条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>133、蒲萄  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000533,"note":"\n【本经原文】味甘平，主筋骨湿痹：益气倍力，强志，令人肥健耐饥，忍风寒，久服轻身，不老延年，可作酒。  \n\n【产地】处处有之，多种植园区山地之间，美法诸国盛产之。  \n\n【性味】味甘涩，性平，无毒。 \n\n【主治】蒲萄主补身益气养血，治筋骨湿痹，作酒用良。  \n\n【别录】逐水，利小便。  \n\n【甄权】除肠间水，调中治淋。  \n\n【苏颂】时气痘疮不出，食之或研酒饮之效。 \n\n【灵胎】补益筋骨，滋养肌肉。 \n\n【用量】普通做食品，入药无定量。 \n\n【禁忌】多食令人卒烦闷眼暗，东南商人食之多病热，西北人食之无恙。","videoMemo":"","fangList":[],"bieMing":"蒲萄"}}', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '133、蒲萄', '2025-01-15T08:44:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iDRw94FDO7E', 4, '{"title":"第902000531条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>131、藕实,莲子,藕实茎  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000531,"note":"\n【本经原文】味甘平，主补中养神，益气力，除百疾，久服轻身耐老，不饥延年。即莲子也。\n\n【产地】处处有之，产湖泽池塘，家园多种植，花名荷花，亦名莲花，根茎曰藕，叶梗曰荷叶,荷梗，均入药。  \n\n【性味】味甘涩，性平，无毒。  \n\n【主治】莲子为健脾，养胃，清心，固精，资益气血，主补中倍力，除烦养神，治白浊梦遗，女子崩带，疗久痢，脾虚泄泻。  \n\n【孟铣】主五脏不足，伤中，益十二经脉血气。 \n\n【大明】止渴去热，安心止痢。治腰痛及泄精，多食令人欢喜。  \n\n【苏颂】捣碎和米作粥饭食轻身益气，令人强健。  \n\n【嘉谟】安靖上下君相火邪。  \n\n【灵胎】滋血脉，养脾胃。  \n\n【用量】普通三至四钱。  \n\n【禁忌】莲子甘平无毒，于诸疾并无所忤，第生者食之过多，微动冷气胀人，熟者食之过多，涩大便，莲藕忌犯铁。  ","videoMemo":"","fangList":[],"bieMing":"莲子,藕实,藕实茎"}}', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '131、藕实,莲子,藕实茎', '2025-01-15T08:44:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DpuuLDkVqLX', 4, '{"title":"第902000532条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>132、大枣  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000532,"note":"\n【本经原文】味甘平，主心腹邪气，安中养脾，助十二经，平胃气，通九窍，补少气少津液，身中不足，大惊，四肢重，和百药，久服轻身长年。  \n\n【产地】生河东平泽。产我国山东山西河北等省，他处亦有，生枣晒干，即名大枣。  \n\n【性味】味甘，性平，无毒。 \n\n【主治】大枣为补中益气，和解百药要药，主养脾平胃，调荣卫，生津液，润心肺，治虚损。  \n\n【别录】补中益气，坚志强力，除烦闷，疗心下悬。除肠癖。（痢疾的古名)  \n\n【孟铣】小儿患秋痢，与蛀枣食之良。 \n\n【大明】润心肺，止嗽，补五脏，洽虚损，除肠胃癖气。 \n\n【之才】杀乌头附子天雄毒。 \n\n【药征】主治挛急引强急也，旁治咳嗽奔豚烦躁，身疼胁痛，腹中痛。  \n\n【灵胎】补脾和中。  \n\n【用量】普通二至三钱。  \n\n【禁忌】生枣多食，令人热渴膨胀、动脏腑，损脾元，助湿热，忌与葱鱼同食，大枣多食，壅气助湿，凡中满者，小儿疳病者，齿痛及患痰热者，均忌。  \n\n【吴克潜】古方中多用大枣，因欲调和营卫，使气血流通津液输布，百药都须其协助，因此方中多用姜枣甘草等，经云：里不足者，以甘补之，形不足者温之以气，大枣甘温，专补脾胃，令津液自生，使十二经脉皆通畅，今医以温脾健胃时多选用红枣，滋阴养胃则用黑枣，而红枣即大枣，黑枣生于南方，黏液多而温性少，又名南枣，著名方剂有大枣汤（大枣十五枚，附子一枚，甘草一尺，黄耆四两，生姜二两，麻黄五两)治历节疼痛甚良。  \n\n【容川】大枣禀火之赤色，亦入心以养血，肉黄，得火生土之性，故纯于补脾胃。  ","videoMemo":"","fangList":[],"bieMing":"大枣"}}', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '132、大枣', '2025-01-15T08:44:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RvOU9Uunqku', 4, '{"title":"第902000530条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>130、鲤鱼胆  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000530,"note":"\n【本经原文】味苦寒，主目热，赤痛，青盲，明目，久服强悍，益志气．功同青鱼胆。  \n\n【产地】即鲤鱼体内之胆。 \n\n【性味】味苦寒，无毒。 \n\n【主治】主各类目疾，能明目。 \n\n【甄权】鲤鱼胆点眼治赤肿翳痛。 \n\n【肘后】鲤鱼胆点雀目燥痛即明。 \n\n【容川】以类入肝胆，味苦又生水中，正得水性．为治肝胆火之正药，故治喉目。  \n\n【附方】 赤眼肿痛——鲤鱼胆五枚，黄连末半两，和匀，入蜂蜜少许，瓶盛，安饭上蒸熟，每日点目眦，日五七次。 阴痿——鲤鱼胆，雄鸡肝各一枚，为末，雀卵和丸小豆大，每吞一丸。  ","videoMemo":"","fangList":[],"bieMing":"鲤鱼胆"}}', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '130、鲤鱼胆', '2025-01-15T08:44:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Q53xSkjPIJZ', 4, '{"title":"第902000529条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>129、蠡鱼  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000529,"note":"【本经原文】味甘寒，主湿痹，面目浮肿，下大水。 因过去诸多论述，各自意见不同，故今已无人能识，编者认为应是指鲤鱼，因为排列在下一位的药就是鲤鱼胆。 本草衍义亦认为是鲤鱼。  \n\n【产地】江南一带最多，以黑鲤鱼入药为最佳。  \n\n【性味】鲤肉甘味，性平。 \n\n【主治】黑鲤鱼有排水，利尿，消肿之效，治咳逆，黄疸，水肿，脚气肿痛，妊妇水肿。\n\n【别录】鲤鱼煮食治咳逆上气，黄疸，止渴，治水肿脚满，下气。 \n\n【日华】鲤鱼治妊娠身肿，及胎气不安。 \n\n【藏器】鲤鱼作脍温补，去冷气痃癖气块，横关伏梁，结在心腹。  \n\n【用量】为食物，无定量。  \n\n【禁忌】无。  \n\n【附方】 水肿——大鲤鱼一尾，赤小豆一升，同煮食肉饮汁，一顿尽服，当下利，尽即愈 妊妇水肿——如上方。 水肿满胀——鲤鱼一尾，破开不见水及盐，以生白矾末五钱入腹内，火纸包裹，外以黄土泥涂之，煨熟，一日食尽，屡验。  ","videoMemo":"","fangList":[],"bieMing":"蠡鱼"}}', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '129、蠡鱼', '2025-01-15T08:44:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VSPk2jUYkwL', 4, '{"title":"第902000528条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>128、文蛤 </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000528,"note":" 【本经原文】主恶疮，蚀五痔。  \n\n【产地】产东海之滨，壳表有文彩者佳。  \n\n【性味】味咸，性平，无毒。 \n\n【主治】主咳逆胸痹，腰痛胁急，女人崩中漏下，止烦渴，利小便，化痰软坚，敷治口鼻中蚀疳，恶疮五痔。 \n\n【用量】普通一至二钱，外用无定量。 \n\n【禁忌】畏甘遂芫花，虽善消痰积血块，然脾胃虚寒者宜少用。  ","videoMemo":"","fangList":[],"bieMing":"文蛤 "}}', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '128、文蛤', '2025-01-15T08:44:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XmYtPtkfi4x', 4, '{"title":"第902000527条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>127、海蛤  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000527,"note":"\n【本经原文】味苦平，主咳逆上气、喘息烦满，胸痛寒热。  \n\n【产地】产海滨，为蛤类之壳，经海水漂集海边泥沙中者，细小如棋子，光润莹净。  \n\n【性味】味苦咸．性平，无毒。  \n\n【主治】海蛤粉为软坚润下要药，主老痰，热痰，痰气喘咳，消瘿核，散肿毒，止呕逆，利小便，治妇人血病。  \n\n【丹溪】主热痰湿痰老痰顽痰，疝气，白浊带下，香附末姜汁调服，主心痛。  \n\n【用量】普通一至二钱。 \n\n【禁忌】畏甘遂芫花，虽善消痰积血块，然脾胃虚寒者宜少用。  ","videoMemo":"","fangList":[],"bieMing":"海蛤 "}}', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '127、海蛤', '2025-01-15T08:44:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GK4zUe08mpH', 4, '{"title":"第902000526条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>126、桑蜱蛸  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000526,"note":"【本经原文】味咸平，主伤中，疝瘕阴痿，益精生子，女子血闭，腰痛，通五淋，利小便水道。今名桑螵蛸。  \n\n【产地】处处有之，乃螳螂所作房，着生于桑枝上者，入药。  \n\n【性味】味咸甘，性平，无毒。 \n\n【主治】桑蜱蛸为固肾益精要药，主遗尿，滑精，治白浊疝瘕，肾衰阴痿，通五淋，疗便浊。  \n\n【别录】疗男子虚损，四脏气微，梦寐失精，遗溺，久服益气养神。  \n\n【甄权】炮熟空心食之，止小便利。  \n\n【吴克潜】桑螵蛸为小儿梦中遗尿要药，得覆盆子菟丝子益智仁补骨脂等甚效，合龙骨疗滑精，著名方剂有桑螵蛸散（盐灸桑螵蛸远志肉龙骨盐炙菖蒲人参茯神醋炙龟板当归）治男子因女劳，小便日数十次，如稠米泔色，心神恍惚，有实效。  \n\n【灵胎】养血逐瘀，补肾利水。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】凡膀胱有热，小便短数者忌之。  ","videoMemo":"","fangList":[],"bieMing":"桑螵蛸,桑螵蛸"}}', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '126、桑蜱蛸', '2025-01-15T08:44:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('enP2RfKD0cx', 4, '{"title":"第902000525条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>125、龟甲  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000525,"note":"【本经原文】味咸平，主漏下赤白，破症瘕疟痎，五痔阴蚀，湿痹四肢重弱，小儿囟不合。久服轻身不饥。  \n\n【产地】处处有之，生池泽及海水中，其甲即龟甲，肉亦入药。  \n\n【性味】味甘咸，性平，无毒。  \n\n【主治】龟板为益阴滋血要药，主补心肾，益大肠，去瘀血，续筋骨，治久疟，劳复，血痹，湿痹，症瘕，产难，久痢久泻。  \n\n【别录】惊恚气，心腹痛不可久立，骨中寒热，伤寒劳复；或肌体寒热欲死，以作汤良，久服益气资智，烧灰治小儿头疮难燥，女子阴疮。  \n\n【甄权】烧灰治脱肛。  \n【弘景】壳主久嗽，断疟。  \n\n【肃炳】壳炙末酒服，主风脚弱。  \n\n【日华】治血麻痹。 \n\n【丹溪】下甲补阴，主阴血不足，去瘀血，止血痢，续筋骨，治劳倦四肢无力。  \n\n【容川】龟之性伏，其精在板，能通任脉，任为离中之阴，以下交于督，合为既济之象，故龟板益阴滋心肾。与鹿茸是对子。以水配火，不使壮火食气，如此气纳矣。  \n\n【用量】普通二至四钱。 \n\n【禁忌】妊娠及病人虚而无热者，均忌，凡使用时须研极细，否则留滞肠胃，能变症瘕，鳖甲亦然，合猪肉菰米瓜笕食损人。  \n\n常见方剂有大补阴丸，黄柏知母熟地败龟板治阴亏火旺，肺痿咳血，呃逆烦热易饥，骨蒸盗汗，足膝疼热虚劳等症，能降阴火，益肾水，龟鹿二仙膏，败龟板鹿角枸杞人参，主大 补精髓，益气养神，治视物不清，加味芎归汤，治横生倒产，交骨不开。用以催生良。  \n\n【龟肉】味甘酸，性温，无毒。主筋骨疼痛，年久寒嗽，泻血血痢，酿酒治大风缓急，四肢 拘挛，瘫缓不收，煮食治疗身肿痿折。 ","videoMemo":"","fangList":[],"bieMing":"龟甲"}}', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '125、龟甲', '2025-01-15T08:44:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('H4ViI1rZgCc', 4, '{"title":"第902000524条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>124、牡蛎</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000524,"note":"【本经原文】味咸平，主伤寒寒热温疟，洒洒惊恚，怒气除拘，缓鼠瘘，女子带下赤白，久服强骨节 , 杀邪气延年。  \n\n【产地】生东海池泽。产浅海泥沙中，右壳小而薄，左壳大而凸，常连缀重叠，附于岩石。  \n\n【性味】味咸，性平，微寒，无毒。  \n\n【主治】牡蛎为软坚利水，敛汗固肠要药，主益肝肾，除老血，治伤寒，留热在骨间，化痰破积，去胁下坚满。涩大小肠。清热安神。  \n\n【别录】除留热在关节，营卫虚热去来不定，烦满心痛气结，止汗止渴，除老血，疗泄精，涩大小肠，止大小便，治喉痹，咳嗽，心胁下痞热。  \n\n【藏器】粉身止大人小儿盗汗，同麻黄根蛇床子，干姜为粉去阴汗。  \n\n【孟铣】治女子崩中，止痛，除风热风疟，鬼交精出。  \n\n【李珣】男子虚劳，补肾安神，去烦热，小儿惊痫。  \n\n【好古】去胁下坚满，瘰疬，一切疮。  \n\n【药征】主治胸腹之动也，旁治惊狂烦躁。牡蛎黄连龙骨同治烦躁，而各有所主也，心口黄连所主，脐下龙骨所主也，而部位不定，胸腹烦躁者，牡蛎所主也。  \n\n【用量】普通三四钱。 \n\n【禁忌】恶麻黄细辛吴萸伏磠砂，凡病虚而有寒者忌，肾虚无火，寒精自出者亦忌。  \n\n","videoMemo":"","fangList":[],"bieMing":"牡蛎"}}', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '124、牡蛎', '2025-01-15T08:44:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gCCsmD4z6G4', 4, '{"title":"第902000523条・第三章、上经 $a{上药共一百二十种为君主养命以应天，皆无毒多服久服而不伤人，想要轻身益气不老延 年寿者皆须本于上经。}","description":"<p>123、蜜蜡 </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000523,"note":"【本经原文】味甘微温，主下利脓血，补中益气续绝伤，治金创，益气不饥耐老，今用之甚稀。  \n\n【性味】味淡甘，性温。  \n\n【主治】止血，安胎，补益要药，治孕妇胎动下血有殊效，又为硬膏基础剂。  \n\n【甄权】蜜蜡主孕妇胎动，下血不绝欲死，以鸡子大煎三五沸，投美酒半升服立瘥。又主白发镊去，消腊点孔中，即生黑者。  ","videoMemo":"","fangList":[],"bieMing":"蜜蜡"}}', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '2025-01-15T08:44:28.000Z', '123、蜜蜡', '2025-01-15T08:44:28.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'RLI5VpO0qTq');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('u8K7PXvnXGn', 4, '{"title":"第902000601条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>143、雄黄  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000601,"note":"\n【本经原文】味苦平寒、主寒热鼠瘘，恶创疽痔死肌，杀精恶物鬼邪气，百虫毒，胜五兵，炼食之，轻身神仙。  \n\n【产地】产我国西部，南省亦有。  \n\n【性味】味辛苦，性温，有毒。  \n\n【主治】雄黄为蚀疮杀虫要药，主辟邪气，疗诸疮，解毒，为外科要剂，亦可内服。  \n\n【别录】疗疥虫疮，鼻中息肉，及绝筋破骨，百节中大风，积聚癖气，中恶腹痛，鬼疰，诸蛇毒，解藜芦毒。  \n\n【大明】风邪癫痫岚瘴，一切虫兽伤。  \n\n【好古】搜肝气，泻肝风，消涎积。  \n\n【用量】普通内服数分，外用无定量。  \n\n【禁忌】雄黄性热有毒，外用易见长，内服难免害，凡服之中病即止，无过剂也，能柔五金干汞，转硫磺，伏粉霜（以轻粉升成之霜。）与雌黄同，或云雄黄变铁，雌黄变锡。  \n\n【吴克潜】按雄黄于疮痬螫外科，最为急用，以其性能杀虫解毒也，吴俗于五月五日饮雄黄酒，并洒之室角以驱五毒，但须要知道雄黄虽有腐蚀之力，能蚀恶肉以杀虫治疮，但过用终不免侵蚀好肉，故不可多服，外科亦须审慎使用，著名方剂有安虫丸（干漆雄黄巴豆霜），治吐沫水后腹中必虫痛。雄黄解毒丸（巴豆雄黄玉金）治急喉痹咽喉不通，胸膈气促，金锁 匙（朴消雄黄大黄）治一切风热，咽喉闭塞为末，吹入喉中。 ","videoMemo":"","fangList":[],"bieMing":"雄黄"}}', '2025-01-15T08:48:49.000Z', '2025-01-15T08:48:49.000Z', '2025-01-15T08:48:49.000Z', '143、雄黄', '2025-01-15T08:48:49.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PBsevTZ9bqW', 4, '{"title":"第902000618条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>160、瓜篓根 ,天花粉</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000618,"note":"\n【本经原文】味苦寒，主消渴身热，烦满大热，补虚安中，续绝伤。今名天花粉。  \n\n【产地】生弘农川谷。产我国陕西者良，他处亦有之，为山野自生之蔓草，根名天花粉，实名瓜篓实，皮名瓜篓皮，中含仁甚多，名瓜篓仁，俱入药。  \n\n【性味】味甘，性寒，无毒。  \n\n【主治】瓜篓实为润肺降气要药，主袪痰止嗽，涤胸中垢腻，润心肺及胃，治吐血，天花粉主消渴，烦满大热，通乳消肿。  \n\n【别录】主胸痹，悦泽人面。  \n\n【纲目】润肺燥降火，治咳嗽，涤痰结，利咽喉，止消渴，利大肠，消痈肿疮毒。  \n\n【大明】子炒用补虚劳，口干，润心肺，治吐血，肠风泻血，赤白痢。  \n\n【吴克潜】瓜篓根实，皆能润肺治痰，此其同也，其中仁以清胸中痰火，润肠涤秽之功为主，其根治时热大渴，痈疮肿毒。皮能润肠消炎并行。一般治痰剂有宣有下有消有攻有润，而瓜篓实为润也，润剂之别是瓜篓清而润，苏子温而润，莱服子消而润，麦冬补而润，牛蒡杏仁 散而润，补以治痰则有五味子之收敛，除湿健脾以治痰则有半夏之温而燥。  \n\n【倪注】按伤寒杂病论之用根为生津要药，滋润太阳经之燥与胃经之燥，实为去心包积痰之要药。  \n\n【容川】花粉清热，入气分，色白味苦而有液，故泻热之功轻，入胃生津之力重。瓜篓实能治膈间之结气，因篓之膜似人胸之膈膜，又似人腹之象，又治大腹之气，因子有油而气烈，包有瓠而味苦，捣烂合用，能解膈膜之痰火  \n\n【药征】主治胸痹也，旁治痰饮。治消渴。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】脾胃虚寒作泄者忌，恶干姜畏牛膝，反乌头，忌铁。  ","videoMemo":"","fangList":[],"bieMing":"栝蒌,瓜篓根,天花粉"}}', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '160、瓜篓根 ,天花粉', '2025-01-15T09:37:00.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RN1geeYIdB6', 4, '{"title":"第902000617条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>159、葛根 </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000617,"note":"\n【本经原文】味甘平，主消渴，身大热，呕吐，诸痹，起阴气，解诸毒。【葛谷】主下利，治下痢十岁已上。一名鸡齐根。\n\n【产地】生汶山川谷。处处有之，江浙尤多，花名葛花，子名葛谷，根制粉名葛粉，捣汁名葛汁，均入药。\n\n【性味】味甘，性平，无毒。 \n\n【主治】葛根为发汗解肌升阳散火要药，主消渴大热，伤寒中风，治头痛，泄泻，开胃气，解酒毒。 \n\n【别录】疗伤寒中风头痛，解肌发表出汗，开腠理，疗金疮，止胁风痛。 \n\n【甄权】治天行上气呕逆，开胃下食，解酒毒。 \n\n【大明】治胸膈烦热发狂，止血痢，通小便，排脓破血，傅蛇虫毒，毒箭伤。 \n\n【之材】杀野葛巴豆百药毒。 \n\n【藏器】生者堕胎，蒸食消酒毒，可断谷不饥，作粉尤妙。 \n\n【开宝】作粉止渴，利大小便，解酒去烦热，压丹石，傅小儿热疮，捣汁饮治小儿热痞。 \n\n【苏敬】猘狗伤捣汁饮，并末傅之。 \n\n【容川】葛根其根深，能以地中水气，上达于苗叶，其苗极长，象人身之太阳经，从膀胱水  \n中，达阳气于经脉，以卫周身，故入太阳经。葛根气味较平，故发散而不伤血，根深能引水气，上达苗叶，故兼能升津液以治太阳之痉。其根色纯白，属金，又能吸水气上升，是金水相生之物，故又能引津气治阳明之燥，故入太阳阳明二经。与升麻不同，葛根根实，故升津不升气，升麻根空，有孔道以行气，故升气而不升津。  \n\n【药征】主治项背强也，旁治喘而汗出。  \n\n【用量】普通二钱至六钱。  \n\n【禁忌】多用反伤胃气，升散太过也，丹溪曰已见红密点，不可服葛根升麻，恐表虚反增斑 烂。  \n\n【吴克潜】认为葛根为解热之剂，与麻黄桂枝同为伤寒要药，然麻黄发汗解表，乃解太阳皮表之邪以退热，桂枝发汗解肌，乃调和营卫解肌腠之邪以退热，麻黄治表实（汗不得出），桂枝治表虚（汗出恶风），而葛根发汗，主治则在病将由太阳而入阳明，热甚或呕或痢，必须汗出以解之，此三药之发汗不同之处。  \n\n【倪注】葛根为升津之要药，故仲景使用于太阳痉病，与下热痢，因能升津也，口噤用之也因其升津之性也，故伤寒论中之葛根汤实为仲景先师为温病立下之处方，今之温病学家误解仲景先师无温病之识，故曰北方无温病，为南方有之，因此分出温病学，殊不知伤寒论中的葛根汤就是治疗温病的第一优先方。  \n\n【炮制】捡去杂质，劈成0.6—1 厘米厚长条块，去灰屑即得。","videoMemo":"","fangList":[],"bieMing":"葛根"}}', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '159、葛根', '2025-01-15T09:37:00.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('efXc7W97fd4', 4, '{"title":"第902000616条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>158、枲耳实</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000616,"note":"\n【本经原文】味甘温，主风头寒痛，风湿周痹，四肢拘挛痛，恶肉死肌，久服益气，耳目聪明，强志轻身。  ","videoMemo":"","fangList":[],"bieMing":"枲耳实"}}', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '158、枲耳实', '2025-01-15T09:37:00.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pAc2pZflc0h', 4, '{"title":"第902000615条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>157、干姜  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000615,"note":"\n【本经原文】味辛温，主胸满咳逆上气，温中止血，珠汗，逐风湿痹，肠澼下利，生者尤良，久服去臭气通神明。生犍为川谷。  \n\n【性味】味辛，性温，无毒。 \n\n【主治】干姜为除寒散结要药，主温中逐寒，回阳通脉，治四肢逆冷，中寒霍乱，冷痛疝气，寒泻腹痛，开脏腑，宣脉络。  \n\n【甄权】治腰肾间疼痛冷气，破血去风，通四肢关节，开五脏六腑，宣诸络脉，去风毒冷痹，夜多小便。  \n\n【大明】消痰下气，治转筋吐泻肠脏，反胃干呕，瘀血扑损，止鼻红，解冷热毒，开胃消宿食。  \n\n【好古】主心下寒痞，目睛久赤。  \n\n【容川】干姜炮制则温而不烈，性轻而上浮，而四逆理中，则干姜不炮，取其性烈，乃能去寒，能温土中之阳，阳出则阴消，为治寒湿之药，补火之药是火能化水也，故能行血。能补 脾之火，是以土治水。  \n\n【药征】主治结滞水毒也，旁治呕吐咳，下利，厥冷，腹痛，胸痛，腰痛。  \n\n【用量】普通一钱至三钱，大剂上两许。 \n\n【禁忌】生姜干姜炮姜禁忌同，久服伤阴损目，误服劫津耗液，凡阴虚内热，阴虚咳嗽吐血，表虚有热，汗出自汗盗汗，脏毒下血，因热呕恶，火热胀痛均忌。  ","videoMemo":"","fangList":[],"bieMing":"干姜"}}', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '157、干姜', '2025-01-15T09:37:00.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Eh70T59Dern', 4, '{"title":"第902000614条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>156、肤青  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000614,"note":"\n【本经原文】味辛平，主虫毒及蛇，菜肉诸毒，恶创。  ","videoMemo":"","fangList":[],"bieMing":"肤青"}}', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '156、肤青', '2025-01-15T09:37:00.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kGEcp44DUJh', 4, '{"title":"第902000613条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>155、长石  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000613,"note":"\n【本经原文】味辛寒，主身热，四肢寒厥，利小便，通血脉明目去翳眇，下三虫，杀蛊毒久服不饥。  ","videoMemo":"","fangList":[],"bieMing":"长石"}}', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '155、长石', '2025-01-15T09:37:00.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('A3ihtW0KQm2', 4, '{"title":"第902000612条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>154、理石  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000612,"note":"\n【本经原文】味辛寒，主身热利胃，解烦益精，明目，破积聚，去三虫。","videoMemo":"","fangList":[],"bieMing":"理石"}}', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '154、理石', '2025-01-15T09:37:00.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WgYyQ0RCSrs', 4, '{"title":"第902000611条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>153、铁精  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000611,"note":"\n【本经原文】平主明目，化铜铁落，味辛平，主风热，恶创，疡疽创痂，疥气在皮肤中，铁主坚肌耐痛。  \n\n【产地】铁精或铁落为錬铁时锤打所落之皮甲。  \n\n【性味】味辛，性平。 \n\n【主治】铁精为解热，安神，补血药，能除风热，治风痉，癫痫，善怒发狂。  \n\n【苏敬】炒热投酒中饮，疗贼风痉，裹以熨腋下，疗狐臭有验。  \n\n【用量】普通内服一厘至五厘，煎服者虽数钱亦可，近时多用以融化他药中服之。  \n\n【禁忌】铁性重坠，有碍消化，服原质者宜慎之，患肿者服之，一生须忌盐。","videoMemo":"","fangList":[],"bieMing":"铁精"}}', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '153、铁精', '2025-01-15T09:37:00.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mAkaTmKsNlG', 4, '{"title":"第902000610条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>152、殷孽  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000610,"note":"\n【本经原文】味辛温主烂伤瘀血泄利寒热鼠瘘症瘕结气，今少用。","videoMemo":"","fangList":[],"bieMing":"殷孽"}}', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '152、殷孽', '2025-01-15T09:37:00.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('euGJGdIdg2s', 4, '{"title":"第902000609条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>151、孔公孽  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000609,"note":"\n【本经原文】味辛温，主伤食不化，邪结气，恶创疽瘘痔，利九窍，下乳汁。  ","videoMemo":"","fangList":[],"bieMing":"孔公孽"}}', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '151、孔公孽', '2025-01-15T09:37:00.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fp4RUpVyLBw', 4, '{"title":"第902000608条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>150、阳起石  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000608,"note":"\n【本经原文】味咸微温，主崩中漏下，破子臧中血，症瘕结气，寒热腹痛，无子，阴痿不起，补不足。  \n\n【产地】产深山山谷，或曰，惟齐山有之。  \n\n【性味】味咸，性微温，无毒。 \n\n【主治】阳起石为补命门壮阳道要药，功能疗阴痿，男女下部虚冷，补不足。\n\n【别录】疗男子阴头寒，阴下湿痒，去汗臭，消水肿，令人有子。 \n\n【甄权】补肾气，精乏腰痛，膝冷湿痹，子宫久冷，冷症寒瘕，止月水不定。\n\n【大明】治带下瘟疫，冷气，补五劳七伤。  \n\n【好古】补命门火不足。  \n\n【灵胎】助阳益气。  \n\n【用量】普通水飞用，五分至一钱。  \n\n【禁忌】凡阴虚及阳痿属于失志，以致火气闭密，不得发越而然，与崩漏由于火盛，而非虚寒者，均忌，忌羊血，凡使用火灸酒淬七次，研细水飞用，不入汤药，又石药冷热皆有毒（因不易消化），非可久服之物。为云母石之根，其山冬不积雪，夏则生云，积阳上升，故凡病人阳气下陷，阳物不举者，用以升举阳气，此以阳助阳。  \n\n【炮制】拣去杂质，捣碎，置铁锅中，煅透，趁热倒入酒渍淬，取出晾干，研粉即得。  ","videoMemo":"","fangList":[],"bieMing":"阳起石"}}', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '150、阳起石', '2025-01-15T09:37:00.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZPHfyYnDr5a', 4, '{"title":"第902000607条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>149、凝水石  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000607,"note":"\n【本经原文】味辛寒，主身热腹中积聚邪气，皮中如火烧，烦满水饮之，久服不饥，又名寒水石。  \n\n【产地】生于卤地积盐之下，精液渗入土中，年久至泉，结而成石，清莹如水晶，亦有带黑色者。 \n\n【性味】味辛亦做咸，性寒，无毒。 \n\n【主治】凝水石主明目固齿凉血降火，时气热盛，腹中积聚，疗汤火伤（烧研敷）。 \n\n【别录】除时气热盛，五脏伏热，胃中热，止渴，水肿，小腹痹。 \n\n【甄权】压丹石毒风，解伤寒劳复。 \n\n【用量】普通煎剂一钱至三钱。 \n\n【禁忌】性寒，虚寒之体不宜，入肾走血，除热之功与诸盐同，畏地榆，解丹石巴豆毒，制丹砂，伏玄精石。  ","videoMemo":"","fangList":[],"bieMing":"凝水石"}}', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '149、凝水石', '2025-01-15T09:37:00.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('beBSr2G2lNk', 4, '{"title":"第902000606条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>148、慈石,磁石</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000606,"note":"\n【本经原文】味辛寒，主周痹，风湿肢节中痛不可持物，洗洗，酸消，除大热，烦满及耳聋，今名磁石。  \n\n【产地】产山中能吸铁。  \n\n【性味】味辛，性寒，无毒。  \n\n【主治】磁石为补肾强阴要药，取其能引肺气入肾，使阴阳安宅，镇惊，明目，通耳，益精。  \n\n【别录】养肾脏，强骨气，益精除烦，通关节，消痈肿鼠瘘，颈核喉痛，小儿惊痫，炼水饮之。  \n\n【甄权】补男子肾虚风虚身强，腰中不利，加而明之。  \n\n【大明】治筋骨羸弱，补五劳七伤，眼昏，除烦躁，小儿误呑针铁等，即研细末以筋肉莫令断与末同呑下。  \n\n【灵胎】补肾降火，强筋壮骨。  \n\n【用量】入煎剂二钱至四钱，水飞用三分至八分。  \n\n【禁忌】凡石药皆有毒，独磁石冲和无悍猛之气，然体重，难于消化，渍酒优于丸散，凡使火炙醋淬，研末水飞，或醋煮三日夜用，恶丹皮杀铁消金。 久则化铁，为铁之母，药性为，石属金，铁为水，故磁石本兼金水两性，而归于肾，故其主治肾，能自肾中吸引肺金之气，以归于根。  \n\n【炮制】捡去杂质，捣碎，置铁锅中，煅透，趁热倒入醋渍淬，取出晾干，研粉即得。","videoMemo":"","fangList":[],"bieMing":"磁石,慈石"}}', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '148、慈石,磁石', '2025-01-15T09:37:00.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Lags4RQuVce', 4, '{"title":"第902000605条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>147、石膏 </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000605,"note":"\n【本经原文】味辛微寒，主中风寒热，心下逆气，惊喘口干，舌焦不能息，腹中坠痛，除邪鬼，产乳金创，又名寒水石。 \n\n【产地】生齐山山谷。产浙江江苏山东，他省亦有出产。 \n\n【性味】味甘辛，性微寒，无毒。 \n\n【主治】石膏为清凉解热要药，主治肺胃三焦气分之热，大渴热狂，能解肌发汗，又能清热止汗。\n\n【别录】除时气头痛身热，三焦大热，皮肤热，肠胃中结气，解肌发汗，止消渴烦逆腹胀，暴气喘息，咽热，亦可作浴汤。 \n\n【甄权】治伤寒头痛如裂，壮热皮如火燥，和葱煎茶去头痛。 \n\n【大明】治天行热狂头风旋，下乳，揭齿益齿。 \n\n【元素】止阳明经头痛，发热恶寒，日晡潮热，大渴引饮，中暑潮热，牙痛。 \n\n【容川】得石之性多，味虽咸而不甚，且此山之石即能生水，流而为泉，是故此石纯具水性，禀天水之寒，故能清热。 \n\n【药征】主治烦渴，旁治谵语烦躁身热。 \n\n【用量】普通三钱至五钱，大剂二三两。 \n\n【禁忌】伤寒中风太阳症，少阳症之往来寒热等均忌，真寒假热之症或因里虚引起之虚热症亦忌，有金疮下乳亦忌，胃家寒症者亦忌，恶巴豆畏铁。  ","videoMemo":"","fangList":[],"bieMing":"石膏"}}', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '147、石膏', '2025-01-15T09:37:00.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XL3YlWxUfSM', 4, '{"title":"第902000604条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>146、水银 </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000604,"note":"\n【本经原文】味辛寒，主疥瘘痂伤白秃，杀皮肤中虱，堕胎，除热，杀金银铜锡毒，镕化还 复为丹，久服神仙不死。 \n\n【产地】产山西陕西山中。 \n\n【性味】味辛，性寒，有毒。 \n\n【主治】水银为杀虫要药，主治杨梅疮毒，及皮肤诸病，润肠下死胎。 \n\n【别录】以傅男子阴，阴消无气。 \n\n【藏器】利水道，去热毒。 \n\n【大明】主天行热疾，除风，安神，镇心，治恶疮疥，杀虫，催生下死胎。 \n\n【宗奭】治小儿惊痫热潮。 \n\n【灵胎】除湿热，解疮毒。 \n\n【用量】普通多配合丸散方用，内服约数分，外用无定量。 \n\n【禁忌】水银性沉，与金银诸物同，吞服金银水银者，皆足以致命，饵服者须慎之。 ","videoMemo":"","fangList":[],"bieMing":"水银"}}', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '146、水银', '2025-01-15T09:37:00.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('R3NDoqygfDJ', 4, '{"title":"第902000603条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>145、雌黄  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000603,"note":"【本经原文】味辛平，主恶创头秃痂疥，杀毒虫虱，身痒邪气，诸毒炼之，久服轻身，增年 不老。  \n\n【产地】产地同雄黄。  \n\n【性味】味辛性平有毒主恶疮杀虫虱，身痒，邪气诸毒，治身面白驳，散皮死肌，血气虫积 心腹痛，为外科要药，与雄黄功相仿。  ","videoMemo":"","fangList":[],"bieMing":"雌黄"}}', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '145、雌黄', '2025-01-15T09:37:00.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4gweBgGbAWT', 4, '{"title":"第902000602条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>144、石硫黄  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000602,"note":"\n【本经原文】味酸温，主妇人阴蚀，疽痔恶血，坚筋骨，除头秃，能化金银铜铁奇物。  \n\n【产地】产火山地带。 \n\n【性味】味酸，性温，有毒。 \n\n【主治】硫磺为补阳要药，主治脾胃虚寒，寒痹冷癖，命门火衰，能发汗以祛寒痰，及疏利大肠，通常性便秘，杀虫，治疮疥。\n\n【别录】疗心腹积聚，邪气冷痛在胁，咳逆上气，脚冷疼弱无力，及鼻衄，恶疮下部虫疮，止血杀疥虫。 \n\n【甄权】下气，治腰肾久冷，除冷风顽痹，寒热，生用治疥癣，炼服主虚损泄精。 \n\n【大明】壮阳道，补精骨劳损，风劳气，止嗽，杀脏虫邪鬼。 \n\n【吴普】治妇人血结。 \n\n【李珣】长肌肤，益气力，老人风秘，并宜炼服。 \n\n【容川】能燃，是水中之火也，其味酸，是得木味，水中之阳，发则为木，故味酸而能燃，又是水中之木也，为温下焦肝肾之猛药。 \n\n【灵胎】驱寒燥湿。杀虫化金。 \n\n【用量】普通五分至二钱。 \n\n【禁忌】硫磺为救急妙药，但中病便当已，不可尽剂，畏细辛朴消，中硫磺毒，黑铅煎汤解之，或是食鸭肉可解之。  ","videoMemo":"","fangList":[],"bieMing":"石硫黄"}}', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '2025-01-15T09:37:00.000Z', '144、石硫黄', '2025-01-15T09:37:00.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8NK6Z8TTDz0', 4, '{"title":"第902000624条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>166、蠡实 </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000624,"note":"\n【本经原文】味苦，平，无毒。治皮肤寒热，胃中热气。风寒湿痹。坚筋骨，令人嗜食。久服轻身。花、叶，去白虫，喉痹。一名剧草。一名三坚。一名豕首。又名马蔺子。  \n\n【产地】产我国陕西河南一带多有之，为山野自生之宿根草，实入药。  \n\n【主治】蠡实主治皮肤寒热，一切疮疖，产后血晕，寒疝诸疾，利大小便。  \n\n【别录】止心烦满，利大小便，长肌肤肥大。  \n\n【苏敬】疗金疮血内流，痈肿有效。 \n\n【大明】妇人血气烦闷，产后血晕，并经脉不止，崩中带下，消一切疮疖，止鼻衄吐血，通小肠，消酒毒，治黄病，杀蕈毒，傅蛇虫咬。  \n\n【用量】普通一钱至三钱。\n\n【禁忌】不详。","videoMemo":"","fangList":[],"bieMing":"蠡实"}}', '2025-01-15T14:36:14.000Z', '2025-01-15T14:36:14.000Z', '2025-01-15T14:36:14.000Z', '166、蠡实', '2025-01-15T14:36:14.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xdiIF8rAwKq', 4, '{"title":"第902000623条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>165、芍药  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000623,"note":"\n【本经原文】味苦，平，有小毒。治邪气腹痛，除血痹，破坚积，寒热，疝瘕，止痛，利小便，益气。一名白木。  \n\n【产地】处处有之，为多年生草本，山野自生，或种植，因芍药花美也，根做纺锤形，外淡褐色而内白色，其稍赤者名赤芍。  \n\n【性味】味苦酸，性平，无毒。  \n【主治】白芍为泻肝安脾，缓中去水要药，功能养血散瘀清热利肠，止腹痛，治痢疾，治胎产前后诸病，为女科良药。 【别录】通顺血脉，缓中散恶血，逐贼血，去水气，利膀胱大小肠，消痈肿，时行寒热，中恶，腹痛腰痛。 【大明】女人一切病，胎前产后诸疾，治风补劳，退热除烦，益气，惊狂头痛目赤，明目，肠风泻血，痔瘘，发背，疮疥。 \n\n【元素】泻肝安脾，收肺气，止泻痢，固腠理，和血脉，收阴气敛逆。 \n\n【好古】理中气治脾虚中满，心下痞，胁下痛，善噫，肺急胀逆，喘咳，太阳鼻衄，目涩肝血不足，阳维病苦寒热，带脉病苦腹痛满，腰溶溶如坐水中。（血痹即血凝于肌肤而为痹）。【容川】为春之花，而根微酸，故主能敛肝木，降火行血。苦性较轻，故白芍只微降，大黄则降力大。味苦能泻血，其色白，故又能行气分之水。 \n\n【药征】主治结实而拘挛，旁治腹痛头痛，身体不仁，疼痛腹满，咳逆下利肿脓。  \n\n【用量】普通二钱而五钱，大剂一两以上。 \n\n【禁忌】凡中寒腹痛，中寒作泄，肠胃中觉冷，均忌，反藜芦恶芒硝，鳖甲，小蓟。  ","videoMemo":"","fangList":[],"bieMing":"芍药"}}', '2025-01-15T14:36:14.000Z', '2025-01-15T14:36:14.000Z', '2025-01-15T14:36:14.000Z', '165、芍药', '2025-01-15T14:36:14.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DwRpRQNL08a', 4, '{"title":"第902000622条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>164、通草  ,白通草</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000622,"note":"\n【本经原文】味辛，平，无毒。主去恶虫，除脾胃寒热，通利九窍、血脉、关节，令人不忘。一名附支。又名白通草。  \n\n【产地】生石城山谷。产于江南，多生山侧，茎入药。 \n\n【性味】味甘淡，性平，无毒。 \n\n【主治】通草为利水退热要药，主泄肺热利阴窍，舒胃气，除水肿，治五淋，下乳催生。\n\n【东垣】主利阴窍，治五淋，除水肿癃，泻肺。 \n\n【苏颂】解诸毒，虫毒。 \n\n【汪机】明目退热，下乳催生。 \n\n【用量】普通五分至一钱。 \n\n【禁忌】虚脱之人与孕妇禁忌。 \n\n【容川】白通草象人身之油膜，故能通达油膜，上可以通乳，下可以通小便。","videoMemo":"","fangList":[],"bieMing":"通草"}}', '2025-01-15T14:36:14.000Z', '2025-01-15T14:36:14.000Z', '2025-01-15T14:36:14.000Z', '164、通草 ,白通草', '2025-01-15T14:36:14.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ne2q77tkodu', 4, '{"title":"第902000621条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>163、麻黄 </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000621,"note":"\n【本经原文】味甘，温，无毒。治中风，伤寒，头痛。温疟，发表出汗，去邪热气，止咳逆上气，除寒热，破症坚积聚。一名龙沙。 \n\n【产地】我国西北部皆有出产，生晋地。以山西大同为最良，其它如印度及西伯利亚南非洲皆有产。\n\n【性味】味苦，性温散，无毒。 \n\n【主治】麻黄为发汗解散要药，功能退热平喘利水，主伤寒表实无汗，治肺实喘逆，通利水道。  \n\n【别录】五脏邪气缓急，风胁痛，止好睡，通腠理，解肌泄邪恶气，消赤黑斑毒，不可多服，令人虚。  \n\n【甄权】治身上毒风疹痹，皮肉不仁，主壮热温疫，山岚瘴气等。  \n\n【大明】通九窍，调血脉，开毛孔皮肤。  \n\n【元素】去营中寒邪，泄卫中风热。  \n\n【纲目】散赤目肿痛，水肿风肿，产后血滞。  \n\n【容川】虽其茎直上，但却如草之丛生，故能上升又能外散，其茎空，直达而上，且无大味，纯得天轻阳之气，故专主气分。一般取其苗，以其苗细长中空，象人毛孔，而气轻扬，故能发汗，能通阳气，直走鼻皮毛，其根坚实味涩，故能止汗。  \n\n【炮制】捡去杂质，去尽木质及残根，喷淋清水，微润，切 1.5  厘米段片，晒干或烘干，去 灰即得。  \n\n【药征】主治喘咳水气也，旁治恶风恶寒，无汗，身疼，骨节痛，一身黄肿。  \n\n【灵胎】发汗止喘。  \n\n【用量】普通五分至一钱，大剂三钱。 \n\n【禁忌】平日阳虚，腠理不密之人忌之，诸虚有汗，肺虚痰嗽，气虚发喘，均忌。  \n\n【倪注】麻黄为发汗第一要药，能退热平喘利水，皆其解散之功，凡风寒初袭肌表，不得解散则发为头痛项强恶寒诸症状，发其汗则风寒得以解散，诸症自除，举凡外感初起之发热，多由汗不得出，因势利导使汗出而热解，此本经之所言去邪热也，又肺受风寒不解，则咳气上逆，用麻黄利水道，外为发汗，是故痰水因而下行，风寒因而得以宣泄，因病根解除，咳气上逆自愈，若以之点眼，可使瞳孔放大，此因其能散。今麻黄配桂枝能散营分之寒邪，配膏能泄卫分之风热，皮肉不仁，著名方剂如麻黄汤，麻杏甘石汤，大青龙汤。因麻黄根能止汗，节亦止汗，故欲发汗，则须去根与节。","videoMemo":"","fangList":[],"bieMing":"麻黄"}}', '2025-01-15T14:36:14.000Z', '2025-01-15T14:36:14.000Z', '2025-01-15T14:36:14.000Z', '163、麻黄', '2025-01-15T14:36:14.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Bfbf2ItEm31', 4, '{"title":"第902000620条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>162、当归  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000620,"note":"\n【本经原文】味甘，温，无毒。治咳逆上气，温疟，寒热洒洒在皮肤中。妇人漏下，绝子。诸恶疮疡，金疮。煮饮之。一名干归。 \n\n【产地】我国西部皆有出产，以陕西四川为最良。 \n\n【性味】味甘苦辛，性温，无毒。 \n\n【主治】当归为补血清血要药，主一切血虚血浊，治瘘弱，痹痛，诸疮，破恶血，生新血，补女子诸不足，为调经良药。 \n\n【别录】温中止痛，除客血内塞，中风痉汗不出，湿痹中恶，客气虚冷，补五脏，生肌肉。\n\n【甄权】止呕逆虚劳寒热，下痢腹痛，齿痛，女人沥血腰痛，崩中补诸不足。 \n\n【大明】治一切风一切气，补一切劳，破恶血养新血，及症癖胃冷。 \n\n【好古】主瘘痹嗜卧，足下热痛，冲脉为痛，气逆里急，带脉为病，腹痛腰溶溶如坐水中。\n\n【容川】当归辛苦，得地火之味，其气微温，得木之性，质多油，此因得地之湿，故能助心生血，以行于肝，其功专生血。归首之性升，故主生血，尾之性降，故主行血，性温润，可以去寒结。风能胜湿，风伤血则筋燥，当归能润燥。其味辛温，火也，其汁油润，水也，一物而具二者，是水交于火所化之物也，恰与血之生化相同，故主补血。 \n\n【灵胎】补血养血，润肺润肠。 \n\n【用量】普通二钱至五钱，大剂一至二两。 \n\n【禁忌】性滑润，泄泻者慎用，脾胃薄弱者忌，用时须它药来佐。  ","videoMemo":"","fangList":[],"bieMing":"当归"}}', '2025-01-15T14:36:14.000Z', '2025-01-15T14:36:14.000Z', '2025-01-15T14:36:14.000Z', '162、当归', '2025-01-15T14:36:14.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0NTANxx0JVV', 4, '{"title":"第902000619条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>161、苦参  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000619,"note":"\n【本经原文】味苦寒，主心腹结气，症瘕积聚，黄疸，溺有余沥，逐水，除痈肿，补中，明目，止泪。 \n\n【产地】产河南四川，各地山野及田畔湿地亦俱有之，根黄白色类牛蒡，甚苦，入药。  \n\n 【性味】味苦，性寒，无毒。 \n\n【主治】苦参为燥湿胜热健胃杀虫积要药，主治积聚，症瘕，恶疮，疳症，泄血中热，清湿 养阴。 \n\n【别录】养肝胆气，安五脏，除伏热，肠澼，止渴，醒酒，小便黄赤，疗恶疮下部虫。 \n\n【甄权】治热毒风，皮肌烦躁，生疮，赤癞，眉脱，除大热，嗜睡，治腹中冷痛，中恶腹痛。\n\n【弘景】渍酒饮治疥杀虫。 \n\n【苏敬】治恶虫胫酸。 \n\n【纲目】杀疳虫，炒存性，米饮服，治肠风泻血并热痢。 \n\n【括要】遍身风疹，痛不可忍，肺热生疮，遍身皆是；瘰疬结核，下部疮瘺，诸般实症用之有效。 \n\n【灵胎】清心肝火，去小肠热。  \n\n【用量】普通一钱至三钱。  \n\n【禁忌】久服损肾气，肝肾虚而无大热者忌。  ","videoMemo":"","fangList":[],"bieMing":"苦参"}}', '2025-01-15T14:36:14.000Z', '2025-01-15T14:36:14.000Z', '2025-01-15T14:36:14.000Z', '161、苦参', '2025-01-15T14:36:14.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('blwKN7ZBo5j', 4, '{"title":"第902000679条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>221、合欢  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000679,"note":"\n【本经原文】味甘，平，无毒。主安五脏，和心志，令人欢乐无忧。久服轻身，明目，得所欲。生山谷。一名蠲忿，一名夜合。  \n\n【产地】山中有之。皮供药用。 \n\n【性味】合欢皮味甘，性平。 \n\n【主治】为合血，消肿，止痛药，治筋骨折伤及肺痈吐脓。 \n\n【大明】煎膏消痈肿，续筋骨。 \n\n【用量】一般二至四钱。 \n\n【禁忌】无禁忌。  ","videoMemo":"","fangList":[],"bieMing":"合欢"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '221、合欢', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RuCDdd9UAQG', 4, '{"title":"第902000678条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>220、卫矛,鬼箭,神箭  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000678,"note":"\n【本经原文】味苦，寒，无毒。治女子崩中下血，腹满，汗出，除邪，杀鬼毒，蛊疰，生山谷。一名鬼箭。又名神箭。  \n\n【产地】处处有之。 \n\n【性味】味苦涩，性寒。 \n\n【主治】为调经止痛要药，治女子崩中，产后腹绞痛。 \n\n【别录】主中恶腹痛，去白虫，消皮肤风毒肿。令阴中解。 \n\n【甄权】破陈血，能落胎。 \n\n【大明】通月水，破症结，止血崩带下，杀腹臓虫，及产后血绞腹痛。\n\n【苏敬】疗妇人血气大效。 \n\n【用量】一般一钱至三钱。 \n\n【禁忌】寒利者禁用。  ","videoMemo":"","fangList":[],"bieMing":"卫矛,鬼箭,神箭"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '220、卫矛,鬼箭,神箭', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5oudc9oILw6', 4, '{"title":"第902000677条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>219、松萝,女萝,菘萝  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000677,"note":"\n【本经原文】味苦，平，无毒，治嗔怒，邪气，止虚汗，头风，女子阴寒肿痛。生川谷松树上。一名女萝。一名菘萝。  \n\n【产地】松树上之地衣植物。 \n\n【性味】味苦，性平。 \n\n【主治】为祛痰，涌吐药，可以吐痰涎，治温疟，项瘿及女子阴寒肿痛。 \n\n【别录】疗痰热温疟，可为吐汤，利水道。 \n\n【甄权】治寒热，胸中客热痰涎，去头疮，项上瘿瘤，令人得眠。 \n\n【用量】一般二至四钱。 \n\n【禁忌】呕家禁用。  ","videoMemo":"","fangList":[],"bieMing":"松萝,女萝,菘萝  "}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '219、松萝,女萝,菘萝', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('M8sIlGd4B5I', 4, '{"title":"第902000676条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>218、龙眼  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000676,"note":"\n【本经原文】味甘，平，无毒。治五脏邪气，安志，厌食。久服强魂魄，聪明，轻身，不老，通神明。生南海山谷。一名益智。 \n\n【产地】产我国福建四川广东等地，实形圆，故名。 \n\n【性味】味甘，性平，无毒。 \n\n【主治】龙眼为滋养要药，主益脾长肌，养心安神，治血虚怔忡劳神健忘。 \n\n【别录】主五脏邪气，安志厌食，除蛊毒，去三虫。 \n\n【括要】主补血气，养肌肉，益虚气，除健忘，治怔忡，开胃益脾，补虚长智。 \n\n【用量】普通二至三钱。  \n\n【禁忌】甘能作胀，凡中满气膈之证均忌。  ","videoMemo":"","fangList":[],"bieMing":"龙眼"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '218、龙眼', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('X1m1IBFOTNv', 4, '{"title":"第902000675条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>217、白棘  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000675,"note":"\n【本经原文】味辛，寒，无毒。治心腹痛，痈肿溃脓，止痛。生川谷。一名棘针  ","videoMemo":"","fangList":[],"bieMing":"白棘"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '217、白棘', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5WD0KLGnhCG', 4, '{"title":"第902000674条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>216、猪苓  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000674,"note":"\n【本经原文】味甘，平，无毒。治痎疟，解毒，蛊疰不祥。利水道。久服轻身，耐老。生山谷。一名猳猪屎。  \n\n【产地】生衡山川谷。产我国四川及其它省山中，多生枫根下，结成块状。 \n\n【性味】味甘，性平，无毒。 \n\n【主治】猪苓为行水渗湿要药，主肿胀腹满，热渴懊憹，治淋肿，白浊子淋，尿闭，开腠理，泻膀胱。 \n\n【甄权】解伤寒瘟疫大热，发汗，主肿胀满腹急痛。 \n\n【元素】治渴除湿，去心中懊憹。 \n\n【好古】泻膀胱。 \n\n【药征】主治渴而小便不利也。 \n\n【用量】普通钱半至三四钱。 \n\n【禁忌】猪苓利水之功多，久服必损肾气，昏人目，元素曰，淡渗大燥，能亡津液，无湿者忌之。 ","videoMemo":"","fangList":[],"bieMing":"猪苓"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '216、猪苓', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Xh9ASvLj8PF', 4, '{"title":"第902000673条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>215、紫葳  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000673,"note":"\n【本经原文】味酸，微寒，无毒。治妇人产乳余疾，崩中，症瘕，血闭，寒热，羸瘦，养胎。生西海川谷及山阳。一名芺华，一名陵苕。 \n\n【产地】产山野，或栽植庭园，亦名凌霄花。 \n\n【性味】味酸，性微寒，无毒（或作有毒）。 \n\n【主治】紫葳主行血通经，祛瘀血，治淋沥，清血中伏火。 \n\n【甄权】产后奔血不定，淋沥，主热风风痫，大小便不利，肠中结实。 \n\n【大明】酒齄热毒风，刺风，妇人血膈游风崩中带下。 \n\n【用量】普通一至二钱。 \n\n【禁忌】花不可进鼻闻，伤脑，花上露入目昏蒙。  ","videoMemo":"","fangList":[],"bieMing":"紫葳"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '215、紫葳', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UH1rMGTzh7D', 4, '{"title":"第902000672条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>214、山茱萸  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000672,"note":"\n【本经原文】味酸，平，无毒。治心下邪气，寒热，温中，逐寒湿痹，去三虫，久服轻身。生山谷。一名蜀枣。  \n\n【产地】产我国山东河南等地，与吴茱萸甚不相类，树实入药。  \n\n【性味】味酸，{或辛酸}，性平，或作性温，无毒。  \n\n【主治】山茱萸为滋阴助阳，养血涩精要药。主逐寒湿痹，安五脏，通九窍，暖腰膝，添精髓，治阳痿遗精，血弱体痛。  \n\n【别录】肠胃风邪，寒热疝瘕，头风，鼻塞，目黄耳聋，面疱下气，出汗强阴，益精，安五脏，通九窍，止小便利，久服明目强力。  \n\n【甄权】治脑骨痛，疗耳鸣，补肾气，兴阳道，坚阴茎，添精髓，止老人尿不节，治面上疮，能发汗，止月水不定。  \n\n【大明】暖腰膝，助水脏，除一切风，逐一切气，破症结。  \n\n【元素】温肝。 \n\n【用量】普通一钱至二至三钱。  \n\n【禁忌】命门火燥，强阳不痿者，膀胱热结，不宜用，即用，当与黄柏同功。\n\n【容川】山茱萸酸而质润，故专入肝，滋养阴血。  ","videoMemo":"","fangList":[],"bieMing":"山茱萸"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '214、山茱萸', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('K9dbfB5B9g5', 4, '{"title":"第902000671条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>213、秦椒  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000671,"note":"\n【本经原文】味辛，温，有毒。治风邪气，温中，除寒痹，坚齿，长发，明目。久服轻身，好颜色，耐老，增年，通神。生川谷。  \n\n【产地】椒之一种，产我国陕西甘肃，今处处有之。  \n\n【性味】味辛，性温，有毒。 \n\n【主治】秦椒主温中去寒，除风邪气，治风湿痹，喉痹吐逆，疝瘕老血。 \n\n【别录】疗喉痹，吐逆，疝瘕，去老血，产后余疾，腹痛，出汗，利五脏。 \n\n【甄权】治恶风遍身四肢，疗痹，口齿肿胀摇动，女人月闭不通，产后恶血痢，多年痢，疗腹中冷痛，生毛发，灭瘢。 \n\n【用量】普通五分至钱半。 \n\n【禁忌】用椒红，去目，恶栝楼防葵，畏雌黄，闭口者有毒勿用。参看蜀椒条。 ","videoMemo":"","fangList":[],"bieMing":"秦椒"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '213、秦椒', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cummDeeVDxz', 4, '{"title":"第902000670条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>212、秦皮  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000670,"note":"\n【本经原文】味苦，微寒，无毒。治风寒湿痹，洒洒寒气，除热，目中青翳，白膜。久服头不白，轻身。生川谷。  \n\n【产地】生庐江川谷。产我国陕西河南等地，树皮入药。  \n\n【性味】味苦，性寒，无毒。  \n\n【主治】秦皮为收敛除热要药，主痢疾带下，男子少精，治风湿痹，目中翳膜，除肝热，补下焦。  \n\n【别录】疗男子少精，妇人带下，小儿痫身热，可作洗目汤，久服皮肤光泽肥大有子。  \n\n【甄权】痛风泪不止，作汤浴小儿身热，煎水澄清洗赤目极效。 \n\n【容川】此药象人之皮，味苦兼降湿热。故仲景用治皮肤发黄之症。\n\n【用量】一般二至五钱。 \n\n【禁忌】里寒之症不用。  ","videoMemo":"","fangList":[],"bieMing":"秦皮"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '212、秦皮', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BqzQHC4ggav', 4, '{"title":"第902000669条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>211、厚朴  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000669,"note":"\n【本经原文】味苦，温，无毒。治中风，伤寒，头痛，寒热，惊悸气，血痹，死肌，去三虫。生山谷。  \n\n【产地】生交趾山谷。产我国四川河南陕西湖南等地，树皮入药，以厚肉者为良。  \n\n【性味】味苦辛，性温，无毒。 \n\n【主治】厚朴为下实散满，袪湿健胃要药，主温中益气，消痰下气，气血痹，湿霍乱，治中风伤寒头痛，反胃，冷痛，腹满喘咳，杀肠中虫。  \n\n【别录】温中益气，消痰下气，疗霍乱及腹痛胀满，胃中冷逆，胸中呕不止，泄痢淋露，除惊去留热，心烦满，厚肠胃。  \n\n【甄权】治积年冷气，腹内雷鸣虚吼，宿食不消，去结水，破宿血，化水谷，止吐酸水，大温胃气，治冷痛，主妇人虚而尿白。  \n\n【大明】健脾，治反胃霍乱转筋冷热气，泻膀胱及五脏一切气，妇人产前产后腹脏不安，杀肠中虫，明耳目，调关节。  \n\n【好古】主肺气胀满，膨而喘咳。  \n\n【药征】主治胸腹涨满也，旁治腹痛。  \n\n【容川】厚朴本皮，味比枳壳更重，故理脾气，故仲景用枳壳治心下满，用厚朴治腹痛，此为此二药轻重之别所在。厚朴行大肠之气，故肺气得泄。仲景治喘有桂枝加厚朴杏仁汤，即因于此。  \n【用量】普通七分至二钱。 \n\n【禁忌】恶泽泻磁石寒水石，忌豆，性能耗气，凡脾胃虚者忌之，孕妇无故亦忌用。  ","videoMemo":"","fangList":[],"bieMing":"厚朴"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '211、厚朴', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('os7ajA6jPG2', 4, '{"title":"第902000668条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>210、枳实  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000668,"note":"\n【本经原文】味苦，寒，无毒。治大风在皮肤中，如麻豆苦痒，除寒热结，止利，长肌肉，利五脏，益气轻身。生川泽。  \n\n【产地】生河内川泽。产陕西河南等地，周礼有云，橘逾淮而为枳，即此是也，其实成熟时，早采者为枳实，皮厚而中坚；晚采者为枳壳，皮薄而中虚，皆入药。  \n\n【性味】味苦，性寒，无毒。  \n\n【主治】枳实为破气行痰要药，主破结实，消胀满，治胸胁痰癖，心下痞痛，消食散血，去胃中湿热。  \n\n【别录】除胸胁痰癖。逐停水，破结实，消胀满，心下急痞痛逆气，胁风痛，安胃气，止溏 泄，明目。  \n\n【甄权】解伤寒结胸，主上气喘咳，肾内伤冷，阴痿而有气加而用之。  \n\n【元素】消食，散败血，破积坚，去胃中湿热。 \n\n【药征】主治结实之毒，旁治胸满胸痹，腹满腹痛。  \n\n【用量】普通八分至二钱。  \n\n【禁忌】肺气虚弱，脾胃虚，中气不运，而痰壅喘急，咳嗽不因风寒入肺气壅，及咳嗽阴虚 火炎，与一概胎前产后，均忌。  \n\n【容川】枳壳为木实，有木之质，木能疏土，故归脾胃，其味比厚朴轻，故理胃气。 ","videoMemo":"","fangList":[],"bieMing":"枳实"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '210、枳实', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('O2z8rLjrJtF', 4, '{"title":"第902000667条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>209、芜荑  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000667,"note":"\n【本经原文】味辛，平，无毒。治五内邪气，散皮肤骨节中淫淫行毒，去三虫，化食，逐寸 白，散腹中嗢嗢喘息。生川谷，一名芜菇。  ","videoMemo":"","fangList":[],"bieMing":"芜荑"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '209、芜荑', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JVAZQ2H8wGt', 4, '{"title":"第902000666条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>208、栀子,木丹  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000666,"note":"\n【本经原文】味苦，寒，无毒。治五内邪气，胃中热气，面赤，酒疱皶鼻，白癞，赤癞，疮 疡。生川谷。一名木丹。  \n\n【产地】生南阳川谷。处处有之，我国南方及四川尤多产，实又名卮子盖象卮形也。  \n\n【性味】味苦，性寒，无毒。  \n\n【主治】栀子为泻火要药，主五内邪气时热，心烦懊憹，泻三焦火，清胃脕血，治五种黄病，通小便，解消渴。  \n\n【别录】疗目赤热疮，胸心大小肠大热，心中烦闷。  \n\n【甄权】去热毒风，除时疾热，解五种黄病，利五淋，通小便，解消渴，明目，主中恶，杀蟅虫毒。  \n\n【元素】治心烦懊憹不得眠，脐下血滞而小便不利。  \n\n【丹溪】泻三焦火，清胃脕血，治热厥心痛，解热郁，行结气。  \n\n【容川】栀子味苦象心包。故能泻心包之火。性苦寒，有皮膈，象心包，内之子赤，正属心之色，其花色白，当属肺金，结子成赤，当属心火，是为从肺入心，正治心中烦热之药。心为君主之官，肺为相傅之官，以制节心火之太过，栀子花白子赤，正是以肺金而归制心火也，故仲景治心中懊憹必用栀子豆豉汤。  \n\n【药征】主治心烦也，旁治发黄。\n\n【灵胎】清胃热，泻肺火。 \n\n【用量】普通一钱至三钱。  \n\n【禁忌】凡脾胃虚弱，血虚发热，心肺无邪热，小便闭由膀胱气虚，均忌。  ","videoMemo":"","fangList":[],"bieMing":"栀子,木丹"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '208、栀子,木丹', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nhe5ZTFUUgO', 4, '{"title":"第902000665条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>207、吴茱萸  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000665,"note":"\n【本经原文】味辛，温，有小毒。主温中，下气，止痛，咳逆，寒热，除湿，血痹，逐风邪，开腠理。根，温，杀三虫。久服轻身。生川谷。一名藙。  \n\n【产地】生上谷川谷。处处有之，或曰，吴地最良，故名，其子紧小，气味芳烈。  \n\n【性味】味辛，性温，有小毒。  \n\n【主治】吴茱萸为下气开郁，除风寒湿要药，主温中逐寒，驱风散热，止痛疗痹，治心腹冷痛，下焦冷气，中寒中恶，呕吐泻利，亦杀虫，治口舌生疮。  \n\n【别录】利五脏，去痰冷逆气，饮食不消，心腹诸冷绞痛，中恶心腹痛。  \n\n【甄权】霍乱转筋，胃冷吐泻，腹痛，产后心痛，治遍身瘰痹刺痛。腰脚软弱，利大肠壅气，肠风痔疾，杀三虫。  \n\n【大明】下产后余血，治肾气脚气，水肿，通关节，起阳健脾。  \n\n【容川】味辛气烈，去湿极速。 \n\n【好古】治痞满塞胸，咽膈不通，润肝燥脾。  \n\n【药征】主治呕而胸满。  \n\n【灵胎】驱肝风，逐肺寒。  \n\n【用量】普通三分至钱半。  \n\n【禁忌】多食伤神，令人起伏气，咽喉不通，动火昏目发疮，恶丹参硝石白垩，畏紫石英，凡一切阴虚之证，及五脏六腑有热无寒之人，均忌用吴茱萸。  \n\n【容川】吴茱萸辛而带苦，子性又主下降，故主降水饮，行滞气。专治肝寒之吐逆，此药虽不上头，然可以降肝胃之寒，使不上冲入头，故仲景用之治头痛如破，此为治脏腑而经脉自治也。  ","videoMemo":"","fangList":[],"bieMing":"吴茱萸"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '207、吴茱萸', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7zODc43fKQm', 4, '{"title":"第902000664条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>206、竹叶  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000664,"note":"\n【本经原文】味苦，平，无毒。治咳逆上气，溢筋急，恶疡，杀小虫。根，作汤，益气，止渴，补虚，下气。汁，治风痉。实，通神明，轻身，益气。  \n\n【产地】为暖地山中之常绿苞木。 \n\n【性味】味辛平，性寒。 \n\n【主治】竹叶为解热，祛痰，止渴，镇静药，止消喝，热狂烦闷及小儿警痫。压丹石毒。  \n\n【别录】治胸中痰热，咳逆上气。  \n\n【大明】消痰，治狂热烦闷，中风失音不语，壮热，头风，头痛，止惊悸，温痔烦闷，妊妇头旋倒地，小儿惊痫天吊。  \n\n【容川】因叶在四旁，则主四散，故能清肌中之热，竹茹象人之筋脉，则清脉络之热以和血，秉天水之寒气，故治一切热。  \n\n【用量】五钱至一两。  \n\n【禁忌】寒症忌用。  ","videoMemo":"","fangList":[],"bieMing":"竹叶"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '206、竹叶', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sFjc12wCQjG', 4, '{"title":"第902000663条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>205、桑根白皮,桑白皮</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000663,"note":"\n【本经原文】味甘，寒，无毒。治伤中，五劳，六极，羸瘦，崩中，脉绝，补虚益气。叶，主除寒热，出汗。桑耳，平。黑者。治女子漏下赤白汁，血病，症瘕积聚，阴痛，阴阳寒热，无子。（王不留行散）  \n\n【产地】处处有之，其根皮入药。  \n\n【性味】味甘辛，性寒，无毒。  \n\n【主治】桑白皮为泻肺火行水道要药，主肺气喘满伤中，益气，开胃，消痰，解渴，治咳嗽吐血，去肺中水气，水肿腹满。  \n\n【别录】去肺中水气，唾血，热渴，水肿腹满胪胀，利水道，去寸白，可以缝金疮。  \n\n【甄权】治肺气喘满，虚劳客热，头痛，内补不足。 \n\n【大明】调中下气，消痰止渴，开胃下食，杀腹脏虫，止霍乱吐泻，研汁治小儿天吊惊痫客忤。及敷鹅口疮，大验。  \n\n【用量】普通一钱至三钱。 \n\n【禁忌】肺虚无火，因风寒而嗽者均忌。  ","videoMemo":"","fangList":[],"bieMing":"桑白皮,桑根白皮 "}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '205、桑根白皮,桑白皮', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5KcF3uF9AvH', 4, '{"title":"第902000662条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>204、翘根  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000662,"note":"\n【本经原文】味甘，寒，有小毒。治下热气，益阴精，令人面悦好，明目。久服轻身，耐老。生平泽。  ","videoMemo":"","fangList":[],"bieMing":"翘根"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '204、翘根', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('O4e0egkPeuC', 4, '{"title":"第902000661条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>203、假苏,荆芥</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000661,"note":"\n【本经原文】味辛，温，无毒。治寒热，鼠，瘰疬生疮，破结聚气，下瘀血，除湿痹。生川泽。一名鼠蓂。又名荆芥。 \n\n【产地】多生野地，处处有之，气味芳香，茎与叶皆入药。 \n\n【性味】味辛，性温，无毒。 \n\n【主治】荆芥为发表要药，功能祛风理血，发汗退热。主治寒热头疼诸风疮毒。亦为妇人胎前产后良剂。 【藏器】去邪除劳渴，冷风出汗，煮汁服之，捣烂醋和，敷疔肿毒。  \n【甄权】单用治恶风贼风，口面歪斜，遍身瘰痹，心虚忘事，益力添精，辟邪毒气，通利血 脉，传送五脏不足气，助脾胃。  \n\n【志良】主血劳，风气壅满，背脊疼痛，虚汗，理丈夫脚气，筋骨烦痛，及阴阳毒，伤寒头痛，头旋目眩，手足筋急。  \n\n【日华】利五脏，消食下气醒酒，作菜生熟皆可食，并煎茶饮之，以豉汁煎服，治暴伤寒能发汗。  \n\n【苏颂】治妇人血风，及疮疥为要药。  \n\n【用量】普通八分至二钱。 \n\n【禁忌】凡表虚有汗，血虚寒热，阴虚火炎面赤，因而头痛者均忌。 ","videoMemo":"","fangList":[],"bieMing":"荆芥,假苏"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '203、假苏,荆芥', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KBON7hK4C6i', 4, '{"title":"第902000660条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>202、爵床  ,香苏</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000660,"note":"\n【本经原文】味咸，寒，无毒。治腰脊病不得着床，俛仰艰难。除热，可做浴汤。生川谷及田野。又名香苏。  \n\n【产地】处处有之。 \n\n【性味】味咸性寒。 \n\n【主治】散瘀血，镇痛药，治腰痛及杖疮。\n\n【苏敬】疗血胀下气，治杖疮捣汁涂之。  ","videoMemo":"","fangList":[],"bieMing":"爵床,香苏"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '202、爵床 ,香苏', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hWSI1X68Z1B', 4, '{"title":"第902000659条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>201、蜀羊泉,羊泉</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000659,"note":"【本经原文】味苦，微寒，无毒。治头秃，恶疮，热气，疥瘙，痂廯虫，龋齿。生川谷，又名羊泉。全草可用。  \n\n【产地】处处有之。 \n\n【性味】味苦，性寒，  \n\n 【主治】为杀虫灭菌药，治疗疥廯，白秃，漆疮及蛀齿。\n\n【别录】女子阴中内伤。皮间积实。 \n\n【苏敬】主小儿惊，生毛发，捣涂漆疮。 \n\n【用量】一般二至四钱。 \n\n【禁忌】多外用，少内服。","videoMemo":"","fangList":[],"bieMing":"蜀羊泉,羊泉"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '201、蜀羊泉,羊泉', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vPqqfOENFrw', 4, '{"title":"第902000658条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>200、王孙  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000658,"note":"\n【本经原文】味苦，平，无毒。治五脏邪气，寒湿痹，四肢疼酸，膝冷痛。生川谷及城郭垣 下。吴名白功草。楚名王孙，齐名长孙。  ","videoMemo":"","fangList":[],"bieMing":"王孙"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '200、王孙', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('k0QO2yg3moK', 4, '{"title":"第902000657条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>199、女菀  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000657,"note":"\n【本经原文】味辛，温，无毒。治风寒洒洒，霍乱，泻利，肠鸣上下无常处，惊痫，寒热，百疾。生川谷或山阳。  ","videoMemo":"","fangList":[],"bieMing":"女菀"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '199、女菀', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NCAFMUsVFAz', 4, '{"title":"第902000656条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>198、积雪草  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000656,"note":"\n【本经原文】味苦，寒，无毒。治大热，恶疮，痈疽，浸淫，赤熛，皮肤赤，身热。生川谷。","videoMemo":"","fangList":[],"bieMing":"积雪草"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '198、积雪草', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uIj8mLqrhr6', 4, '{"title":"第902000655条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>197、马先蒿  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000655,"note":"\n【本经原文】味苦，平，无毒。治寒热，鬼疰，中风，湿痹；女子带下病，无子。生川泽，一名马屎蒿。","videoMemo":"","fangList":[],"bieMing":"马先蒿"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '197、马先蒿', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('P7YARwRYEm4', 4, '{"title":"第902000654条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>196、牡丹  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000654,"note":"\n【本经原文】一名鼠姑。味辛，寒，无毒。治寒热，中风，瘛瘲，痉，惊痫，邪气，除症坚，瘀血留舍肠胃，安五脏，疗痈疮。生山谷，一名鹿韭，今名丹皮。  \n\n【产地】牡丹处处皆有，庭院亦多种植之，花开美丽而大，为群花之王，色有红白紫等。其根部之皮入药。  \n\n【性味】味辛苦，性微寒（或作性温），无毒。  \n\n【主治】丹皮为理血要药，功能清伏火，凉血热，通月经，排瘀血。主治胎前产后，冷热气血之病，为女科良剂。  \n\n【别录】除时气头痛客热，五劳劳气，腰痛，风噤癫疾。  \n\n【甄权】治冷气，散诸痛，女子经脉不通，血沥腰痛。  \n\n【大明】通关腠血脉，排脓，消扑损瘀血，续筋骨，除风痹，治胎下胞，产后一切冷热血气。\n\n【元素】治神智不足无汗之谷蒸，衄血吐血。  \n\n【容川】其色味如红花，而根性主下达，与花不同，故主内及泄中下焦之血。气属阳，血属阴，瘀血阻气，则阳不入阴，蒸热汗出，宜破其血，使气得入于血中，则不壅热，丹皮主之。气通则热不蒸，此为治热之变法也。色赤味苦，泻火，即能泻血。  \n\n【灵胎】疏肝气，通经脉。  \n\n【用量】普通一钱至三钱。 \n\n【禁忌】入血凉血能行血，凡女子血崩，及经血过期不尽，均忌与行血药同用。忌蒜及芫荽铁器。  ","videoMemo":"","fangList":[],"bieMing":"牡丹皮,牡丹, 丹皮"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '196、牡丹', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JkT7P1Oc9t8', 4, '{"title":"第902000653条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>195、款冬花  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000653,"note":"\n【本经原文】一名颗东。一名虎须。一名菟奚。味辛，温，无毒。治咳逆上气，善喘，喉痹，诸惊痫，寒热邪气。生山谷及水傍，一名橐吾。  \n\n【产地】产我国陕西山河西北诸地，为山野多年生草，庭园亦可栽植，百草中惟此不顾冰雪，至冬即生芽而花，故名。  \n\n【性味】味辛甘，性温，无毒。 \n\n【主治】款冬花为润肺祛痰止嗽要药，主治咳逆上气，肺痿肺痈，寒热邪气。  \n\n【别录】消渴，喘息呼吸。 \n\n【甄权】疗肺气心促，急热劳咳，连连不绝，涕唾稠粘，肺痿肺痈吐脓血。  \n\n【大明】润心肺，益五脏，除烦消痰，洗肝明目，及中风等疾。  \n\n【用量】普通钱半至三钱。 \n\n【禁忌】咳逆消渴喘急，皆火炎气逆之病，款冬隆冬独秀，辛散而润，甘缓而和，故虚实寒热皆可用，无禁忌。  \n\n【容川】此药生于冬月冰雪之中，而花又在根下，乃坎中之阳象，故能引肺中阳气下行，而 为利痰止咳之要药。  ","videoMemo":"","fangList":[],"bieMing":"款冬花"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '195、款冬花', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xICS5ZdtmBD', 4, '{"title":"第902000652条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>194、防己  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000652,"note":"\n【本经原文】味辛，平，无毒．治风寒，温疟，热气，诸痫，除邪，利大小便，通腠理，利九窍。生川谷。一名解离。  \n\n【产地】产我国四川陕西及贵州，有汉防己及木防己两种根俱入药。  \n\n【性味】味辛苦，性寒，无毒。  \n\n【主治】防己为通膀胱利小便要药，主行全身祛风行水，泻下焦血分湿热，治水肿，淋病，散痈肿恶结。  \n\n【别录】疗水肿风肿，去膀胱热，伤寒热邪气，中风手脚挛急，通腠理，利九窍，止泄，散 痈肿恶结，诸瘑疥癣虫疮。  \n\n【甄权】治湿风，口面歪斜，手足拘痛，散留痰肺气喘嗽。 木防己主治男子肢节中风，毒风不语，散结气痈肿温疟，风水肿，去膀胱热。  \n\n【容川】能去湿热，属苦降之品，其形中空，纹如车轮，能外行腠理，内行三焦，能通水气。味似龙胆，能利水行。  \n\n【元素】治中下湿热肿泄脚气，行十二经。\n\n【药征】主治水也。 \n\n【用量】普通一至二钱。  \n【禁忌】凡肾虚阴虚，自汗盗汗，口舌苦干，肾虚小便不利，及产前后血虚，虽有下焦湿热，均忌。  ","videoMemo":"","fangList":[],"bieMing":"防己"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '194、防己', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('t2zyhmXnq7p', 4, '{"title":"第902000651条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>193、泽兰  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000651,"note":"\n【本经原文】一名龙枣。味苦，微温，无毒。治乳妇衄血，中风余疾，大腹水肿，身面四肢浮肿，骨节中水，金疮，痈肿疮脓。生诸大泽旁。一名虎兰。  \n\n【产地】生于溪涧或湿地，叶类薄荷，根紫黑色，叶与子根（地笋）皆入药。  \n\n【性味】味苦甘，性微温，无毒。 \n\n【主治】泽兰为女科要药，功能行血消水，主养血气，破宿瘀，消症瘕痈肿，胎前产后诸病。  \n\n【甄权】产后腹痛，频产血气衰冷，成劳瘦羸，妇人血沥腰痛。 \n\n【大明】胎前产后百病，通九窍，利关节，养血气破宿血，消症瘕，通小肠，长肌肉，消扑损瘀血，治鼻血吐血，头风目痛，妇人劳瘦，丈夫面黄。  \n\n【灵胎】清湿热，治水肿。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】破血通积，大虚不宜。","videoMemo":"","fangList":[],"bieMing":"泽兰"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '193、泽兰', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OGVmvmMrDcy', 4, '{"title":"第902000650条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>192、海藻  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000650,"note":"\n【本经原文】味苦，寒，无毒．治瘿瘤气，颈下核，破散结气，痈肿，症瘕，坚气，腹中上下鸣，下十二水肿。生东海池泽。一名落首。  \n\n【产地】产海岛中，为藻类之产于海中者，种类颇多，入药用马尾藻。  \n\n【性味】味咸，性寒，无毒。 \n\n【主治】海藻为除热软坚要药，主瘿瘤瘰疬，治瘫肿老痰，通血脉，利小便。  \n\n【别录】疗皮间积聚，暴溃瘤气，结热，利小便。 \n\n【甄权】辟百邪鬼魅，治气急心下满，疝气下坠，疼痛卵肿，去腹中幽幽作声。  \n\n【用量】普通一钱至三钱。 \n\n【禁忌】脾家有湿者忌。 \n\n【容川】海藻昆布皆生于水中，味微咸，又具草之质，是禀水木二气而生，故能清火润肝。  ","videoMemo":"","fangList":[],"bieMing":"海藻"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '192、海藻', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yP49AgFjslo', 4, '{"title":"第902000649条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>191、地榆  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000649,"note":"\n【本经原文】味苦，微寒，无毒。治妇人乳痉痛、七伤、带下十二病，止痛，除恶肉，止汗气。消酒，明目，治金疮。生山谷。  \n\n【产地】生山间向阳之地，今处处平原川泽亦有之，根直而柔，入药。  \n\n【性味】味苦【或作苦甘酸】，性微寒，无毒。 \n\n【主治】地榆为止血收敛要药，功能止吐血下血久痢，妇人崩带。  \n\n【用量】普通二钱至三至四钱。 \n\n【禁忌】性寒下行，脾胃虚寒作泄，白痢久而胃弱，胎产虚寒泄泻，血崩脾虚作泄，均忌，恶麦冬，丹砂，硫黄，雄黄。  ","videoMemo":"","fangList":[],"bieMing":"地榆"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '191、地榆', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0Dg3yDOuBAg', 4, '{"title":"第902000647条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>189、浮萍,水萍,水花</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000647,"note":"\n【本经原文】味辛，寒，无毒．治暴热身痒，下水气，胜酒，长须发，止消渴。久服轻身。生池泽水上．一名水花或浮萍。  \n\n【藏器】捣汁服，主水肿，利小便。 \n\n【大明】治热毒，风热，热狂，熁肿毒，汤火伤，风疹。  \n\n【元素】下气，以沐浴生毛发。  \n\n【灵胎】其性清浮，治在肌表。  \n\n【用量】普通八分至二钱。 \n\n【禁忌】发汗力猛，证非大实大热者，不可轻用，表虚自汗者尤忌。  \n\n【附方】 水气洪肿——小便不利者，浮萍日干为未，每服方寸匕，日二。身上虚痒——浮萍末一钱，以黄芩一钱，用四物汤煎汤调下。  ","videoMemo":"","fangList":[],"bieMing":"浮萍,水萍,水花"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '189、浮萍,水萍,水花', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OJuB3qhjfmW', 4, '{"title":"第902000648条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>190、王瓜  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000648,"note":"\n【本经原文】味苦，寒，无毒．治消渴，内痹，瘀血，月闭，寒热，酸疼。益气，愈聋。生平泽田野及人家垣墙间．一名土瓜。  \n\n【产地】产山东平泽田野，各地亦存栽种，多蔓生墙垣问，根及子入药。  \n\n【性味】味苦，性寒，无毒。（或作小毒）。 \n\n【主治】王瓜根主泻热，利水，行血，益气，治天行热疾，消渴，痞满，热结，黄疸变黑，妇女经闭。  \n\n【别录】疗诸邪气，热结鼠瘘，散痈肿流血，妇人带下，下乳汁不通，止小便数不禁，逐四肢骨节中水，治马谷刺人疮。  \n\n【大明】天行热疾，酒黄病，壮热心烦闷，热劳，排脓，消扑损瘀血，破症癖，落胎。  \n\n【用量】普通一至二钱。 \n\n【禁忌】能使人吐下，不宜多服。  ","videoMemo":"","fangList":[],"bieMing":"王瓜"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '190、王瓜', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('a9i5TkuYW22', 4, '{"title":"第902000646条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>188、白薇  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000646,"note":"\n【本经原文】味苦，平，无毒。治暴中风，身热，肢满，忽忽不知人。狂惑，邪气，寒热，酸疼，温疟洒洒、发作有时。生平原、川谷。 \n\n【产地】产陕西及关外，生平原川谷间，茎叶俱青，根黄白色入药。 \n\n【性味】味苦咸，性平，无毒。阳明冲任之药。 \n\n【主治】白薇为凉血退热要药，功能清虚火，除胃热，主治身热肢满，风温灼热，汗出热不退，妇人身热，伤中淋露。 \n\n【别录】疗伤中淋露，下水气，利阴气，益精。 \n\n【弘景】治惊邪风狂痣病，百邪鬼魅。 \n\n【本草】主治中风，身热支满，忽忽不知人，血虚，热淋，温疟，洗洗寒热酸痛。妇人伤中淋露，产虚烦呕。 \n\n【用量】普通一钱至二钱。 \n\n【禁忌】恶大黄，大戟，山茱，姜枣。  ","videoMemo":"","fangList":[],"bieMing":"白薇"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '188、白薇', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('015SKoWrN5l', 4, '{"title":"第902000645条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>187、萆薢  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000645,"note":"\n【本经原文】味苦，平，无毒。治腰背痛，强骨节，风寒湿周痹，恶疮不瘳，热气。生山谷。\n\n【产地】处处有之。 \n\n【性味】甘苦性平。功能除浊分清。 \n\n【主治】入足阳明厥阴，祛风去湿，以固下焦，补肝虚，坚筋骨，益睛明目。恶疮梅毒及淋浊。 \n\n【本草】主治风寒湿痹。腰痛久冷，关节老血。膀胱宿水，阴痿，茎痛，遗浊，痔瘘，恶疮。\n\n【别录】阴痿失溺，老人五缓，关节老血。 \n\n【甄权】冷气节痹，腰脚瘫缓不遂，手足惊挚，男子腰痛，久冷，膀胱宿水。 \n\n【用量】有黄白二种，黄长硬，白虚软，软者佳。一般用四至五钱，大剂量用一两。 \n\n【禁忌】下焦有寒之人忌用。阴虚内热者禁服。  ","videoMemo":"","fangList":[],"bieMing":"萆薢"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '187、萆薢', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WVR9uYZJUI3', 4, '{"title":"第902000644条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>186、石苇  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000644,"note":"【本经原文】味苦，平，无毒。治劳热邪气，五癃，闭不通，利小便水道。生山谷石上。\n\n 【产地】产我国山西安徽福建等地，多生山中石上及阴湿之地，他处亦多有之，叶入药。\n\n【性味】味甘，（或作苦），性寒，（或作平），无毒。 \n\n【主治】石苇为利尿治淋要药，主清肺火以滋源，通膀胱以利水，益精气，治淋闭。 \n\n【别录】止烦下气，通膀胱满，补五劳，安五脏，去恶风，益精。 \n\n【日华】治淋沥遗溺。 \n\n【苏颂】炒末冷酒调服，治发背。 \n\n【用量】普通一至二钱。 \n\n【禁忌】制丹砂矾石，得菖蒲滑石射干良。  ","videoMemo":"","fangList":[],"bieMing":"石苇"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '186、石苇', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KN03CNvLEmp', 4, '{"title":"第902000643条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>185、槀本  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000643,"note":"\n【本经原文】一名地新。味辛，温，无毒。治妇人疝瘕，阴中寒肿痛，腹中急，除风头痛，长肌肤，悦颜色。生山谷。名鬼卿。  \n\n【性味】味苦辛，性温。 \n\n【主治】鬼卿为祛风寒镇痛要药，治大寒犯脑头痛齿亦痛，女人阴寒肿痛，体肤风湿。\n\n 【东垣】头面身体皮肤风湿。 \n\n【大明】治皮肤疵皯，酒皻，粉刺，癫疾。 \n\n【元素】治太阳头痛，巅顶痛，大寒犯脑，痛连齿颊。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】热病头痛，血虚头痛，均忌服。  \n\n【附方】头屑干洗—槀本，白芷等份共末，夜擦旦梳，垢自去。","videoMemo":"","fangList":[],"bieMing":"槀本"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '185、槀本', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('07pMezPuv4j', 4, '{"title":"第902000642条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>184、紫参  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000642,"note":"\n【本经原文】味苦，寒，无毒。治心腹积聚，寒热邪气。通九窍，利大小便。治牛病。生山谷。一名牡蒙。  \n\n【产地】珍珠菜之地下茎谓之紫参，多产于深山溪涧之旁，色紫黑。  \n\n【性味】味苦，性寒，无毒。 \n\n【主治】紫参为破血通经要药，功能治心腹寒热积聚，产后恶露不行。\n\n【别录】疗肠胃大热，唾血衄血，肠中聚血，廱肿诸疮，止渴益精。 \n\n【甄权】治心腹坚胀，散瘀血，治妇人血闭不通。 \n\n【好古】主狂疟温疟，鼽血，汗出，治血痢。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】畏辛夷。  ","videoMemo":"","fangList":[],"bieMing":"紫参"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '184、紫参', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PcG724IzPhq', 4, '{"title":"第902000641条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>183、酸浆,醋浆,洛神珠,灯笼草</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000641,"note":"\n【本经原文】味酸，平，无毒。治热，烦满，定志，益气，利水道。产难，吞其实立产。生川泽及人家田园中，一名醋浆。又名洛神珠。灯笼草。  \n\n【产地】田园之中。 \n\n【性味】其根及苗味苦，性寒。酸浆果味酸，性平。 \n\n【主治】其苗，叶，根，茎皆为解热，排水药，治百日咳，黄疸，小便赤涩，果能催生。\n\n【别录】酸浆果主治烦热，定志益气，利水道，难产吞之，立产。 \n\n【弘景】酸浆捣汁服，治黄病多效。 \n\n【唐本】灯笼草治上气咳嗽，风热，明目，根茎花实并用。 \n\n【苏颂】酸浆果食之除热，治黄疸，尤宜小儿。 \n\n【用量】一般一钱至四钱。 \n\n【禁忌】孕妇禁忌","videoMemo":"","fangList":[],"bieMing":"酸浆,醋浆,洛神珠,灯笼草"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '183、酸浆,醋浆,洛神珠,灯笼草', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AudlabWDpXI', 4, '{"title":"第902000640条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>182、白鲜皮  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000640,"note":"\n【本经原文】味苦寒，无毒，治头风，黄疸，咳逆淋漓，女子阴中肿痛。生川谷。\n\n【产地】处处有之，以四川者为良。 \n\n【性味】味苦，性寒，无毒。 \n\n【主治】白鲜皮主治头风黄疸，天行时疾。 \n\n【别录】疗四肢不安，时行腹中大热，饮水欲走大呼，小儿惊痫，妇人产后余痛。  \n\n【甄权】治一切热毒风，恶风，疮疥癣赤烂，眉发脱脆，皮肌急，壮热恶寒，解热黄，酒黄，急黄，谷黄，劳黄。 \n\n【大明】通关节，利九窍，及血脉，通小肠水气，天行时疾，头痛眼疼，其花同功。 \n\n【用量】钱半至三钱。 \n\n【禁忌】不详  ","videoMemo":"","fangList":[],"bieMing":"白鲜皮"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '182、白鲜皮', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zNjUFaqkx66', 4, '{"title":"第902000639条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>181、败酱  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000639,"note":"\n【本经原文】一名鹿肠．味苦，平，无毒。治暴热，火疮赤气，疥瘙，疽，痔，马鞍热气。生川谷。  \n\n【产地】处处有之，生川谷间。 \n\n【性味】味苦【或作咸】，性平（或作寒），无毒。 \n\n【主治】败酱草主治赤眼，障膜，弩肉，聤耳，痈肿结热，破凝聚血，化脓为水。 \n\n【别录】除痈肿，浮肿，结热，风痹不足，产后痛。 \n\n【甄权】治毒风瘰痹，破多年凝血，能化脓为水，产后诸病，止腹痛，余疹烦渴。 \n\n【大明】治血气心腹痛，破症结，催生落胞，血运鼻衄，吐血，赤白带下，赤眼障膜，弩肉，聤耳，疮疖疥癣，丹毒，排脓补瘘。 \n\n【用量】普通一二钱。 \n\n【禁忌】忌葱，性专下泄，无瘀者忌。","videoMemo":"","fangList":[],"bieMing":"败酱"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '181、败酱', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VUYNDBe4XOo', 4, '{"title":"第902000638条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>180、紫草,紫丹,紫芙</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000638,"note":"\n【本经原文】味苦，寒，无毒。治心腹邪气，五疸，补中益气，利九窍，通水道。一名紫丹。一名紫芙。  \n\n【产地】为山野自生之宿根草，园圃亦可栽种，产于寒地野生之根为良。  \n\n【性味】紫草味甘咸，性寒，无毒。 \n\n【主治】紫草为痧痘要药，功能凉血，活血，透发解毒，治恶疮天花，麻疹及小儿疮疖与面皻。  \n\n【别录】通水道，疗肿胀满痛，以合膏疗小儿疮及面皻。  \n\n【灵胎】淸血除邪。 \n\n【用量】普通二钱至三钱，大剂一两。 \n\n【禁忌】痘已出而红活及白陷，脾胃肠虚寒大便溏者忌服。","videoMemo":"","fangList":[],"bieMing":"紫草,紫丹,紫芙"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '180、紫草,紫丹,紫芙', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CnYAtemHs6t', 4, '{"title":"第902000637条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>179、紫苑  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000637,"note":"\n【本经原文】味苦，温，无毒。治咳逆上气，胸中寒热结气，去蛊毒，痿厥，安五脏．一名 青菀。  \n\n【产地】为山野多年生草本，产我国中部，庭园亦可栽植，其花美丽，根状似细辛，其质柔轫，入药。  \n\n【性味】味苦辛，性温，无毒。  \n\n【主治】紫苑为祛痰止咳要药，主治咳逆，痰涎，吐脓血，益肺气。\n\n【别录】疗咳唾脓血，止喘悸，五劳体虚，补不足，小儿惊痫。  \n\n【甄权】治尸疰，补虚下气，劳气虚热，百邪鬼魅。\n\n【大明】调中消痰，止渴润肌肤，添骨髓。  \n\n【好古】益肺气，主息贲。  \n\n【用量】普通七分至钱半。  \n\n【禁忌】肺病咳逆喘嗽，皆阴虚肺热也，忌独用多用，即用亦须与二冬百部桑皮等苦寒药参用，方无害以其性温也。  ","videoMemo":"","fangList":[],"bieMing":"紫苑"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '179、紫苑', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3mxS8eYCIjf', 4, '{"title":"第902000636条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>178、茅根,兰根,茹根</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000636,"note":"\n【本经原文】味甘，寒，无毒。治劳伤、虚羸，补中益气，除瘀血、血闭、寒热，利小便。其苗，主下水。一名兰根。一名茹根。 \n\n【产地】生于原野路傍之宿根草，产楚地，今处处皆有。 \n\n【性味】味甘，性寒，无毒。 \n\n【主治】白茅根为止血利尿要药，功能止吐血行瘀血，治消渴水肿，不伤胃气。 \n\n【别录】下五淋，客热在肠胃，止渴，坚筋，妇人崩中。 \n\n【大明】主妇人月经不匀，通血脉，淋沥。 \n\n【用量】普通钱半至三钱。 \n\n【禁忌】不宜遇铁。胃寒脾湿者忌之。 ","videoMemo":"","fangList":[],"bieMing":"茅根,兰根,茹根"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '178、茅根,兰根,茹根', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qU05nuaUNKb', 4, '{"title":"第902000635条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>177、石龙芮  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000635,"note":"\n【本经原文】味苦，平，无毒。治风寒湿痹，心腹邪气，利关节，止烦满。久服轻身、明目、不老。一名鲁果能。一名地椹。  \n\n【产地】产山东等地，生川泽石边，子入药。 \n\n【性味】味苦，性平，无毒。 \n\n【主治】石龙芮主治风寒湿痹，利关节，养胃气，能强阴益精。  \n\n 【别录】平肾胃气，补阴气不足，失精茎冷，令人皮肤光泽有子。\n\n【大明】逐诸风，除心热燥。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】宜大戟为使，畏茱萸蛇蜕皮。  ","videoMemo":"","fangList":[],"bieMing":"石龙芮,地椹,鲁果能"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '177、石龙芮', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vCrBOWB2GiY', 4, '{"title":"第902000634条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>176、狗脊  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000634,"note":"【本经原文】味苦，平，无毒。治腰背强。关机缓急，周痹，寒湿膝痛。颇利老人。一名百枝。 \n\n【产地】产山野湿地自生之宿根草，根黑色，长而多岐似狗脊，故名。 \n\n【性味】味苦甘，性微温（或作平），无毒。 \n\n【主治】狗脊为益气血，强筋骨要药，功能治肝虚肾亏，脚弱腰痛，筋肉拘急，失溺淋露。\n\n【别录】疗失溺不节，男女脚弱腰痛，风邪淋露，少气，目暗，坚脊，利俯仰，女子伤中关节重。 \n\n【甄权】男子女人毒风软脚，肾气虚弱，续筋骨，补益男子。 \n\n【灵胎】去寒湿，强筋骨。 \n\n【用量】普通钱半至三四钱。 \n\n【禁忌】肾虚有热，小水不利或短涩黄赤，口苦舌干，均忌，恶香附败酱草。  ","videoMemo":"","fangList":[],"bieMing":"狗脊"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '176、狗脊', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nROqtJ4hzt4', 4, '{"title":"第902000633条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>175、黄芩  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000633,"note":"\n【本经原文】味苦，平，无毒。治诸热，黄疸，肠澼，泄利，逐水，下血闭。恶疮，疽蚀，火疡。一名腐肠。  \n\n【产地】生秭归川谷。产山谷间，亦为园圃之多年生草，根深黄色带褐。  \n\n【性味】味苦，性平，无毒。  \n\n【主治】黄芩为清热要药，功能去心肺大小肠诸经之热，肝胆之火。主治黄疸，肠澼泄利，风热，湿热：天行热疾，女科养阴安胎。  \n\n【别录】疗痰热，胃中热，小腹绞痛，消谷，利小肠，女子血闭，淋露下血，小儿腹痛。  \n\n【甄权】治热毒骨蒸，寒热往来，肠胃不利，破壅气，治五淋，令人宣畅，解热渴。  \n\n【容川】黄芩味苦，中多空虚，有孔道，人身惟三焦；是行水气之孔道主相火，故主清相火，火逆呕苦、黄芩为正药。此药苦而色绿，故能入瞻。  \n\n【药征】治心下痞也，旁治胸胁满，呕吐下利也。  \n\n【灵胎】清热止利。  \n\n【用量】普通钱半至三钱。  \n\n【禁忌】过服损胃，血虚寒中者忌。  ","videoMemo":"","fangList":[],"bieMing":"黄芩"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '175、黄芩', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('d4LFpaxLOeG', 4, '{"title":"第902000632条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>174、淫羊藿  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000632,"note":"\n【本经原文】味辛，寒，无毒。治阴痿，绝伤，茎中痛，利小便，益气力，强志。一名刚前。\n\n【产地】产四川北部，据云其地有淫羊，一日百遍合，乃食此霍所至，叶为卵圆形类杏叶，入药。  \n\n【性味】味辛苦，性温（或作小寒）  \n\n【主治】淫羊霍为壮阳益精要药，功能治阳痿茎痛，坚筋骨，利小便。  \n\n【大明】治丈夫绝阳无子，女人绝阴无子，老人昏耄，中年健忘，一切冷风劳气，筋骨挛急，四肢不仁，补腰膝，强心力。  \n\n【用量】普通钱半至三钱。 \n\n【禁忌】凡虚阳易举，梦遗不止，便赤口干，强阳不痿均忌。得酒良。  ","videoMemo":"","fangList":[],"bieMing":"淫羊藿"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '174、淫羊藿', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NZM1ydX22AC', 4, '{"title":"第902000631条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>173、白芷  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000631,"note":"\n【本经原文】味辛，温，无毒。治女人漏下赤白、血闭、阴肿、寒热、风头侵目泪出，长肌肤。润泽。可作面脂。  一名芳香。一名虈。  \n\n【性味】味辛，性温，无毒。 \n\n【主治】白芷为散风表汗要药，功能通窍去湿，疗风行血，止头痛，和肠胃，烧之辟邪气。\n\n【别录】疗风邪，久渴吐呕，两胁满，头眩目痒。 \n\n【甄权】能蚀脓，止心腹血刺痛，女人沥血腰痛血崩。 \n\n【大明】治目赤努肉，去面皯疵瘢，补胎漏滑落，破宿血，补新血，乳痈，发背，一切痈疮疥癣，止痛排脓。  \n\n【元素】解利手阳明头痛，中风寒热，及肺经风热，头面皮肤风痹燥痒。  \n\n【灵胎】驱风燥湿。  \n\n【用量】普通五分至钱半。  \n\n【禁忌】呕吐由于火，漏下赤白，阴虚火炽。病由血热所致者，均忌。恶旋覆花，制雄黄硫黄。  \n\n【容川】白芷辛香，色白入肺，入阳明陉，根性又主升，故能升散肺与阳明之风寒。  ","videoMemo":"","fangList":[],"bieMing":"白芷"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '173、白芷', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JE3Rvy00X19', 4, '{"title":"第902000630条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>172、贝母  ,空草</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000630,"note":"\n【本经原文】味辛，平，无毒。治伤寒烦热，淋沥邪气，疝瘕。喉痹，乳难，金疮，风痉。一名空草。 \n\n【产地】生晋地。产四川山西等地，为圆球形之根。色白入药，今浙江亦有之，称浙贝母，功用稍异。\n\n【性味】味辛苦，性平无毒。 \n\n【主治】贝母为袪痰治咳要药，功能散结泄热，润肺清火，治烦热疮疡。 \n\n【别录】疗腹中结实，心下满，洗洗恶恶，风目眩项直，咳嗽上气，止烦热渴，出汗。 \n\n【大明】消痰润心肺。末和沙糖丸含之，止嗽，烧灰油调，传人畜恶疮，敛疮口。 \n\n【容川】色白性平，利胸肺之痰气。 \n\n【药征】主治胸膈郁结痰饮。 \n\n【用量】普通钱半至三钱。 \n\n【禁忌】寒湿痰食痰嗽，湿痰在胃，恶心欲吐，痰饮作寒热，脾胃湿痰作眩，及痰厥头痛，中恶呕吐，胃寒作泄，法宜用辛温燥热者，均忌贝母。  ","videoMemo":"","fangList":[],"bieMing":"贝母,空草"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '172、贝母 ,空草', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pfVm8KEEX0b', 4, '{"title":"第902000629条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>171、知母 ,蚳母,连母,野蓼,地参,水参,水浚,货母,蝭母</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000629,"note":"\n【本经原文】味苦，寒，无毒。治消渴，热中，除邪气。肢体浮肿。下水，补不足。益气。  \n\n一名蚳母。一名连母。一名野蓼，一名地参。一名水参。一名水浚。一名货母。一名蝭母。\n\n【产地】我国河内川谷濒河，及解州滁州多产之，为多年生草根横生，类万年青。 \n\n【性味】味苦，性寒，无毒。 \n\n【主治】知母为清凉解热要药，功能泻肺火，清胃火，下水消肿，利二便。 \n\n【别录】疗伤寒久疟烦热，胁下邪气，膈中恶，及风汗内疽，多服令人泄。 \n\n【甄权】心烦燥闷，骨热劳往来，产后蓐劳，肾气劳。憎寒虚烦。 \n\n【大明】热劳传尸疰痛，通小肠，消痰止嗽，润心肺，安心止惊悸。 \n\n【元素】凉心去热，治阳明火热，泻膀胱肾经火热，痰厥头痛，下痢腰痛，喉中腥臭。 \n\n【好古】泻火而上清肺金，滋水而下润肾燥，治命门相火有馀。 \n\n【容川】知母叶至难死。拔之犹生，即知其得水气多，故能清气分之热。 \n\n【用量】普通钱半至三钱。 \n\n【禁忌】能滑肠，泄泻者忌，阳痿及易举易痿，脾弱饮食不化，胃虚不思食，均忌，勿犯铁器，得黄相及酒良。  ","videoMemo":"","fangList":[],"bieMing":"知母,蚳母,连母,野蓼,地参,水参,水浚,货母,蝭母"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '171、知母 ,蚳母,连母,野蓼,地参,水参,水浚,货母,蝭母', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oJsh79D660C', 4, '{"title":"第902000628条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>170、百合  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000628,"note":"【本经原文】味甘，平，无毒。治邪气腹胀，心痛，利大小便。 补中益气。生山谷。  \n\n【产地】处处有之，生山谷中，种类颇多，以味苦者为真，白花者为良，根入药。 \n\n【性味】味甘，性平，无毒。 \n\n【主治】百合为清凉退热要药，主润肺宁心，清热止咳，补中益气，治百合病，肺病，吐血。\n\n【别录】除浮肿胪胀，痞满寒热。通身疼痛，及乳难喉痹，止涕泪。 \n\n【甄权】百邪鬼魅，涕泣不止。除心下急满痛，脚气热咳。  \n\n【大明】安心定胆益志，养五脏，治颠邪狂叫惊悸，产后血狂运，杀虫毒气，胁痈乳痈发背 诸疮肿。  \n\n【元素】温肺止嗽。  \n\n【灵胎】补肺益气。  \n\n【用量】普通一钱至三钱。  \n\n【禁忌】中寒者勿服。   如天下之下垂，本天清之气。皆入气分。以敛肺气。  \n\n【炮制】拣去杂质，筛去灰即得。 ","videoMemo":"","fangList":[],"bieMing":"百合"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '170、百合', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OZP7bPy9MQ1', 4, '{"title":"第902000627条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>169、秦艽  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000627,"note":"\n【本经原文】味苦，平，无毒。治寒热邪气，寒湿风痹，肢节痛。下水，利小便。一名秦瓜。\n\n【产地】产我国陕西河北河南等地，生山谷中，根做土黄色，以有罗纹相交者良。 \n\n【性味】味苦辛，性平，无毒。 \n\n【主治】秦艽为治风湿要药，功能清风热治湿热，主寒热身酸痛，黄疸酒毒，养血，荣筋，安胎。 \n\n【别录】疗风无问久新，通身挛急。 \n\n【甄权】利大小便，疗酒黄，黄疸，解酒毒，去头风。 \n\n【大明】傅尸骨蒸，治疳疾及时气。 \n\n【元素】除阳明风湿，及手足不遂，口噤牙痛，口疮，肠风泻血，养血荣筋。 \n\n【好古】泄热，益胆气。 \n\n【用量】普通钱半至三钱。 \n\n【禁忌】下部虚寒人及小便不禁者均忌。 \n\n【吴克潜】秦艽味苦能杀虫、故外科亦用之，时珍曰：阳明有湿则身体疼烦热，阳明有热则日晡潮热骨蒸，沈金鳌曰感受风寒发热，遍身疼痛，必以秦艽治之，以其能散结除邪也。 \n\n【容川】秦艽肌纹多，左右交缠。故治左右偏风，筋脉疼痛之症，利于续接经脉。  ","videoMemo":"","fangList":[],"bieMing":"秦艽"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '169、秦艽', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bLTq49Hw8n1', 4, '{"title":"第902000626条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>168、玄参  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000626,"note":"【本经原文】味苦，微寒，无毒。治腹中寒热积聚，女子产乳余疾。补肾气，令人目明。一名重台。又名黑参，元参。 \n\n【产地】处处原野多产之，根直而肥大，生时本白色，切片后即变黑。 \n\n【性味】味苦，性微寒，无毒。 \n\n【主治】元参为清火退热要药，功能治一切实热，狂热，燥热，肿疡，瘰疬。 \n\n【别录】暴中风伤寒，身热又满，狂邪忽忽不知人，温疟洒洒，血瘕，下寒血，除胸中气，下水，止烦渴，散颈下核，痈肿，心腹痛，坚症。 \n\n【甄权】热风头痛，伤寒劳复，暴结热，散瘿瘤瘰疬。 \n\n【大明】治游风，补劳损，心惊烦躁，骨蒸，传尸邪气，消肿毒。 \n\n【纲目】滋阴降火，解斑毒，利咽喉，通小便血滞。 \n\n【灵胎】育阴滋水。 \n\n【用量】普通钱半至三四钱，大剂一二两。 \n\n【禁忌】凡血少目昏，停饮支满，血虚腹痛，脾虚泄泻，均忌。恶黄耆干姜、茴香山萸，反 藜芦勿犯铜铁。 ","videoMemo":"","fangList":[],"bieMing":"玄参"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '168、玄参', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('S1U7kwghY3D', 4, '{"title":"第902000625条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>167、瞿麦  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000625,"note":"【本经原文】味苦，寒，无毒。治关格，诸癃结，小便不通。出刺，决痈肿，去翳，破胎堕 子，下闭血。一名巨句麦。  \n\n【产地】为山野河边自生之宿根草，子黑色扁平，入药。  \n\n【性味】味苦，性寒，无毒。 \n\n【主治】瞿麦为利水破血要药，主五淋，治小便癃闭，月经不通，降心火，利小肠。  \n\n【别录】养肾气，逐膀胱邪逆，止霍乱，长毛发。\n\n【大明】主五淋，月经不通，破血块排脓。  \n\n【用量】普通一钱至三钱。  \n\n【禁忌】瞿麦性猛利，善下逐，凡肾气虚，小肠无大热，胎前产后一切虚人患小水不利，及水肿鼓胀脾虚者均忌，能堕胎孕妇忌用，恶螵蛸，伏丹砂。 王执中曰五淋大抵皆属湿热，热淋用八正散（瞿麦萹蓄车前滑石甘草山栀仁木通大黄），血淋宜小蓟牛膝膏，肾虚淋宜补肾，不可独泻，老人气虚者。宜参术加木通山栀，亦有痰滞中焦作淋，宜行痰兼通利药，最忌发汗，汗之必便血。","videoMemo":"","fangList":[],"bieMing":"瞿麦"}}', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '2025-01-16T03:34:35.000Z', '167、瞿麦', '2025-01-16T03:34:35.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nmr7NFacV8W', 4, '{"title":"第902000712条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>254、水苏  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000712,"note":"\n【本经原文】味辛，微温，无毒。主下气，杀谷，除饮食，辟口臭，去毒。辟恶气。久服通神明，轻身，耐老。生池泽。一名芥蒩。","videoMemo":"","fangList":[],"bieMing":"水苏"}}', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '254、水苏', '2025-01-16T06:54:24.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mGNMl434Tqo', 4, '{"title":"第902000711条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>253、葱实  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000711,"note":"\n【本经原文】味辛，温，无毒。主明目，补中不足。\n\n其茎，平，作汤，治伤寒寒热，出汗，中凤，面目肿。\n\n薤，味辛，温，无毒。治金疮疮败，轻身，不饥，耐老。生平泽。  ","videoMemo":"","fangList":[],"bieMing":"葱实"}}', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '253、葱实', '2025-01-16T06:54:24.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vE5s0f11rxx', 4, '{"title":"第902000710条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>252、蓼实  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000710,"note":"\n【本经原文】味辛，温，无毒。主明目，温中，耐风寒，下水气，面目浮肿，痈疡。马蓼，去肠中蛏虫，轻身。生川泽。  ","videoMemo":"","fangList":[],"bieMing":"蓼实"}}', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '252、蓼实', '2025-01-16T06:54:24.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yaw5Q62UdSE', 4, '{"title":"第902000709条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>251、黍米  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000709,"note":"\n【本经原文】味甘，温，无毒。主益气补中。多热，令人烦。\n \n 丹黍米，味苦，微温，无毒。主咳逆，霍乱，止泄，除热，止烦渴。  ","videoMemo":"","fangList":[],"bieMing":"黍米"}}', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '251、黍米', '2025-01-16T06:54:24.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bfNfevrZcm6', 4, '{"title":"第902000708条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>250、粟米  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000708,"note":"\n【本经原文】味咸，微寒，无毒。主养肾气：去胃中脾中热，益气。陈粟，味苦，寒，无毒。主胃熟，消渴，利小便。","videoMemo":"","fangList":[],"bieMing":"粟米"}}', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '250、粟米', '2025-01-16T06:54:24.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Fi3A3V1NfvK', 4, '{"title":"第902000707条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>249、大豆黄卷  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000707,"note":"\n【本经原文】味甘，平，无毒。治湿痹，筋挛，膝痛。\n\n  生大豆。平。涂痈肿，煮汁饮，杀鬼毒。止痛。\n\n  赤小豆，平。主下水，排痈肿脓血。生平泽。  \n\n【产地】黑大豆所制成，处处有之。 \n\n【性味】味甘，性平，无毒。 \n\n【主治】大豆黄卷为清热开胃，推陈去积要药，主行水去湿，胃气结积，治湿痹筋挛膝痛。\n\n【别录】五脏不足，味气结积，益气止痛，去黑皯，润肌肤皮毛。 \n\n【用量】普通钱半至三钱。 \n\n【禁忌】恶海藻龙胆。  ","videoMemo":"","fangList":[],"bieMing":"大豆黄卷"}}', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '249、大豆黄卷', '2025-01-16T06:54:24.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('au1dBl4z2Yj', 4, '{"title":"第902000706条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>248、梅实  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000706,"note":"\n【本经原文】味酸，平，无毒。主下气，除热，烦满，安心，止肢体痛，偏枯不仁，死肌，去青黑痣，恶疾。能益气，不饥。生川谷。 \n\n【产地】生汉中川谷。即梅花之实，有乌梅与白梅二种，处处有之。乌梅系采半黄之梅实，用烟熏黑，再以稻草灰淋汁润湿蒸过，白梅又叫盐梅，用大青梅实用盐腌渍，日晒夜渍，十日即成。 \n\n【性味】乌梅味酸，性平而涩：白梅味酸咸，性平。  \n\n【主治】乌梅为收敛，解热，消肿，驱虫之药，治久利，痢疾，反胃，去面痣，蚀恶肉，蚘 厥吐利，反胃膈噎。驱蛔虫。白梅与乌梅之效用相同。 \n\n【别录】去痹，利筋脉，止下痢，好唾口干。 \n\n【藏器】止渴，调中，去痰，治瘴疟。止吐逆霍乱，除冷热利。 \n\n【大明】治虚劳骨蒸，消酒毒，令人得睡，和建茶干姜为丸服，止休息痢大验。 \n\n【弘景】白梅和药点痣，蚀恶肉。水渍汁饮治伤寒烦热。 \n\n【时珍】敛肺，涩肠，止久嗽泻利，反胃咦膈，蛔厥吐逆，消肿涌痰，杀虫，解鱼毒，硫磺 毒。 \n\n【容川】乌梅极酸，能敛肝木之阳，能化蛔虫，能去坏肉，此是以木来克土，酸能收之义。\n\n【汪颖】治乳痈肿毒，杵烂贴之佳。 \n\n【用量】一般一钱至三钱。 \n\n【禁忌】多食梅肉损齿伤筋。凡风寒初起，疟痢未久者均忌，忌猪肉。  ","videoMemo":"","fangList":[],"bieMing":"梅实"}}', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '248、梅实', '2025-01-16T06:54:24.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('n8Olf6GbxDD', 4, '{"title":"第902000705条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>247、伏翼,蝙蝠,夜明砂  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000705,"note":"\n【本经原文】味咸，平，无毒。治目瞑，明目，夜视有精光。久服令人喜乐、媚好、无忧。  生川谷及人家屋间。一名蝙蝠，今名夜明砂。  \n\n 【产地】山洞之中，倒悬于洞顶之上。其屎供药用。 \n\n【性味】味辛性寒。 \n\n【主治】为散血明目要药，治障翳，青盲，夜盲，头面痈肿，疳积，瘰疬。 \n\n【灵胎】养血明日。 \n\n【苏敬】烧灰酒服可下死胎。 \n\n【日华】炒服治瘰疬。 \n\n【宗奭】治疳有效。 \n\n【时珍】治目盲障翳。 \n\n【用量】一般一钱至二钱。 \n\n【禁忌】胃肠寒之人禁忌。 右虫鱼中品十七种，旧十六种，增伏翼于此。  ","videoMemo":"","fangList":[],"bieMing":"伏翼,蝙蝠,夜明砂 "}}', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '247、伏翼,蝙蝠,夜明砂', '2025-01-16T06:54:24.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ly9zmPxLnWA', 4, '{"title":"第902000704条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>246、蟅虫,土鳖,地鳖  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000704,"note":"\n【本经原文】味咸，寒，有毒。治心腹寒热洒洒，血积，症瘕，破坚，下血闭，生子大良。  \n\n【产地】处处有之，多生墙壁下土中湿处，形扁小，六足，似鳖而无甲。 \n\n【性味】味咸，性寒，有毒。 \n\n【主治】蟅虫为破症瘕下血积要药，主心腹寒热，留血积聚，治乳脉不通，妇人经闭，产后血积，折伤瘀血。 \n\n【药征】主治干血，故兼治少腹满痛，及妇人经水不利。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】用皂荚菖蒲，无瘀血停留者忌，孕妇慎用。 ","videoMemo":"","fangList":[],"bieMing":"蟅虫,土鳖,地鳖"}}', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '246、蟅虫,土鳖,地鳖', '2025-01-16T06:54:24.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7n2A3gQ2zjh', 4, '{"title":"第902000703条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>245、蜚蠊,蟑螂</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000703,"note":"\n【本经原文】味咸，寒，有毒。治血瘀症坚，寒热，破积聚，喉咽痹，内寒无子。生川泽及人家屋间。 ","videoMemo":"","fangList":[],"bieMing":"蜚蠊,蟑螂"}}', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '245、蜚蠊,蟑螂', '2025-01-16T06:54:24.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kXI0Z9MWO7i', 4, '{"title":"第902000702条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>244、蜚虻,虻虫, 牛虻</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000702,"note":"\n【本经原文】味苦，微寒，有毒。主逐瘀血，破下血积，坚痞症瘕，寒热，通利血脉及九窍。生川谷。又名虻虫，寄生于牛身者为真品。名牛虻。 \n\n【产地】产于牛舍之中为上品。 \n\n【性味】味苦微寒，有毒。 \n\n【主治】活血化瘀，专攻妇女子脏之瘀，与少腹中之瘀血。  \n\n【药征】瘀血，少腹鞭满，兼治发狂瘀热喜忘，及妇人经水不利。\n\n【容川】蝱虫为飞而食血；故主行上下之血。可以攻血。 \n\n【用量】一般一钱至三钱 \n\n【禁忌】下利者忌用。","videoMemo":"","fangList":[],"bieMing":"蜚虻,虻虫, 牛虻"}}', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '244、蜚虻,虻虫, 牛虻', '2025-01-16T06:54:24.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JoX1HFtj26E', 4, '{"title":"第902000701条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>243、木虻  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000701,"note":"\n【本经原文】味苦，平，有毒。治目赤痛。眦伤，泪出，瘀血，血闭，寒热，酸痟，无子。生川泽。一名魂常。  ","videoMemo":"","fangList":[],"bieMing":"木虻"}}', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '243、木虻', '2025-01-16T06:54:24.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Yqud631tqaL', 4, '{"title":"第902000700条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>242、石龙子,  蜥蜴</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000700,"note":"\n【本经原文】味咸，寒，有小毒。治五癃，邪结气，破石淋，下血，利小便水道。生川谷及山石间。一名蜥蜴。  \n\n【产地】今之蜥蜴。处处有之 \n\n【性味】味咸性寒，有小毒。 \n\n【主治】有利尿通淋下血之效，妊妇不得服用。 \n\n【别录】主治五癃结气，利小便水道，破石淋，下血。\n\n【用量】一般一条至两条，烧灰研粉酒服。 \n\n【禁忌】有寒利者禁忌。  ","videoMemo":"","fangList":[],"bieMing":"石龙子,  蜥蜴"}}', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '242、石龙子, 蜥蜴', '2025-01-16T06:54:24.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0Rvkr4RAZlg', 4, '{"title":"第902000699条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>241、蛞蝓,蜗牛</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000699,"note":"\n【本经原文】味咸，寒，无毒。治贼风喎僻,轶筋及脱肛，惊痫，挛缩。生池泽及阴地、沙石、垣下。一名陵蠡。","videoMemo":"","fangList":[],"bieMing":"蛞蝓,蜗牛"}}', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '241、蛞蝓,蜗牛', '2025-01-16T06:54:24.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8tOc5S1yahb', 4, '{"title":"第902000698条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>240、樗鸡  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000698,"note":"\n【本经原文】味苦，平，有小毒。治心腹邪气，阴痿，益精，强志，生子，好色，补中，轻身。生川谷樗树上。","videoMemo":"","fangList":[],"bieMing":"樗鸡"}}', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '240、樗鸡', '2025-01-16T06:54:24.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MpgJkJuGRik', 4, '{"title":"第902000697条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>239、鮀鱼甲  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000697,"note":"\n【本经原文】味辛，微温，有毒。治心腹症瘕，伏坚积聚，寒热，女子崩中下血五色，小腹阴中相引痛，疮疥死肌。生南海池泽。  ","videoMemo":"","fangList":[],"bieMing":"鮀鱼甲"}}', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '239、鮀鱼甲', '2025-01-16T06:54:24.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('H4ZDrIyBr8z', 4, '{"title":"第902000696条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>238、白僵蚕  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000696,"note":"\n【本经原文】味咸，平，无毒。治小儿惊，夜啼，去三虫，灭黑，令人面色好，男子阴易病。生平泽。  \n\n【产地】处处有之，乃蚕之病风而机殭者，入药。  \n\n【性味】味咸辛，性平，无毒。  \n\n【主治】白僵蚕为祛风化痰要药，主小儿惊痫，头风齿痛，喉痹咽肿，中风失音，治丹毒搔 痒，瘰疬结核，去皮肤中如虫行。外用灭诸疮瘢痕。  \n\n【别录】女子崩中赤白，产后腹痛，灭诸疮瘢痕，为末封疔肿，拔根极效。  \n\n【灵胎】驱风逐痰。 \n\n【用量】普通八分至三钱。 \n\n【禁忌】所治诸病，非由风寒外邪客入者，均忌。","videoMemo":"","fangList":[],"bieMing":"白僵蚕"}}', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '238、白僵蚕', '2025-01-16T06:54:24.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FJklLAnc4oc', 4, '{"title":"第902000695条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>237、乌贼鱼骨  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000695,"note":"\n【本经原文】味咸，微温，无毒。治女子漏下赤白经汁，血闭，阴蚀肿痛，寒热，惊气，症瘕，无子，生东海、池泽。  \n\n【产地】产于海滨，形如革囊，骨及肉入药。  \n\n【性味】味咸，性微温，无毒。  \n\n【主治】乌贼骨主通经络，祛寒湿，治寒热症瘕，阴蚀肿痛，赤白漏下，血枯经闭，能补肝伤疗血不足。  \n\n【别录】惊气入腹，腹痛环脐，丈夫阴中肿痛，令人有子，又止疮多脓汁不燥。  \n\n【日华】疗血崩，杀虫。 \n\n【用量】普通一钱至三钱。\n\n【禁忌】血病多热者勿用。","videoMemo":"","fangList":[],"bieMing":"海螵蛸,乌贼鱼骨"}}', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '237、乌贼鱼骨', '2025-01-16T06:54:24.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Cxj1G0HqF05', 4, '{"title":"第902000694条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>236、蛴螬  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000694,"note":"\n【本经原文】味咸，微温，有毒。治恶血，血瘀，痹气，破折，血在胁下坚满痛，月闭，目中淫肤，青翳，白膜。生平泽及人家积粪草中。一名蟦蛴  ","videoMemo":"","fangList":[],"bieMing":"蛴螬"}}', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '236、蛴螬', '2025-01-16T06:54:24.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('y5MsUhF1cVi', 4, '{"title":"第902000693条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>235、蚱蝉  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000693,"note":"\n【本经原文】味咸，寒，无毒。治小儿惊痫，夜啼，癫病，寒热。生杨柳上。\n\n【灵胎】清火散风。即今日之蝉。  ","videoMemo":"","fangList":[],"bieMing":"蝉蜕,蚱蝉"}}', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '235、蚱蝉', '2025-01-16T06:54:24.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bM0EQWfC9wE', 4, '{"title":"第902000692条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>234、蟹  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000692,"note":"\n【本经原文】味咸，寒，有毒。治胸中邪气，热结痛，喎僻，面肿，败漆。烧之致鼠。生池泽诸水中。  \n\n【产地】处处有之，产陂泽中，八足两螯，有甲壳。  \n\n【性味】味咸，性寒，有小毒。  \n\n【主治】蟹主散血，解结，疏肝气，理经脉，利肢节，续筋骨，治热结痛，胸中邪气，面肿，妇人经血不通。  \n\n【别录】解结散血，愈漆创，养筋益气。  \n\n【用量】普通为服食之品，入药无定量。  \n\n【禁忌】能动风，有风疾人不可食，不可合柿及荆介食，发霍乱动风，孕妇忌之，中蟹毒，紫苏煎浓汁，冷服。  \n","videoMemo":"","fangList":[],"bieMing":"蟹"}}', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '234、蟹', '2025-01-16T06:54:24.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('N4cAsQQnMmg', 4, '{"title":"第902000691条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>233、鳖甲  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000691,"note":"\n【本经原文】味咸，平，无毒。治心腹症瘕坚积，寒热，去痞，息肉，阴蚀，痔，恶肉。生池泽。  \n\n【产地】处处有之，生水中，岳州沅江所出甲有九肋者为胜。 \n\n【性味】味咸，性平，无毒。 \n\n【主治】鳖甲为益阴除热散结要药，主心腹症瘕坚积寒热，治老疟疟母，骨节间劳热，消肿下瘀，能堕胎。 \n\n【别录】疗温疟，血瘕腰痛，小儿胁下坚。 \n\n【甄权】宿食症块痃癖，冷瘕劳瘦，除骨热结实壅，下气，妇人瘘下五色，下瘀血。 \n\n【容川】鳖甲攻破肝气，去症瘕。  \n\n【用量】普通二钱至四钱。 \n\n【禁忌】妊娠及阴虚胃弱，阴虚泄泻，产后泄泻，产后饮食不消，不思食及呕恶等证均忌。  ","videoMemo":"","fangList":[],"bieMing":"鳖甲"}}', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '233、鳖甲', '2025-01-16T06:54:24.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('G7NDOR4pYQy', 4, '{"title":"第902000690条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>232、露蜂房  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000690,"note":"\n【本经原文】味苦，平，有毒。治惊痫，瘛瘲，寒热，邪气，癫疾，鬼精，蛊毒，肠痔。生山谷。一名蜂肠。  \n\n【产地】处处有之。 \n\n【性味】味甘咸，性平，有毒，火烧灰用。 \n\n【主治】露蜂房为解毒，杀虫药，治附骨瘫疽，瘰疬，恶疮，惊痫，癫疾，杀肠中寄生虫，兴肠道。 【别录】合乱发、蛇皮烧灰，以酒日服二方寸匕，治恶疽附骨痈，根在脏腑间，歴节肿出，疔肿恶脉，诸毒皆瘥。 \n\n【苏讼】煎水治热病后毒气冲目，炙研和猪脂涂瘰疬成瘘。 \n\n【大明】煎水漱牙齿，止风虫疼痛，又洗乳癕，蜂疔，恶疮。 \n\n【苏敬】疗上气，赤白痢，遗尿失禁，烧灰酒服主阴痿，水煮服汁下乳石毒。 \n\n【用量】一般一钱至三钱。 \n\n【禁忌】禁生用。  ","videoMemo":"","fangList":[],"bieMing":"露蜂房"}}', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '232、露蜂房', '2025-01-16T06:54:24.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ikQP2z9phFR', 4, '{"title":"第902000689条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>231、猬皮  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000689,"note":"\n【本经原文】味苦，平，无毒。治五痔，阴蚀，下血赤白，五色血汁不止，阴肿痛引腰背。酒者杀之。生川谷、田野。  \n\n【产地】山地多有之。 \n\n【性味】味苦，性平。 \n\n【主治】猬皮治五痔，泻血，阴肿痛及反胃，炙为末或烧灰服。\n\n【别录】疗腹痛疝积，烧灰酒服。 \n\n【毅明】治反胃吐食。 \n\n【用量】一般一钱至三钱。 \n\n【禁忌】禁生用。  ","videoMemo":"","fangList":[],"bieMing":"猬皮"}}', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '231、猬皮', '2025-01-16T06:54:24.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cZTvSFZBXRa', 4, '{"title":"第902000688条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>230、天鼠屎  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000688,"note":"\n【本经原文】味辛，寒，无毒。治面痈肿，皮肤洒洒时痛，腹中血气，破寒热积聚，除惊悸。生山谷。一名鼠法，一名石肝。","videoMemo":"","fangList":[],"bieMing":"天鼠屎 "}}', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '230、天鼠屎', '2025-01-16T06:54:24.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Jr00GRGn2uY', 4, '{"title":"第902000687条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>229、燕屎  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000687,"note":"\n【本经原文】味辛，平，有毒。治蛊毒，鬼疰，逐不祥邪气，破五癃，利小便。生高山平谷。","videoMemo":"","fangList":[],"bieMing":"燕屎"}}', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '229、燕屎', '2025-01-16T06:54:24.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0KyepkDVQbY', 4, '{"title":"第902000686条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>228、犀角  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000686,"note":"\n【本经原文】味苦，寒，无毒。治百毒，蛊疰，邪鬼，瘴气，杀钩吻，鸩羽，蛇毒，除邪，不迷惑，魇寐，外服轻身。生山谷。 \n\n【产地】产我国云南贵州四川等地，生山谷中，角入药。 \n\n【性味】味苦酸咸，性寒，无毒。 \n\n【主治】犀角为散邪清热凉血解毒要药，主伤寒时疫，发黄发斑，风毒中恶，狂言妄语，治胃中大热，痘疮黑陷，吐血下血，蓄血谵语，能消痈化脓，解毒定惊。 \n\n【别录】伤寒瘟疫头痛寒热诸毒气，令人骏健。 \n\n【药性】辟中恶毒气，镇心神，解大热，散风毒，治发背痈疽疮肿，化脓作水，疗时疾热如火，烦毒入心，狂言妄语。 \n\n【灵胎】养心开窍，解毒除邪。 \n\n【用量】普通三分至一钱。 \n\n【禁忌】恶乌头，忌盐，能消胎气，孕妇忌服，痘疮气虚无大热，伤寒阴症发躁，脉沉细，足冷，渴而饮不多，且复吐出者均忌。  ","videoMemo":"","fangList":[],"bieMing":"犀角"}}', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '228、犀角', '2025-01-16T06:54:24.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('L501c7GJLf2', 4, '{"title":"第902000685条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>227、羚羊角  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000685,"note":"\n【本经原文】味咸，寒，无毒。主明目，益气，起阴，去恶血，注下，辟蛊毒，恶鬼，不祥，安心气，常不魇寐。外服强筋骨，轻身。生川谷。 \n\n【产地】产非洲，我国蒙古等地。 \n\n【性味】味咸，性寒。 \n\n【主治】羚羊角为清热，明目，强筋骨，起阴气药，治伤寒，热病寒热，中风附骨痛，产后恶血动心，食噎及惊痫，能抑低血压，防止脑溢血。 \n\n【别录】疗伤寒时气寒热，热在肌肤，湿风注毒伏在骨间，食噎不通，久服强筋骨，轻身，起阴益气，利丈夫。 \n\n【孟铣】治中风筋挛，附骨疼痛，作末蜜服治卒热闷，及热毒，利血，疝气，磨水涂肿毒。\n\n【藏器】治惊悸烦闷，心胸恶气，瘰疬恶疮，溪毒。 \n\n【容川】羚羊挂树干而眠，身悬而能眠，因其筋最直，故能治筋缩抽扯之症，角尤精气之所在，故性微寒，功专舒筋，本天水之阴，以清热也。 \n\n【用量】一般一钱至三钱。 \n\n【禁忌】有寒利者禁忌。  ","videoMemo":"","fangList":[],"bieMing":"羚羊角"}}', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '227、羚羊角', '2025-01-16T06:54:24.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HOofTiOKscL', 4, '{"title":"第902000684条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>226、牡狗阴茎  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000684,"note":"\n【本经原文】味咸，平，无毒。治伤中，阴痿不起，令强热大，生子，除女子带下十二疾。胆，平。主明目。一名狗精。  ","videoMemo":"","fangList":[],"bieMing":"狗阴茎,牡狗阴茎,狗精"}}', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '226、牡狗阴茎', '2025-01-16T06:54:24.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0KT8svbE7P4', 4, '{"title":"第902000683条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>225、羖羊角</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000683,"note":"【本经原文】味咸，温，无毒，治青盲，明目，杀疥虫，止寒泄，辟恶鬼，虎，狼，止惊悸。久服安心，益气，轻身。生川谷。","videoMemo":"","fangList":[],"bieMing":"羖羊角"}}', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '2025-01-16T06:54:24.000Z', '225、羖羊角', '2025-01-16T06:54:24.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xcmOwQP6ZOE', 4, '{"title":"第902000682条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>224、牛角鳃  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000682,"note":"\n【本经原文】牛黄味苦，平，有小毒。治惊痫，寒热，热盛，狂，痉，除邪，逐鬼。生平泽。\n\n           牛角鳃，温，无毒。下闭血，瘀血疼痛，女人带下血。 \n\n          髓，补中，填骨髓，久服增年。\n\n          胆，治惊，寒热，可丸药。 \n\n【产地】牛黄生于病牛胆中，状如鸡子黄，多出陕西甘肃等地。 \n\n【性味】味苦（或作甘），性平（或作凉），有小毒（或作无毒）。 \n\n【主治】牛黄为泻热定惊，利痰清心要药，主惊痫，寒热中恶，口噤，小儿惊邪，痘疮发狂，治痰迷，径急，斑痧，疮毒，益肝胆，定魂魄。 \n\n【别录】疗小儿百病，诸痫热，口不开，大人狂癫，又堕胎，久服令人不忘。 \n\n【甄权】安魂定魄，辟邪魅，卒中恶，小儿夜啼。 \n\n【日华】主中风失音，口噤，惊悸，天行时疾，健忘虚乏。 \n\n【思邈】益肝胆，定惊神，除热止惊痢，辟恶气，除百病。 \n\n【用量】普通五分至一钱。 \n\n【禁忌】恶龙骨龙胆，地黄常山蜚蠊，畏牛膝干漆，风热未深入者忌用。","videoMemo":"","fangList":[],"bieMing":"牛角鳃"}}', '2025-01-16T06:54:25.000Z', '2025-01-16T06:54:25.000Z', '2025-01-16T06:54:25.000Z', '224、牛角鳃', '2025-01-16T06:54:25.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TigGG28XzO2', 4, '{"title":"第902000681条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>223、鹿茸  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000681,"note":"\n【本经原文】味甘，温，无毒。治漏下，恶血，寒热，惊痫，益气，强志，生齿，不老。角，温，无毒。治恶疮，痈肿，逐邪恶气，留血在阴中。 \n\n【产地】鹿产山林中，处处有之，我国西北及东三省为多，其茸及角入药。 \n\n【性味】味甘咸，性温，无毒。 \n\n【主治】鹿茸为大补真阳要药，主养血益阳，强筋健骨，生精充髓，治男子虚劳，老人精衰，腰膝无力，滑精，眩晕，妇人崩瘘带下。 \n\n【别录】疗虚劳洒洒如疟，羸瘦，四肢酸痛，腰脊痛，小便数利，泄经溺血，破瘀血在腹，散石淋，痈肿，骨中热，举疽痒，安胎下气，杀鬼精物，久服耐老，不可近丈夫阴令萎。 \n\n【日华】补男子腰肾虚冷，脚膝无力，夜梦鬼交，精溢自出，女人崩中瘘血，赤白带下，炙末空心酒服方寸匕，壮筋骨。  \n\n【容川】其宿以头顾尾，能通督脉，督者肾脉，坎中一阳之主脉也，鹿生北方，得坎中一阳之气也，故其督脉极旺，而脊与脑髓极足，因而上发而生角，每年一换，初生为鹿茸，茸之精气极足，为补髓强精壮阳益血之圣药。但其性上行，凡是血逆火逆者不宜用。惟血虚火弱，阳不举，气不上者，乃为合宜。 \n\n【灵胎】补阳益血。 \n\n【用量】普通七分至钱半。  \n\n治，男子阴茎近入易于痿弱。 鹿胎—浑然元气所在，归下焦而不上行，为种子益肾补胞宫之要药。  ","videoMemo":"","fangList":[],"bieMing":"鹿茸"}}', '2025-01-16T06:54:25.000Z', '2025-01-16T06:54:25.000Z', '2025-01-16T06:54:25.000Z', '223、鹿茸', '2025-01-16T06:54:25.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BsHlF5asY46', 4, '{"title":"第902000680条・第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}","description":"<p>222、白马茎  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000680,"note":"\n【本经原文】味咸，平，无毒，治伤中，脉绝，阴不起，强志，益气，长肌肉，肥健，生子。眼，平。治惊痫，腹满，疟疾。悬蹄，平。治惊邪，瘛瘲，乳难，辟恶气，鬼毒，蛊疰，不祥。生平泽。 ","videoMemo":"","fangList":[],"bieMing":"白马茎"}}', '2025-01-16T06:54:25.000Z', '2025-01-16T06:54:25.000Z', '2025-01-16T06:54:25.000Z', '222、白马茎', '2025-01-16T06:54:25.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'XZk0F9iCLrO');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NOpwWQ25kFh', 4, '{"title":"第902000801条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>255、石灰  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000801,"note":"\n【本经原文】味辛，温。治疽，疡，疥瘙，热气，恶疮，癞疾，死肌，堕眉，杀痔虫，去黑 子、息肉。生川谷。一名恶灰。  \n\n【产地】近山处皆有之，其石青白色，作窑烧之，则成石灰。  \n\n【性味】味辛，性温，有毒 \n\n【主治】石灰为止血要药，功能蚀恶肉，止吐血，疗金疮，又能解酸类中毒。  \n\n【别录】疗髓谷疽。 \n\n【甄权】治病疥，蚀恶肉，止金疮血甚长。 \n\n【大明】生肌长肉，吐血，白癜疬疡，瘢疵，痔瘘，瘿赘疣子，妇人粉刺，产后阴不能合，解酒酸，治酒毒，暖水臓，治气。 \n\n【用量】普通三分至一钱。 \n\n【禁忌】性燥，且能蚀肉，不可多服。  ","videoMemo":"","fangList":[],"bieMing":"石灰"}}', '2025-01-16T06:57:10.000Z', '2025-01-16T06:57:10.000Z', '2025-01-16T06:57:10.000Z', '255、石灰', '2025-01-16T06:57:10.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZJpaVTv54W0', 4, '{"title":"第902000844条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>298、白头翁 </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000844,"note":"\n【本经原文】一名野丈人，一名胡王使者．味苦，温，有毒。治温疟，狂易，寒热，症瘕积聚，瘿气，逐血，止痛，治金疮。生山谷及田野。  \n\n【产地】生嵩山山谷。处处有之，生山谷及田野，近根处有白茸，故名。  \n\n【性味】味辛苦，性温，无毒（或作小毒）。 \n\n【主治】白头翁为治痢要药，功能泄热凉血，治毒痢赤痢，下血腹痛，及妇女经闭，  \n\n【别录】治鼻衄。 \n\n【甄权】赤痢腹痛，齿痛，百节骨痛，项下瘿瘤。  \n\n【弘景】止毒痢 \n\n【容川】白头翁一茎直上如柴胡，所以能治下痢后重者，升散郁结也。其无风动摇，有风不动，色白有毛，凡毛皆得风气，采于秋月，得金木交合之气，故能熄风，从肺金以达风木之气，使木不侮土，故功在升举后重，而止痢疾，又其味苦，是治风热之妙药，仲景治产后中风，及痢疾后重者，走取其熄风火，达肝阳也。 【药征】主治热痢下重也。  \n【用量】普通钱半至三钱。 \n\n【禁忌】滞下胃虚不思食，及完谷不化，泄泻由虚寒寒热而不由湿毒者，均忌，得酒良。  ","videoMemo":"","fangList":[],"bieMing":"白头翁"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '298、白头翁', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WNb3zt074hl', 4, '{"title":"第902000843条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>297、狼毒  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000843,"note":"\n【本经原文】味辛，平，有大毒。治咳逆上气，破积聚，饮食寒热，水气，恶疮，鼠瘰，疽蚀，鬼精，蛊毒，杀飞鸟走兽。生山谷。一名续毒。  \n\n【产地】产我国山西陕西等地，叶似商陆及大黄，茎叶上有毛，其根皮黄肉白。  \n\n【性味】味辛，性平，有大毒。 \n\n【主治】狼毒主破积聚，治九种心痛。 \n\n【别录】除胸下积癖。 \n\n【大明】治痰饮症瘕，亦杀鼠。 \n\n【括要】经年癣疮生痂，搔之有黄水出，每阴雨痒甚，为末敷之效。 \n\n【用量】普通三分至钱许。 \n\n【禁忌】狼毒有毒，用之宜慎，畏密陀僧。  ","videoMemo":"","fangList":[],"bieMing":"狼毒,续毒"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '297、狼毒', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2oG4tAhdTHb', 4, '{"title":"第902000842条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>296、萹蓄  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000842,"note":"\n【本经原文】味苦，平，无毒．治浸淫，疥瘙，疽，痔，杀三虫。生山谷。一名萹竹。  \n\n【产地】处处有之，多繁殖路旁，叶细绿。 \n\n【性味】味苦，性平，无毒。 \n\n【主治】萹蓄草为杀虫疥，利小便要药，治湿疮浸淫，热淋涩痛，热疾黄疸。 \n\n【别录】疗女子阴蚀。 \n\n【甄权】煮汁饮小儿，疗蚘虫有验。 \n\n【用量】普通一钱至三钱。 \n\n【禁忌】无湿热者勿用。","videoMemo":"","fangList":[],"bieMing":"萹蓄"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '296、萹蓄', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XPLw9DXwGzf', 4, '{"title":"第902000841条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>295、羊蹄</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000841,"note":"  \n【本经原文】味苦、寒、无毒。治头秃，疥瘙，除热，女子阴蚀。生川泽。一名东方宿，一名连虫陆，一名鬼目。 \n\n【产地】处处有之，多生山野下湿之地，叶长似菜，故亦曰羊蹄菜，根黄白色，粗大似葫芦巴。  \n\n【性味】味苦、性寒、无毒。  \n\n【主治】羊蹄主杀虫，治疥癣，肿疡，清血热，疗肠风，便秘。\n\n【别录】浸淫疽痔，杀虫。 \n\n【大明】治癣，杀一切虫，醋磨贴肿毒。 \n\n【用量】普通二至三钱，外用无定量。 \n\n【禁忌】多食下气，令人作泻，故有人取以代大黄者。  ","videoMemo":"","fangList":[],"bieMing":"羊蹄"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '295、羊蹄', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cgjAnY7hFNR', 4, '{"title":"第902000840条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>294、商陆  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000840,"note":"\n【本经原文】味辛，平，有毒。治水胀，疝瘕，痹，熨除痈肿，杀鬼精物。生川谷。一名䓪根。  \n\n【产地】处处有之，多生山野阴地，其根有赤白两种，赤者有毒，白者入药。 \n\n【性味】味苦（或作辛），性寒，有毒。 \n\n【主治】商陆为利水消肿要药，主治水肿，瘕疝，脚气胀满，能疏五臓，散水气，通利大小 肠，并可傅痈疮。 \n\n【别录】疗胸邪气，水肿痿痹，腹满洪，直疏五臓，散水气。 \n\n【甄权】泻十种水病，喉痹不通，薄切醋炒涂喉外良。 \n\n【大明】通大小肠，泻蛊毒，堕胎，熁肿毒，傅恶物。 \n\n【容川】商陆用根，取其内透膜膈，以导水下行。一般用苗则升，用根则降。 \n\n【用量】普通五分至一钱左右 \n\n【禁忌】虚人禁用，赤者有毒伤人，只堪贴脐，商陆入麝香少许，用以利溲水肿。","videoMemo":"","fangList":[],"bieMing":"商陆"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '294、商陆', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Q1yX6RGDXpB', 4, '{"title":"第902000839条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>293、羊踯躅  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000839,"note":"\n【本经原文】味辛，温，有大毒。治贼风在皮肤中淫淫痛，温疟，恶毒，诸痹。生川谷。  \n\n【产地】产我国广东广西四川一带，花冠为漏斗状，色黄似杜鹃花而大。 \n\n【性味】味辛，性温，有大毒。 \n\n【主治】羊踯躅为诸风湿痹痛药，主痛风走注，风痰湿痹，治蛊毒。 \n\n【别录】邪气鬼疰，蛊毒。 \n\n【用量】普通分许 \n\n【禁忌】羊食其草，踯躅而死，有毒之药，宜慎用之，近眼令人昏翳，其根误服，亦能杀人，中毒者，绿豆汁解之。  \n","videoMemo":"","fangList":[],"bieMing":"羊踯躅"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '293、羊踯躅', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0L2kXiogaZH', 4, '{"title":"第902000838条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>292、牙子  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000838,"note":"\n【本经原文】一名狼牙。味苦，寒，有毒。治邪气，热气，疥瘙，恶疡，疮，痔，去白虫。生川谷。  \n\n【产地】山中处处有之。  \n\n【性味】味苦，性寒，有毒。 \n\n【主治】为解毒杀虫要药，治风搔，恶疮，驱寸白条虫。\n\n【甄权】治浮风搔痒，煎汁洗恶疮。 \n\n【大明】杀腹臓一切虫，止赤白痢，煎服。 \n\n【禁忌】内服须慎重  ","videoMemo":"","fangList":[],"bieMing":"狼牙,牙子"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '292、牙子', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('u8YB4MFwrtM', 4, '{"title":"第902000837条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>291、荛花  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000837,"note":"\n【本经原文】味苦，寒，有毒。治伤寒，温疟，下十二水，破积聚大坚，症瘕，荡涤肠胃中留癖饮食，寒热邪气，利水道。生川谷。又名黄芫花。 \n\n【产地】为山地小灌木。花供药用。 \n\n【性味】味苦，性寒，有毒。 \n\n【主治】为排水要药，治腹水，水肿，肋膜积水及湿痰咳嗽。 \n\n【别录】疗痰饮咳嗽 \n\n【甄权】治咳逆上气，喉中肿满，蛊毒，痃癖气块。 \n\n【用量】一般一钱左右。 \n\n【禁忌】同芫花。","videoMemo":"","fangList":[],"bieMing":"荛花,黄芫花"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '291、荛花', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('InOd8j8WNGw', 4, '{"title":"第902000836条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>290、贯众  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000836,"note":"\n【本经原文】一名贯节，一名贯渠，一名百头，一名虎卷，一名扁苻。味苦，微寒，有毒。治腹中邪热气，诸毒，杀三虫。生山谷。 \n\n【产地】处处有之，多自生山中溪畔，或森林阴处，根黑褐色。 \n\n【性味】味苦，性微寒，有小毒。 \n\n【主治】贯众为解毒要药，功能治腹中邪热之毒，软坚破积，及妇科诸血症。 \n\n【别录】去寸白，破症瘕，除头风，止金疮。 \n\n【苏颂】为末水服一钱，止鼻血有效。 \n\n【灵胎】解毒杀虫。 \n\n【用量】普通一钱至二钱。 \n\n【禁忌】无。 ","videoMemo":"","fangList":[],"bieMing":"贯众"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '290、贯众', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0kjJIkaf8JO', 4, '{"title":"第902000835条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>289、茵芋  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000835,"note":"\n【本经原文】味苦，温，有毒。治五臓邪气，心腹寒热，羸瘦，如疟状，发作有时，诸关节风湿痹痛，生川谷。  ","videoMemo":"","fangList":[],"bieMing":"茵芋"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '289、茵芋', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CxL1zrqv6SV', 4, '{"title":"第902000834条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>288、泽漆  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000834,"note":"\n【本经原文】味苦，微寒，无毒。治皮肤热，大腹水气，四肢面目浮肿，丈夫阴气不足，生川泽。  \n\n【产地】产江湖原泽，处处有之，绿叶绿花，茎有白汁粘人，故曰泽漆。  \n\n【性味】味苦，性微寒，无毒（或作小毒）。 \n\n【主治】泽漆主治水肿脚肿，消痰退热，敷之消疣。  \n\n【别录】利大小肠，明目。  \n\n【大明】止疟疾，消痰，退热。  \n\n【用量】普通五分至钱半。  \n\n【禁忌】赤小豆为使，恶薯蓣。  ","videoMemo":"","fangList":[],"bieMing":"泽漆"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '288、泽漆', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nEQg6tCQGNO', 4, '{"title":"第902000833条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>287、大戟  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000833,"note":"\n【本经原文】一名邛巨。味苦，寒，有小毒。治蛊毒，十二水，腹满急痛，积聚，中风，皮肤疼痛，吐逆。  \n\n【产地】生常山。山野或平泽自生之宿根有毒草，产江浙等地，春生红芽，茎高尺许，伤其茎，有白汁流出，根外部赤黄，内白色。 \n\n【性味】味苦性寒，有小毒。 \n\n【主治】大戟为泻脏腑水湿要药，主消水肿，袪痰涎，利大小便，泻痘毒陷。 \n\n【别录】颈腋痈肿头痛，发汗，利大小便。 \n\n【甄权】下恶血癖块，腹内雷鸣，通月水，堕胎。 \n\n【大明】泻毒药，泻天行，黄病温疟，破症结。  \n【用量】普通八分至二钱。 \n\n【禁忌】大戟力峻，取效甚捷而用之亦宜慎，反甘草，用菖蒲解之，得枣良，不损脾。  ","videoMemo":"","fangList":[],"bieMing":"大戟"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '287、大戟', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LpiGvVqQ8Oy', 4, '{"title":"第902000832条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>286、白及  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000832,"note":"\n【本经原文】一名甘根，一名连及草。味苦，平，无毒。治痈肿，恶疮，败疽，伤阴，死肌，胃中邪气，贼风，鬼击，痱缓不收，生川谷。  \n\n 【产地】山野多年生草本，庭园亦可种类，根黄白色，中含粘液颇多。 \n\n【性味】味苦辛，性寒，无毒。 \n\n【主治】白及为止血疗疮要药，功能逐瘀生新，补肺损，止吐血。 \n\n【甄权】除白癣疥虫，结热不消，阴下痿，面上皯疱。 \n\n【大明】止惊邪，血，痫疾，风痹，赤眼，症结，温热，疟疾，发背，瘰疬，肠风痔瘘，扑 损刀箭伤，汤火疮，生肌止痛。 \n\n【东垣】止肺血。 \n\n【灵胎】敛疮涩血。 \n\n【用量】普通一钱至三钱。","videoMemo":"","fangList":[],"bieMing":"白及"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '286、白及', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Mzsy23fQ5VM', 4, '{"title":"第902000831条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>285、雚菌  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000831,"note":"\n【本经原文】一名雚卢。味咸，平，有小毒。治心痛，温中，去长虫，白癣，蛲虫，蛇螫毒，症瘕，诸虫。生东海池泽及渤海。","videoMemo":"","fangList":[],"bieMing":"雚菌"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '285、雚菌', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('P3Eok0BUbjn', 4, '{"title":"第902000830条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>284、青葙子,草蒿,萎蒿</p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000830,"note":"\n【本经原文】味苦，微寒，无毒。治邪气，皮肤中热，风瘙身痒，杀三虫，子，名草决明，治唇口青，生平谷道旁。一名草蒿，一名萎蒿。  \n\n【产地】产我国南方暖地田野，为草本植物，茎直立，叶作披针形，花作淡红色，茎叶皆入药，名草决明，子名青葙子，别有一种名决明子，与此名似而物殊。  \n\n【性味】味苦，性微寒，无毒。 \n\n【主治】青葙子为眼科要药，主镇肝明目，治赤障青盲翳膜。 \n\n【甄权】治肝脏热毒充眼，赤障青盲翳肿，恶疮疥疮。 \n\n【大明】治五脏邪气，益脑髓，镇肝，明耳目，坚筋骨，去风寒湿痹。\n\n【用量】普通一钱至二、三钱。 \n\n【禁忌】虚寒之人，火衰目病者不宜。  ","videoMemo":"","fangList":[],"bieMing":"青葙子"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '284、青葙子,草蒿,萎蒿', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lwTKK0KTfyc', 4, '{"title":"第902000829条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>283、白敛  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000829,"note":"\n【本经原文】味苦，平，无毒。治痈肿，疽，疮，散结气，止痛，除热，目中赤，小儿惊痫，温疟，女子阴中肿痛。生山谷。一名莬核，一名白草。 \n\n【产地】产我国湖南湖北，及北地各省亦多有之，根入药。 \n\n【性味】味苦，性平，无毒。 \n\n【主治】白敛主散结聚，治痈疽疮毒，痔瘘血痢，生肌止痛，外用敷一切疮，并治面上粉刺赤鼻。 \n\n【别录】杀火毒。 \n\n【大明】治发背瘰疬，面上疱疮，肠风痔瘘，血痢，刀箭疮扑损，生肌止痛。 \n\n【用量】普通五分至钱半。 \n\n【禁忌】反乌头。  ","videoMemo":"","fangList":[],"bieMing":"白敛"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '283、白敛', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TMMfWl6Rk75', 4, '{"title":"第902000828条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>282、甘遂  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000828,"note":"\n【本经原文】一名主田。味苦，寒，有毒。治大腹疝瘕，腹满，面目浮肿，留饮，宿食，破症坚积聚，利水谷道。生川谷。 \n\n【产地】产陕西河南一带，自生山野间，为类似大戟之毒草，茎叶含乳液，切断则流白汁，其根为连珠状，多节，皮有赤色斑点，内白色。 \n\n【性味】味苦甘，性寒，有毒 \n\n【主治】甘遂为行水要药，主治身体浮肿，腹胀，囊肿，攻决痰水，利大小便。 \n\n【别录】下五水，散膀胱留热，皮中痞热气肿满。 \n\n【甄权】能泻十二种水疾，去痰水。 \n\n【药征】主利水也，旁治掣痛，咳烦，短气，小便难，心下满。 \n\n【用量】普通八分至二钱。 \n\n【禁忌】元气虚人，除伤寒水结胸不得不用外，其余水肿蛊胀，谨慎用之，恶远志，反甘草。 ","videoMemo":"","fangList":[],"bieMing":"甘遂"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '282、甘遂', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MyUO0THsPgm', 4, '{"title":"第902000827条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>281、蜀漆  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000827,"note":"\n【本经原文】味辛，平，有毒。治疟，及咳逆，寒热，腹中症坚，痞结，积聚，邪气，蛊毒。鬼疰。生川谷。又名常山。\n\n【产地】产我国陕西河南四川等地，江浙亦有之，生于山野阴湿之处，为落叶小灌木，根名\n\n为常山，苗即为蜀漆。\n\n【性味】味苦辛，性寒，有毒。\n\n【主治】蜀漆为驱痰截疟要药，主袪老痰积饮，治新久诸疟，能引痰上行使吐，下行使下，逐水消肿，杀虫，疗蛊。（春夏用蜀漆，秋冬用常山）\n\n【别录】疗鬼蛊往来，水胀，洒洒恶寒，鼠瘘\n\n【甄权】治诸疟，吐痰涎，治项下瘤瘘。\n\n【容川】为治疟要药，痰疟是积湿而成的，常山苗能透达以吐之。\n\n【药征】主治胸腹及脐下动剧者，故兼治惊狂火逆疟疾。\n\n【用量】普通八分至三钱。\n\n【禁忌】凡真气虚者忌，忌葱菜及菘茗，得甘草吐疟痰，酒炒用良。","videoMemo":"","fangList":[],"bieMing":"蜀漆"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '281、蜀漆', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('85tWmMTf7Iv', 4, '{"title":"第902000826条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>280、恒山  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000826,"note":"\n【本经原文】一名玄草。味苦，寒，有毒。治伤寒寒热，发温疟，鬼毒，胸中痰结，吐逆。生川谷。","videoMemo":"","fangList":[],"bieMing":"恒山"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '280、恒山', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IGCK6SXo2wo', 4, '{"title":"第902000825条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>279、蛇含  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000825,"note":"\n【本经原文】一名蛇衔。味苦，微寒，无毒。治惊痫，寒热邪气，除热，金疮，疽，痔，鼠瘰，恶疮，头疡。生山谷。 \n\n【产地】产山野之地，处处有之。 \n\n【性味】味苦，微寒，无毒。 \n\n【主治】蛇含草主治痈疮，蛇咬，清热解毒。 \n\n【别录】疗心腹邪气，腹痛湿痹，养胎，利小儿。 \n\n【甄权】治小儿寒热丹疹。 \n\n【用量】普通一至二钱，外用无定量。 \n\n【禁忌】忌火。","videoMemo":"","fangList":[],"bieMing":"蛇含"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '279、蛇含', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KksUg4CzHdY', 4, '{"title":"第902000824条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>278、射干  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000824,"note":"\n【本经原文】一名乌扇，一名乌蒲。味苦，平，有毒。治咳逆上气，喉痹，咽痛，不得消息，散结气，腹中邪逆，食饮大热。生川谷田野。  \n\n【产地】处处有之，生于各地山中，为多年生草本，园圃亦可栽种，叶似菖蒲，其花可供玩赏。  \n\n【性味】味苦，性平，有毒。  \n\n【主治】射干清火解毒散血消痰要药，主咽喉肿痛，咳逆上气，降实火，利大肠，治积痰瘀 血，热气结毒。  \n\n【别录】疗老血在心脾间，咳唾言语气臭，散胸中热气。  \n\n【甄权】治疰气消瘀血，通女人月闭。 \n\n【大明】消痰破症结，胸膈满腹胀，气喘，痃癖，开胃下食，镇肝明目。  \n\n【元素】去胃中痈疮。 \n\n【用量】普通钱半至三钱。 \n\n【禁忌】性不益阴，凡脾胃弱，脏寒，气血虚，病无实热，均忌。\n\n【容川】射干微苦，利喉中之痰。  ","videoMemo":"","fangList":[],"bieMing":"射干"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '278、射干', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dVkeK9CC9Lv', 4, '{"title":"第902000823条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>277、钩吻  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000823,"note":"\n【本经原文】一名野葛。味辛，温，有大毒。治金疮，乳痉，中恶风，咳逆上气，水肿，杀鬼疰，蛊毒。生山谷。  ","videoMemo":"","fangList":[],"bieMing":"钩吻"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '277、钩吻', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MN4mwUE8r2q', 4, '{"title":"第902000822条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>276、藜芦  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000822,"note":"\n【本经原文】一名葱苒。味辛，寒，有毒。治蛊毒，咳逆，泄利，肠澼，头疡，疥瘙，恶疮，杀诸虫毒，去死肌。生山谷。 \n\n【产地】产我国陕西一带，各省亦多有之，生山谷中，根似葱有须而多毛。 \n\n【性味】味辛苦，性寒，有毒。 \n\n【主治】藜芦为催吐要药，主风痰上塞，用吐一切恶物，通顶发嚏（嗅之），治风痫，外用治疮疥杀虫。  \n\n【别录】疗哕逆喉痹不通，鼻中息肉，马刀乱疮，不入汤用。\n\n【甄权】主上气，去积年脓血泄利。 \n\n【灵胎】除湿泄热解毒杀虫。  \n\n【用量】普通一至二分。  \n\n【禁忌】多服引吐，损人元气，畏葱白，服之吐即止，有辛烈气味，入鼻发嚏不止，饮冷水即止，能杀蝇，亦称蝇毒，黄莲为使，反细辛芍药，人参沙参，苦参，丹参，恶大黄。  ","videoMemo":"","fangList":[],"bieMing":"藜芦"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '276、藜芦', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NYM6oR75GS8', 4, '{"title":"第902000821条・第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }","description":"<p>275、旋复花  </p>","content_format":"html","_microfeed":{"bookId":"ZhuBd0Vj7kl","receiptNo":902000821,"note":"\n【本经原文】一名筋根花，一名金沸。味甘，温，无毒。主益气，去面黑，色媚好。其根，味辛，治腹中寒热邪气，利小便。久服不饥，轻身。生平泽。  \n\n【产地】产原野湿地，各处有之，园圃亦可栽植，亦名金钱花。  \n\n【主治】旋覆花为下气祛痰健胃行水要药，主治肺胃气虚，痰水胶结，上气喘急，根能续筋断。  \n\n【别录】消胸上痰结，唾如胶漆，心胸痰水，膀胱留饮，风气湿痹，皮间死肉，利大肠，通血脉，益色泽。  \n\n【甄权】主水肿，逐大腹，开胃，止呕逆不下食。  \n\n【灵胎】降气消痰。 \n\n【用量】普通一钱至二、三钱。 \n\n【禁忌】病人涉虚者，忌多服，冷利大肠，虚寒人禁用。","videoMemo":"","fangList":[],"bieMing":"旋覆花,旋复花"}}', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '2025-01-16T09:23:45.000Z', '275、旋复花', '2025-01-16T09:23:45.000Z', 1, NULL, 'ZhuBd0Vj7kl', 'section', 'hgs1R3LpkzF');
